        """ALTER TABLE youth_programs ADD COLUMN IF NOT EXISTS meeting_start_time TEXT DEFAULT ''""",
        """ALTER TABLE youth_programs ADD COLUMN IF NOT EXISTS meeting_end_time TEXT DEFAULT ''""",
