def serialize_row(r):
    out = {}
    for k, v in r.items():
        if isinstance(v, (datetime, date)):
            out[k] = v.isoformat()
        elif isinstance(v, Decimal):
            # Postgres NUMERIC columns (e.g. seat x/y) come back as Decimal,
            # which can't be JSON-serialized and can't be mixed with plain
            # floats in arithmetic (TypeError). Normalize once here so every
            # caller just gets an ordinary Python number.
            out[k] = float(v)
        else:
            out[k] = v
    return out

def parse_db_datetime(val):
    """Safely parse a datetime value that may be a string (from serialize_row) or datetime object.
    Always returns a naive UTC datetime, or None if unparseable."""
    if val is None:
        return None
    if isinstance(val, datetime):
        return val.replace(tzinfo=None) if val.tzinfo else val
    if isinstance(val, str):
        s = val.strip()
        # Strip timezone offset if present (handles Python < 3.11)
        import re as _re
        s = _re.sub(r'[+-]\d{2}:\d{2}$', '', s).replace('Z', '')
        try:
            return datetime.fromisoformat(s)
        except Exception:
            pass
        # Try common formats
        for fmt in ('%Y-%m-%dT%H:%M:%S.%f', '%Y-%m-%dT%H:%M:%S', '%Y-%m-%d %H:%M:%S.%f', '%Y-%m-%d %H:%M:%S'):
            try:
                return datetime.strptime(s, fmt)
            except Exception:
                pass
    return None

def fetchall(conn, sql, params=()):
    with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as c:
        c.execute(sql, params)
        return [serialize_row(r) for r in c.fetchall()]

def fetchone(conn, sql, params=()):
    with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as c:
        c.execute(sql, params)
        r = c.fetchone()
        return serialize_row(r) if r else None

def execute(conn, sql, params=()):
    with conn.cursor() as c:
        c.execute(sql, params)

def maybe_auto_reveal_cast_list(conn, context_type, context_id, row):
    """If a cast list is queued (Publish was clicked while a countdown was
    still running) and the reveal time has now passed, flip it live. Shared
    by both the public cast-list endpoint and the admin settings endpoint so
    the reveal shows up the moment anyone — family or staff — next loads
    either page, without needing a background job."""
    if not row or not row.get('cast_list_queued') or row.get('cast_list_published'):
        return row
    reveal_at = parse_db_datetime(row.get('cast_list_reveal_at'))
    if not reveal_at or reveal_at <= now_eastern():
        execute(conn, """UPDATE audition_settings SET cast_list_published=TRUE, cast_list_queued=FALSE,
            updated_at=NOW() WHERE context_type=%s AND context_id=%s""", (context_type, context_id))
        conn.commit()
        row['cast_list_published'] = True
        row['cast_list_queued'] = False
    return row

def get_waiver_summary(conn, vol_id):
    from datetime import date as _date, datetime as _datetime
    waivers = fetchall(conn,
        'SELECT vw.*, wt.name as type_name FROM volunteer_waivers vw JOIN waiver_types wt ON vw.waiver_type_id=wt.id WHERE vw.volunteer_id=%s ORDER BY vw.signed_date DESC',
        (vol_id,))
    today = _date.today()
    # Check required waivers first — respecting any age restriction on the waiver type
    vol = fetchone(conn, 'SELECT birthday FROM volunteers WHERE id=%s', (vol_id,))
    vol_age = compute_age(vol.get('birthday')) if vol else None
    required = fetchall(conn, 'SELECT id, min_age, max_age FROM waiver_types WHERE required_for_volunteering=TRUE OR required_all=TRUE')
    required = [r for r in required if waiver_applies_to_age(r, vol_age)]
    signed_type_ids = set(w['waiver_type_id'] for w in waivers)
    has_missing_required = any(r['id'] not in signed_type_ids for r in required)

    worst = 'none'
    for w in waivers:
        if not w['expiry_date']:
            if worst == 'none': worst = 'valid'
            continue
        try:
            diff = (_datetime.strptime(str(w['expiry_date'])[:10], '%Y-%m-%d').date() - today).days
        except Exception:
            if worst == 'none': worst = 'valid'
            continue
        if diff < 0: worst = 'expired'; break
        elif diff < 30 and worst != 'expired': worst = 'expiring'
        elif worst == 'none': worst = 'valid'

    # If missing a required waiver, downgrade to expired (worst)
    if has_missing_required and worst not in ('expired',):
        worst = 'expired'
    return worst, waivers

