@app.route('/api/events/bulk-update', methods=['POST'])
def bulk_update_events():
    """Change several events at once. Only the fields sent are changed:
    room, location, status, event_type_id, start_time, end_time,
    show_on_lobby. room_mode 'add'/'remove' adds or takes a room off each
    event's room list instead of replacing it."""
    err = require_permission('events', 'edit')
    if err: return err
    d = request.json or {}
    ids = [x for x in (d.get('ids') or []) if x][:2000]
    f = d.get('fields') or {}
    if not ids:
        return jsonify({'error': 'Pick at least one event.'}), 400
    allowed = {'location': str, 'status': str, 'event_type_id': str, 'start_time': str, 'end_time': str}
    sets, vals = [], []
    for k, typ in allowed.items():
        if k in f:
            v = (f.get(k) or '').strip()
            if k == 'status' and v not in ('draft', 'open', 'closed', 'cancelled', 'completed', ''):
                return jsonify({'error': 'Unknown status'}), 400
            sets.append(k + '=%s'); vals.append(v or None if k == 'event_type_id' else v)
    if 'show_on_lobby' in f:
        sets.append('show_on_lobby=%s'); vals.append(bool(f.get('show_on_lobby')))
    mode = d.get('room_mode') or 'replace'
    conn = get_db()
    try:
        changed = 0
        if 'room' in f and mode == 'replace':
            sets.append('room=%s'); vals.append(', '.join(x.strip() for x in str(f.get('room') or '').split(',') if x.strip()))
        if sets:
            execute(conn, 'UPDATE events SET ' + ', '.join(sets) + ', updated_at=NOW() WHERE id = ANY(%s)', tuple(vals + [ids]))
            changed = len(ids)
        if 'room' in f and mode in ('add', 'remove'):
            target = [x.strip() for x in str(f.get('room') or '').split(',') if x.strip()]
            for ev in fetchall(conn, 'SELECT id, room FROM events WHERE id = ANY(%s)', (ids,)) or []:
                cur = [x.strip() for x in (ev.get('room') or '').split(',') if x.strip()]
                if mode == 'add':
                    new = cur + [t for t in target if t.lower() not in [c.lower() for c in cur]]
                else:
                    new = [c for c in cur if c.lower() not in [t.lower() for t in target]]
                if new != cur:
                    execute(conn, 'UPDATE events SET room=%s, updated_at=NOW() WHERE id=%s', (', '.join(new), ev['id']))
            changed = len(ids)
        conn.commit()
        return jsonify({'ok': True, 'updated': changed})
    finally:
        conn.close()


@app.route('/api/events')
def get_events():
    err = require_auth()
    if err: return err
    conn = get_db()
    events = fetchall(conn, '''SELECT e.*,
        COALESCE(e.requires_background_check, FALSE) as requires_background_check,
        et.name as event_type_name, et.color as event_type_color,
        p.name as production_name, COALESCE(p.stage,'mainstage') as production_stage,
        pg.name as program_name, ps.name as linked_session_name
        FROM events e
        LEFT JOIN event_types et ON e.event_type_id=et.id
        LEFT JOIN productions p ON e.production_id=p.id
        LEFT JOIN youth_programs pg ON e.program_id=pg.id
        LEFT JOIN program_sessions ps ON e.linked_session_id=ps.id
        ORDER BY e.event_date DESC NULLS LAST, e.start_time ASC NULLS LAST''')
    for e in events:
        e['required_waivers'] = fetchall(conn,
            'SELECT ew.*, wt.name as waiver_name FROM event_waivers ew JOIN waiver_types wt ON ew.waiver_type_id=wt.id WHERE ew.event_id=%s', (e['id'],))
        e['elics'] = fetchall(conn, """SELECT ee.id as assignment_id, el.id as elic_id,
            el.is_master, v.name as volunteer_name, v.id as volunteer_id,
            COALESCE(v.background_check_status,'none') as background_check_status
            FROM event_elics ee JOIN elics el ON ee.elic_id=el.id
            JOIN volunteers v ON el.volunteer_id=v.id
            WHERE ee.event_id=%s""", (e['id'],))
        e['staff'] = []
        try:
            e['staff'] = fetchall(conn, """SELECT es.*, v.name as volunteer_name,
                v.background_check_status, v.email
                FROM event_staff es JOIN volunteers v ON es.volunteer_id=v.id
                WHERE es.event_id=%s ORDER BY es.role, v.name""", (e['id'],))
        except Exception:
            pass
        e['status'] = e.get('status') or 'draft'
    conn.close()
    # Add rental occurrences as synthetic calendar events — but only for
    # occurrences that don't already have a real linked event (see
    # _sync_rental_events_for_request). Going forward every approved
    # occurrence gets a real event, so this is now just a safety net for
    # any edge case where the sync hasn't run yet.
    try:
        conn2 = get_db()
        rentals = fetchall(conn2, '''SELECT ro.*, rr.title, rr.start_time AS req_start, rr.end_time AS req_end,
            rp.name AS partner_name, rs.name AS space_name
            FROM rental_occurrences ro
            JOIN rental_requests rr ON rr.id=ro.request_id
            LEFT JOIN rental_partners rp ON rp.id=rr.partner_id
            LEFT JOIN rental_spaces rs ON rs.id=rr.space_id
            WHERE ro.status != \'cancelled\'
            AND NOT EXISTS (SELECT 1 FROM events e2 WHERE e2.rental_occurrence_id=ro.id)''') or []
        conn2.close()
        for r in rentals:
            events.append({
                'id': 'rental_' + r['id'],
                'name': f"{r.get('title','')} \u2013 {r.get('partner_name','')}",
                'event_date': r.get('occurrence_date',''),
                'start_time': r.get('start_time') or r.get('req_start',''),
                'end_time': r.get('end_time') or r.get('req_end',''),
                'event_type_name': 'Artistic Partnership',
                'event_type_color': '#7c3aed',
                'status': r.get('status','scheduled'),
                'location': r.get('space_name',''),
                'is_rental': True,
                'required_waivers': [], 'elics': [], 'staff': [],
            })
    except Exception as e:
        app.logger.warning(f'Rental calendar merge error: {e}')
    # Add scheduled venue tours as synthetic calendar events — distinct color
    # from actual bookings, since a tour is just a prospective visit, not a
    # confirmed rental of the space.
    try:
        conn3 = get_db()
        tours = fetchall(conn3, '''SELECT rr.id, rr.title, rr.tour_scheduled_date, rr.tour_scheduled_time,
            rp.name AS partner_name, rs.name AS space_name
            FROM rental_requests rr
            LEFT JOIN rental_partners rp ON rp.id=rr.partner_id
            LEFT JOIN rental_spaces rs ON rs.id=rr.space_id
            WHERE rr.tour_scheduled_date IS NOT NULL AND rr.tour_scheduled_date != \'\'
            AND rr.status NOT IN (\'denied\', \'cancelled\')''') or []
        conn3.close()
        for t in tours:
            events.append({
                'id': 'rental_tour_' + t['id'],
                'name': f"Tour: {t.get('title','')} \u2013 {t.get('partner_name','')}",
                'event_date': t.get('tour_scheduled_date', ''),
                'start_time': t.get('tour_scheduled_time', ''),
                'end_time': '',
                'event_type_name': 'Venue Tour',
                'event_type_color': '#ea580c',
                'status': 'scheduled',
                'location': t.get('space_name', ''),
                'is_rental': True,
                'required_waivers': [], 'elics': [], 'staff': [],
            })
    except Exception as e:
        app.logger.warning(f'Rental tour calendar merge error: {e}')
    # Add program/class sessions as synthetic calendar events — but only
    # ones that actually have a registrant, and only ones that don't already
    # have a real linked event (see linked_session_id): once someone's
    # created a real event for hour-logging/ELICs/staffing purposes and
    # linked it to a session, that real event IS the calendar entry — the
    # synthetic one would just be a confusing duplicate. Otherwise a bulk-
    # imported schedule (which can easily be a few hundred open hourly
    # slots) would bury the calendar in mostly-empty class times nobody's
    # confirmed for yet.
    try:
        conn4 = get_db()
        prog_sessions = fetchall(conn4, '''SELECT ps.id, ps.name, ps.start_date, ps.start_time, ps.end_time,
            ps.location, ps.status, pg.id AS program_id, pg.name AS program_name
            FROM program_sessions ps
            JOIN youth_programs pg ON pg.id=ps.program_id
            WHERE ps.start_date IS NOT NULL AND ps.start_date != \'\'
            AND EXISTS (SELECT 1 FROM program_registrations pr
                WHERE pr.program_id=ps.program_id
                AND pr.session_ids LIKE \'%%"\' || ps.id || \'"%%\'
                AND pr.status NOT IN (\'cancelled\',\'waitlisted\'))
            AND NOT EXISTS (SELECT 1 FROM events e3 WHERE e3.linked_session_id=ps.id)
            ''') or []
        conn4.close()
        for s in prog_sessions:
            events.append({
                'id': 'session_' + s['id'],
                'name': s.get('name') or 'Session',
                'event_date': s.get('start_date', ''),
                'start_time': s.get('start_time', ''),
                'end_time': s.get('end_time', ''),
                'event_type_name': 'Class Session',
                'event_type_color': '#0d9488',
                'status': 'scheduled',
                'location': s.get('location', '') or '',
                'is_program_session': True,
                'program_id': s.get('program_id', ''),
                'program_name': s.get('program_name', ''),
                'required_waivers': [], 'elics': [], 'staff': [],
            })
    except Exception as e:
        app.logger.warning(f'Program session calendar merge error: {e}')
    return jsonify(events)

@app.route('/api/events', methods=['POST'])
def create_event():
    d = request.json or {}
    if session.get('role') == 'director':
        if not d.get('production_id'):
            return jsonify({'error': 'Directors can only create events tied to their own production'}), 403
        err = require_own_production(d.get('production_id'))
    else:
        err = require_permission('events')
    if err: return err
    if not (d.get('name') or '').strip():
        return jsonify({'error': 'Event name is required'}), 400
    if not (d.get('event_date') or '').strip():
        return jsonify({'error': 'Event date is required'}), 400
    eid = str(uuid.uuid4())
    conn = get_db()
    execute(conn, '''INSERT INTO events
        (id,name,event_date,end_date,start_time,end_time,event_type_id,location,address,room,production_id,program_id,linked_session_id,expected_volunteers,description,notes,status,requires_background_check,auto_log_hours,hours_store_bonus_type,hours_store_bonus_multiplier,hours_store_bonus_flat_cents,kiosk_signin_mode,show_on_lobby)
        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,'draft',%s,%s,%s,%s,%s,%s,%s)''',
        (eid, d.get('name',''), d.get('event_date') or None, d.get('end_date') or None,
         d.get('start_time') or None, d.get('end_time') or None,
         d.get('event_type_id') or None, d.get('location',''), d.get('address',''), d.get('room',''),
         d.get('production_id') or None, d.get('program_id') or None, d.get('linked_session_id') or None,
         d.get('expected_volunteers') or None,
         d.get('description',''), d.get('notes',''), d.get('requires_background_check',False),
         d.get('auto_log_hours', False),
         d.get('hours_store_bonus_type') or None,
         d.get('hours_store_bonus_multiplier') or None,
         d.get('hours_store_bonus_flat_cents') or None,
         d.get('kiosk_signin_mode') or 'auto',
         d.get('show_on_lobby', True)))
    conn.commit()
    # Auto-assign program instructor/default ELIC when event belongs to a program
    program_id = d.get('program_id') or None
    if program_id:
        try:
            prog = fetchone(conn, 'SELECT default_elic_id, instructor_id FROM youth_programs WHERE id=%s', (program_id,))
            if prog:
                elic_vol_id = prog.get('default_elic_id') or prog.get('instructor_id')
                if elic_vol_id:
                    elic = fetchone(conn, 'SELECT id FROM elics WHERE volunteer_id=%s', (elic_vol_id,))
                    if elic:
                        existing = fetchone(conn, 'SELECT id FROM event_elics WHERE event_id=%s AND elic_id=%s', (eid, elic['id']))
                        if not existing:
                            execute(conn, 'INSERT INTO event_elics (id,event_id,elic_id) VALUES (%s,%s,%s)',
                                (str(uuid.uuid4()), eid, elic['id']))
                            conn.commit()
        except Exception as e:
            app.logger.warning(f'Auto-ELIC assignment failed: {e}')
    row = fetchone(conn, '''SELECT e.*,
        COALESCE(e.requires_background_check, FALSE) as requires_background_check,
        et.name as event_type_name, et.color as event_type_color,
        p.name as production_name, COALESCE(p.stage,'mainstage') as production_stage,
        pg.name as program_name, ps.name as linked_session_name
        FROM events e
        LEFT JOIN event_types et ON e.event_type_id=et.id
        LEFT JOIN productions p ON e.production_id=p.id
        LEFT JOIN youth_programs pg ON e.program_id=pg.id
        LEFT JOIN program_sessions ps ON e.linked_session_id=ps.id
        WHERE e.id=%s''', (eid,))
    conn.close()
    if not row:
        # The insert itself succeeded (we'd have raised already if not) —
        # this means the id genuinely can't be read back, which points at
        # a bad linked_session_id (references a session belonging to a
        # different program, or one that no longer exists) tripping up the
        # LEFT JOIN in a way that's worth surfacing clearly instead of a
        # raw crash.
        return jsonify({'error': 'Event was created but could not be reloaded — the selected session may be invalid.'}), 500
    row['required_waivers'] = []; row['elics'] = []
    return jsonify(row)

def staff_actor_name():
    return 'Staff: ' + (session.get('name') or session.get('email') or 'RoleCall user')


@app.route('/api/events/<eid>/status', methods=['POST'])
def set_event_status(eid):
    err = require_permission('events')
    if err: return err
    d = request.json or {}
    status = d.get('status','').strip()
    if status not in ('draft','open','closed','cancelled'):
        return jsonify({'error': f'Invalid status: {status}'}), 400
    conn = get_db()
    execute(conn, 'UPDATE events SET status=%s WHERE id=%s', (status, eid))
    # The kiosk determines open/closed state purely from the latest event_logs
    # row (not events.status), so admin-side status changes need a matching
    # log entry or they won't be reflected on the kiosk.
    if status in ('open', 'closed'):
        try:
            action = 'open' if status == 'open' else 'close'
            execute(conn, '''INSERT INTO event_logs (id,event_id,elic_id,action,notes,signature,actor_name)
                VALUES (%s,%s,NULL,%s,%s,'',%s)''',
                (str(uuid.uuid4()), eid, action, f'Status set to {status} in RoleCall', staff_actor_name()))
        except Exception as e:
            app.logger.warning(f'set_event_status log entry failed (non-fatal): {e}')
    conn.commit()
    row = fetchone(conn, 'SELECT * FROM events WHERE id=%s', (eid,))
    conn.close()
    return jsonify({'ok': True, 'status': row['status'], 'id': eid})

@app.route('/api/events/<eid>', methods=['PUT'])
def update_event(eid):
    conn = get_db()
    existing_event = fetchone(conn, 'SELECT production_id FROM events WHERE id=%s', (eid,))
    if session.get('role') == 'director':
        pid_to_check = (existing_event or {}).get('production_id')
        if not pid_to_check:
            conn.close()
            return jsonify({'error': 'Directors can only manage events tied to their own production'}), 403
        err = require_own_production(pid_to_check)
    else:
        err = require_permission('events')
    if err: conn.close(); return err
    d = request.json or {}
    prev = fetchone(conn, 'SELECT status FROM events WHERE id=%s', (eid,))
    prev_status = prev.get('status') if prev else None
    new_status = d.get('status','draft')
    execute(conn, '''UPDATE events SET name=%s,event_date=%s,end_date=%s,start_time=%s,end_time=%s,
        event_type_id=%s,location=%s,address=%s,room=%s,production_id=%s,program_id=%s,linked_session_id=%s,expected_volunteers=%s,
        description=%s,notes=%s,requires_background_check=%s,auto_log_hours=%s,
        rsvp_enabled=%s,rsvp_message=%s,rsvp_kind=%s,invite_headline=%s,hide_block_names=%s,status=%s,carpools_enabled=%s,
        hours_store_bonus_type=%s,hours_store_bonus_multiplier=%s,hours_store_bonus_flat_cents=%s,
        kiosk_signin_mode=%s,show_on_lobby=%s WHERE id=%s''',
        (d.get('name',''), d.get('event_date') or None, d.get('end_date') or None,
         d.get('start_time') or None, d.get('end_time') or None,
         d.get('event_type_id') or None, d.get('location',''), d.get('address',''), d.get('room',''),
         d.get('production_id') or None, d.get('program_id') or None, d.get('linked_session_id') or None,
         d.get('expected_volunteers') or None,
         d.get('description',''), d.get('notes',''), d.get('requires_background_check',False),
         d.get('auto_log_hours', False), d.get('rsvp_enabled', False),
         d.get('rsvp_message',''), d.get('rsvp_kind') or 'volunteer', (d.get('invite_headline') or '').strip(), bool(d.get('hide_block_names', False)), new_status,
         d.get('carpools_enabled', False),
         d.get('hours_store_bonus_type') or None,
         d.get('hours_store_bonus_multiplier') or None,
         d.get('hours_store_bonus_flat_cents') or None,
         d.get('kiosk_signin_mode') or 'auto', d.get('show_on_lobby', True), eid))
    # Kiosk state is driven by event_logs, not events.status — if the status
    # actually changed to open/closed here, mirror it into event_logs too.
    if new_status != prev_status and new_status in ('open', 'closed'):
        try:
            action = 'open' if new_status == 'open' else 'close'
            execute(conn, '''INSERT INTO event_logs (id,event_id,elic_id,action,notes,signature,actor_name)
                VALUES (%s,%s,NULL,%s,%s,'',%s)''',
                (str(uuid.uuid4()), eid, action, f'Status set to {new_status} while editing the event', staff_actor_name()))
        except Exception as e:
            app.logger.warning(f'update_event log entry failed (non-fatal): {e}')
    conn.commit()
    row = fetchone(conn, '''SELECT e.*,
        COALESCE(e.requires_background_check, FALSE) as requires_background_check,
        et.name as event_type_name, et.color as event_type_color,
        p.name as production_name, COALESCE(p.stage,'mainstage') as production_stage,
        pg.name as program_name, ps.name as linked_session_name
        FROM events e
        LEFT JOIN event_types et ON e.event_type_id=et.id
        LEFT JOIN productions p ON e.production_id=p.id
        LEFT JOIN youth_programs pg ON e.program_id=pg.id
        LEFT JOIN program_sessions ps ON e.linked_session_id=ps.id
        WHERE e.id=%s''', (eid,))
    if not row:
        conn.close()
        return jsonify({'error': f'Event {eid} not found after update — the selected session may be invalid.'}), 500
    row['required_waivers'] = fetchall(conn,
        'SELECT ew.*, wt.name as waiver_name FROM event_waivers ew JOIN waiver_types wt ON ew.waiver_type_id=wt.id WHERE ew.event_id=%s', (eid,))
    row['elics'] = fetchall(conn, """SELECT ee.id as assignment_id, el.id as elic_id,
        el.is_master, v.name as volunteer_name, v.id as volunteer_id,
        COALESCE(v.background_check_status,'none') as background_check_status
        FROM event_elics ee JOIN elics el ON ee.elic_id=el.id
        JOIN volunteers v ON el.volunteer_id=v.id
        WHERE ee.event_id=%s""", (eid,))
    conn.close()
    return jsonify(row)

def _delete_event_cascade(conn, eid):
    """Delete an event and everything that references it (waivers, ELIC
    assignments, checklist responses, logged hours, carpools). Used by the
    manual delete-event route and by the rental-event sync when an
    approved booking's date is edited or the request is denied/withdrawn."""
    cur = conn.cursor()
    def try_sql(sql, params=()):
        try:
            cur.execute('SAVEPOINT sp')
            cur.execute(sql, params)
            cur.execute('RELEASE SAVEPOINT sp')
        except Exception as e:
            cur.execute('ROLLBACK TO SAVEPOINT sp')
            app.logger.warning(f'_delete_event_cascade skip: {e}')

    try_sql('UPDATE youth_sign_ins SET event_id=NULL WHERE event_id=%s', (eid,))
    try_sql('UPDATE kiosk_sessions SET event_id=NULL WHERE event_id=%s', (eid,))
    try_sql('DELETE FROM event_waivers WHERE event_id=%s', (eid,))
    try_sql('DELETE FROM event_elics WHERE event_id=%s', (eid,))
    try_sql('DELETE FROM event_checklist_responses WHERE event_id=%s', (eid,))
    try_sql('DELETE FROM hours WHERE event_id=%s', (eid,))

    try:
        cur.execute('SAVEPOINT sp_carpools')
        cur.execute('SELECT id FROM carpools WHERE event_id=%s', (eid,))
        carpool_ids = [r[0] for r in cur.fetchall()]
        for cid in carpool_ids:
            cur.execute('DELETE FROM carpool_members WHERE carpool_id=%s', (cid,))
        if carpool_ids:
            cur.execute('DELETE FROM carpools WHERE event_id=%s', (eid,))
        cur.execute('RELEASE SAVEPOINT sp_carpools')
    except Exception as e:
        cur.execute('ROLLBACK TO SAVEPOINT sp_carpools')
        app.logger.warning(f'_delete_event_cascade carpools: {e}')

    # The main delete — if this fails we want the real error
    cur.execute('DELETE FROM events WHERE id=%s', (eid,))
    conn.commit()
    cur.close()

@app.route('/api/events/bulk-update-type', methods=['POST'])
def bulk_update_event_type():
    """Change the event type on many events at once — e.g. every rehearsal
    on a production that was miscategorized, without opening each one."""
    err = require_permission('events')
    if err: return err
    d = request.json or {}
    event_ids = d.get('event_ids') or []
    event_type_id = d.get('event_type_id') or None
    if not event_ids:
        return jsonify({'error': 'No events selected'}), 400
    conn = get_db()
    ph = ','.join(['%s']*len(event_ids))
    execute(conn, f'UPDATE events SET event_type_id=%s WHERE id IN ({ph})', tuple([event_type_id]+event_ids))
    conn.commit()
    conn.close()
    return jsonify({'ok': True, 'updated': len(event_ids)})


@app.route('/api/events/<eid>', methods=['DELETE'])
def delete_event(eid):
    conn = get_db()
    if session.get('role') == 'director':
        existing_event = fetchone(conn, 'SELECT production_id FROM events WHERE id=%s', (eid,))
        pid_to_check = (existing_event or {}).get('production_id')
        if not pid_to_check:
            conn.close()
            return jsonify({'error': 'Directors can only manage events tied to their own production'}), 403
        err = require_own_production(pid_to_check)
    else:
        err = require_permission('events')
    if err: conn.close(); return err
    try:
        _delete_event_cascade(conn, eid)
        conn.close()
        return jsonify({'ok': True})
    except Exception as e:
        try: conn.rollback()
        except: pass
        conn.close()
        app.logger.error(f'delete_event {eid}: {e}')
        return jsonify({'error': str(e)}), 500

