@app.route('/api/youth-participants/check-duplicates', methods=['POST'])
def check_youth_duplicates():
    err = require_auth()
    if err: return err
    d = request.json or {}
    rows = d.get('rows', [])
    conn = get_db()
    results = []
    for row in rows:
        first = (row.get('first_name') or '').strip().lower()
        last  = (row.get('last_name') or '').strip().lower()
        dob   = (row.get('dob') or '').strip()
        if dob:
            match = fetchone(conn, 'SELECT id,first_name,last_name,dob FROM youth_participants WHERE LOWER(first_name)=%s AND LOWER(last_name)=%s AND dob=%s', (first, last, dob))
        else:
            match = fetchone(conn, 'SELECT id,first_name,last_name,dob FROM youth_participants WHERE LOWER(first_name)=%s AND LOWER(last_name)=%s', (first, last))
        results.append({'existing': match})
    conn.close()
    return jsonify(results)

@app.route('/api/youth-participants/bulk-import', methods=['POST'])
def bulk_import_youth():
    err = require_permission('youth')
    if err: return err
    d = request.json or {}
    rows = d.get('rows', [])
    program_id = d.get('program_id') or None
    enrolled_date = d.get('enrolled_date') or None
    if not rows:
        return jsonify({'error': 'No rows provided'}), 400
    conn = get_db()
    results = {'created': 0, 'updated': 0, 'skipped': 0, 'errors': []}
    for i, row in enumerate(rows):
        try:
            first = (row.get('first_name') or '').strip()
            last  = (row.get('last_name') or '').strip()
            if not first or not last:
                results['errors'].append(f'Row {i+1}: first_name and last_name required')
                continue
            action      = row.get('action', 'create')
            existing_id = row.get('existing_id')
            if action == 'skip':
                results['skipped'] += 1
                continue
            dob             = (row.get('dob') or '').strip() or None
            status          = (row.get('status') or 'active').strip()
            medical_notes   = (row.get('medical_notes') or '').strip()
            allergies       = (row.get('allergies') or '').strip()
            photo_consent   = 1 if str(row.get('photo_consent','')).lower() in ('1','yes','true','y') else 0
            medical_consent = 1 if str(row.get('medical_consent','')).lower() in ('1','yes','true','y') else 0
            if action == 'update' and existing_id:
                execute(conn, 'UPDATE youth_participants SET first_name=%s,last_name=%s,dob=%s,status=%s,medical_notes=%s,allergies=%s,photo_consent=%s,medical_consent=%s WHERE id=%s',
                    (first, last, dob, status, medical_notes, allergies, photo_consent, medical_consent, existing_id))
                yid = existing_id
                results['updated'] += 1
            else:
                yid = str(uuid.uuid4())
                pp = default_passphrase(first, last)
                execute(conn, 'INSERT INTO youth_participants (id,first_name,last_name,dob,status,medical_notes,allergies,photo_consent,medical_consent,passphrase) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)',
                    (yid, first, last, dob, status, medical_notes, allergies, photo_consent, medical_consent, pp))
                results['created'] += 1
            # Guardian
            gname = (row.get('guardian_name') or '').strip()
            if gname:
                existing_g = fetchone(conn, 'SELECT id FROM youth_guardians WHERE youth_id=%s AND is_primary=1', (yid,))
                if existing_g:
                    execute(conn, 'UPDATE youth_guardians SET name=%s,relationship=%s,phone=%s,email=%s WHERE id=%s',
                        (gname, (row.get('guardian_relationship') or '').strip(), (row.get('guardian_phone') or '').strip(), (row.get('guardian_email') or '').strip(), existing_g['id']))
                else:
                    execute(conn, 'INSERT INTO youth_guardians (id,youth_id,name,relationship,phone,email,is_primary) VALUES (%s,%s,%s,%s,%s,%s,1)',
                        (str(uuid.uuid4()), yid, gname, (row.get('guardian_relationship') or '').strip(), (row.get('guardian_phone') or '').strip(), (row.get('guardian_email') or '').strip()))
            # Emergency contact
            ecname = (row.get('emergency_name') or '').strip()
            if ecname and (row.get('emergency_phone') or '').strip():
                try:
                    execute(conn, 'INSERT INTO youth_emergency_contacts (id,youth_id,name,relationship,phone) VALUES (%s,%s,%s,%s,%s) ON CONFLICT DO NOTHING',
                        (str(uuid.uuid4()), yid, ecname, (row.get('emergency_relationship') or '').strip(), (row.get('emergency_phone') or '').strip()))
                except Exception:
                    pass
            # Authorized pickups
            for priority, prefix in enumerate(['pickup1','pickup2'], 1):
                puname = (row.get(prefix+'_name') or '').strip()
                if puname:
                    try:
                        execute(conn, 'INSERT INTO youth_authorized_pickups (id,youth_id,name,relationship,phone,priority) VALUES (%s,%s,%s,%s,%s,%s) ON CONFLICT DO NOTHING',
                            (str(uuid.uuid4()), yid, puname, (row.get(prefix+'_relationship') or '').strip(), (row.get(prefix+'_phone') or '').strip(), priority))
                    except Exception:
                        pass
            # Program enrollment
            if program_id:
                try:
                    execute(conn, 'INSERT INTO youth_program_enrollments (id,youth_id,program_id,enrolled_date) VALUES (%s,%s,%s,%s) ON CONFLICT (youth_id,program_id) DO NOTHING',
                        (str(uuid.uuid4()), yid, program_id, enrolled_date))
                except Exception:
                    pass
            conn.commit()
        except Exception as e:
            results['errors'].append(f'Row {i+1} ({row.get("first_name","")} {row.get("last_name","")}): {str(e)}')
            try: conn.rollback()
            except Exception: pass
    conn.close()
    return jsonify(results)

@app.route('/api/youth-programs')
def get_youth_programs():
    err = require_auth()
    if err: return err
    conn = get_db()
    programs = fetchall(conn, '''SELECT yp.*, v.name as default_elic_name,
        (SELECT COUNT(*) FROM program_registrations WHERE program_id=yp.id AND status='confirmed') AS reg_confirmed,
        (SELECT COUNT(*) FROM program_registrations WHERE program_id=yp.id AND status='pending_payment') AS reg_pending,
        (SELECT COUNT(*) FROM program_registrations WHERE program_id=yp.id AND status='waitlisted') AS reg_waitlisted,
        (SELECT COUNT(*) FROM program_registrations WHERE program_id=yp.id AND status NOT IN (\'cancelled\',\'waitlisted\')) AS reg_enrolled,
        (SELECT COALESCE(SUM(
            CASE WHEN pr.is_comped THEN 0
                WHEN su.hold_status = 'charged' THEN su.amount
                WHEN su.hold_status = 'pending' THEN 0
                ELSE COALESCE(pr.amount_paid_cents,
                    COALESCE(yp.price,0) * COALESCE(pr.participant_count,1)
                    - COALESCE(pr.discount_amount,0) - COALESCE(pr.sibling_discount_amount,0))
                    - COALESCE(pr.refund_amount_cents,0)
            END), 0)
         FROM program_registrations pr
         LEFT JOIN step_up_child_holds su ON su.registration_id = pr.id
         WHERE pr.program_id=yp.id AND pr.status='confirmed') AS confirmed_revenue_cents
        FROM youth_programs yp
        LEFT JOIN elics el ON yp.default_elic_id=el.id
        LEFT JOIN volunteers v ON el.volunteer_id=v.id
        ORDER BY yp.name''')
    conn.close()
    return jsonify(programs)


def _save_event_program_fields(conn, pid, d):
    """For program_type='event': the event's date, times, place, who it's
    for, price, spots and the practical details people need. Maps onto the
    same columns classes use (single date, meeting times, location, price,
    capacity) so registration, the calendar and payments all just work."""
    if (d.get('program_type') or '') != 'event':
        return
    date = (d.get('event_date') or '').strip()[:10] or None
    aud = d.get('event_audience') if d.get('event_audience') in ('adults', 'youth', 'all') else 'all'
    def cents(v):
        try: return int(round(float(v) * 100)) if str(v).strip() != '' else 0
        except Exception: return 0
    cap = d.get('event_capacity')
    try: cap = int(cap) if str(cap).strip() != '' else None
    except Exception: cap = None
    execute(conn, '''UPDATE youth_programs SET schedule_type='single', single_date=%s, start_date=COALESCE(%s,start_date),
            end_date=COALESCE(%s,end_date), meeting_start_time=%s, meeting_end_time=%s, event_arrival_time=%s,
            program_location=%s, price=%s, capacity=%s, event_audience=%s, event_includes=%s, event_bring=%s,
            event_refund_policy=%s, registration_form_type=%s, requires_guardian=%s WHERE id=%s''',
        (date or '', date, date, (d.get('event_start_time') or '')[:5], (d.get('event_end_time') or '')[:5],
         (d.get('event_arrival_time') or '')[:5], (d.get('event_location') or '').strip()[:300], cents(d.get('event_price')), cap, aud,
         (d.get('event_includes') or '').strip()[:2000], (d.get('event_bring') or '').strip()[:2000],
         (d.get('event_refund_policy') or '').strip()[:2000],
         'adult' if aud == 'adults' else 'youth', aud == 'youth', pid))

@app.route('/api/youth-programs', methods=['POST'])
def create_youth_program():
    err = require_permission('youth')
    if err: return err
    d = request.json or {}
    if not (d.get('name') or '').strip(): return jsonify({'error': 'Name is required'}), 400
    pid = str(uuid.uuid4())
    conn = get_db()
    try:
        execute(conn, 'INSERT INTO youth_programs (id,name,description,program_type,start_date,end_date,instructor_id,default_elic_id,requires_guardian,bundle_enabled,bundle_price,bundle_label,instructor_expected_pay,is_paid_instruction,pay_rate_type,pay_rate_amount) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)',
                (pid, (d.get('name') or '').strip(), d.get('description',''),
                 d.get('program_type','class'), d.get('start_date') or None,
                 d.get('end_date') or None, d.get('instructor_id') or None,
                 d.get('default_elic_id') or None,
                 bool(d.get('requires_guardian', False)),
                 bool(d.get('bundle_enabled', False)),
                 int(float(d['bundle_price'])*100) if d.get('bundle_price') else None,
                 d.get('bundle_label') or 'Book All Sessions',
                 float(d.get('instructor_expected_pay') or 0),
                 bool(d.get('is_paid_instruction', False)),
                 d.get('pay_rate_type') or 'hourly',
                 float(d.get('pay_rate_amount') or 0)))
        _save_event_program_fields(conn, pid, d)
        conn.commit()
    except psycopg2.IntegrityError:
        conn.rollback(); conn.close()
        return jsonify({'error': 'Program already exists'}), 400
    row = fetchone(conn, '''SELECT yp.*, v.name as default_elic_name FROM youth_programs yp LEFT JOIN elics el ON yp.default_elic_id=el.id LEFT JOIN volunteers v ON el.volunteer_id=v.id WHERE yp.id=%s''', (pid,))
    conn.close()
    return jsonify(row)

@app.route('/api/youth-programs/<pid>', methods=['PUT'])
def update_youth_program(pid):
    err = require_own_program(pid, 'youth')
    if err: return err
    d = request.json or {}
    if not (d.get('name') or '').strip(): return jsonify({'error': 'Name is required'}), 400
    conn = get_db()
    execute(conn, 'UPDATE youth_programs SET name=%s,description=%s,program_type=%s,start_date=%s,end_date=%s,instructor_id=%s,default_elic_id=%s,requires_guardian=%s,status=%s,bundle_enabled=%s,bundle_price=%s,bundle_label=%s,instructor_expected_pay=%s,is_paid_instruction=%s,pay_rate_type=%s,pay_rate_amount=%s WHERE id=%s',
            ((d.get('name') or '').strip(), d.get('description',''),
             d.get('program_type','class'), d.get('start_date') or None,
             d.get('end_date') or None, d.get('instructor_id') or None,
             d.get('default_elic_id') or None,
             bool(d.get('requires_guardian', False)),
             d.get('status','active'),
             bool(d.get('bundle_enabled', False)),
             int(float(d['bundle_price'])*100) if d.get('bundle_price') else None,
             d.get('bundle_label') or 'Book All Sessions',
             float(d.get('instructor_expected_pay') or 0),
             bool(d.get('is_paid_instruction', False)),
             d.get('pay_rate_type') or 'hourly',
             float(d.get('pay_rate_amount') or 0),
             pid))
    _save_event_program_fields(conn, pid, d)
    conn.commit()
    sync_hours_store_for_program(conn, pid)   # name, status, and bundle feed the store items
    row = fetchone(conn, '''SELECT yp.*, v.name as default_elic_name FROM youth_programs yp LEFT JOIN elics el ON yp.default_elic_id=el.id LEFT JOIN volunteers v ON el.volunteer_id=v.id WHERE yp.id=%s''', (pid,))
    conn.close()
    return jsonify(row)

@app.route('/api/youth-programs/<pid>/registration-status', methods=['PUT'])
def set_program_registration_status(pid):
    """Quick action to open/close registrations without touching any other program settings."""
    err = require_permission('youth')
    if err: return err
    d = request.json or {}
    reg_status = d.get('registration_status')
    if reg_status not in ('draft', 'interest_list', 'open', 'closed', 'cancelled'):
        return jsonify({'error': 'Invalid registration status'}), 400
    conn = get_db()
    prog = fetchone(conn, 'SELECT id FROM youth_programs WHERE id=%s', (pid,))
    if not prog:
        conn.close()
        return jsonify({'error': 'Program not found'}), 404
    execute(conn, 'UPDATE youth_programs SET registration_status=%s WHERE id=%s', (reg_status, pid))
    conn.commit()
    sync_hours_store_for_program(conn, pid)
    row = fetchone(conn, '''SELECT yp.*, v.name as default_elic_name FROM youth_programs yp LEFT JOIN elics el ON yp.default_elic_id=el.id LEFT JOIN volunteers v ON el.volunteer_id=v.id WHERE yp.id=%s''', (pid,))
    conn.close()
    return jsonify(row)

@app.route('/api/youth-programs/<pid>/archive-status', methods=['PUT'])
def set_program_archive_status(pid):
    """Quick action to archive/unarchive a program without touching any other program settings."""
    err = require_permission('youth')
    if err: return err
    d = request.json or {}
    status = d.get('status')
    if status not in ('upcoming', 'active', 'completed', 'archived'):
        return jsonify({'error': 'Invalid status'}), 400
    conn = get_db()
    prog = fetchone(conn, 'SELECT id FROM youth_programs WHERE id=%s', (pid,))
    if not prog:
        conn.close()
        return jsonify({'error': 'Program not found'}), 404
    execute(conn, 'UPDATE youth_programs SET status=%s WHERE id=%s', (status, pid))
    conn.commit()
    sync_hours_store_for_program(conn, pid)
    row = fetchone(conn, '''SELECT yp.*, v.name as default_elic_name FROM youth_programs yp LEFT JOIN elics el ON yp.default_elic_id=el.id LEFT JOIN volunteers v ON el.volunteer_id=v.id WHERE yp.id=%s''', (pid,))
    conn.close()
    return jsonify(row)

@app.route('/api/youth-programs/<pid>/announcements/<aid>/push', methods=['POST'])
def push_program_announcement(pid, aid):
    err = require_auth()
    if err: return err
    conn = get_db()
    # Mark as published
    execute(conn, '''UPDATE portal_announcements
        SET status='published', pushed_at=NOW(), push_count=COALESCE(push_count,0)+1
        WHERE id=%s AND program_id=%s''', (aid, pid))
    conn.commit()
    ann = fetchone(conn, 'SELECT * FROM portal_announcements WHERE id=%s', (aid,))
    prog = fetchone(conn, 'SELECT * FROM youth_programs WHERE id=%s', (pid,))
    if not ann or not prog:
        conn.close()
        return jsonify({'error': 'Not found'}), 404
    # Gather recipient emails
    recipients = set()
    enrolled = fetchall(conn, '''SELECT y.id FROM youth_participants y
        JOIN youth_program_enrollments ype ON ype.youth_id=y.id
        WHERE ype.program_id=%s AND y.status='active' ''', (pid,))
    for y in enrolled:
        guardians = fetchall(conn, "SELECT email FROM youth_guardians WHERE youth_id=%s AND email IS NOT NULL AND email!=''", (y['id'],))
        for g in guardians:
            if g['email']: recipients.add(g['email'].strip().lower())
    # Instructor
    if prog.get('instructor_id'):
        vol = fetchone(conn, 'SELECT email FROM volunteers WHERE id=%s', (prog['instructor_id'],))
        if vol and vol.get('email'): recipients.add(vol['email'].strip().lower())
    conn.close()
    if not recipients:
        return jsonify({'ok': True, 'sent_to': 0, 'warning': 'No email addresses on file'})
    prog_name = prog.get('name','Program')
    html_body = f'''<div style="font-family:sans-serif;max-width:600px;margin:0 auto">
      <div style="background:#0d9488;padding:24px;border-radius:8px 8px 0 0">
        <div style="color:rgba(255,255,255,0.8);font-size:13px;margin-bottom:4px">New Announcement</div>
        <h2 style="color:white;margin:0;font-size:22px">{prog_name}</h2>
      </div>
      <div style="background:#f8fafc;padding:28px;border-radius:0 0 8px 8px;border:1px solid #e2e8f0;border-top:none">
        <h3 style="color:#1e293b;margin:0 0 12px 0;font-size:18px">{ann['title']}</h3>
        <div style="white-space:pre-wrap;font-size:15px;line-height:1.8;color:#334155">{ann['body']}</div>
        <hr style="border:none;border-top:1px solid #e2e8f0;margin:24px 0"/>
        <p style="font-size:12px;color:#94a3b8;margin:0">
          Posted by Horizon West Theater Company for <strong>{prog_name}</strong>.
          Log in to the family portal to view and respond to announcements.
        </p>
      </div>
    </div>'''
    try:
        fi = (request.get_json(silent=True) or {}).get('from_identity') or {}
        send_email(list(recipients), f'{prog_name}: {ann["title"]}', build_hwtc_email_html(f'{prog_name}: {ann["title"]}', html_body), fi.get('email') or None, fi.get('name') or None)
        return jsonify({'ok': True, 'sent_to': len(recipients)})
    except Exception as e:
        app.logger.error(f'push_program_announcement email error: {e}')
        return jsonify({'ok': True, 'sent_to': 0, 'warning': str(e)})

@app.route('/api/youth-programs/<pid>/announcements/<aid>/unpublish', methods=['POST'])
def unpublish_program_announcement(pid, aid):
    err = require_auth()
    if err: return err
    conn = get_db()
    execute(conn, "UPDATE portal_announcements SET status='draft' WHERE id=%s AND program_id=%s", (aid, pid))
    conn.commit(); conn.close()
    return jsonify({'ok': True})

@app.route('/api/youth-programs/<pid>', methods=['DELETE'])
def delete_youth_program(pid):
    err = require_permission('youth')
    if err: return err
    conn = get_db()
    # Clear any FK references that don't cascade
    execute(conn, 'UPDATE youth_sign_ins SET program_id=NULL WHERE program_id=%s', (pid,))
    execute(conn, 'UPDATE events SET program_id=NULL WHERE program_id=%s', (pid,))
    execute(conn, 'UPDATE store_items SET active=false WHERE linked_program_id=%s AND auto_synced=true', (pid,))
    execute(conn, 'DELETE FROM youth_programs WHERE id=%s', (pid,))
    conn.commit(); conn.close()
    return jsonify({'ok': True})

@app.route('/api/youth-programs/<pid>/send-email', methods=['POST'])
def send_program_email(pid):
    err = require_auth()
    if err: return err
    d = request.json or {}
    subject = d.get('subject', '').strip()
    body = d.get('body', '').strip()
    include_guardians = d.get('include_guardians', True)
    include_instructors = d.get('include_instructors', True)
    if not subject or not body:
        return jsonify({'error': 'Subject and body are required'}), 400
    conn = get_db()
    prog = fetchone(conn, 'SELECT * FROM youth_programs WHERE id=%s', (pid,))
    if not prog:
        conn.close()
        return jsonify({'error': 'Program not found'}), 404

    recipients = set()

    # Guardian emails for all enrolled youth
    if include_guardians:
        enrolled = fetchall(conn, '''SELECT y.id FROM youth_participants y
            JOIN youth_program_enrollments ype ON ype.youth_id=y.id
            WHERE ype.program_id=%s AND y.status='active' ''', (pid,))
        for y in enrolled:
            guardians = fetchall(conn, 'SELECT email FROM youth_guardians WHERE youth_id=%s AND email IS NOT NULL AND email != \'\'', (y['id'],))
            for g in guardians:
                if g['email']:
                    recipients.add(g['email'].strip().lower())

    # Instructor email
    if include_instructors and prog.get('instructor_id'):
        vol = fetchone(conn, 'SELECT email FROM volunteers WHERE id=%s', (prog['instructor_id'],))
        if vol and vol.get('email'):
            recipients.add(vol['email'].strip().lower())

    conn.close()

    if not recipients:
        return jsonify({'error': 'No email addresses found for this program'}), 400

    prog_name = prog.get('name', 'Program')
    html_body = f'''<div style="font-family:sans-serif;max-width:600px;margin:0 auto">
      <div style="background:#0d9488;padding:20px;border-radius:8px 8px 0 0">
        <h2 style="color:white;margin:0"> {prog_name}</h2>
      </div>
      <div style="background:#f8fafc;padding:24px;border-radius:0 0 8px 8px;border:1px solid #e2e8f0">
        <div style="white-space:pre-wrap;font-size:15px;line-height:1.7;color:#1e293b">{body}</div>
        <hr style="border:none;border-top:1px solid #e2e8f0;margin:24px 0"/>
        <p style="font-size:12px;color:#94a3b8">This message was sent by Horizon West Theater Company regarding the <strong>{prog_name}</strong> program.</p>
      </div>
    </div>'''

    try:
        send_email(list(recipients), subject, build_hwtc_email_html(subject, html_body))
        return jsonify({'ok': True, 'sent_to': len(recipients), 'recipients': list(recipients)})
    except Exception as e:
        app.logger.error(f'send_program_email error: {e}')
        return jsonify({'error': str(e)}), 500

def _resolve_welcome_entity(conn, pid):
    """The welcome-email feature (send-welcome / welcome-recipients) works
    the same way for youth_programs (classes) and productions with youth
    cast (e.g. Rising Stars) — checks youth_programs first since that's the
    more common case, falls back to productions. Returns (entity, kind)
    with kind 'program' or 'production', or (None, None) if neither matches."""
    prog = fetchone(conn, 'SELECT * FROM youth_programs WHERE id=%s', (pid,))
    if prog:
        return prog, 'program'
    prod = fetchone(conn, 'SELECT * FROM productions WHERE id=%s', (pid,))
    if prod:
        return prod, 'production'
    return None, None

@app.route('/api/youth-programs/<pid>/send-welcome', methods=['POST'])
def send_program_welcome(pid):
    err = require_auth()
    if err: return err
    d = request.json or {}
    # mode: 'all' | 'family' | 'participant' | 'unlogged' ('unlogged' is
    # 'all' filtered to participants who've never signed into the portal)
    mode       = d.get('mode', 'all')
    family_id  = d.get('family_id')
    youth_id   = d.get('youth_id')
    subject_override = d.get('subject', '').strip()

    conn = get_db()
    entity, kind = _resolve_welcome_entity(conn, pid)
    if not entity:
        conn.close()
        return jsonify({'error': 'Not found'}), 404
    prog = entity if kind == 'program' else None
    prod = entity if kind == 'production' else None

    prog_name = entity.get('name', 'Program')

    # Load template
    tmpl = get_system_template(conn, 'welcome_email')
    if not tmpl:
        conn.close()
        return jsonify({'error': 'Welcome email template not found  -  check Email Templates in Settings'}), 404
    body_tmpl    = tmpl['body']
    subject_tmpl = tmpl['subject']

    # Build recipient list: list of dicts {email, passphrase, family_greeting, age, youth_id}
    recipients = []

    if mode == 'participant' and youth_id:
        y = fetchone(conn, 'SELECT * FROM youth_participants WHERE id=%s', (youth_id,))
        if y:
            guardians = fetchall(conn, "SELECT email, name FROM youth_guardians WHERE youth_id=%s AND email IS NOT NULL AND email != ''", (youth_id,))
            pp = ensure_youth_passphrase(conn, y)
            greeting = f"{y['first_name']} {y['last_name']}"
            age = calc_age_from_dob(y.get('dob'))
            for g in guardians:
                if g['email']:
                    recipients.append({'email': g['email'].strip(), 'passphrase': pp, 'family_greeting': greeting, 'age': age, 'youth_id': youth_id, 'name': g.get('name','')})
            # Also check family passphrase
            if y.get('family_id'):
                fam = fetchone(conn, 'SELECT * FROM families WHERE id=%s', (y['family_id'],))
                if fam and fam.get('passphrase'):
                    for r in recipients:
                        r['passphrase'] = fam['passphrase']

    elif mode == 'family' and family_id:
        fam = fetchone(conn, 'SELECT * FROM families WHERE id=%s', (family_id,))
        if fam:
            members = fetchall(conn, "SELECT * FROM youth_participants WHERE family_id=%s AND status='active'", (family_id,))
            pp = fam.get('passphrase', '')
            greeting = fam.get('name', 'HWTC Family')
            # Family email first — not tied to one specific child, so age is
            # unknown here; calc_age_from_dob(None) → None → treated as "under 18"
            # by the passphrase-block check below, which is the safer default.
            # Schedule falls back to the program's general schedule since there's
            # no single child to key off of for this particular address.
            if fam.get('email'):
                recipients.append({'email': fam['email'].strip(), 'passphrase': pp, 'family_greeting': greeting, 'age': None, 'youth_id': None})
            # Guardian emails
            for m in members:
                guardians = fetchall(conn, "SELECT email, name FROM youth_guardians WHERE youth_id=%s AND email IS NOT NULL AND email != ''", (m['id'],))
                member_age = calc_age_from_dob(m.get('dob'))
                for g in guardians:
                    if g['email']:
                        recipients.append({'email': g['email'].strip(), 'passphrase': pp, 'family_greeting': greeting, 'age': member_age, 'youth_id': m['id']})

    else:  # 'all' or 'unlogged' — everyone (currently) enrolled, via
           # youth_program_enrollments for a program or youth_production_members
           # for a production, optionally filtered to never-logged-in-yet
        if kind == 'program':
            enrolled_sql = """SELECT y.* FROM youth_participants y
                JOIN youth_program_enrollments ype ON ype.youth_id=y.id
                WHERE ype.program_id=%s AND y.status='active'"""
        else:
            enrolled_sql = """SELECT y.* FROM youth_participants y
                JOIN youth_production_members ypm ON ypm.youth_id=y.id
                WHERE ypm.production_id=%s AND y.status='active'"""
        if mode == 'unlogged':
            enrolled_sql += " AND y.portal_last_login IS NULL"
        enrolled = fetchall(conn, enrolled_sql, (pid,))
        for y in enrolled:
            pp = ensure_youth_passphrase(conn, y)
            greeting = f"{y['first_name']} {y['last_name']}"
            age = calc_age_from_dob(y.get('dob'))
            # Prefer family passphrase if set
            if y.get('family_id'):
                fam = fetchone(conn, 'SELECT * FROM families WHERE id=%s', (y['family_id'],))
                if fam and fam.get('passphrase'):
                    pp = fam['passphrase']
                    greeting = fam.get('name', greeting)
            guardians = fetchall(conn, "SELECT email, name FROM youth_guardians WHERE youth_id=%s AND email IS NOT NULL AND email != ''", (y['id'],))
            for g in guardians:
                if g['email']:
                    recipients.append({'email': g['email'].strip(), 'passphrase': pp, 'family_greeting': greeting, 'age': age, 'youth_id': y['id']})

    # Schedule description per recipient — looks up each child's own registration
    # so families with session-based programs see the specific session(s) they
    # actually picked, not just the program's overall date range. Falls back to
    # the program's general schedule for addresses not tied to one specific
    # child (the family-level email above) or if no registration row is found.
    program_schedule_info = _format_registration_schedule(conn, prog, prod, {})
    program_schedule_block = ''
    if program_schedule_info:
        program_schedule_block = (
            '<div class="callout" style="background:#f1efe8;border-left-color:#0d4a38">'
            '<p style="color:#04342C"><strong>You\'re registered for:</strong><br>' + program_schedule_info + '</p></div>'
        )
    schedule_block_by_youth = {}
    reg_fk_col = 'program_id' if kind == 'program' else 'production_id'
    for r in recipients:
        yid = r.get('youth_id')
        if not yid:
            r['schedule_block'] = program_schedule_block
            continue
        if yid not in schedule_block_by_youth:
            their_reg = fetchone(conn, f'''SELECT * FROM program_registrations
                WHERE youth_id=%s AND {reg_fk_col}=%s AND status='confirmed'
                ORDER BY created_at DESC LIMIT 1''', (yid, pid))
            info = _format_registration_schedule(conn, prog, prod, their_reg or {}) if their_reg else program_schedule_info
            block = ''
            if info:
                block = (
                    '<div class="callout" style="background:#f1efe8;border-left-color:#0d4a38">'
                    '<p style="color:#04342C"><strong>You\'re registered for:</strong><br>' + info + '</p></div>'
                )
            schedule_block_by_youth[yid] = block
        r['schedule_block'] = schedule_block_by_youth[yid]

    conn.close()

    # Deduplicate by email (keep first passphrase seen per address)
    seen = {}
    deduped = []
    for r in recipients:
        e = r['email'].lower()
        if e not in seen:
            seen[e] = True
            deduped.append(r)

    if not deduped:
        no_recip_msg = ('No one enrolled here has skipped logging in — everyone with an email on file has signed in at least once'
            if mode == 'unlogged' else 'No email addresses found for the selected recipients')
        return jsonify({'error': no_recip_msg}), 400

    subject_base = subject_override or subject_tmpl.replace('{{program_name}}', prog_name)

    sent = 0
    errors = []
    fi = d.get('from_identity') or {}
    passphrase_block_html = (
        '<div class="callout"><p><strong>Important  -  your passphrase is your child\'s pick-up password.</strong> '
        'Once you set it, our staff will ask for this word whenever you pick up your child. '
        'Choose something only you and approved pick-up adults know.</p></div>'
    )
    for r in deduped:
        age = r.get('age')
        is_adult = age is not None and age >= 18
        passphrase_block = '' if is_adult else passphrase_block_html
        adult_blocks = _welcome_email_adult_aware_blocks(is_adult, prog_name)
        html_body = (body_tmpl
            .replace('{{program_name}}', prog_name)
            .replace('{{passphrase}}', r.get('passphrase', ''))
            .replace('{{family_greeting}}', r.get('family_greeting', 'HWTC Family'))
            .replace('{{schedule_block}}', r.get('schedule_block', ''))
            .replace('{{passphrase_block}}', passphrase_block)
            .replace('{{intro_block}}', adult_blocks['intro_block'])
            .replace('{{portal_tagline}}', adult_blocks['portal_tagline'])
            .replace('{{passphrase_reminder_line}}', adult_blocks['passphrase_reminder_line'])
            .replace('{{closing_line}}', adult_blocks['closing_line']))
        subject = subject_base.replace('{{program_name}}', prog_name)
        ok, err_msg = send_email([r['email']], subject, build_hwtc_email_html(subject, html_body), fi.get('email') or None, fi.get('name') or None)
        if ok:
            sent += 1
        else:
            errors.append({'email': r['email'], 'error': err_msg})

    return jsonify({
        'ok': True,
        'sent': sent,
        'total': len(deduped),
        'errors': errors,
        'recipients': [r['email'] for r in deduped],
    })


@app.route('/api/youth-programs/<pid>/welcome-recipients', methods=['GET'])
def get_welcome_recipients(pid):
    """Preview who would receive the welcome email — works for a youth_programs
    row or a productions row (e.g. Rising Stars), see _resolve_welcome_entity."""
    err = require_auth()
    if err: return err
    conn = get_db()
    entity, kind = _resolve_welcome_entity(conn, pid)
    if not entity:
        conn.close()
        return jsonify({'error': 'Not found'}), 404
    if kind == 'program':
        enrolled = fetchall(conn, """
            SELECT y.id, y.first_name, y.last_name, y.passphrase, y.family_id,
                   y.status, y.portal_last_login
            FROM youth_participants y
            JOIN youth_program_enrollments ype ON ype.youth_id=y.id
            WHERE ype.program_id=%s AND y.status='active'
            ORDER BY y.last_name, y.first_name""", (pid,))
    else:
        enrolled = fetchall(conn, """
            SELECT y.id, y.first_name, y.last_name, y.passphrase, y.family_id,
                   y.status, y.portal_last_login
            FROM youth_participants y
            JOIN youth_production_members ypm ON ypm.youth_id=y.id
            WHERE ypm.production_id=%s AND y.status='active'
            ORDER BY y.last_name, y.first_name""", (pid,))

    result = []
    for y in enrolled:
        pp = ensure_youth_passphrase(conn, y)
        family_name = None
        family_id   = y.get('family_id')
        if family_id:
            fam = fetchone(conn, 'SELECT * FROM families WHERE id=%s', (family_id,))
            if fam:
                if fam.get('passphrase'):
                    pp = fam['passphrase']
                family_name = fam.get('name')
        guardians = fetchall(conn, "SELECT name, email FROM youth_guardians WHERE youth_id=%s AND email IS NOT NULL AND email != ''", (y['id'],))
        result.append({
            'youth_id':     y['id'],
            'name':         f"{y['first_name']} {y['last_name']}",
            'family_id':    family_id,
            'family_name':  family_name,
            'passphrase':   pp,
            'guardians':    guardians,
            'portal_last_login': y.get('portal_last_login'),
        })

    conn.close()
    return jsonify(result)


# ─────────────────────────────────────────────────────────────
#  PORTAL MESSAGING THREADS
# ─────────────────────────────────────────────────────────────

def _resolve_family_id_from_passphrase(conn, passphrase):
    """A parent can log into the portal with either the one shared family
    passphrase OR any one individual child's own passphrase (see
    portal_auth — both are valid, independent login paths). The messaging
    feature only ever checked the family-level passphrase, so a parent who
    logs in as one specific kid could send a message that never resolved
    to an actual family record — meaning no notification email went out,
    and the thread couldn't be found again under a different login (e.g.
    the other kid's passphrase, or the family passphrase itself). This
    always resolves to the real family_id regardless of which credential
    was used, so a message thread behaves the same no matter how the
    parent is logged in."""
    if not passphrase:
        return None
    fam = fetchone(conn, 'SELECT id FROM families WHERE LOWER(passphrase)=%s', (passphrase.lower(),))
    if fam:
        return fam['id']
    youth = fetchone(conn, 'SELECT family_id FROM youth_participants WHERE LOWER(passphrase)=%s', (passphrase.lower(),))
    if youth and youth.get('family_id'):
        return youth['family_id']
    return None


def _family_notification_emails(conn, family_id):
    """Best-effort recipient list for notifying a family: the family
    record's own email if set, plus every linked child's guardian emails —
    since families.email isn't always filled in depending on how the
    family was set up, but guardian emails on file are more consistently
    present."""
    emails = []
    if not family_id:
        return emails
    fam = fetchone(conn, 'SELECT email FROM families WHERE id=%s', (family_id,))
    if fam and fam.get('email'):
        emails.append(fam['email'])
    guardians = fetchall(conn, '''SELECT DISTINCT g.email FROM youth_guardians g
        JOIN youth_participants y ON y.id=g.youth_id
        WHERE y.family_id=%s AND g.email IS NOT NULL AND g.email != \'\'''', (family_id,)) or []
    for g in guardians:
        if g['email'] and g['email'] not in emails:
            emails.append(g['email'])
    return emails


def message_text_html(text):
    """A typed message as email-safe HTML that keeps its formatting: blank
    lines become paragraphs, single line breaks stay line breaks, and any
    HTML someone typed is shown as text rather than run."""
    import html as _hm, re as _re
    t = (text or '').replace('\r\n', '\n').replace('\r', '\n').strip()
    if not t:
        return ''
    paras = [p for p in _re.split(r'\n\s*\n', t) if p.strip()]
    out = []
    for p in paras:
        safe = _hm.escape(p.strip()).replace('\n', '<br>')
        safe = _re.sub(r'(https?://[^\s<]+)', r'<a href="\1" style="color:#145466">\1</a>', safe)
        out.append('<p style="margin:0 0 12px;line-height:1.6">' + safe + '</p>')
    return ''.join(out)


@app.route('/api/portal/messages/start', methods=['POST'])
def portal_start_message_thread():
    d = request.json or {}
    passphrase   = d.get('passphrase','').strip()
    subject      = (d.get('subject') or '').strip()
    body         = (d.get('body') or '').strip()
    program_id   = d.get('program_id') or None
    production_id = d.get('production_id') or None
    if not subject or not body:
        return jsonify({'error': 'Subject and message are required'}), 400
    conn = get_db()
    family_id = _resolve_family_id_from_passphrase(conn, passphrase)
    family = fetchone(conn, 'SELECT * FROM families WHERE id=%s', (family_id,)) if family_id else None
    sender_name = d.get('sender_name','').strip() or (family.get('name') if family else 'Family')
    tid = str(uuid.uuid4())
    execute(conn, """INSERT INTO portal_message_threads
        (id, family_id, program_id, production_id, subject, status, unread_admin, unread_family, family_passphrase)
        VALUES (%s,%s,%s,%s,%s,'open',1,0,%s)""",
        (tid, family_id, program_id, production_id, subject, passphrase or None))
    execute(conn, "INSERT INTO portal_messages (id,thread_id,sender_side,sender_name,body) VALUES (%s,%s,'family',%s,%s)",
        (str(uuid.uuid4()), tid, sender_name, body))
    conn.commit()
    # Email notify  -  configured recipients + all admins + anyone with youth permission
    s = get_email_settings()
    recipients = list(get_recipient_emails(s))
    try:
        staff_with_perm = fetchall(conn, """SELECT email FROM users
            WHERE email IS NOT NULL AND email!='' AND active=TRUE
            AND (role='admin' OR role_permissions::text LIKE '%"youth"%')""")
        for u in staff_with_perm:
            if u['email'] and u['email'] not in recipients:
                recipients.append(u['email'])
    except Exception as e:
        app.logger.warning(f'portal message staff lookup failed: {e}')
    # Always fall back to all admin users if list is still empty
    if not recipients:
        try:
            admins = fetchall(conn, "SELECT email FROM users WHERE role='admin' AND email IS NOT NULL AND email!=''")
            recipients = [u['email'] for u in admins if u.get('email')]
        except Exception: pass
    # Also notify the program instructor if one is set
    try:
        if program_id:
            prog_row = fetchone(conn, 'SELECT name, instructor_id FROM youth_programs WHERE id=%s', (program_id,))
            if prog_row and prog_row.get('instructor_id'):
                vol = fetchone(conn, 'SELECT email FROM volunteers WHERE id=%s', (prog_row['instructor_id'],))
                if vol and vol.get('email') and vol['email'] not in recipients:
                    recipients.append(vol['email'])
        elif production_id:
            prod_row = fetchone(conn, 'SELECT name FROM productions WHERE id=%s', (production_id,))
    except Exception: pass

    if recipients:
        ctx = ''
        if program_id:
            p = fetchone(conn, 'SELECT name FROM youth_programs WHERE id=%s', (program_id,))
            if p: ctx = f' - {p["name"]}'
        elif production_id:
            p = fetchone(conn, 'SELECT name FROM productions WHERE id=%s', (production_id,))
            if p: ctx = f' - {p["name"]}'
        html = f'<div style="font-family:-apple-system,sans-serif;max-width:600px"><h2 style="color:#145466">New Portal Message{ctx}</h2><p><strong>From:</strong> {_h(sender_name)}<br/><strong>Subject:</strong> {_h(subject)}</p><div style="background:#f5f9fa;padding:14px 14px 2px;border-radius:8px;margin:12px 0">{message_text_html(body)}</div><p style="color:#9ca3af;font-size:12px">Reply via Programs or Productions - Portal Content - Messages tab in RoleCall admin.</p></div>'
        send_email(recipients, f'Portal Message: {subject}', build_hwtc_email_html(f'Portal Message: {subject}', html))
    conn.close()
    return jsonify({'ok': True, 'thread_id': tid})


@app.route('/api/portal/messages/thread/<tid>')
def portal_get_thread(tid):
    passphrase = request.args.get('passphrase','')
    conn = get_db()
    thread = fetchone(conn, 'SELECT * FROM portal_message_threads WHERE id=%s', (tid,))
    if not thread:
        conn.close(); return jsonify({'error': 'Not found'}), 404
    is_admin  = session.get('user_id') is not None
    resolved_family_id = _resolve_family_id_from_passphrase(conn, passphrase) if passphrase else None
    is_family = (resolved_family_id is not None and resolved_family_id == thread.get('family_id')) \
        or (passphrase and thread.get('family_passphrase') == passphrase)
    if not is_admin and not is_family:
        conn.close(); return jsonify({'error': 'Unauthorized'}), 403
    messages = fetchall(conn, 'SELECT * FROM portal_messages WHERE thread_id=%s ORDER BY sent_at', (tid,))
    if is_admin:
        execute(conn, 'UPDATE portal_message_threads SET unread_admin=0 WHERE id=%s', (tid,))
    if is_family:
        execute(conn, 'UPDATE portal_message_threads SET unread_family=0 WHERE id=%s', (tid,))
    conn.commit()
    prog = fetchone(conn, 'SELECT name FROM youth_programs WHERE id=%s', (thread.get('program_id'),)) if thread.get('program_id') else None
    prod = fetchone(conn, 'SELECT name FROM productions WHERE id=%s', (thread.get('production_id'),)) if thread.get('production_id') else None
    conn.close()
    return jsonify({**dict(thread), 'messages': messages,
        'program_name': prog['name'] if prog else None,
        'production_name': prod['name'] if prod else None,
        'from_name': messages[0]['sender_name'] if messages else 'Family'})


@app.route('/api/portal/messages/thread/<tid>/reply', methods=['POST'])
def portal_reply_thread(tid):
    d = request.json or {}
    body = (d.get('body') or '').strip()
    if not body: return jsonify({'error': 'Message body required'}), 400
    conn = get_db()
    thread = fetchone(conn, 'SELECT * FROM portal_message_threads WHERE id=%s', (tid,))
    if not thread:
        conn.close(); return jsonify({'error': 'Not found'}), 404
    is_admin  = session.get('user_id') is not None
    passphrase = d.get('passphrase','')
    resolved_family_id = _resolve_family_id_from_passphrase(conn, passphrase) if passphrase else None
    is_family = (resolved_family_id is not None and resolved_family_id == thread.get('family_id')) \
        or (passphrase and thread.get('family_passphrase') == passphrase)
    if not is_admin and not is_family:
        conn.close(); return jsonify({'error': 'Unauthorized'}), 403
    side = 'admin' if is_admin else 'family'
    sender_name = session.get('user_name','Staff') if is_admin else (d.get('sender_name') or 'Family')
    execute(conn, 'INSERT INTO portal_messages (id,thread_id,sender_side,sender_name,body) VALUES (%s,%s,%s,%s,%s)',
        (str(uuid.uuid4()), tid, side, sender_name, body))
    if is_admin:
        execute(conn, 'UPDATE portal_message_threads SET unread_family=unread_family+1, updated_at=NOW() WHERE id=%s', (tid,))
    else:
        execute(conn, 'UPDATE portal_message_threads SET unread_admin=unread_admin+1, updated_at=NOW() WHERE id=%s', (tid,))
    conn.commit()
    s = get_email_settings()
    if is_admin:
        try:
            recipients = _family_notification_emails(conn, thread.get('family_id'))
            if not recipients and thread.get('family_passphrase'):
                # Legacy fallback for threads created before this fix, where
                # family_id never resolved — the raw passphrase string is
                # still the best link back to who this is from.
                fam = fetchone(conn, 'SELECT email FROM families WHERE passphrase=%s', (thread['family_passphrase'],))
                if fam and fam.get('email'): recipients = [fam['email']]
            if recipients:
                html = f'<div style="font-family:-apple-system,sans-serif;max-width:600px"><h2 style="color:#145466">New reply: {_h(thread["subject"] or "")}</h2><div style="background:#f5f9fa;padding:14px 14px 2px;border-radius:8px;margin:12px 0">{message_text_html(body)}</div><p><a href="https://rolecall.hwtco.org/portal.html" style="background:#145466;color:#fff;padding:10px 20px;border-radius:8px;text-decoration:none;font-weight:700">View in Portal</a></p></div>'
                send_email(recipients, f'Re: {thread["subject"]}', build_hwtc_email_html(f'Re: {thread["subject"]}', html))
            else:
                app.logger.warning(f'portal_reply_thread {tid}: no family email found to notify (family_id={thread.get("family_id")})')
        except Exception as e:
            app.logger.warning(f'portal reply family-notify failed: {e}')
    elif is_family:
        recipients = list(get_recipient_emails(s))
        try:
            staff = fetchall(conn, """SELECT email FROM users WHERE email IS NOT NULL AND email!='' AND active=TRUE
                AND (role='admin' OR role_permissions::text LIKE '%"youth"%')""")
            for u in staff:
                if u['email'] and u['email'] not in recipients: recipients.append(u['email'])
        except Exception as e:
            app.logger.warning(f'portal reply staff lookup failed: {e}')
        if not recipients:
            try:
                admins = fetchall(conn, "SELECT email FROM users WHERE role='admin' AND email IS NOT NULL AND email!=''")
                recipients = [u['email'] for u in admins if u.get('email')]
            except Exception: pass
        # Also notify the program instructor
        try:
            if thread.get('program_id'):
                prog_row = fetchone(conn, 'SELECT instructor_id FROM youth_programs WHERE id=%s', (thread['program_id'],))
                if prog_row and prog_row.get('instructor_id'):
                    vol = fetchone(conn, 'SELECT email FROM volunteers WHERE id=%s', (prog_row['instructor_id'],))
                    if vol and vol.get('email') and vol['email'] not in recipients:
                        recipients.append(vol['email'])
        except Exception: pass
        if recipients:
            html = f'<div style="font-family:-apple-system,sans-serif;max-width:600px"><h2 style="color:#145466">Family replied: {_h(thread["subject"] or "")}</h2><div style="background:#f5f9fa;padding:14px 14px 2px;border-radius:8px;margin:12px 0">{message_text_html(body)}</div></div>'
            send_email(recipients, f'Portal Reply: {thread["subject"]}', build_hwtc_email_html(f'Portal Reply: {thread["subject"]}', html))
    conn.close()
    return jsonify({'ok': True})


@app.route('/api/portal/messages/unread-summary')
def portal_unread_summary():
    err = require_auth()
    if err: return err
    conn = get_db()
    program_total = (fetchone(conn, "SELECT COALESCE(SUM(unread_admin),0) AS t FROM portal_message_threads WHERE unread_admin>0 AND program_id IS NOT NULL") or {}).get('t', 0)
    # Youth productions (Rising Stars + Teen Show) live in the same
    # `productions` table as mainstage ones (distinguished by stage), but
    # they're managed on a separate "Youth Productions" nav item — so
    # their unread counts need to be split out here too, the same way
    # program vs production already are.
    mainstage_total = (fetchone(conn, """SELECT COALESCE(SUM(t.unread_admin),0) AS c
        FROM portal_message_threads t JOIN productions p ON p.id=t.production_id
        WHERE t.unread_admin>0 AND p.stage NOT IN ('rising_stars','teen_show')""") or {}).get('c', 0)
    rising_stars_total = (fetchone(conn, """SELECT COALESCE(SUM(t.unread_admin),0) AS c
        FROM portal_message_threads t JOIN productions p ON p.id=t.production_id
        WHERE t.unread_admin>0 AND p.stage IN ('rising_stars','teen_show')""") or {}).get('c', 0)
    by_program = fetchall(conn, """
        SELECT program_id, COALESCE(SUM(unread_admin),0) AS unread
        FROM portal_message_threads
        WHERE unread_admin>0 AND program_id IS NOT NULL
        GROUP BY program_id""")
    by_production = fetchall(conn, """
        SELECT production_id, COALESCE(SUM(unread_admin),0) AS unread
        FROM portal_message_threads
        WHERE unread_admin>0 AND production_id IS NOT NULL
        GROUP BY production_id""")
    conn.close()
    # 'total'/'production_total' kept for backward compatibility (any old
    # caller expecting the old combined shape) — mainstage_total/
    # rising_stars_total are the correct split for badging each nav item.
    return jsonify({
        'total': int(program_total) + int(mainstage_total) + int(rising_stars_total),
        'program_total': int(program_total),
        'production_total': int(mainstage_total) + int(rising_stars_total),
        'mainstage_total': int(mainstage_total),
        'rising_stars_total': int(rising_stars_total),
        'by_program': {r['program_id']: int(r['unread']) for r in (by_program or [])},
        'by_production': {r['production_id']: int(r['unread']) for r in (by_production or [])},
    })


@app.route('/api/portal/messages/threads')
def portal_list_threads():
    err = require_auth()
    if err: return err
    program_id    = request.args.get('program_id')
    production_id = request.args.get('production_id')
    conn = get_db()
    where, vals = [], []
    if program_id:    where.append('t.program_id=%s');    vals.append(program_id)
    if production_id: where.append('t.production_id=%s'); vals.append(production_id)
    clause = ('WHERE ' + ' AND '.join(where)) if where else ''
    threads = fetchall(conn, f"""
        SELECT t.*,
            (SELECT COUNT(*) FROM portal_messages WHERE thread_id=t.id) as message_count,
            (SELECT body FROM portal_messages WHERE thread_id=t.id ORDER BY sent_at DESC LIMIT 1) as last_body,
            (SELECT sent_at FROM portal_messages WHERE thread_id=t.id ORDER BY sent_at DESC LIMIT 1) as last_at,
            (SELECT sender_name FROM portal_messages WHERE thread_id=t.id ORDER BY sent_at ASC LIMIT 1) as from_name,
            yp.name as program_name, p.name as production_name
        FROM portal_message_threads t
        LEFT JOIN youth_programs yp ON yp.id=t.program_id
        LEFT JOIN productions p ON p.id=t.production_id
        {clause}
        ORDER BY t.updated_at DESC""", vals)
    conn.close()
    return jsonify(threads)


@app.route('/api/portal/messages/thread/<tid>/close', methods=['POST'])
def portal_close_thread(tid):
    err = require_auth()
    if err: return err
    conn = get_db()
    execute(conn, "UPDATE portal_message_threads SET status='closed' WHERE id=%s", (tid,))
    conn.commit(); conn.close()
    return jsonify({'ok': True})


@app.route('/api/portal/messages/family')
def portal_family_threads():
    passphrase = request.args.get('passphrase','').strip()
    if not passphrase: return jsonify([])
    conn = get_db()
    family_id = _resolve_family_id_from_passphrase(conn, passphrase)
    threads = fetchall(conn, """
        SELECT t.*,
            (SELECT COUNT(*) FROM portal_messages WHERE thread_id=t.id) as message_count,
            (SELECT body FROM portal_messages WHERE thread_id=t.id ORDER BY sent_at DESC LIMIT 1) as last_body,
            (SELECT sent_at FROM portal_messages WHERE thread_id=t.id ORDER BY sent_at DESC LIMIT 1) as last_at,
            yp.name as program_name, p.name as production_name
        FROM portal_message_threads t
        LEFT JOIN youth_programs yp ON yp.id=t.program_id
        LEFT JOIN productions p ON p.id=t.production_id
        WHERE (%s IS NOT NULL AND t.family_id=%s) OR t.family_passphrase=%s
        ORDER BY t.updated_at DESC""", (family_id, family_id, passphrase))
    conn.close()
    return jsonify(threads)



