    """Delete many slots at once instead of one at a time — mainly for
    clearing out a batch generated with the wrong settings."""
    err = require_auth()
    if err: return err
    d = request.json or {}
    slot_ids = d.get('slot_ids') or []
    if not slot_ids:
        return jsonify({'error': 'No slots selected'}), 400
    conn = get_db()
