def find_discount_code(conn, code, scope_column, scope_id):
    """Look up a discount code — first scoped to this specific program/production,
    then fall back to cart-wide codes (managed from Marquee) which work across any
    program, class, or Rising Stars show. Returns (dc_dict, table_name) or (None, None).
    table_name is 'discount_codes' or 'cart_discount_codes', used for the uses+=1 update."""
    dc = fetchone(conn, f'SELECT * FROM discount_codes WHERE {scope_column}=%s AND code=%s AND active=TRUE', (scope_id, code))
    if dc:
        return dc, 'discount_codes'
    dc = fetchone(conn, 'SELECT * FROM cart_discount_codes WHERE code=%s AND active=TRUE', (code,))
    if dc and not benefit_cart_code_usable(conn, dc, scope_column):
        return None, None
    if dc:
        return dc, 'cart_discount_codes'
    return None, None


def benefit_cart_code_usable(conn, dc, scope_column='program_id'):
    """Donor class codes only work on classes (not show enrollment) and only
    while the donor is inside their benefit window."""
    if (dc.get('applies_to') or 'all') == 'programs' and scope_column != 'program_id':
        return False
    if dc.get('benefit_code_id'):
        bc = fetchone(conn, 'SELECT * FROM benefit_codes WHERE id=%s', (dc['benefit_code_id'],))
        if not bc or bc.get('status') != 'active':
            return False
        donor = fetchone(conn, 'SELECT * FROM donors WHERE id=%s', (bc['donor_id'],))
        if not donor or not donor_benefit_window(donor, donor_benefit_settings(conn))[2]:
            return False
    return True


def capped_participants(dc, count):
    cap = dc.get('max_participants')
    return min(count, int(cap)) if cap else count


def mark_benefit_cart_code_used(conn, dc, context=''):
    """A donor class code was just applied to a registration: log it."""
    if not dc or not dc.get('benefit_code_id'):
        return
    bc = fetchone(conn, 'SELECT * FROM benefit_codes WHERE id=%s', (dc['benefit_code_id'],))
    if not bc:
        return
    execute(conn, '''INSERT INTO benefit_code_redemptions (id, code_id, registration_id, discount_cents)
        VALUES (%s,%s,NULL,0)''', (str(uuid.uuid4()), bc['id']))
    execute(conn, '''INSERT INTO donor_benefit_usage (id, donor_id, benefit_id, notes, recorded_by, quantity)
        VALUES (%s,%s,%s,%s,%s,1)''', (str(uuid.uuid4()), bc['donor_id'], bc['benefit_id'],
        'Code ' + bc['code'] + (' · ' + context if context else ''), 'Class registration'))


@app.route('/api/public/program/<slug>/validate-discount', methods=['POST'])
def validate_discount(slug):
    d = request.json or {}
    code = (d.get('code') or '').strip().upper()
    if not code:
        return jsonify({'valid': False, 'error': 'Code required'})
    conn = get_db()
    prog = fetchone(conn, 'SELECT * FROM youth_programs WHERE slug=%s OR id=%s', (slug, slug))
    if not prog or program_hidden_from_request(prog):
        conn.close()
        return jsonify({'valid': False, 'error': 'Program not found'})
    dc, dc_table = find_discount_code(conn, code, 'program_id', prog['id'])
    conn.close()
    if not dc:
        return jsonify({'valid': False, 'error': 'Invalid or expired code'})
    if dc.get('max_uses') and (dc.get('uses') or 0) >= dc['max_uses']:
        return jsonify({'valid': False, 'error': 'This code has reached its maximum uses'})
    price = prog.get('price') or 0
    num_regs = int(d.get('num_registrations') or 1)
    basket = price * num_regs
    min_spend = dc.get('min_spend') or 0
    if min_spend > 0 and basket < min_spend:
        return jsonify({'valid': False, 'error': f'This code requires a minimum spend of ${min_spend/100:.2f}'})
    is_sib = bool(dc.get('is_sibling_discount'))
    if is_sib:
        if num_regs < 2:
            return jsonify({'valid': False, 'error': 'Sibling discount requires 2+ participants'})
        per_child = int(price * dc['discount_value'] / 100) if dc['discount_type'] == 'percent' else min(dc['discount_value'], price)
        discount_amount = per_child * (num_regs - 1)
        label = f'Sibling discount: {dc["discount_value"]}{"%" if dc["discount_type"]=="percent" else "¢"} off each additional participant'
    else:
        if dc['discount_type'] == 'percent':
            discount_amount = int(price * capped_participants(dc, num_regs) * dc['discount_value'] / 100)
            label = f'{dc["discount_value"]}% off' + (f' (up to {dc["max_participants"]} people)' if dc.get('max_participants') else '')
        else:
            discount_amount = min(dc['discount_value'] * num_regs, basket)
            label = f'${dc["discount_value"]/100:.2f} off'
    if min_spend:
        label += f' (min. ${min_spend/100:.2f})'
    final_price = max(0, basket - discount_amount)
    return jsonify({'valid': True, 'discount_amount': discount_amount,
                    'final_price': final_price, 'is_sibling': is_sib,
                    'label': label, 'square_discount_id': dc.get('square_discount_id')})


def square_create_discount(name, discount_type, value):
    import uuid as _u
    if not SQUARE_ACCESS_TOKEN:
        return None
    payload = {'idempotency_key': _u.uuid4().hex, 'object': {
        'type': 'DISCOUNT', 'id': '#discount_' + _u.uuid4().hex[:12],
        'discount_data': {'name': name, 'discount_type': 'FIXED_AMOUNT' if discount_type == 'fixed' else 'FIXED_PERCENTAGE'}}}
    if discount_type == 'fixed':
        payload['object']['discount_data']['amount_money'] = {'amount': value, 'currency': 'USD'}
    else:
        payload['object']['discount_data']['percentage'] = str(value)
    try:
        r = requests.post(f'{SQUARE_API_BASE}/v2/catalog/object', json=payload, headers=square_headers(), timeout=10)
        data = r.json()
        return data.get('catalog_object', {}).get('id')
    except Exception:
        return None


