@app.route('/api/youth/<yid>/history', methods=['GET'])
def get_youth_history(yid):
    err = require_auth()
    if err: return err
    conn = get_db()
    timeline = []
    # 1. Added to RoleCall
    try:
        yp = fetchone(conn, 'SELECT created_at, first_name, last_name FROM youth_participants WHERE id=%s', (yid,))
        if yp and yp.get('created_at'):
            timeline.append({'type':'joined','icon':'','label':'Added to RoleCall',
                'detail':f'{yp["first_name"]} {yp["last_name"]} profile created',
                'ts':str(yp['created_at'])})
    except Exception as e: app.logger.warning(f'history joined: {e}')
    # 2. Program enrollments
    try:
        regs = fetchall(conn, '''SELECT pr.created_at, pr.status, pr.child_first_name, pr.child_last_name,
            yp.name as program_name FROM program_registrations pr
            JOIN youth_programs yp ON yp.id=pr.program_id
            WHERE pr.youth_id=%s ORDER BY pr.created_at DESC''', (yid,)) or []
        for r in regs:
            sl = {'confirmed':'Enrolled','pending_payment':'Pending Payment','waitlisted':'Waitlisted','cancelled':'Cancelled'}.get(r.get('status',''),'Registered')
            timeline.append({'type':'program','icon':'','label':f'Program: {r.get("program_name","")}',
                'detail':sl,'ts':str(r.get('created_at') or '')})
    except Exception as e: app.logger.warning(f'history programs: {e}')
    # 3. Events attended
    try:
        signins = fetchall(conn, '''SELECT ys.signed_in_at, ys.signed_out_at, ys.signed_in_by,
            e.name as event_name FROM youth_sign_ins ys
            LEFT JOIN events e ON ys.event_id=e.id
            WHERE ys.youth_id=%s AND ys.event_id IS NOT NULL
            ORDER BY ys.signed_in_at DESC''', (yid,)) or []
        for s in signins:
            detail = f'Dropped off by {s["signed_in_by"]}' if s.get('signed_in_by') else 'Attended'
            if s.get('signed_out_at') and s.get('signed_in_at'):
                try:
                    diff = int((s['signed_out_at'] - s['signed_in_at']).total_seconds() // 60)
                    hrs = diff // 60; mins = diff % 60
                    detail += f' · {hrs}h {mins}m' if hrs else f' · {mins}m'
                except Exception: pass
            timeline.append({'type':'event','icon':'','label':f'Attended: {s.get("event_name","Event")}',
                'detail':detail,'ts':str(s.get('signed_in_at') or '')})
    except Exception as e: app.logger.warning(f'history events: {e}')
    # 4. Waivers
    try:
        waivers = fetchall(conn, '''SELECT yw.created_at, yw.signed_date, yw.signed_by, wt.name as waiver_name
            FROM youth_waivers yw JOIN waiver_types wt ON wt.id=yw.waiver_type_id
            WHERE yw.youth_id=%s ORDER BY yw.created_at DESC''', (yid,)) or []
        for w in waivers:
            detail = f'Signed {w.get("signed_date","")}' + (f' by {w["signed_by"]}' if w.get('signed_by') else '')
            timeline.append({'type':'waiver','icon':'','label':f'Waiver: {w.get("waiver_name","")}',
                'detail':detail,'ts':str(w.get('created_at') or w.get('signed_date') or '')})
    except Exception as e: app.logger.warning(f'history waivers: {e}')
    # 5. Notes
    try:
        notes = fetchall(conn, 'SELECT * FROM youth_notes WHERE youth_id=%s ORDER BY created_at DESC', (yid,)) or []
        for n in notes:
            c = (n.get('content') or '')
            timeline.append({'type':'note','icon':'','label':'Note Added',
                'detail':c[:80]+('…' if len(c)>80 else '') + (f' — {n["author"]}' if n.get('author') else ''),
                'ts':str(n.get('created_at') or '')})
    except Exception as e: app.logger.warning(f'history notes: {e}')
    # 6. Incidents
    try:
        incidents = fetchall(conn, 'SELECT * FROM youth_incidents WHERE youth_id=%s ORDER BY created_at DESC', (yid,)) or []
        for i in incidents:
            timeline.append({'type':'incident','icon':'','label':f'Incident: {i.get("title","")}',
                'detail':(i.get('description') or '')[:80],
                'ts':str(i.get('incident_date') or i.get('created_at') or '')})
    except Exception as e: app.logger.warning(f'history incidents: {e}')
    timeline.sort(key=lambda x: x.get('ts','') or '', reverse=True)
    conn.close()
    return jsonify(timeline)

@app.route('/api/youth/<yid>/waivers', methods=['POST'])
def add_youth_waiver(yid):
    err = require_permission('youth')
    if err: return err
    waiver_type_id = request.form.get('waiver_type_id')
    signed_date    = request.form.get('signed_date')
    expiry_date    = request.form.get('expiry_date') or None
    signed_by      = request.form.get('signed_by') or None
    if not waiver_type_id or not signed_date:
        return jsonify({'error': 'Waiver type and signed date are required'}), 400
    filename = original_name = None
    if 'file' in request.files:
        f = request.files['file']
        if f and f.filename:
            ext = os.path.splitext(secure_filename(f.filename))[1].lower()
            filename = str(uuid.uuid4()) + ext
            original_name = f.filename
            f.save(os.path.join(UPLOAD_FOLDER, filename))
    wid = str(uuid.uuid4())
    conn = get_db()
    execute(conn, 'INSERT INTO youth_waivers (id,youth_id,waiver_type_id,signed_date,expiry_date,signed_by,filename,original_name) VALUES (%s,%s,%s,%s,%s,%s,%s,%s)',
            (wid, yid, waiver_type_id, signed_date, expiry_date, signed_by, filename, original_name))
    conn.commit()
    row = fetchone(conn,
        'SELECT yw.*, wt.name as type_name FROM youth_waivers yw JOIN waiver_types wt ON yw.waiver_type_id=wt.id WHERE yw.id=%s', (wid,))
    conn.close()
    return jsonify(row)

# ─────────────────────────────────────────────
#  DASHBOARD
# ─────────────────────────────────────────────

@app.route('/api/dashboard')
def dashboard():
    err = require_auth()
    if err: return err
    conn = get_db()
    total_vols  = fetchone(conn, 'SELECT COUNT(*) as c FROM volunteers')['c']
    total_hours = fetchone(conn, "SELECT COALESCE(SUM(hours),0) as s FROM hours WHERE COALESCE(pay_type,'volunteer')='volunteer'")['s']
    total_youth = fetchone(conn, "SELECT COUNT(*) as c FROM youth_participants WHERE status='active'")['c']
    today = date.today()
    all_waivers = fetchall(conn,
        'SELECT vw.volunteer_id, vw.expiry_date, v.name FROM volunteer_waivers vw JOIN volunteers v ON vw.volunteer_id=v.id')
    vol_worst = {}; vol_names = {}
    for w in all_waivers:
        vid = w['volunteer_id']; vol_names[vid] = w['name']
        if not w['expiry_date']:
            if vid not in vol_worst: vol_worst[vid] = 'valid'
            continue
        diff = (datetime.strptime(w['expiry_date'], '%Y-%m-%d').date() - today).days
        prev = vol_worst.get(vid, 'none')
        if diff < 0: vol_worst[vid] = 'expired'
        elif diff < 30 and prev != 'expired': vol_worst[vid] = 'expiring'
        elif prev == 'none': vol_worst[vid] = 'valid'
    expiring = sum(1 for s in vol_worst.values() if s == 'expiring')
    expired  = sum(1 for s in vol_worst.values() if s == 'expired')
    alerts = []
    for vid, status in vol_worst.items():
        if status == 'expiring': alerts.append({'type':'warning','name':vol_names[vid],'msg':'waiver expiring soon','id':vid})
        if status == 'expired':  alerts.append({'type':'danger', 'name':vol_names[vid],'msg':'waiver has expired','id':vid})
    monthly = []
    for i in range(5, -1, -1):
        m = today.month - i; y = today.year + (m - 1) // 12; m = ((m - 1) % 12) + 1
        label = datetime(y, m, 1).strftime('%b')
        total = fetchone(conn,
            "SELECT COALESCE(SUM(hours),0) as s FROM hours WHERE TO_CHAR(TO_DATE(date,'YYYY-MM-DD'),'YYYY-MM')=%s AND COALESCE(pay_type,'volunteer')='volunteer'",
            (f'{y:04d}-{m:02d}',))['s']
        monthly.append({'label': label, 'total': float(total)})
    top = fetchall(conn, '''
        SELECT v.id, v.name,
               COALESCE(SUM(CASE WHEN COALESCE(h.pay_type,'volunteer')='volunteer' THEN h.hours END),0) as total_hours,
               COUNT(DISTINCT CASE WHEN COALESCE(h.pay_type,'volunteer')='volunteer' THEN h.event END) as total_events
        FROM volunteers v LEFT JOIN hours h ON v.id=h.volunteer_id
        GROUP BY v.id, v.name ORDER BY total_hours DESC LIMIT 5
    ''')
    conn.close()
    return jsonify({'total_volunteers': total_vols, 'total_hours': float(total_hours), 'total_youth': total_youth,
                    'expiring_waivers': expiring, 'expired_waivers': expired,
                    'alerts': alerts, 'monthly_hours': monthly, 'top_volunteers': top})

