@app.route('/api/productions')
def get_productions():
    err = require_auth()
    if err: return err
    conn = get_db()
    prods = fetchall(conn, """SELECT p.*, COALESCE(p.stage,'mainstage') as stage,
        v.name as default_elic_name,
        (SELECT COUNT(*) FROM program_registrations WHERE production_id=p.id AND status NOT IN ('cancelled','waitlisted')) AS reg_enrolled,
        (SELECT COUNT(*) FROM program_registrations WHERE production_id=p.id AND status='waitlisted') AS reg_waitlisted
        FROM productions p
        LEFT JOIN elics el ON p.default_elic_id=el.id
        LEFT JOIN volunteers v ON el.volunteer_id=v.id
        ORDER BY p.start_date DESC NULLS LAST""")
    visible = productions_visible_to_user(conn)
    if visible is not None:
        grants = production_grants_for_user(conn, session['user_id'])
        prods = [p for p in prods if p['id'] in visible]
        for p in prods:
            p['my_access'] = grants.get(p['id'], 'edit')
    for p in prods:
        p['members'] = fetchall(conn, '''
            SELECT pm.*, v.name as volunteer_name, v.email as volunteer_email, v.phone as volunteer_phone
            FROM production_members pm
            JOIN volunteers v ON pm.volunteer_id=v.id
            WHERE pm.production_id=%s ORDER BY pm.role''', (p['id'],))
        p['required_waivers'] = fetchall(conn,
            '''SELECT prw.*, wt.name as waiver_name, wt.can_sign_online, wt.min_age, wt.max_age
               FROM production_required_waivers prw JOIN waiver_types wt ON prw.waiver_type_id=wt.id
               WHERE prw.production_id=%s ORDER BY wt.name''', (p['id'],))
        try:
            p['callout_alert_volunteer_ids'] = json.loads(p.get('callout_alert_volunteer_ids') or '[]')
        except Exception:
            p['callout_alert_volunteer_ids'] = []
    conn.close()
    return jsonify(prods)

@app.route('/api/productions', methods=['POST'])
def create_production():
    err = require_permission('productions')
    if err: return err
    d = request.json or {}
    pid = str(uuid.uuid4())
    conn = get_db()
    execute(conn, 'INSERT INTO productions (id,name,production_type,stage,start_date,end_date,description,status,default_elic_id) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s)',
            (pid, d.get('name',''), d.get('production_type','show'), d.get('stage','mainstage'),
             d.get('start_date') or None, d.get('end_date') or None,
             d.get('description',''), d.get('status','upcoming'),
             d.get('default_elic_id') or None))
    if d.get('image_url') or d.get('ticket_logo_url'):
        # The INSERT above never took the photo — a poster chosen while
        # creating a production used to be silently dropped.
        execute(conn, 'UPDATE productions SET image_url=%s, ticket_logo_url=%s WHERE id=%s',
                (d.get('image_url') or None, d.get('ticket_logo_url') or None, pid))
    lic_id = d.get('from_licensing_request_id')
    if lic_id:
        lr = fetchone(conn, "SELECT id FROM licensing_requests WHERE id=%s AND approved_to_produce=TRUE AND (production_id IS NULL OR production_id='')", (lic_id,))
        if lr:
            execute(conn, 'UPDATE licensing_requests SET production_id=%s, updated_at=NOW() WHERE id=%s', (pid, lic_id))
    conn.commit()
    prod = fetchone(conn, '''SELECT p.*, COALESCE(p.stage,'mainstage') as stage, v.name as default_elic_name FROM productions p LEFT JOIN elics el ON p.default_elic_id=el.id LEFT JOIN volunteers v ON el.volunteer_id=v.id WHERE p.id=%s''', (pid,))
    prod['members'] = []
    conn.close()
    return jsonify(prod)

