@app.route('/api/kiosk/toggle-trust-mode', methods=['POST'])
def kiosk_toggle_trust_mode():
    """Re-verifies the PIN live (not just trusting whatever ELIC is already
    logged into the kiosk session) so flipping Trust Mode always requires
    someone to actually punch in a PIN at that moment — and only if that
    PIN belongs to a master ELIC or one specifically flagged
    can_toggle_trust_mode. Scoped to one event; does not affect any other
    event running trust mode independently."""
    d = request.json or {}
    pin = (d.get('pin') or '').strip()
    event_id = d.get('event_id')
    if not event_id:
        return jsonify({'error': 'Missing event_id'}), 400
    conn = get_db()
    elic = fetchone(conn, '''SELECT e.*, v.name as volunteer_name
        FROM elics e LEFT JOIN volunteers v ON e.volunteer_id=v.id
        WHERE e.pin=%s AND e.active=TRUE''', (pin,))
    if not elic:
        conn.close(); return jsonify({'error': 'Invalid PIN'}), 401
    if not elic.get('is_master') and not elic.get('can_toggle_trust_mode'):
        conn.close(); return jsonify({'error': 'This PIN is not authorized to toggle Trust Mode'}), 403
    evt = fetchone(conn, 'SELECT trust_mode FROM events WHERE id=%s', (event_id,))
    if not evt:
        conn.close(); return jsonify({'error': 'Event not found'}), 404
    new_state = not evt.get('trust_mode')
    execute(conn, 'UPDATE events SET trust_mode=%s WHERE id=%s', (new_state, event_id))
    conn.commit()
    conn.close()
    return jsonify({'ok': True, 'trust_mode': new_state, 'elic_name': elic.get('volunteer_name', 'ELIC')})

@app.route('/api/kiosk/elic-auth', methods=['POST'])
@app.route('/api/kiosk/elic-login', methods=['POST'])
def kiosk_elic_auth():
    d = request.json or {}
    pin = d.get('pin','')
    conn = get_db()
    elic = fetchone(conn, '''SELECT e.*, v.name as volunteer_name
        FROM elics e LEFT JOIN volunteers v ON e.volunteer_id=v.id
        WHERE e.pin=%s''', (pin,))
    if not elic:
        conn.close(); return jsonify({'error': 'Invalid PIN'}), 401
    # Get assigned events  -  check both assigned_events field AND event_elics table
    assigned = json.loads(elic.get('assigned_events') or '[]')
    # Also get events assigned via the event detail page (event_elics table)
    event_elics_rows = fetchall(conn, 'SELECT event_id FROM event_elics WHERE elic_id=%s', (elic['id'],))
    for row in event_elics_rows:
        if row['event_id'] not in assigned:
            assigned.append(row['event_id'])
    if elic.get('is_master'):
        events = fetchall(conn, '''
            SELECT e.*, p.name as production_name,
                   COALESCE(p.stage,'mainstage') as stage,
                   p.stage as production_stage,
                   pg.name as program_name,
                   pg.requires_guardian as requires_guardian,
                   el.action as current_status
            FROM events e
            LEFT JOIN productions p ON e.production_id=p.id
            LEFT JOIN youth_programs pg ON e.program_id=pg.id
            LEFT JOIN (SELECT event_id, action FROM event_logs
                WHERE id IN (SELECT id FROM event_logs WHERE (event_id, timestamp) IN (SELECT event_id, MAX(timestamp) FROM event_logs GROUP BY event_id))) el
                ON el.event_id=e.id
            WHERE (
                -- Currently open events (regardless of date)
                el.action = 'open'
                OR
                -- Upcoming and recent events (14 days past to 180 days future)
                (e.event_date::date >= CURRENT_DATE - INTERVAL '14 days'
                 AND e.event_date::date <= CURRENT_DATE + INTERVAL '180 days'
                 AND (el.action IS NULL OR el.action != 'close'))
                OR
                -- Events with no date that aren't closed
                (e.event_date IS NULL AND (el.action IS NULL OR el.action != 'close'))
            )
            ORDER BY e.event_date ASC NULLS LAST, e.name''')
    else:
        if assigned:
            placeholders = ','.join(['%s']*len(assigned))
            events = fetchall(conn, f'''
                SELECT e.*, p.name as production_name,
                       COALESCE(p.stage,'mainstage') as stage,
                       p.stage as production_stage,
                       pg.name as program_name,
                       pg.requires_guardian as requires_guardian,
                       el.action as current_status
                FROM events e
                LEFT JOIN productions p ON e.production_id=p.id
                LEFT JOIN youth_programs pg ON e.program_id=pg.id
                LEFT JOIN (SELECT event_id, action FROM event_logs
                    WHERE id IN (SELECT id FROM event_logs WHERE (event_id, timestamp) IN (SELECT event_id, MAX(timestamp) FROM event_logs GROUP BY event_id))) el
                    ON el.event_id=e.id
                WHERE e.id IN ({placeholders})
                AND (
                    el.action = 'open'
                    OR (e.event_date::date >= CURRENT_DATE - INTERVAL '14 days'
                        AND (el.action IS NULL OR el.action != 'close'))
                    OR (e.event_date IS NULL AND (el.action IS NULL OR el.action != 'close'))
                )
                ORDER BY e.event_date ASC NULLS LAST, e.name''', tuple(assigned))
        else:
            events = []
    conn.close()
    return jsonify({'ok': True, 'elic': elic, 'events': events})

def _is_paid_instructor(vid):
    c = get_db()
    try:
        return bool(fetchone(c, 'SELECT 1 AS x FROM paid_instructors WHERE volunteer_id=%s', (vid,)))
    finally:
        c.close()


# ── Instructor day checklist (once per day, not per lesson) ───────────────
# A paid instructor teaching on their own (no ELIC has the building open)
# does a short opening checklist the first time they check in for the day,
# and a closing checklist once when they're done for the day — not for
# every lesson. Items are editable in Settings → Paid instructors.
INSTRUCTOR_DAY_DEFAULTS = {
    'open': ['Front door unlocked (Inox app, Passage Mode on)', 'Lights on', 'Thermostat set to 72–74°F'],
    'close': ['All students picked up', 'Lights off', 'Thermostat set back', 'Passage Mode off and front door locked (check it from outside)'],
}


def _instructor_day_items(conn):
    try:
        v = json.loads(_setting(conn, 'instructor_day_checklist') or '{}')
    except Exception:
        v = {}
    return {'open': v.get('open') or INSTRUCTOR_DAY_DEFAULTS['open'], 'close': v.get('close') or INSTRUCTOR_DAY_DEFAULTS['close']}


def _building_opened_by_elic_today(conn):
    """An ELIC has an event open right now (opened today, not closed)."""
    return bool(fetchone(conn, """SELECT 1 AS x FROM event_logs l JOIN events e ON e.id=l.event_id
        WHERE l.action='open' AND l.elic_id IS NOT NULL
          AND (l.timestamp AT TIME ZONE 'America/New_York')::date = (CURRENT_TIMESTAMP AT TIME ZONE 'America/New_York')::date
          AND NOT EXISTS (SELECT 1 FROM event_logs c WHERE c.event_id=l.event_id AND c.action='close' AND c.timestamp > l.timestamp)
        LIMIT 1"""))


@app.route('/api/kiosk/instructor-day', methods=['GET'])
def kiosk_instructor_day():
    vid = request.args.get('volunteer_id')
    if not vid or not _is_paid_instructor(vid):
        return jsonify({'error': 'Not a paid instructor'}), 400
    conn = get_db()
    try:
        day = today_eastern().isoformat()
        row = fetchone(conn, 'SELECT * FROM instructor_day_logs WHERE volunteer_id=%s AND day=%s', (vid, day))
        items = _instructor_day_items(conn)
        elic_open = _building_opened_by_elic_today(conn)
        return jsonify({'opened': bool(row and row.get('opened_at')), 'closed': bool(row and row.get('closed_at')),
                        'needs_open': not (row and row.get('opened_at')) and not elic_open, 'elic_has_building': elic_open,
                        'open_items': items['open'], 'close_items': items['close']})
    finally:
        conn.close()


@app.route('/api/kiosk/instructor-day/<which>', methods=['POST'])
def kiosk_instructor_day_submit(which):
    if which not in ('open', 'close'):
        return jsonify({'error': 'Unknown'}), 404
    d = request.json or {}
    vid = d.get('volunteer_id')
    if not vid or not _is_paid_instructor(vid):
        return jsonify({'error': 'Not a paid instructor'}), 400
    responses = d.get('responses') or []
    conn = get_db()
    try:
        day = today_eastern().isoformat()
        row = fetchone(conn, 'SELECT id FROM instructor_day_logs WHERE volunteer_id=%s AND day=%s', (vid, day))
        if not row:
            execute(conn, 'INSERT INTO instructor_day_logs (id, volunteer_id, day) VALUES (%s,%s,%s)', (str(uuid.uuid4()), vid, day))
        col = 'opened_at' if which == 'open' else 'closed_at'
        rcol = 'open_responses' if which == 'open' else 'close_responses'
        execute(conn, f'UPDATE instructor_day_logs SET {col}=NOW(), {rcol}=%s WHERE volunteer_id=%s AND day=%s',
                (json.dumps(responses)[:5000], vid, day))
        conn.commit()
        return jsonify({'ok': True})
    finally:
        conn.close()


@app.route('/api/instructor-day-logs', methods=['GET', 'PUT'])
def instructor_day_logs_admin():
    """Staff: recent instructor open/close days, and (PUT) the checklist items."""
    err = require_auth()
    if err: return err
    conn = get_db()
    try:
        if request.method == 'PUT':
            e2 = require_admin()
            if e2: return e2
            d = request.json or {}
            clean = lambda xs: [str(x).strip()[:200] for x in (xs or []) if str(x).strip()][:15]
            _set_setting(conn, 'instructor_day_checklist', json.dumps({'open': clean(d.get('open')), 'close': clean(d.get('close'))}))
            conn.commit()
        rows = fetchall(conn, '''SELECT l.*, v.name FROM instructor_day_logs l JOIN volunteers v ON v.id=l.volunteer_id
            ORDER BY l.day DESC, v.name LIMIT 60''') or []
        for r in rows:
            for k in ('opened_at', 'closed_at'):
                r[k] = r[k].strftime('%-I:%M %p') if hasattr(r.get(k), 'strftime') else None
            r['day'] = str(r['day'])[:10]
        return jsonify({'items': _instructor_day_items(conn), 'logs': rows})
    finally:
        conn.close()


@app.route('/api/kiosk/paid-instruction-login', methods=['POST'])
def kiosk_paid_instruction_auth():
    """Per-instructor PIN, same pattern as ELIC login: identifies the person
    (so the kiosk can skip volunteer search entirely) and marks whatever they
    log next as paid instruction, regardless of whether the automatic
    instructor/program match in determine_kiosk_pay_type applies."""
    d = request.json or {}
    pin = (d.get('pin') or '').strip()
    conn = get_db()
    row = fetchone(conn, '''SELECT pi.*, v.name as volunteer_name
        FROM paid_instructors pi JOIN volunteers v ON pi.volunteer_id=v.id
        WHERE pi.pin=%s AND pi.active=TRUE''', (pin,))
    conn.close()
    if not row:
        return jsonify({'error': 'Invalid code'}), 401
    return jsonify({'ok': True, 'volunteer': {'id': row['volunteer_id'], 'name': row['volunteer_name']}})

