@app.route('/api/pending-hours/<hid>/approve', methods=['POST'])
def approve_pending_hours(hid):
    err = require_auth()
    if err: return err
    conn = get_db()
    ph = fetchone(conn, 'SELECT * FROM pending_hours WHERE id=%s', (hid,))
    if not ph: conn.close(); return jsonify({'error': 'Not found'}), 404
    if ph.get('event_id') and not (request.json or {}).get('allow_duplicate'):
        have = fetchone(conn, 'SELECT hours FROM hours WHERE volunteer_id=%s AND event_id=%s LIMIT 1', (ph['volunteer_id'], ph['event_id']))
        if have:
            conn.close()
            return jsonify({'error': f'They already have {have["hours"]:g} approved hours for this event. Reject this entry, or edit the existing one if it\'s wrong.',
                            'duplicate': True}), 409
    pid = str(uuid.uuid4())
    try:
        execute(conn, '''INSERT INTO hours (id,volunteer_id,event,event_id,date,hours,role,notes,pay_type,source,logged_by,submitted_at,approved_by,approved_at)
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,NOW())''',
            (pid, ph['volunteer_id'], ph['event'], ph.get('event_id'),
             ph['date'], ph['hours'], ph.get('role',''), ph.get('notes',''), ph.get('pay_type') or 'volunteer',
             ph.get('source'), ph.get('logged_by'), ph.get('submitted_at'), session.get('name') or session.get('email') or 'Staff'))
    except Exception:
        # May already exist  -  just mark as approved
        pass
    execute(conn, "UPDATE pending_hours SET status='approved' WHERE id=%s", (hid,))
    conn.commit(); conn.close()
    return jsonify({'ok': True})

