@app.route('/api/email-settings', methods=['PUT'])
def save_email_settings_route():
    err = require_admin()
    if err: return err
    d = request.json or {}
    conn = get_db()
    # Ensure rental columns exist
    for col in ['rental_approver_emails TEXT DEFAULT \'\'', 'rental_approval_levels TEXT DEFAULT \'[]\'', 'rental_agreement_template TEXT DEFAULT \'\'',
                'rental_signatory_name TEXT DEFAULT \'\'', 'rental_signatory_title TEXT DEFAULT \'\'',
                'twilio_account_sid TEXT DEFAULT \'\'', 'twilio_auth_token TEXT DEFAULT \'\'',
                'twilio_phone TEXT DEFAULT \'\'', 'twilio_fallback_phone TEXT DEFAULT \'\'',
                'twilio_voice_greeting TEXT DEFAULT \'\'',
                'twilio_voice_no_answer TEXT DEFAULT \'\'',
                'twilio_voice_unavailable TEXT DEFAULT \'\'',
                'twilio_after_hours_msg TEXT DEFAULT \'\'',
                'twilio_coverage_start TEXT DEFAULT \'08:00\'',
                'twilio_coverage_end TEXT DEFAULT \'22:00\'',
                'twilio_audio_greeting TEXT DEFAULT \'\'',
                'twilio_audio_no_answer TEXT DEFAULT \'\'',
                'twilio_audio_unavailable TEXT DEFAULT \'\'',
                'twilio_audio_after_hours TEXT DEFAULT \'\'',
                'twilio_voice_voicemail TEXT DEFAULT \'\'',
                'twilio_audio_voicemail TEXT DEFAULT \'\'',
                'slack_call_webhook TEXT DEFAULT \'\'',
                'oncall_report_schedule TEXT DEFAULT \'monday\'',
                'oncall_report_time TEXT DEFAULT \'08:00\'',
                'oncall_report_enabled TEXT DEFAULT \'0\'',
                'slack_bot_token TEXT DEFAULT \'\'',
                'slack_call_channel TEXT DEFAULT \'\'']:
        try:
            execute(conn, f'ALTER TABLE email_settings ADD COLUMN IF NOT EXISTS {col}')
            conn.commit()
        except Exception:
            pass
    # on_call_schedule column migrations
    for col in ["start_time TEXT DEFAULT '08:00'", "end_time TEXT DEFAULT '22:00'",
                "days_of_week TEXT DEFAULT '[0,1,2,3,4,5,6]'", "recurrence TEXT DEFAULT 'once'", "color TEXT DEFAULT ''"]:
        try:
            execute(conn, f'ALTER TABLE on_call_schedule ADD COLUMN IF NOT EXISTS {col}')
            conn.commit()
        except Exception:
            pass
    # event_logs column migrations
    for col in ["signature TEXT DEFAULT ''"]:
        try:
            execute(conn, f'ALTER TABLE event_logs ADD COLUMN IF NOT EXISTS {col}')
            conn.commit()
        except Exception:
            pass
    allowed = ['resend_api_key','from_email','sender_identities','report_recipients','report_recipient_user_ids',
        'alert_pending_hours','alert_profile_updates','alert_callouts','alert_waiver_expiry',
        'alert_conflicts','alert_waivers','alert_event_not_opened','alert_event_not_closed',
        'auto_send_checklist_report','alert_new_rsvp','alert_role_filled',
        'rental_approver_emails','rental_approval_levels','rental_agreement_template',
        'rental_signatory_name','rental_signatory_title',
        'twilio_account_sid','twilio_auth_token','twilio_phone','twilio_fallback_phone',
        'twilio_voice_greeting','twilio_voice_no_answer','twilio_voice_unavailable',
        'twilio_after_hours_msg','twilio_coverage_start','twilio_coverage_end',
        'twilio_audio_greeting','twilio_audio_no_answer','twilio_audio_unavailable','twilio_audio_after_hours',
        'twilio_voice_voicemail','twilio_audio_voicemail',
        'twilio_hold_music_url','twilio_audio_hold_music',
        'slack_call_webhook',
        'oncall_report_schedule','oncall_report_time','oncall_report_enabled',
        'slack_bot_token','slack_call_channel']
    sets = []; vals = []
    for key in allowed:
        if key in d:
            sets.append(f'{key}=%s')
            val = d[key]
            if isinstance(val, list): val = json.dumps(val)
            vals.append(val)
    if sets:
        vals.append(1)
        execute(conn, f"UPDATE email_settings SET {','.join(sets)} WHERE id=%s", vals)
        conn.commit()
    else:
        app.logger.warning(f'save_email_settings: nothing to save. keys in d: {list(d.keys())}')
    conn.close()
    return jsonify({'ok': True})

@app.route('/api/email-templates/<tid>/test', methods=['POST'])
def test_template_email(tid):
    err = require_admin()
    if err: return err
    d = request.json or {}
    conn = get_db()
    tmpl = fetchone(conn, 'SELECT * FROM email_templates WHERE id=%s', (tid,))
    user = fetchone(conn, 'SELECT email, name FROM users WHERE id=%s', (session.get('user_id',''),))
    conn.close()
    if not tmpl: return jsonify({'error': 'Template not found'}), 404
    to = (d.get('to') or '').strip() or (user['email'] if user else '')
    if not to: return jsonify({'error': 'No recipient email  -  add your email to your user profile.'}), 400
    # Replace variables with sample values
    sample = {
        '{{name}}': user['name'] if user else 'Test User',
        '{{email}}': to,
        '{{volunteer_name}}': user['name'] if user else 'Test User',
        '{{event_name}}': 'Sample Event',
        '{{event_date}}': 'June 1, 2025',
        '{{hours}}': '3',
        '{{month}}': 'June',
        '{{year}}': '2025',
        '{{link}}': '#',
        '{{signup_link}}': '#',
        '{{review_link}}': '#',
        '{{temp_password}}': 'TEMP-1234',
        '{{role}}': 'Stage Crew',
        '{{location}}': 'HWTC Theater',
        '{{message}}': 'We would love to have you join us!',
        '{{date}}': 'June 1, 2025',
        '{{elic_name}}': 'Test ELIC',
        '{{volunteer_count}}': '12',
        '{{total_hours}}': '36',
        '{{checklist_html}}': '<p><em>(Checklist items would appear here)</em></p>',
        '{{hours_html}}': '<p><em>(Hours breakdown would appear here)</em></p>',
        '{{participant_name}}': 'Test Participant',
        '{{pickup_name}}': 'Unknown Person',
        '{{timestamp}}': 'June 1, 2025 at 3:00 PM',
        '{{interests}}': 'Acting, Stage Crew',
        '{{employer_program}}': 'Disney Cast Member',
        '{{how_heard}}': 'Social Media',
        '{{notes}}': ' - ',
        '{{phone}}': '555-1234',
    }
    body = tmpl['body']
    subject = '[TEST] ' + tmpl['subject']
    for var, val in sample.items():
        body = body.replace(var, val)
        subject = subject.replace(var, val)
    # Wrap with test banner
    body = f'''<div style="background:#fef9c3;border:2px dashed #f59e0b;border-radius:8px;padding:12px 16px;margin-bottom:16px;font-family:sans-serif;font-size:13px;color:#854d0e">
        <strong> This is a test email</strong>  -  sent to {to}. Sample values have been substituted for real data.
    </div>''' + body
    ok, msg = send_email([to], subject, build_hwtc_email_html(subject, body))
    if ok: return jsonify({'ok': True, 'sent_to': to})
    return jsonify({'error': msg or 'Failed to send'}), 500

