@app.route('/api/admin/backfill-participant-dobs', methods=['POST'])
def backfill_participant_dobs():
    """Recover birthdays that were correctly captured on a registration but never copied
    to the participant's profile — caused by a bug where updating an EXISTING participant
    (a returning family) never touched the dob field, only new-participant creation did.
    Safe to re-run anytime; only fills in participants that currently have no dob on file."""
    err = require_permission('youth')
    if err:
        err = require_permission('rising_stars')
        if err:
            err = require_permission('productions')
            if err: return err
    conn = get_db()
    regs = fetchall(conn, '''SELECT id, youth_id, child_first_name, child_last_name, child_dob, guardian_email
        FROM program_registrations
        WHERE child_dob IS NOT NULL AND child_dob != '' AND status != 'cancelled' ''') or []
    fixed, already_had_dob, no_dob_on_reg, no_match = 0, 0, 0, 0
    for r in regs:
        youth_id = r.get('youth_id')
        yp = None
        if youth_id:
            yp = fetchone(conn, 'SELECT id, dob FROM youth_participants WHERE id=%s', (youth_id,))
        if not yp:
            yp = fetchone(conn, '''SELECT yp.id, yp.dob FROM youth_participants yp
                JOIN youth_guardians yg ON yg.youth_id=yp.id
                WHERE LOWER(yg.email)=LOWER(%s) AND LOWER(yp.first_name)=LOWER(%s) AND LOWER(yp.last_name)=LOWER(%s)''',
                (r.get('guardian_email') or '', r.get('child_first_name') or '', r.get('child_last_name') or ''))
        if not yp:
            no_match += 1
            continue
        if yp.get('dob'):
            already_had_dob += 1
            continue
        execute(conn, 'UPDATE youth_participants SET dob=%s WHERE id=%s', (r['child_dob'], yp['id']))
        fixed += 1
    # Separately count registrations that never had a dob captured at all (a genuine gap,
    # not something this backfill can recover)
    missing = fetchone(conn, '''SELECT COUNT(*) AS c FROM program_registrations
        WHERE (child_dob IS NULL OR child_dob = '') AND status != 'cancelled' ''')
    conn.commit()
    conn.close()
    return jsonify({'ok': True, 'fixed': fixed, 'already_had_dob': already_had_dob,
                    'no_match': no_match, 'registrations_with_no_dob_at_all': (missing or {}).get('c', 0),
                    'total_registrations_checked': len(regs)})


@app.route('/api/productions/<pid>/youth-members/sync-from-registrations', methods=['POST'])
def sync_prod_cast_from_registrations(pid):
    """Catch up youth_production_members from confirmed registrations — for the initial
    backlog, and safe to re-run anytime afterward as a manual sync/safety net."""
    err = require_auth()
    if err: return err
    conn = get_db()
    prod = fetchone(conn, 'SELECT id, stage FROM productions WHERE id=%s', (pid,))
    if not prod:
        conn.close()
        return jsonify({'error': 'Production not found'}), 404
    regs = fetchall(conn, '''SELECT id, youth_id, child_first_name, child_last_name, guardian_email
        FROM program_registrations WHERE production_id=%s AND status='confirmed' ''', (pid,)) or []
    added, already_member, skipped_no_match = 0, 0, 0
    import uuid as _bfu
    for r in regs:
        youth_id = r.get('youth_id')
        if not youth_id:
            yp = fetchone(conn, '''SELECT yp.id FROM youth_participants yp
                JOIN youth_guardians yg ON yg.youth_id=yp.id
                WHERE LOWER(yg.email)=LOWER(%s) AND LOWER(yp.first_name)=LOWER(%s) AND LOWER(yp.last_name)=LOWER(%s)''',
                (r.get('guardian_email') or '', r.get('child_first_name') or '', r.get('child_last_name') or ''))
            youth_id = yp['id'] if yp else None
        if not youth_id:
            skipped_no_match += 1
            continue
        existing = fetchone(conn, 'SELECT id FROM youth_production_members WHERE production_id=%s AND youth_id=%s', (pid, youth_id))
        if existing:
            already_member += 1
            continue
        execute(conn, 'INSERT INTO youth_production_members (id,production_id,youth_id,role) VALUES (%s,%s,%s,%s)',
            (str(_bfu.uuid4()), pid, youth_id, ''))
        added += 1
    conn.commit()
    conn.close()
    return jsonify({'ok': True, 'added': added, 'already_member': already_member,
                    'skipped_no_match': skipped_no_match, 'total_checked': len(regs)})


# ── Cast members not in RoleCall yet ──────────────────────────────────────
# Add people to a production by name only (for example, a cast list from
# auditions before everyone has a RoleCall record). They show with a
# "Not in RoleCall" flag; "Link" connects one to their real record once it
# exists, carrying their role over, and the placeholder goes away.
@app.route('/api/productions/<pid>/run-attendance', methods=['GET'])
def production_run_attendance(pid):
    """Everyone on the show x every rehearsal/performance: who signed in,
    for how long, who had a reported conflict, and who was missing. Covers
    adults (production sign-in), youth (parent pickup sign-in) and names
    added by hand."""
    err = require_auth()
    if err: return err
    import datetime as _dt
    conn = get_db()
    try:
        events = fetchall(conn, '''SELECT id, name, event_date, start_time FROM events
            WHERE production_id=%s AND COALESCE(status,'') <> 'cancelled' ORDER BY event_date, start_time''', (pid,)) or []
        today = today_eastern().isoformat()
        ev_ids = [e['id'] for e in events]
        people = []
        for m in fetchall(conn, '''SELECT pm.volunteer_id AS pid, v.name, pm.role, pm.department FROM production_members pm
                JOIN volunteers v ON v.id=pm.volunteer_id WHERE pm.production_id=%s AND COALESCE(pm.status,'') <> 'dropped'
                ORDER BY pm.department, v.name''', (pid,)) or []:
            people.append({'key': 'v:' + m['pid'], 'kind': 'adult', 'name': m['name'], 'role': m.get('role') or '',
                           'group': m.get('department') or 'Cast & Crew'})
        for y in fetchall(conn, '''SELECT ypm.youth_id AS pid, y.first_name||' '||y.last_name AS name, ypm.role FROM youth_production_members ypm
                JOIN youth_participants y ON y.id=ypm.youth_id WHERE ypm.production_id=%s ORDER BY y.last_name, y.first_name''', (pid,)) or []:
            people.append({'key': 'y:' + y['pid'], 'kind': 'youth', 'name': y['name'], 'role': y.get('role') or '', 'group': 'Youth'})
        for c in fetchall(conn, 'SELECT id, name, role, kind FROM production_pending_cast WHERE production_id=%s ORDER BY name', (pid,)) or []:
            people.append({'key': 'pc:' + c['id'], 'kind': 'pending', 'name': c['name'], 'role': c.get('role') or '',
                           'group': 'Added by name', 'not_in_rolecall': True})
        cells = {}
        def put(key, eid, cell):
            cur = cells.setdefault(key, {}).get(eid)
            if not cur or cell.get('status') == 'in':
                cells[key][eid] = cell
        if ev_ids:
            def _t(v):
                return v.strftime('%-I:%M %p') if hasattr(v, 'strftime') else ''
            for a in fetchall(conn, 'SELECT volunteer_id, event_id, signed_in_at, signed_out_at FROM prod_attendance WHERE event_id = ANY(%s)', (ev_ids,)) or []:
                put('v:' + a['volunteer_id'], a['event_id'], {'status': 'in', 'in': _t(a['signed_in_at']), 'out': _t(a['signed_out_at'])})
            for a in fetchall(conn, 'SELECT youth_id, event_id, signed_in_at, signed_out_at FROM youth_sign_ins WHERE event_id = ANY(%s)', (ev_ids,)) or []:
                put('y:' + a['youth_id'], a['event_id'], {'status': 'in', 'in': _t(a['signed_in_at']), 'out': _t(a['signed_out_at'])})
            for a in fetchall(conn, 'SELECT pending_cast_id, event_id, signed_in_at, signed_out_at FROM pending_cast_attendance WHERE event_id = ANY(%s)', (ev_ids,)) or []:
                put('pc:' + a['pending_cast_id'], a['event_id'], {'status': 'in', 'in': _t(a['signed_in_at']), 'out': _t(a['signed_out_at'])})
            # time credited by any route (kiosk session, ELIC, staff) also counts as being there
            hrs = {}
            for h in fetchall(conn, '''SELECT volunteer_id, event_id, SUM(hours) AS h FROM hours WHERE event_id = ANY(%s) GROUP BY volunteer_id, event_id''', (ev_ids,)) or []:
                hrs[(h['volunteer_id'], h['event_id'])] = ('approved', float(h['h'] or 0))
            for h in fetchall(conn, '''SELECT volunteer_id, event_id, SUM(hours) AS h FROM pending_hours WHERE event_id = ANY(%s) AND status='pending' GROUP BY volunteer_id, event_id''', (ev_ids,)) or []:
                hrs.setdefault((h['volunteer_id'], h['event_id']), ('pending', float(h['h'] or 0)))
            for (vid, eid), (st, h) in hrs.items():
                key = 'v:' + vid
                c = cells.setdefault(key, {}).get(eid) or {'status': 'in'}
                c['hours'] = round(h, 2); c['hours_status'] = st
                cells[key][eid] = c
            for c in fetchall(conn, '''SELECT event_id, youth_id, volunteer_id, status, notes FROM production_conflicts
                    WHERE production_id=%s AND event_id IS NOT NULL''', (pid,)) or []:
                key = ('y:' + c['youth_id']) if c.get('youth_id') else ('v:' + c['volunteer_id']) if c.get('volunteer_id') else None
                if key and not (cells.get(key) or {}).get(c['event_id']):
                    cells.setdefault(key, {})[c['event_id']] = {'status': 'conflict', 'note': c.get('notes') or c.get('status') or ''}
        past = [e for e in events if str(e['event_date'])[:10] <= today]
        for p in people:
            row = cells.get(p['key'], {})
            p['attended'] = sum(1 for e in past if (row.get(e['id']) or {}).get('status') == 'in')
            p['conflicts'] = sum(1 for e in past if (row.get(e['id']) or {}).get('status') == 'conflict')
            p['missed'] = len(past) - p['attended'] - p['conflicts']
            p['hours'] = round(sum((c.get('hours') or 0) for c in row.values()), 2)
        return jsonify({'events': [{'id': e['id'], 'name': e['name'], 'date': str(e['event_date'])[:10], 'time': e.get('start_time') or '',
                                    'past': str(e['event_date'])[:10] <= today} for e in events],
                        'people': people, 'cells': cells, 'past_count': len(past)})
    finally:
        conn.close()


@app.route('/api/productions/<pid>/pending-cast', methods=['GET', 'POST'])
def production_pending_cast(pid):
    err = require_auth()
    if err: return err
    conn = get_db()
    try:
        if request.method == 'POST':
            d = request.json or {}
            lines = [l.strip() for l in (d.get('names') or '').replace('\r', '').split('\n') if l.strip()]
            added = 0
            for line in lines[:300]:
                # "Name - Role" or "Name, Role" (role optional)
                parts = re.split(r'\s+[-–]\s+|\t|,\s*', line, maxsplit=1)
                name = parts[0].strip()[:120]
                role = (parts[1].strip() if len(parts) > 1 else (d.get('role') or '')).strip()[:120]
                if not name:
                    continue
                execute(conn, '''INSERT INTO production_pending_cast (id, production_id, name, role, cast_section, kind, notes, created_by)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s)''', (str(uuid.uuid4()), pid, name, role, (d.get('cast_section') or '')[:60],
                    d.get('kind') if d.get('kind') in ('youth', 'adult') else 'unknown', '', session.get('name') or ''))
                added += 1
            conn.commit()
            return jsonify({'ok': True, 'added': added})
        rows = fetchall(conn, 'SELECT * FROM production_pending_cast WHERE production_id=%s ORDER BY name', (pid,)) or []
        # suggest likely matches already in RoleCall (same name)
        for r in rows:
            nm = (r['name'] or '').strip().lower()
            r['youth_matches'] = fetchall(conn, '''SELECT id, first_name||' '||last_name AS name, dob FROM youth_participants
                WHERE LOWER(TRIM(first_name||' '||last_name))=%s LIMIT 5''', (nm,)) or []
            r['volunteer_matches'] = fetchall(conn, "SELECT id, name, email FROM volunteers WHERE LOWER(TRIM(name))=%s LIMIT 5", (nm,)) or []
        return jsonify(rows)
    finally:
        conn.close()


@app.route('/api/productions/<pid>/pending-cast/<cid>', methods=['PUT', 'DELETE'])
def production_pending_cast_item(pid, cid):
    err = require_auth()
    if err: return err
    conn = get_db()
    try:
        if request.method == 'DELETE':
            execute(conn, 'DELETE FROM production_pending_cast WHERE id=%s AND production_id=%s', (cid, pid))
        else:
            d = request.json or {}
            execute(conn, '''UPDATE production_pending_cast SET name=COALESCE(NULLIF(%s,''),name), role=%s, cast_section=%s, notes=%s
                WHERE id=%s AND production_id=%s''', ((d.get('name') or '').strip()[:120], (d.get('role') or '')[:120],
                (d.get('cast_section') or '')[:60], (d.get('notes') or '')[:500], cid, pid))
        conn.commit()
        return jsonify({'ok': True})
    finally:
        conn.close()


@app.route('/api/productions/<pid>/pending-cast/<cid>/link', methods=['POST'])
def production_pending_cast_link(pid, cid):
    """Connect a by-name cast member to their real RoleCall record:
    kind 'youth' (a participant) or 'volunteer' (an adult)."""
    err = require_auth()
    if err: return err
    d = request.json or {}
    conn = get_db()
    try:
        pc = fetchone(conn, 'SELECT * FROM production_pending_cast WHERE id=%s AND production_id=%s', (cid, pid))
        if not pc:
            return jsonify({'error': 'Not found'}), 404
        person = d.get('person_id')
        if d.get('kind') == 'youth':
            if not fetchone(conn, 'SELECT 1 AS x FROM youth_participants WHERE id=%s', (person,)):
                return jsonify({'error': 'Participant not found'}), 404
            if not fetchone(conn, 'SELECT 1 AS x FROM youth_production_members WHERE production_id=%s AND youth_id=%s', (pid, person)):
                execute(conn, '''INSERT INTO youth_production_members (id, production_id, youth_id, role, cast_section)
                    VALUES (%s,%s,%s,%s,%s)''', (str(uuid.uuid4()), pid, person, pc.get('role') or '', pc.get('cast_section') or ''))
        elif d.get('kind') == 'volunteer':
            if not fetchone(conn, 'SELECT 1 AS x FROM volunteers WHERE id=%s', (person,)):
                return jsonify({'error': 'Volunteer not found'}), 404
            if not fetchone(conn, 'SELECT 1 AS x FROM production_members WHERE production_id=%s AND volunteer_id=%s', (pid, person)):
                execute(conn, '''INSERT INTO production_members (id, production_id, volunteer_id, role)
                    VALUES (%s,%s,%s,%s)''', (str(uuid.uuid4()), pid, person, pc.get('role') or 'Cast'))
        else:
            return jsonify({'error': 'Pick who this is.'}), 400
        # keep the attendance taken while they were "by name"
        for a in fetchall(conn, 'SELECT * FROM pending_cast_attendance WHERE pending_cast_id=%s', (cid,)) or []:
            try:
                if d.get('kind') == 'youth':
                    execute(conn, '''INSERT INTO youth_sign_ins (id, youth_id, event_id, signed_in_at, signed_out_at, notes)
                        VALUES (%s,%s,%s,%s,%s,'Recorded before they were in RoleCall')''',
                        (str(uuid.uuid4()), person, a['event_id'], a['signed_in_at'], a['signed_out_at'] or a['signed_in_at']))
                else:
                    execute(conn, 'INSERT INTO prod_attendance (id, volunteer_id, event_id, signed_in_at, signed_out_at) VALUES (%s,%s,%s,%s,%s)',
                            (str(uuid.uuid4()), person, a['event_id'], a['signed_in_at'], a['signed_out_at'] or a['signed_in_at']))
            except Exception as e:
                app.logger.warning(f'Carrying attendance over for {cid} failed: {e}')
        execute(conn, 'DELETE FROM production_pending_cast WHERE id=%s', (cid,))
        conn.commit()
        return jsonify({'ok': True})
    finally:
        conn.close()


