@app.route('/api/kiosk/events')
def kiosk_events():
    # When checking in as a paid instructor, only events under programs
    # flagged is_paid_instruction AND assigned to that specific instructor
    # should be selectable — never the general volunteer event list.
    paid_instruction = request.args.get('paid_instruction') == '1'
    volunteer_id = request.args.get('volunteer_id')
    conn = get_db()
    extra_join = ''
    extra_where = ''
    params = []
    if paid_instruction:
        extra_join = "LEFT JOIN youth_programs pg ON e.program_id=pg.id"
        # instructors only see today's classes (Eastern time)
        extra_where = "AND pg.is_paid_instruction=TRUE AND e.event_date::date = (CURRENT_TIMESTAMP AT TIME ZONE 'America/New_York')::date"
        if volunteer_id:
            extra_where += " AND pg.instructor_id=%s"
            params.append(volunteer_id)
    events = fetchall(conn, f"""
        SELECT e.*,
               p.name as production_name,
               COALESCE(p.stage,'mainstage') as stage,
               p.stage as production_stage,
               el.action as current_status,
               (SELECT COUNT(*) FROM youth_production_members ypm WHERE ypm.production_id=e.production_id)
               + (SELECT COUNT(*) FROM production_pending_cast pc WHERE pc.production_id=e.production_id AND pc.kind='youth') AS youth_cast_count
        FROM events e
        LEFT JOIN productions p ON e.production_id=p.id
        {extra_join}
        LEFT JOIN (SELECT event_id, action FROM event_logs
            WHERE (event_id, timestamp) IN (
                SELECT event_id, MAX(timestamp) FROM event_logs GROUP BY event_id
            )) el ON el.event_id=e.id
        WHERE (e.status='open'
           OR el.action='open'
           OR (e.status IN ('draft','published','in_progress')
               AND e.event_date::date >= (CURRENT_TIMESTAMP AT TIME ZONE 'America/New_York')::date - INTERVAL '1 day'
               AND e.event_date::date <= (CURRENT_TIMESTAMP AT TIME ZONE 'America/New_York')::date + INTERVAL '1 day'))
        {extra_where}
        ORDER BY CASE WHEN e.status='open' OR el.action='open' THEN 0 ELSE 1 END, e.event_date ASC NULLS LAST
    """, tuple(params))
    conn.close()
    # Mark events as open if event_logs says so
    for e in events:
        if e.get('current_status') == 'open':
            e['status'] = 'open'
    if paid_instruction and volunteer_id:
        conn2 = get_db()
        for e in events:
            e['can_self_open'] = (e.get('status') != 'open') and (bool(_elic_for_event(conn2, volunteer_id, e['id']))
                                  or determine_kiosk_pay_type(conn2, volunteer_id, e['id']) == 'paid_instruction')
            # paid instructors are credited for the whole scheduled class in
            # one tap (no timer to remember to stop), when the class has a
            # start and end time; otherwise the timer is used
            if e.get('start_time') and e.get('end_time'):
                e['auto_log_hours'] = True
            # what this instructor already has for the class
            ap = fetchone(conn2, 'SELECT SUM(hours) AS h FROM hours WHERE volunteer_id=%s AND event_id=%s', (volunteer_id, e['id'])) or {}
            if ap.get('h'):
                e['my_credit'] = {'status': 'approved', 'hours': float(ap['h'])}
            else:
                pd = fetchone(conn2, "SELECT SUM(hours) AS h FROM pending_hours WHERE volunteer_id=%s AND event_id=%s AND status='pending'",
                              (volunteer_id, e['id'])) or {}
                if pd.get('h'):
                    e['my_credit'] = {'status': 'pending', 'hours': float(pd['h'])}
        conn2.close()
        # next class first (soonest start), then earlier classes (most recent first)
        now_hm = now_eastern().strftime('%H:%M')
        def _end(e): return str(e.get('end_time') or e.get('start_time') or '23:59')[:5]
        upcoming = sorted([e for e in events if _end(e) > now_hm], key=lambda e: str(e.get('start_time') or '99:99')[:5])
        earlier = sorted([e for e in events if _end(e) <= now_hm], key=lambda e: str(e.get('start_time') or '')[:5], reverse=True)
        for e in upcoming: e['when'] = 'next'
        for e in earlier: e['when'] = 'earlier'
        events = upcoming + earlier
    return jsonify(events)

@app.route('/api/kiosk/submit', methods=['POST'])
def kiosk_submit():
    d = request.json or {}
    if not d.get('volunteer_id') or not d.get('event') or not d.get('hours'):
        return jsonify({'error': 'Missing required fields'}), 400
    try:
        hours = float(d.get('hours',0))
        if hours <= 0 or hours > 24:
            return jsonify({'error': 'Hours must be between 0.5 and 24'}), 400
    except Exception:
        return jsonify({'error': 'Invalid hours value'}), 400
    pid = str(uuid.uuid4())
    conn = get_db()
    dup = existing_event_credit(conn, d.get('volunteer_id'), d.get('event_id'))
    if dup:
        conn.close(); return jsonify({'error': dup, 'duplicate': True}), 409
    pay_type = determine_kiosk_pay_type(conn, d.get('volunteer_id'), d.get('event_id'))
    if d.get('paid_instruction'):
        pay_type = 'paid_instruction'
    today_row = fetchone(conn, "SELECT CURRENT_DATE::text as today")
    today = today_row['today'] if today_row else __import__('datetime').date.today().isoformat()
    execute(conn, "INSERT INTO pending_hours (id,volunteer_id,event,event_id,date,hours,role,notes,status,pay_type) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,'pending',%s)",
        (pid, d.get('volunteer_id'), d.get('event',''), d.get('event_id'), today, hours, d.get('role',''), d.get('notes',''), pay_type))
    _tag_hours(conn, 'pending_hours', pid, 'kiosk_manual')
    conn.commit(); conn.close()
    return jsonify({'ok': True})

@app.route('/api/kiosk/waiver-check')
def kiosk_waiver_check():
    vol_id = request.args.get('volunteer_id')
    if not vol_id: return jsonify({'issues': [], 'all_clear': True})
    conn = get_db()
    from datetime import date as _date
    today = _date.today()
    required = fetchall(conn, '''SELECT wt.* FROM waiver_types wt
        WHERE wt.required_all=TRUE OR wt.required_for_volunteering=TRUE''')
    issues = []
    for wt in required:
        signed = fetchone(conn, '''SELECT * FROM volunteer_waivers WHERE volunteer_id=%s AND waiver_type_id=%s
            ORDER BY signed_date DESC LIMIT 1''', (vol_id, wt['id']))
        if not signed:
            issues.append({'waiver_type_id': wt['id'], 'name': wt['name'],
                'description': wt.get('description',''), 'status': 'missing',
                'can_sign_online': bool(wt.get('can_sign_online')),
                'template_body': wt.get('template_body','')})
        elif wt.get('expires_days') and signed.get('expiry_date'):
            try:
                exp = __import__('datetime').date.fromisoformat(str(signed['expiry_date'])[:10])
                if exp < today:
                    issues.append({'waiver_type_id': wt['id'], 'name': wt['name'],
                        'description': wt.get('description',''), 'status': 'expired',
                        'can_sign_online': bool(wt.get('can_sign_online')),
                        'template_body': wt.get('template_body','')})
            except Exception:
                pass
    conn.close()
    return jsonify({'issues': issues, 'all_clear': len(issues) == 0})

@app.route('/api/kiosk/sign-waiver', methods=['POST'])
def kiosk_sign_waiver():
    d = request.json or {}
    vol_id = d.get('volunteer_id')
    waiver_type_id = d.get('waiver_type_id')
    signed_name = d.get('signed_name', '')
    if not vol_id or not waiver_type_id: return jsonify({'error': 'Missing fields'}), 400
    conn = get_db()
    wt = fetchone(conn, 'SELECT * FROM waiver_types WHERE id=%s', (waiver_type_id,))
    if not wt: conn.close(); return jsonify({'error': 'Waiver type not found'}), 404
    from datetime import date as _date, timedelta
    today = _date.today()
    expiry = None
    if wt.get('expires_days'):
        expiry = (today + timedelta(days=int(wt['expires_days']))).isoformat()
    wid = str(uuid.uuid4())
    execute(conn, '''INSERT INTO volunteer_waivers
        (id,volunteer_id,waiver_type_id,signed_date,expiry_date,signed_name,signed_via)
        VALUES (%s,%s,%s,%s,%s,%s,'kiosk')''',
        (wid, vol_id, waiver_type_id, today.isoformat(), expiry, signed_name))
    conn.commit(); conn.close()
    return jsonify({'ok': True})

@app.route('/api/kiosk/update-profile', methods=['POST'])
def kiosk_update_profile():
    d = request.json or {}
    vol_id = d.get('volunteer_id')
    if not vol_id: return jsonify({'error': 'Missing volunteer_id'}), 400
    conn = get_db()
    updates = []
    params = []
    if d.get('phone') is not None:
        updates.append('phone=%s'); params.append(d['phone'])
    if d.get('interests') is not None:
        updates.append('interests=%s'); params.append(json.dumps(d.get('interests','[]')))
    if updates:
        execute(conn, f"UPDATE volunteers SET {','.join(updates)} WHERE id=%s", tuple(params + [vol_id]))
    if d.get('emergency_contact'):
        ec = d['emergency_contact']
        existing = fetchone(conn, 'SELECT id FROM volunteer_emergency_contacts WHERE volunteer_id=%s', (vol_id,))
        if existing:
            execute(conn, 'UPDATE volunteer_emergency_contacts SET name=%s, relationship=%s, phone=%s WHERE volunteer_id=%s',
                (ec.get('name',''), ec.get('relationship',''), ec.get('phone',''), vol_id))
        else:
            ecid = str(uuid.uuid4())
            execute(conn, 'INSERT INTO volunteer_emergency_contacts (id,volunteer_id,name,relationship,phone) VALUES (%s,%s,%s,%s,%s)',
                (ecid, vol_id, ec.get('name',''), ec.get('relationship',''), ec.get('phone','')))
    conn.commit()
    # Log update request for admin review
    pid = str(uuid.uuid4())
    execute(conn, "INSERT INTO pending_hours (id,volunteer_id,event,date,hours,notes,status) VALUES (%s,%s,'Profile Update',CURRENT_DATE,0,'Profile update submitted via kiosk','pending_profile')",
        (pid, vol_id))
    conn.commit(); conn.close()
    return jsonify({'ok': True})

