#  PRODUCTION SIGN-IN (ELIC Kiosk)
# ─────────────────────────────────────────────


# Cast added by name show up on the kiosk rosters with ids like "pc:<id>",
# so the kiosk can sign them in and out like anyone else. They're recorded
# in pending_cast_attendance (attendance only, never volunteer hours).
def _pc_id(x):
    return x[3:] if isinstance(x, str) and x.startswith('pc:') else None


def _pending_cast_roster(conn, prod_id, event_id):
    return fetchall(conn, """SELECT pc.id, pc.name, pc.role, pc.cast_section, pc.kind,
            pa.id AS attendance_id, pa.signed_in_at
        FROM production_pending_cast pc
        LEFT JOIN pending_cast_attendance pa ON pa.pending_cast_id=pc.id AND pa.event_id=%s AND pa.signed_out_at IS NULL
        WHERE pc.production_id=%s ORDER BY pc.name""", (event_id, prod_id)) or []


def _pending_cast_sign(conn, pcid, event_id, sign_in):
    open_row = fetchone(conn, 'SELECT id FROM pending_cast_attendance WHERE pending_cast_id=%s AND event_id=%s AND signed_out_at IS NULL',
                        (pcid, event_id))
    if sign_in:
        if open_row:
            return {'error': 'Already signed in', 'attendance_id': open_row['id']}
        aid = str(uuid.uuid4())
        execute(conn, 'INSERT INTO pending_cast_attendance (id, pending_cast_id, event_id) VALUES (%s,%s,%s)', (aid, pcid, event_id))
        conn.commit()
        return {'ok': True, 'attendance_id': aid}
    if not open_row:
        return {'error': 'No active sign-in found'}
    execute(conn, 'UPDATE pending_cast_attendance SET signed_out_at=NOW() WHERE id=%s', (open_row['id'],))
    conn.commit()
    return {'ok': True, 'hours': 0, 'note': 'Attendance recorded (cast, no volunteer hours).'}

@app.route('/api/kiosk/production-roster/<event_id>')
def kiosk_production_roster(event_id):
    conn = get_db()
    evt = fetchone(conn, 'SELECT * FROM events WHERE id=%s', (event_id,))
    if not evt:
        conn.close()
        return jsonify({'error': 'Event not found'}), 404
    prod_id = evt.get('production_id')
    if not prod_id:
        conn.close()
        return jsonify({'members': [], 'production_id': None})
    members = fetchall(conn, '''
        SELECT pm.id as member_id, pm.volunteer_id, pm.role, pm.department, pm.status,
               v.name as volunteer_name,
               pa.id as attendance_id, pa.signed_in_at,
               CASE WHEN pa.id IS NOT NULL AND pa.signed_out_at IS NULL THEN TRUE ELSE FALSE END as signed_in
        FROM production_members pm
        JOIN volunteers v ON pm.volunteer_id=v.id
        LEFT JOIN prod_attendance pa
            ON pa.volunteer_id=pm.volunteer_id AND pa.event_id=%s AND pa.signed_out_at IS NULL
        WHERE pm.production_id=%s AND pm.status != 'dropped'
        ORDER BY pm.department, v.name
    ''', (event_id, prod_id)) or []
    prod = fetchone(conn, 'SELECT stage FROM productions WHERE id=%s', (prod_id,)) or {}
    if prod.get('stage') not in ('rising_stars', 'teen_show'):   # youth shows list them on the youth roster instead
        for r in _pending_cast_roster(conn, prod_id, event_id):
            if r.get('kind') == 'youth':
                continue   # youth sign in on the youth list (with parent pickup), even on a mainstage show
            members.append({'member_id': 'pc:' + r['id'], 'volunteer_id': 'pc:' + r['id'], 'role': r.get('role') or 'Cast',
                            'department': r.get('cast_section') or 'Cast', 'status': 'confirmed', 'volunteer_name': r['name'],
                            'attendance_id': r.get('attendance_id'), 'signed_in_at': r.get('signed_in_at'),
                            'signed_in': bool(r.get('attendance_id')), 'not_in_rolecall': True})
    conn.close()
    return jsonify({'ok': True, 'members': members, 'production_id': prod_id})

@app.route('/api/kiosk/production-signin', methods=['POST'])
def kiosk_production_signin():
    d = request.json or {}
    vol_id   = d.get('volunteer_id')
    event_id = d.get('event_id')
    if not vol_id or not event_id:
        return jsonify({'error': 'Missing volunteer_id or event_id'}), 400
    if _pc_id(vol_id):
        conn = get_db()
        try:
            r = _pending_cast_sign(conn, _pc_id(vol_id), event_id, True)
        finally:
            conn.close()
        return jsonify(r)
    conn = get_db()
    _h0 = fetchone(conn, 'SELECT hours FROM hours WHERE volunteer_id=%s AND event_id=%s LIMIT 1', (vol_id, event_id)) or \
          fetchone(conn, "SELECT hours FROM pending_hours WHERE volunteer_id=%s AND event_id=%s AND status IN ('pending','approved') LIMIT 1", (vol_id, event_id))
    if _h0:
        conn.close()
        return jsonify({'error': f'Already credited {_h0["hours"]:g} hours for this session, so they can\'t be signed in again.', 'duplicate': True}), 409
    existing = fetchone(conn,
        'SELECT id FROM prod_attendance WHERE volunteer_id=%s AND event_id=%s AND signed_out_at IS NULL',
        (vol_id, event_id))
    if existing:
        conn.close()
        return jsonify({'error': 'Already signed in', 'attendance_id': existing['id']})
    aid = str(uuid.uuid4())
    execute(conn, 'INSERT INTO prod_attendance (id,volunteer_id,event_id,signed_in_at) VALUES (%s,%s,%s,NOW())',
        (aid, vol_id, event_id))
    conn.commit(); conn.close()
    return jsonify({'ok': True, 'attendance_id': aid})

@app.route('/api/kiosk/production-signout', methods=['POST'])
def kiosk_production_signout():
    d = request.json or {}
    att_id   = d.get('attendance_id')
    vol_id   = d.get('volunteer_id')
    event_id = d.get('event_id')
    role     = d.get('role', '')
    if not vol_id or not event_id:
        return jsonify({'error': 'Missing required fields'}), 400
    if _pc_id(vol_id):
        conn = get_db()
        try:
            r = _pending_cast_sign(conn, _pc_id(vol_id), event_id, False)
        finally:
            conn.close()
        return (jsonify(r), 404) if r.get('error') else jsonify(r)
    conn = get_db()
    att = None
    if att_id:
        att = fetchone(conn, 'SELECT * FROM prod_attendance WHERE id=%s', (att_id,))
    if not att:
        att = fetchone(conn,
            'SELECT * FROM prod_attendance WHERE volunteer_id=%s AND event_id=%s AND signed_out_at IS NULL',
            (vol_id, event_id))
    if not att:
        conn.close()
        return jsonify({'error': 'No active sign-in found'}), 404

    # Actual elapsed time from when they really signed in to when they
    # really signed out — this used to default to the event's full
    # scheduled duration whenever start/end times were set, which counted
    # staff as present the whole show even if they arrived late or left
    # early. Elapsed time is now always what's logged.
    evt = fetchone(conn, 'SELECT * FROM events WHERE id=%s', (event_id,))
    evt_name = evt['name'] if evt else 'Production'
    time_row = fetchone(conn,
        'SELECT EXTRACT(EPOCH FROM (NOW() - signed_in_at)) as secs FROM prod_attendance WHERE id=%s',
        (att['id'],))
    elapsed_secs = float(time_row['secs']) if time_row and time_row['secs'] else 0
    event_hours  = round(max(0.25, elapsed_secs / 3600), 2)
    hours_source = 'elapsed time (actual sign-in to sign-out)'

    today_row = fetchone(conn, 'SELECT CURRENT_DATE::text as today')
    today = today_row['today'] if today_row else __import__('datetime').date.today().isoformat()

    execute(conn, 'UPDATE prod_attendance SET signed_out_at=NOW() WHERE id=%s', (att['id'],))
    dup = existing_event_credit(conn, vol_id, event_id, ignore_attendance_id=att['id'])
    if dup and 'signed in' not in dup:
        # already credited for this event another way (e.g. they're the ELIC,
        # or hours were logged separately): attendance is kept, no second entry
        conn.commit(); conn.close()
        return jsonify({'ok': True, 'hours': 0, 'note': 'Signed out. Time for this event was already credited, so no extra hours were added.'})
    pid = str(uuid.uuid4())
    execute(conn, '''INSERT INTO pending_hours (id,volunteer_id,event,event_id,date,hours,role,notes,status)
        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,'pending')''',
        (pid, vol_id, evt_name, event_id, today, event_hours, role or '',
         f'Production member  -  {hours_source}'))
    _tag_hours(conn, 'pending_hours', pid, 'production_signin')
    conn.commit(); conn.close()
    return jsonify({'ok': True, 'hours': event_hours, 'hours_source': hours_source})



