@app.route('/api/kiosk/open-event-checklist', methods=['POST'])
def kiosk_open_event():
    d = request.json or {}
    elic_id  = d.get('elic_id')
    event_id = d.get('event_id')
    responses = d.get('responses', [])
    signature = d.get('signature', '')
    if not elic_id or not event_id:
        return jsonify({'error': 'Missing elic_id or event_id'}), 400
    conn = get_db()
    try:
        # Log the opening
        log_id = str(uuid.uuid4())
        execute(conn, '''INSERT INTO event_logs (id,event_id,elic_id,action,notes,signature)
            VALUES (%s,%s,%s,'open','Event opened via kiosk',%s)''', (log_id, event_id, elic_id, signature))
        # Save checklist responses
        for r in responses:
            rid = str(uuid.uuid4())
            execute(conn, '''INSERT INTO event_checklist_responses
                (id,event_log_id,checklist_item_id,label,item_type,response)
                VALUES (%s,%s,%s,%s,%s,%s)''',
                (rid, log_id, r.get('item_id',''), r.get('label',''),
                 r.get('type','checkbox'), str(r.get('response',''))))
        # Mark event as open
        execute(conn, "UPDATE events SET status='open' WHERE id=%s", (event_id,))
        conn.commit(); conn.close()
        return jsonify({'ok': True, 'log_id': log_id})
    except Exception as e:
        conn.rollback(); conn.close()
        return jsonify({'error': str(e)}), 500

@app.route('/api/admin/fix-event-statuses', methods=['POST'])
def fix_event_statuses():
    err = require_auth()
    if err: return err
    conn = get_db()
    try:
        system_elic = fetchone(conn, 'SELECT id FROM elics WHERE is_master=TRUE LIMIT 1') or \
                      fetchone(conn, 'SELECT id FROM elics LIMIT 1') or {}
        system_elic_id = system_elic.get('id')

        # Find all events whose LAST event_log action is 'open' but event date has passed
        stale = fetchall(conn, """
            SELECT DISTINCT e.id, e.name FROM events e
            JOIN event_logs el ON el.event_id=e.id
            WHERE el.id = (SELECT id FROM event_logs WHERE event_id=e.id ORDER BY timestamp DESC LIMIT 1)
            AND el.action='open'
            AND (e.event_date IS NULL OR e.event_date::date < CURRENT_DATE)
        """) or []

        closed = 0
        for ev in stale:
            execute(conn, """INSERT INTO event_logs
                (id, event_id, elic_id, action, notes, signature, actor_name)
                VALUES (%s,%s,NULL,'close',%s,'',%s)""",
                (str(uuid.uuid4()), ev['id'],
                 'Auto-closed by system — event date passed without formal close', 'RoleCall (automatic)'))
            execute(conn, "UPDATE events SET status='closed' WHERE id=%s", (ev['id'],))
            closed += 1

        conn.commit()
        conn.close()
        return jsonify({'ok': True, 'closed': closed})
    except Exception as e:
        try: conn.rollback(); conn.close()
        except Exception: pass
        return jsonify({'error': str(e)}), 500

@app.route('/api/debug/open-events')
def debug_open_events():
    err = require_auth()
    if err: return err
    conn = get_db()
    rows = fetchall(conn, """SELECT e.id, e.name, e.event_date,
        el.action as last_action, el.timestamp as last_log_time, el.notes
        FROM events e
        LEFT JOIN event_logs el ON el.id = (
            SELECT id FROM event_logs WHERE event_id=e.id ORDER BY id DESC LIMIT 1
        )
        WHERE el.action='open' OR el.action IS NULL
        ORDER BY e.event_date DESC NULLS LAST
        LIMIT 20""") or []
    conn.close()
