@app.route('/api/admin/auto-close-past-events', methods=['POST'])
def auto_close_past_events():
    err = require_auth()
    if err: return err
    conn = get_db()
    closed = 0
    try:
        # Find events still showing as open where event_date is in the past
        open_events = fetchall(conn, """SELECT DISTINCT e.id, e.name FROM events e
            JOIN event_logs el ON el.event_id=e.id
            WHERE el.action='open'
            AND el.id IN (SELECT id FROM event_logs WHERE (event_id, timestamp) IN (SELECT event_id, MAX(timestamp) FROM event_logs GROUP BY event_id))
            AND (
                (e.event_date IS NOT NULL AND e.event_date::date < CURRENT_DATE)
                OR
                (e.event_date IS NULL AND el.timestamp < NOW() - INTERVAL '24 hours')
            )""") or []
        system_elic = fetchone(conn, 'SELECT id FROM elics WHERE is_master=TRUE LIMIT 1') or \
                      fetchone(conn, 'SELECT id FROM elics LIMIT 1') or {}
        system_elic_id = system_elic.get('id')
        if not system_elic_id:
            execute(conn, 'ALTER TABLE event_logs ALTER COLUMN elic_id DROP NOT NULL')
            conn.commit()
        for ev in open_events:
            log_id = str(uuid.uuid4())
            execute(conn, """INSERT INTO event_logs (id, event_id, elic_id, action, notes, signature, actor_name)
                VALUES (%s, %s, NULL, 'close', %s, '', %s)""",
                (log_id, ev['id'],
                 'Auto-closed by system — event date passed without formal close', 'RoleCall (automatic)'))
            closed += 1
            app.logger.info(f'Auto-closed event: {ev["name"]} ({ev["id"]})')
        conn.commit()
        conn.close()
        return jsonify({'ok': True, 'closed': closed,
            'events': [e['name'] for e in open_events]})
    except Exception as e:
        app.logger.error(f'Auto-close error: {e}')
        try: conn.rollback(); conn.close()
        except Exception: pass
        return jsonify({'error': str(e)}), 500

@app.route('/api/kiosk/walkin-signin', methods=['POST'])
def kiosk_walkin_signin():
    d = request.json or {}
    name = (d.get('name') or '').strip()
    event_id = d.get('event_id','')
    if not name or not event_id:
        return jsonify({'error': 'Missing name or event_id'}), 400
    conn = get_db()
    # Find or create participant by name
    parts = name.split(' ', 1)
    first = parts[0]; last = parts[1] if len(parts) > 1 else ''
    yp = fetchone(conn, 'SELECT * FROM youth_participants WHERE LOWER(first_name)=%s AND LOWER(last_name)=%s LIMIT 1',
        (first.lower(), last.lower()))
    if not yp:
        yid = str(uuid.uuid4())
        execute(conn, 'INSERT INTO youth_participants (id,first_name,last_name,status) VALUES (%s,%s,%s,%s)',
            (yid, first, last, 'active'))
        conn.commit()
        yp = {'id': yid}
    # Check not already signed in
    existing = fetchone(conn, 'SELECT id FROM youth_sign_ins WHERE youth_id=%s AND event_id=%s AND signed_out_at IS NULL',
        (yp['id'], event_id))
    if existing:
        conn.close()
        return jsonify({'ok': True, 'already_in': True})
    sid = str(uuid.uuid4())
    execute(conn, 'INSERT INTO youth_sign_ins (id,youth_id,event_id,signed_in_at) VALUES (%s,%s,%s,NOW())',
        (sid, yp['id'], event_id))
    conn.commit(); conn.close()
    return jsonify({'ok': True, 'sign_in_id': sid})

@app.route('/api/kiosk/elic-events')
def kiosk_elic_events():
    """Lightweight endpoint to refresh ELIC event list without full re-login."""
    elic_id = request.args.get('elic_id','')
    if not elic_id: return jsonify({'error': 'Missing elic_id'}), 400
    conn = get_db()
    try:
        elic = fetchone(conn, 'SELECT * FROM elics WHERE id=%s AND active=TRUE', (elic_id,))
        if not elic: conn.close(); return jsonify({'error': 'ELIC not found'}), 404
        events = fetchall(conn, '''SELECT e.*, el.action as current_status
            FROM events e
            LEFT JOIN (SELECT event_id, action FROM event_logs
                WHERE id IN (SELECT id FROM event_logs WHERE (event_id, timestamp) IN (SELECT event_id, MAX(timestamp) FROM event_logs GROUP BY event_id))) el
            ON el.event_id=e.id
            WHERE e.id IN (SELECT event_id FROM event_elics WHERE elic_id=%s)
            ORDER BY e.event_date DESC, e.start_time''', (elic_id,)) or []
        conn.close()
        return jsonify({'events': events})
    except Exception as e:
        app.logger.warning(f'elic-events error: {e}')
        try: conn.close()
        except Exception: pass
        return jsonify({'events': []})

@app.route('/api/kiosk/close-event', methods=['POST'])
def kiosk_close_event():
    d = request.json or {}
    elic_id  = d.get('elic_id')
    event_id = d.get('event_id')
    responses = d.get('responses', [])
    signature = d.get('signature', '')
    if not elic_id or not event_id:
        return jsonify({'error': 'Missing elic_id or event_id'}), 400
    conn = get_db()
    # Block close if any volunteers are still actively logging hours
    try:
        active_sessions = fetchall(conn, '''SELECT ks.*, v.name as volunteer_name
            FROM kiosk_sessions ks
            JOIN volunteers v ON v.id=ks.volunteer_id
            WHERE ks.event_id=%s AND ks.status='active'
            ORDER BY ks.started_at''', (event_id,)) or []
        if active_sessions:
            names = ', '.join(s['volunteer_name'] for s in active_sessions)
            conn.close()
            return jsonify({
                'error': f'Cannot close event — {len(active_sessions)} volunteer(s) are still logging hours: {names}.',
                'active_sessions': [{'name': s['volunteer_name'], 'id': s['id']} for s in active_sessions]
            }), 400
    except Exception as e:
        app.logger.warning(f'Active sessions check failed (non-fatal): {e}')
        try: conn.rollback()
        except Exception: pass
    try:
        log_id = str(uuid.uuid4())
        execute(conn, '''INSERT INTO event_logs (id,event_id,elic_id,action,notes,signature)
            VALUES (%s,%s,%s,'close','Event closed via kiosk',%s)''', (log_id, event_id, elic_id, signature))
        for r in responses:
            rid = str(uuid.uuid4())
            execute(conn, '''INSERT INTO event_checklist_responses
                (id,event_log_id,checklist_item_id,label,item_type,response)
                VALUES (%s,%s,%s,%s,%s,%s)''',
                (rid, log_id, r.get('item_id',''), r.get('label',''),
                 r.get('type','checkbox'), str(r.get('response',''))))
        execute(conn, "UPDATE events SET status='closed' WHERE id=%s", (event_id,))
        # Auto-approve pending kiosk hours for this event
        pending = fetchall(conn,
            "SELECT * FROM pending_hours WHERE event_id=%s AND status='pending'", (event_id,))
        for ph in pending:
            hid = str(uuid.uuid4())
            if fetchone(conn, 'SELECT 1 AS x FROM hours WHERE volunteer_id=%s AND event_id=%s', (ph['volunteer_id'], ph['event_id'])):
                continue   # already has approved time for this event
            try:
                execute(conn, '''INSERT INTO hours (id,volunteer_id,event,event_id,date,hours,role,notes,pay_type,source,logged_by,submitted_at,approved_by,approved_at)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,NOW())''',
                    (hid, ph['volunteer_id'], ph['event'], ph['event_id'],
                     ph['date'], ph['hours'], ph.get('role',''), ph.get('notes',''), ph.get('pay_type') or 'volunteer',
                     ph.get('source'), ph.get('logged_by'), ph.get('submitted_at'), 'Automatic: approved when the event closed'))
            except Exception:
                pass
        execute(conn, "UPDATE pending_hours SET status='approved' WHERE event_id=%s AND status='pending'", (event_id,))
        # Auto-log ELIC hours based on time from open to close
        # Wrapped in a SAVEPOINT so a failure here can never poison/roll back
        # the rest of this transaction (status update, checklist, hours approval).
        elic_auto_hours = None  # populated below if ELIC auto-hours are logged, used in the close-report email
        try:
            execute(conn, 'SAVEPOINT elic_hours_sp')
            open_log = fetchone(conn, '''SELECT el.timestamp FROM event_logs el
                WHERE el.event_id=%s AND el.elic_id=%s AND el.action='open'
                ORDER BY el.timestamp DESC LIMIT 1''', (event_id, elic_id))
            elic_vol = fetchone(conn, '''SELECT v.id, v.name, e.name as event_name
                FROM elics el
                JOIN volunteers v ON v.id=el.volunteer_id
                JOIN events e ON e.id=%s
                WHERE el.id=%s''', (event_id, elic_id))
            already = elic_vol and fetchone(conn, 'SELECT 1 AS x FROM hours WHERE volunteer_id=%s AND event_id=%s', (elic_vol['id'], event_id))
            if open_log and elic_vol and not already:
                import datetime as _dtel
                from zoneinfo import ZoneInfo as _ZIelic
                open_time = open_log['timestamp']
                close_time = _dtel.datetime.now(_ZIelic('America/New_York'))
                if isinstance(open_time, str):
                    open_time = _dtel.datetime.fromisoformat(open_time)
                if open_time.tzinfo is None:
                    open_time = open_time.replace(tzinfo=_ZIelic('America/New_York'))
                duration_hrs = round((close_time - open_time).total_seconds() / 3600, 2)
                duration_hrs = max(0.25, duration_hrs)  # minimum 15 min
                today = close_time.strftime('%Y-%m-%d')
                hid = str(uuid.uuid4())
                execute(conn, '''INSERT INTO hours (id,volunteer_id,event,event_id,date,hours,role,notes)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s)''',
                    (hid, elic_vol['id'], elic_vol['event_name'] or 'Event', event_id,
                     today, duration_hrs, 'ELIC', 'Auto-logged: ELIC opened and closed event'))
                _tag_hours(conn, 'hours', hid, 'elic_auto')
                app.logger.info(f'Auto-logged {duration_hrs}h for ELIC {elic_vol["name"]}')
                elic_auto_hours = {'name': elic_vol['name'], 'hours': duration_hrs}
            execute(conn, 'RELEASE SAVEPOINT elic_hours_sp')
        except Exception as e:
            app.logger.warning(f'ELIC auto-hours error (non-fatal): {e}')
            try:
                execute(conn, 'ROLLBACK TO SAVEPOINT elic_hours_sp')
            except Exception as e2:
                app.logger.error(f'Failed to rollback to savepoint, aborting close: {e2}')
                conn.rollback(); conn.close()
                return jsonify({'error': 'Internal error closing event, please try again'}), 500

        conn.commit()
        # Send checklist report email
        try:
            s = get_email_settings()
            recipients = get_recipient_emails(s)
            if recipients:
                evt = fetchone(conn, 'SELECT name FROM events WHERE id=%s', (event_id,))
                evt_name = evt['name'] if evt else event_id
                now_str = __import__('datetime').datetime.now(__import__('zoneinfo').ZoneInfo('America/New_York')).strftime('%I:%M %p')
                # Get opening checklist from the open log
                open_log = fetchone(conn, '''SELECT el.*, COALESCE(v.name, el.actor_name) as elic_name FROM event_logs el
                    LEFT JOIN elics eli ON el.elic_id=eli.id
                    LEFT JOIN volunteers v ON eli.volunteer_id=v.id
                    WHERE el.event_id=%s AND el.action='open' ORDER BY el.timestamp DESC LIMIT 1''', (event_id,))
                open_responses = []
                open_elic_name = ''
                if open_log:
                    open_responses = fetchall(conn,
                        'SELECT * FROM event_checklist_responses WHERE event_log_id=%s ORDER BY id',
                        (open_log['id'],))
                    open_elic_name = open_log.get('elic_name','')
                # Build opening checklist rows
                ol_rows = ''
                for r in open_responses:
                    val = str(r.get('response',''))
                    val_str = ' Done' if val=='true' else (' Not Done' if val=='false' else val or ' - ')
                    ol_rows += f'<tr><td style="padding:6px 12px;border-bottom:1px solid #eee">{r.get("label","")}</td><td style="padding:6px 12px;border-bottom:1px solid #eee;font-weight:600">{val_str}</td></tr>'
                # Build closing checklist rows
                cl_rows = ''
                for r in responses:
                    val = str(r.get('response',''))
                    val_str = ' Done' if val=='true' else (' Not Done' if val=='false' else val or ' - ')
                    cl_rows += f'<tr><td style="padding:6px 12px;border-bottom:1px solid #eee">{r.get("label","")}</td><td style="padding:6px 12px;border-bottom:1px solid #eee;font-weight:600">{val_str}</td></tr>'
                # Build hours summary
                hrs_rows = ''
                if pending:
                    for ph in pending:
                        vol = fetchone(conn, 'SELECT name FROM volunteers WHERE id=%s', (ph['volunteer_id'],))
                        vname = vol['name'] if vol else 'Unknown'
                        hrs_rows += f'<tr><td style="padding:6px 12px;border-bottom:1px solid #eee">{vname}</td><td style="padding:6px 12px;border-bottom:1px solid #eee;font-weight:600">{ph["hours"]}h</td><td style="padding:6px 12px;border-bottom:1px solid #eee;color:#16a34a">Auto-approved</td></tr>'
                if elic_auto_hours:
                    hrs_rows += f'<tr><td style="padding:6px 12px;border-bottom:1px solid #eee">{elic_auto_hours["name"]} (ELIC)</td><td style="padding:6px 12px;border-bottom:1px solid #eee;font-weight:600">{elic_auto_hours["hours"]}h</td><td style="padding:6px 12px;border-bottom:1px solid #eee;color:#16a34a">Auto-logged (open→close)</td></tr>'
                hrs_count = len(pending) + (1 if elic_auto_hours else 0)
                body = f'''<div style="font-family:sans-serif;max-width:600px;margin:0 auto">
                    <div style="background:linear-gradient(135deg,#0d3d4d,#145466);padding:24px 28px;border-radius:8px 8px 0 0">
                      <div style="color:rgba(255,255,255,0.7);font-size:11px;text-transform:uppercase;letter-spacing:1px;margin-bottom:4px">Event Closed</div>
                      <h2 style="color:#fff;margin:0;font-size:20px"> {evt_name}</h2>
                      <div style="color:rgba(255,255,255,0.75);font-size:13px;margin-top:6px">Closed at <strong>{now_str}</strong>{" · Closed by "+open_elic_name if open_elic_name else ""}</div>
                    </div>
                    <div style="background:#f8fafc;padding:24px 28px;border-radius:0 0 8px 8px;border:1px solid #e2e8f0;border-top:none">
                    <h3 style="color:#145466;margin-top:0">Opening Checklist</h3>
                    {f"""<table style="width:100%;border-collapse:collapse;border:1px solid #e0e0db;margin-bottom:20px">
                    <thead><tr style="background:#f0fdf4"><th style="padding:8px 12px;text-align:left;font-size:11px;font-weight:700;text-transform:uppercase;color:#5f5e5a;border-bottom:2px solid #e0e0db">Item</th><th style="padding:8px 12px;text-align:left;font-size:11px;font-weight:700;text-transform:uppercase;color:#5f5e5a;border-bottom:2px solid #e0e0db">Response</th></tr></thead>
                    <tbody>{ol_rows}</tbody></table>""" if ol_rows else '<p style="margin-bottom:20px"><em>No opening checklist items recorded.</em></p>'}
                    {f"""<h3 style="color:#145466">Closing Checklist</h3>
                    <table style="width:100%;border-collapse:collapse;border:1px solid #e0e0db;margin-bottom:20px">
                    <thead><tr style="background:#f0fdf4"><th style="padding:8px 12px;text-align:left;font-size:11px;font-weight:700;text-transform:uppercase;color:#5f5e5a;border-bottom:2px solid #e0e0db">Item</th><th style="padding:8px 12px;text-align:left;font-size:11px;font-weight:700;text-transform:uppercase;color:#5f5e5a;border-bottom:2px solid #e0e0db">Response</th></tr></thead>
                    <tbody>{cl_rows}</tbody></table>""" if cl_rows else "<p><em>No closing checklist items recorded.</em></p>"}
                    {f"""<h3 style="color:#145466">Hours Auto-Approved ({hrs_count} volunteer{"s" if hrs_count!=1 else ""})</h3>
                    <table style="width:100%;border-collapse:collapse;border:1px solid #e0e0db;margin-bottom:20px">
                    <thead><tr style="background:#eff6ff"><th style="padding:8px 12px;text-align:left;font-size:11px;font-weight:700;text-transform:uppercase;color:#5f5e5a;border-bottom:2px solid #e0e0db">Volunteer</th><th style="padding:8px 12px;text-align:left;font-size:11px;font-weight:700;text-transform:uppercase;color:#5f5e5a;border-bottom:2px solid #e0e0db">Hours</th><th style="padding:8px 12px;text-align:left;font-size:11px;font-weight:700;text-transform:uppercase;color:#5f5e5a;border-bottom:2px solid #e0e0db">Status</th></tr></thead>
                    <tbody>{hrs_rows}</tbody></table>""" if hrs_count else "<p><em>No hours recorded for this event.</em></p>"}
                    </div></div>'''
                send_email(recipients, f'Event Closed: {evt_name}', build_hwtc_email_html(f'Event Closed: {evt_name}', body))
        except Exception as e:
            app.logger.error(f'close-event email error: {e}')
        conn.close()
        return jsonify({'ok': True, 'log_id': log_id})
    except Exception as e:
        conn.rollback(); conn.close()
        return jsonify({'error': str(e)}), 500

@app.route('/api/kiosk/youth')
def kiosk_get_youth():
    """Get youth participants for ELIC youth sign-in."""
    conn = get_db()
    # Get all active youth for today's events linked to this kiosk session
    youth = fetchall(conn, '''
        SELECT yp.id, yp.first_name, yp.last_name, yp.dob,
               yp.passphrase as individual_passphrase,
               ysi.id as sign_in_id, ysi.signed_in_at, ysi.signed_out_at,
               (SELECT f.passphrase FROM youth_family_links yfl
                JOIN families f ON f.id=yfl.family_id
                WHERE yfl.youth_id=yp.id LIMIT 1) as family_passphrase
        FROM youth_participants yp
        LEFT JOIN youth_sign_ins ysi ON ysi.youth_id=yp.id
            AND ysi.signed_in_at >= NOW() - INTERVAL '12 hours'
            AND ysi.signed_out_at IS NULL
        WHERE yp.status='active'
        ORDER BY yp.last_name, yp.first_name''')
    conn.close()
    return jsonify(youth)

