@app.route('/api/kiosk/youth-for-event/<event_id>')
def kiosk_youth_for_event(event_id):
    """Get youth enrolled in the production or program linked to this event."""
    conn = get_db()
    evt = fetchone(conn, 'SELECT production_id, program_id, linked_session_id, event_date, start_time FROM events WHERE id=%s', (event_id,))
    if not evt:
        conn.close()
        return jsonify([])

    youth = []

    if evt.get('production_id'):
        # Rising Stars production  -  get enrolled cast
        youth = fetchall(conn, '''
            SELECT yp.id, yp.first_name, yp.last_name, yp.dob,
                   ypm.role,
                   yp.passphrase as individual_passphrase,
                   (SELECT f.passphrase FROM youth_family_links yfl
                    JOIN families f ON f.id=yfl.family_id
                    WHERE yfl.youth_id=yp.id LIMIT 1) as family_passphrase,
                   ysi.id as sign_in_id, ysi.signed_in_at, ysi.signed_out_at
            FROM youth_production_members ypm
            JOIN youth_participants yp ON ypm.youth_id=yp.id
            LEFT JOIN youth_sign_ins ysi ON ysi.youth_id=yp.id
                AND ysi.event_id=%s AND ysi.signed_out_at IS NULL
            WHERE ypm.production_id=%s
            ORDER BY yp.last_name, yp.first_name''', (event_id, evt['production_id'])) or []
        _ps = fetchone(conn, 'SELECT stage FROM productions WHERE id=%s', (evt['production_id'],)) or {}
        _youth_show = _ps.get('stage') in ('rising_stars', 'teen_show')
        for r in _pending_cast_roster(conn, evt['production_id'], event_id):
            if _youth_show or r.get('kind') == 'youth':
                nm = (r['name'] or '').strip().split(' ', 1)
                youth.append({'id': 'pc:' + r['id'], 'first_name': nm[0], 'last_name': nm[1] if len(nm) > 1 else '', 'dob': None,
                              'role': r.get('role') or '', 'individual_passphrase': None, 'family_passphrase': None,
                              'sign_in_id': r.get('attendance_id'), 'signed_in_at': r.get('signed_in_at'), 'signed_out_at': None,
                              'not_in_rolecall': True})

    elif evt.get('program_id'):
        program_id = evt['program_id']
        # Check if this program uses sessions
        prog = fetchone(conn, 'SELECT sessions_enabled FROM youth_programs WHERE id=%s', (program_id,))
        if prog and prog.get('sessions_enabled'):
            # Which session is this event? It used to be guessed from the
            # date alone (first session that starts that day), so two sessions
            # on the same day, like a morning and an afternoon workshop, both
            # showed the first session's roster. Now, in order:
            #   1. the session the event was created for (linked_session_id)
            #   2. a session on that date whose start time matches the event
            #   3. the only session running that date (incl. multi-day ones)
            event_date = str(evt.get('event_date') or '')[:10]
            session = None
            if evt.get('linked_session_id'):
                session = fetchone(conn, 'SELECT id FROM program_sessions WHERE id=%s AND program_id=%s', (evt['linked_session_id'], program_id))
            if not session and event_date:
                same_day = fetchall(conn, '''SELECT id, start_time FROM program_sessions WHERE program_id=%s
                    AND COALESCE(status,'open') <> 'cancelled'
                    AND (start_date=%s OR (start_date <= %s AND COALESCE(NULLIF(end_date,''), start_date) >= %s))''',
                    (program_id, event_date, event_date, event_date)) or []
                et = (evt.get('start_time') or '')[:5]
                timed = [x for x in same_day if et and (x.get('start_time') or '')[:5] == et]
                if len(timed) == 1:
                    session = timed[0]
                elif len(same_day) == 1:
                    session = same_day[0]
            if session:
                import json as _jskeid
                session_id = session['id']
                regs = fetchall(conn, '''SELECT pr.youth_id, pr.child_first_name, pr.child_last_name,
                    pr.guardian_name, pr.session_ids,
                    yp.id as pid, yp.dob, yp.passphrase as individual_passphrase,
                    (SELECT f.passphrase FROM youth_family_links yfl
                     JOIN families f ON f.id=yfl.family_id
                     WHERE yfl.youth_id=yp.id LIMIT 1) as family_passphrase,
                    ysi.id as sign_in_id, ysi.signed_in_at, ysi.signed_out_at
                    FROM program_registrations pr
                    LEFT JOIN youth_participants yp ON yp.id=pr.youth_id
                    LEFT JOIN youth_sign_ins ysi ON ysi.youth_id=pr.youth_id
                        AND ysi.event_id=%s AND ysi.signed_out_at IS NULL
                    WHERE pr.program_id=%s AND pr.status=\'confirmed\'
                    ORDER BY pr.child_last_name, pr.child_first_name''',
                    (event_id, program_id)) or []
                youth = []
                for r in regs:
                    try: sids = _jskeid.loads(r.get('session_ids') or '[]')
                    except Exception: sids = []
                    if session_id in sids:
                        youth.append({
                            'id': r.get('youth_id') or r.get('pid'),
                            'first_name': r.get('first_name') or r.get('child_first_name',''),
                            'last_name': r.get('last_name') or r.get('child_last_name',''),
                            'dob': r.get('dob',''),
                            'role': None,
                            'individual_passphrase': r.get('individual_passphrase'),
                            'family_passphrase': r.get('family_passphrase'),
                            'sign_in_id': r.get('sign_in_id'),
                            'signed_in_at': str(r['signed_in_at']) if r.get('signed_in_at') else None,
                            'signed_out_at': str(r['signed_out_at']) if r.get('signed_out_at') else None,
                        })
            else:
                # No session match — fall back to all confirmed regs for this program
                youth = fetchall(conn, '''SELECT pr.youth_id as id, pr.child_first_name as first_name,
                    pr.child_last_name as last_name, yp.dob, NULL as role,
                    yp.passphrase as individual_passphrase,
                    (SELECT f.passphrase FROM youth_family_links yfl
                     JOIN families f ON f.id=yfl.family_id
                     WHERE yfl.youth_id=yp.id LIMIT 1) as family_passphrase,
                    ysi.id as sign_in_id, ysi.signed_in_at, ysi.signed_out_at
                    FROM program_registrations pr
                    LEFT JOIN youth_participants yp ON yp.id=pr.youth_id
                    LEFT JOIN youth_sign_ins ysi ON ysi.youth_id=pr.youth_id
                        AND ysi.event_id=%s AND ysi.signed_out_at IS NULL
                    WHERE pr.program_id=%s AND pr.status=\'confirmed\'
                    ORDER BY pr.child_last_name, pr.child_first_name''',
                    (event_id, program_id)) or []
        else:
            # Non-session program — use enrollments table
            youth = fetchall(conn, '''
                SELECT yp.id, yp.first_name, yp.last_name, yp.dob,
                       NULL as role,
                       yp.passphrase as individual_passphrase,
                       (SELECT f.passphrase FROM youth_family_links yfl
                        JOIN families f ON f.id=yfl.family_id
                        WHERE yfl.youth_id=yp.id LIMIT 1) as family_passphrase,
                       ysi.id as sign_in_id, ysi.signed_in_at, ysi.signed_out_at
                FROM youth_program_enrollments ype
                JOIN youth_participants yp ON ype.youth_id=yp.id
                LEFT JOIN youth_sign_ins ysi ON ysi.youth_id=yp.id
                    AND ysi.event_id=%s AND ysi.signed_out_at IS NULL
                WHERE ype.program_id=%s
                ORDER BY yp.last_name, yp.first_name''', (event_id, program_id))

    conn.close()
    return jsonify(youth)


