# ── Notifications ──
@app.route('/api/notifications')
def get_notifications():
    err = require_auth()
    if err: return err
    conn = get_db()
    needs_action = []
    activity     = []

    # Pending hours awaiting approval
    try:
        pending = fetchall(conn, '''
            SELECT ph.id, ph.volunteer_id, ph.event, ph.event_id, ph.date,
                   ph.hours, ph.role, ph.notes, ph.status, ph.submitted_at, ph.source, ph.logged_by,
                   v.name as volunteer_name
            FROM pending_hours ph
            LEFT JOIN volunteers v ON ph.volunteer_id=v.id
            WHERE ph.status IN (\'pending\',\'pending_review\')
            ORDER BY ph.submitted_at DESC NULLS LAST
            LIMIT 100''')
        for ph in pending:
            is_override = ph.get('status') == 'pending_review'
            needs_action.append({
                'id':    ph['id'],
                'type':  'pending_hours',
                'icon':  '',
                'color': 'amber',
                'title': f'{ph["volunteer_name"] or "A volunteer"}  -  {ph["hours"]}h',
                'sub':   f'{ph["event"] or "General"} · {ph["date"] or ""}' +
                         (' · Needs review (no event)' if is_override else '') +
                         (f' · {HOURS_SOURCES.get(ph.get("source"), "")}' if ph.get('source') else '') +
                         (f' by {ph["logged_by"]}' if ph.get('logged_by') and ph.get('source') in ('house_manager', 'staff') else '') +
                         (f' · submitted {ph["submitted_at"].strftime("%b %-d, %-I:%M %p")}' if hasattr(ph.get('submitted_at'), 'strftime') else ''),
                'data':  ph,
            })
    except Exception as e:
        app.logger.warning(f'notifications pending_hours: {e}')

    # Profile update requests
    try:
        profiles = fetchall(conn, '''
            SELECT ph.id, ph.volunteer_id, ph.notes, ph.submitted_at,
                   v.name as volunteer_name
            FROM pending_hours ph
            LEFT JOIN volunteers v ON ph.volunteer_id=v.id
            WHERE ph.status = \'pending_profile\'
            ORDER BY ph.submitted_at DESC NULLS LAST LIMIT 20''')
        for p in profiles:
            needs_action.append({
                'id':    p['id'],
                'type':  'profile_update',
                'icon':  '',
                'color': 'blue',
                'title': f'{p["volunteer_name"] or "A volunteer"}  -  profile update',
                'sub':   'Requested profile change awaiting review',
                'data':  p,
            })
    except Exception as e:
        app.logger.warning(f'notifications profiles: {e}')

    # Show licensing requests awaiting action
    try:
        lic_requests = fetchall(conn, '''
            SELECT id, ref_number, production_name, licensor, requester_name, submitted_at
            FROM licensing_requests
            WHERE status = 'new'
            ORDER BY submitted_at DESC NULLS LAST
            LIMIT 50''')
        for lr in lic_requests:
            needs_action.append({
                'id':    lr['id'],
                'type':  'licensing_request',
                'icon':  '',
                'color': 'purple',
                'title': f'Licensing request  -  {lr["production_name"] or "Untitled production"}',
                'sub':   f'{lr.get("licensor") or "Licensor TBD"} · from {lr.get("requester_name") or "staff"} · Ref {lr["ref_number"]}',
                'data':  lr,
            })
    except Exception as e:
        app.logger.warning(f'notifications licensing_requests: {e}')

    # Licensing contracts expiring soon or already expired — needs a re-request
    try:
        lic_contracts = fetchall(conn, '''
            SELECT id, ref_number, production_name, licensor, contract_expires_date
            FROM licensing_requests
            WHERE contract_received = TRUE AND contract_expires_date IS NOT NULL
              AND contract_expires_date <= (CURRENT_DATE + INTERVAL '60 days')
            ORDER BY contract_expires_date ASC
            LIMIT 50''')
        for lr in lic_contracts:
            exp = lr.get('contract_expires_date')
            days_left = (exp - date.today()).days if exp else None
            expired = days_left is not None and days_left < 0
            needs_action.append({
                'id':    lr['id'],
                'type':  'licensing_contract_expiring',
                'icon':  '' if expired else '',
                'color': 'red' if expired else 'amber',
                'title': f'Licensing contract {"expired" if expired else "expiring soon"}  -  {lr["production_name"] or "Untitled production"}',
                'sub':   f'{lr.get("licensor") or "Licensor TBD"} · {"expired" if expired else "expires"} {exp.strftime("%b %d, %Y") if exp else ""} · Ref {lr["ref_number"]}',
                'data':  lr,
            })
    except Exception as e:
        app.logger.warning(f'notifications licensing_contracts: {e}')

    # Recent approved hours (activity feed)
    try:
        recent = fetchall(conn, '''
            SELECT h.*, v.name as volunteer_name
            FROM hours h LEFT JOIN volunteers v ON h.volunteer_id=v.id
            WHERE h.created_at >= NOW() - INTERVAL \'7 days\'
            ORDER BY h.created_at DESC LIMIT 20''')
        for h in recent:
            activity.append({
                'id':    h['id'],
                'type':  'hours_approved',
                'icon':  '',
                'color': 'green',
                'title': f'{h["volunteer_name"] or "Volunteer"}  -  {h["hours"]}h approved',
                'sub':   f'{h["event"] or ""} · {h["date"] or ""}',
                'data':  h,
            })
    except Exception as e:
        app.logger.warning(f'notifications activity: {e}')

    conn.close()
    return jsonify({
        'needs_action':  needs_action,
        'activity':      activity,
        'total_action':  len(needs_action),
    })

