@app.route('/api/elics/bulk-assign', methods=['POST'])
def bulk_assign_elics():
    """Add (or remove, or replace with) one or more ELICs on every event of
    a production or class, optionally only between two dates and/or on
    certain weekdays. dry_run returns the matching events without changing
    anything, for the preview."""
    err = require_admin()
    if err: return err
    d = request.json or {}
    elic_ids = [x for x in (d.get('elic_ids') or []) if x]
    mode = d.get('mode') if d.get('mode') in ('add', 'replace', 'remove') else 'add'
    prod_id, prog_id = d.get('production_id') or None, d.get('program_id') or None
    if not (prod_id or prog_id):
        return jsonify({'error': 'Pick a production or a class.'}), 400
    if not elic_ids and mode != 'replace':
        return jsonify({'error': 'Pick at least one ELIC.'}), 400
    q = '''SELECT id, name, event_date, start_time FROM events WHERE COALESCE(status,'') <> 'cancelled' '''
    params = []
    if prod_id:
        q += ' AND production_id=%s'; params.append(prod_id)
    if prog_id:
        q += ' AND program_id=%s'; params.append(prog_id)
    frm = (d.get('from') or '')[:10] or (today_eastern().isoformat() if not d.get('include_past') else '')
    to = (d.get('to') or '')[:10]
    if frm:
        q += ' AND event_date >= %s'; params.append(frm)
    if to:
        q += ' AND event_date <= %s'; params.append(to)
    conn = get_db()
    try:
        events = fetchall(conn, q + ' ORDER BY event_date, start_time', tuple(params)) or []
        days = set(int(x) for x in (d.get('weekdays') or []) if str(x).isdigit())   # 0=Mon … 6=Sun
        if days:
            import datetime as _dt
            def _wd(e):
                try: return _dt.date.fromisoformat(str(e['event_date'])[:10]).weekday()
                except Exception: return -1
            events = [e for e in events if _wd(e) in days]
        if d.get('dry_run'):
            return jsonify({'count': len(events), 'events': [{'id': e['id'], 'name': e['name'], 'date': str(e['event_date'])[:10],
                                                               'time': e.get('start_time') or ''} for e in events[:300]]})
        ids = [e['id'] for e in events]
        changed = 0
        if ids:
            if mode == 'replace':
                execute(conn, 'DELETE FROM event_elics WHERE event_id = ANY(%s)', (ids,))
            if mode == 'remove':
                execute(conn, 'DELETE FROM event_elics WHERE event_id = ANY(%s) AND elic_id = ANY(%s)', (ids, elic_ids))
                changed = len(ids)
            else:
                for eid in ids:
                    for lid in elic_ids:
                        execute(conn, 'INSERT INTO event_elics (id,event_id,elic_id) VALUES (%s,%s,%s) ON CONFLICT DO NOTHING',
                                (str(uuid.uuid4()), eid, lid))
                changed = len(ids)
        conn.commit()
        return jsonify({'ok': True, 'events': changed})
    finally:
        conn.close()


@app.route('/api/events/<eid>/elics', methods=['POST'])
def add_event_elic(eid):
    err = require_auth()
    if err: return err
    d = request.json or {}
    elic_id = d.get('elic_id')
    rid = str(uuid.uuid4())
    conn = get_db()
    execute(conn, 'INSERT INTO event_elics (id,event_id,elic_id) VALUES (%s,%s,%s) ON CONFLICT DO NOTHING',
        (rid, eid, elic_id))
    # Also sync to assigned_events on the elic record
    try:
        elic = fetchone(conn, 'SELECT assigned_events FROM elics WHERE id=%s', (elic_id,))
        if elic:
            assigned = json.loads(elic.get('assigned_events') or '[]')
            if eid not in assigned:
                assigned.append(eid)
                execute(conn, 'UPDATE elics SET assigned_events=%s WHERE id=%s', (json.dumps(assigned), elic_id))
    except Exception:
        pass
    conn.commit()
    # Return the full assignment record so frontend can push it properly
    row = fetchone(conn, """SELECT ee.id as assignment_id, el.id as elic_id,
        el.is_master, v.name as volunteer_name, v.id as volunteer_id,
        COALESCE(v.background_check_status,'none') as background_check_status
        FROM event_elics ee JOIN elics el ON ee.elic_id=el.id
        JOIN volunteers v ON el.volunteer_id=v.id
        WHERE ee.event_id=%s AND ee.elic_id=%s""", (eid, elic_id))
    conn.close()
    return jsonify(row or {'ok': True})
def remove_event_elic(eid, rid):
    err = require_auth()
    if err: return err
    conn = get_db()
    # Get elic_id before deleting
    row = fetchone(conn, 'SELECT elic_id FROM event_elics WHERE id=%s AND event_id=%s', (rid, eid))
    execute(conn, 'DELETE FROM event_elics WHERE id=%s AND event_id=%s', (rid, eid))
    # Sync assigned_events
    if row:
        try:
            elic = fetchone(conn, 'SELECT assigned_events FROM elics WHERE id=%s', (row['elic_id'],))
            if elic:
                assigned = json.loads(elic.get('assigned_events') or '[]')
                assigned = [e for e in assigned if e != eid]
                execute(conn, 'UPDATE elics SET assigned_events=%s WHERE id=%s', (json.dumps(assigned), row['elic_id']))
        except Exception:
            pass
    conn.commit(); conn.close()
    return jsonify({'ok': True})

@app.route('/api/events/default-elic')
def get_default_elic():
    err = require_auth()
    if err: return err
    prod_id = request.args.get('production_id')
    prog_id = request.args.get('program_id')
    conn = get_db()
    elic = None
    if prod_id:
        p = fetchone(conn, 'SELECT default_elic_id FROM productions WHERE id=%s', (prod_id,))
        if p and p.get('default_elic_id'):
            elic = fetchone(conn, '''SELECT e.*, v.name as volunteer_name FROM elics e
                JOIN volunteers v ON e.volunteer_id=v.id WHERE e.id=%s''', (p['default_elic_id'],))
    elif prog_id:
        p = fetchone(conn, 'SELECT default_elic_id, instructor_id FROM youth_programs WHERE id=%s', (prog_id,))
        if p:
            elic_id = p.get('default_elic_id')
            # Fall back to instructor's elic record if no default_elic_id set
            if not elic_id and p.get('instructor_id'):
                er = fetchone(conn, 'SELECT id FROM elics WHERE volunteer_id=%s', (p['instructor_id'],))
                if er: elic_id = er['id']
            if elic_id:
                elic = fetchone(conn, '''SELECT e.*, v.name as volunteer_name FROM elics e
                    JOIN volunteers v ON e.volunteer_id=v.id WHERE e.id=%s''', (elic_id,))
    conn.close()
    return jsonify({'elic': elic, 'elic_id': elic['id'] if elic else None})

