# ── Global error handlers  -  return JSON for all API errors ──
@app.errorhandler(500)
def internal_error(e):
    app.logger.error(f'500: {e}')
    return jsonify({'error': str(e)}), 500

@app.errorhandler(404)
def not_found(e):
    if request.path.startswith('/api/'):
        app.logger.warning(f'404 Route not found: {request.method} {request.path}')
        return jsonify({'error': 'Route not found'}), 404
    return e

@app.errorhandler(405)
def method_not_allowed(e):
    if request.path.startswith('/api/'):
        return jsonify({'error': 'Method not allowed'}), 405
    return e

@app.errorhandler(Exception)
def handle_exception(e):
    import traceback
    app.logger.error(f'Unhandled: {traceback.format_exc()}')
    # Try to clean up any aborted transaction
    try:
        from psycopg2 import DatabaseError
        conn = get_db()
        conn.rollback()
        conn.close()
    except Exception:
        pass
    return jsonify({'error': str(e)}), 500




