@app.route('/api/events/<eid>/household-drafts/clear', methods=['POST'])
def clear_household_drafts(eid):
    err = require_permission('events')
    if err: return err
    conn = get_db()
    execute(conn, 'DELETE FROM household_invite_drafts WHERE event_id=%s', (eid,))
    conn.commit(); conn.close()
    return jsonify({'ok': True})

@app.route('/api/events/<eid>/rsvp-invite', methods=['POST'])
def send_rsvp_invite(eid):
    err = require_permission('events')
    if err: return err
    d = request.json or {}
    conn = get_db()
    evt = fetchone(conn, 'SELECT * FROM events WHERE id=%s', (eid,))
    if not evt: conn.close(); return jsonify({'error': 'Event not found'}), 404
    if evt.get('status') == 'cancelled':
        conn.close(); return jsonify({'error': 'Cannot send invites for a cancelled event'}), 400

    # Get roles for this event
    roles = fetchall(conn, '''
        SELECT r.* FROM event_roles r
        WHERE r.event_id=%s ORDER BY r.sort_order, r.name''', (eid,))
    _rc = _role_headcounts_for_event(conn, eid)
    for _r in roles:
        _r['filled'] = _rc.get(_r['id'], 0)

    target_ids = d.get('volunteer_ids') or []
    if target_ids:
        vols = fetchall(conn, "SELECT id,name,email FROM volunteers WHERE id=ANY(%s) AND email IS NOT NULL", (target_ids,))
    elif d.get('adhoc_only'):
        vols = []
    else:
        _blk = suppressed_email_keys(conn)
        vols = [v for v in (fetchall(conn, "SELECT id,name,email FROM volunteers WHERE status='active' AND email!='' AND email IS NOT NULL") or [])
                if ticket_email_key(v['email']) not in _blk]

    # Ad hoc contacts: people not in the Volunteers list at all (e.g. community members
    # for an open house). Pasted as free text, one per line: "Name, email" or just "email".
    adhoc_raw = (d.get('adhoc_contacts') or '').strip()
    if adhoc_raw:
        vols = list(vols)
        for raw_line in adhoc_raw.splitlines():
            raw_line = raw_line.strip()
            if not raw_line: continue
            # Accept "Name, email@x.com" / "Name <email@x.com>" / just "email@x.com"
            m = re.search(r'[\w\.\+\-]+@[\w\-]+\.[\w\.\-]+', raw_line)
            if not m: continue
            email_addr = m.group(0).strip().lower()
            name_part = raw_line.replace(m.group(0), '').strip(' ,<>-')
            vols.append({'id': None, 'name': name_part or email_addr.split('@')[0], 'email': email_addr})

    # Household / party invites: each is one invite record covering multiple named
    # guests (e.g. "The Smith Family: John, Jane, Tommy, Sally") who each get checked
    # off individually on the RSVP page, rather than an open name/email form.
    # Accepts either a single household (household_members/household_email/household_label)
    # or a batch (households: [{members, email, label}, ...]) so a whole list can be
    # built up and sent in one go.
    party_names_by_email = {}
    role_by_email = {}
    is_household_send = False
    households_batch = d.get('households') or []
    if not households_batch:
        single_members = [n.strip() for n in (d.get('household_members') or []) if (n or '').strip()]
        single_email = (d.get('household_email') or '').strip().lower()
        single_label = (d.get('household_label') or '').strip()
        if single_members and single_email:
            households_batch = [{'members': single_members, 'email': single_email, 'label': single_label, 'role_id': d.get('assign_role_id') or ''}]

    if households_batch:
        is_household_send = True
        vols = []
        seen_emails = set()
        for h in households_batch:
            h_email = (h.get('email') or '').strip().lower()
            h_members = [n.strip() for n in (h.get('members') or []) if (n or '').strip()]
            h_label = (h.get('label') or '').strip()
            h_role_id = (h.get('role_id') or '').strip()
            if not h_email or not h_members or h_email in seen_emails:
                continue
            seen_emails.add(h_email)
            display_name = h_label or (h_members[0] if len(h_members) == 1 else f'{h_members[0]} + {len(h_members)-1} more')
            vols.append({'id': None, 'name': display_name, 'email': h_email})
            party_names_by_email[h_email] = h_members
            if h_role_id:
                role_by_email[h_email] = h_role_id

    is_guest = evt.get('rsvp_kind') == 'guest'
    kind_label = 'Community Invite' if is_guest else 'Volunteer Opportunity'
    intro_line = "We're hosting an event and would love for you to join us!" if is_guest else "We're looking for volunteers for an upcoming event and would love to have you join us!"
    slot_word = 'Time Slot' if is_guest else 'Role'
    footer_note = "If you're unable to attend, no need to reply — we just wanted to make sure you had the invite." if is_guest else "If you're unable to attend, no action is needed — we only want to hear from those who can volunteer."

    # Pre-assign everyone in this batch to a specific block, if requested — their
    # personalized link will then show just that block instead of the full picker.
    assign_role_id = (d.get('assign_role_id') or '').strip()
    assign_role_name = ''
    if assign_role_id:
        assigned_role = next((r for r in roles if r['id'] == assign_role_id), None)
        if assigned_role:
            assign_role_name = assigned_role['name']
        else:
            assign_role_id = ''

    cta_label = (" Yes, I'll Be There!" if not roles or assign_role_id else " RSVP & Choose a Time") if is_guest else (" Yes, I Can Help!" if not roles else " Sign Up & Choose a Role")

    sent = 0
    skipped = 0
    skipped_names = []
    custom_msg = (d.get('message') or '').strip()
    force_resend = bool(d.get('force_resend', False))
    base_url = request.host_url.rstrip('/')

    # Build roles/slots table HTML for email (skipped if everyone's pre-assigned to one block)
    roles_html = ''
    if roles and not assign_role_id:
        roles_html = f'<h3 style="color:#145466;margin-top:24px;font-size:15px">Available {slot_word}s</h3>'
        roles_html += '<table style="width:100%;border-collapse:collapse;font-size:14px;margin:8px 0;border:1px solid #e2e8f0">'
        roles_html += f'<thead><tr style="background:#f0fdf4"><th style="padding:8px 12px;text-align:left;border-bottom:2px solid #e2e8f0">{slot_word}</th><th style="padding:8px 12px;text-align:left;border-bottom:2px solid #e2e8f0">Open Spots</th></tr></thead><tbody>'
        for r in roles:
            available = max(0, int(r['slots']) - int(r['filled'] or 0))
            roles_html += f'<tr style="border-bottom:1px solid #f0f0f0"><td style="padding:8px 12px;font-weight:600">{r["name"]}</td>'
            roles_html += f'<td style="padding:8px 12px;color:{"#16a34a" if available>0 else "#dc2626"};font-weight:600">{available} of {r["slots"]} open</td></tr>'
        roles_html += f'</tbody></table><p style="font-size:13px;color:#888">You can choose your preferred {slot_word.lower()} when you RSVP.</p>'
    elif assign_role_id and not evt.get('hide_block_names'):
        roles_html = f'''<div style="background:#f0f8fa;border:1.5px solid #c9e4ea;border-radius:10px;padding:14px 18px;margin:18px 0">
            <div style="font-size:11px;font-weight:700;color:#145466;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:4px">Your {slot_word}</div>
            <div style="font-size:16px;font-weight:700;color:#0d3d4d">{assign_role_name}</div>
        </div>'''

    # Load the editable email templates once (Settings > Email Templates); fall back to
    # the hardcoded defaults below only if a row is somehow missing.
    household_tmpl = get_system_template(conn, 'rsvp_invite_household')
    general_tmpl = get_system_template(conn, 'rsvp_invite_general')

    for v in vols:
        if not v.get('email'): continue
        if v.get('id'):
            existing = fetchone(conn, 'SELECT id, token, status, last_invited_at FROM event_rsvps WHERE event_id=%s AND volunteer_id=%s', (eid, v['id']))
        else:
            existing = fetchone(conn, 'SELECT id, token, status, last_invited_at FROM event_rsvps WHERE event_id=%s AND volunteer_id IS NULL AND LOWER(volunteer_email)=LOWER(%s)', (eid, v['email']))

        # Skip if already signed up (interested/confirmed)
        if existing and existing.get('status') in ('interested', 'confirmed'):
            skipped += 1
            skipped_names.append(v['name'])
            continue

        # Skip if invited recently (within 24h) unless force_resend
        if existing and existing.get('last_invited_at') and not force_resend:
            from datetime import datetime as _dt2
            last_sent = existing['last_invited_at']
            last_sent_dt = parse_db_datetime(last_sent)
            if last_sent_dt is None: last_sent_dt = _dt2.utcnow()
            diff = (_dt2.utcnow() - last_sent_dt).total_seconds()
            if diff < 86400:  # 24 hours
                skipped += 1
                skipped_names.append(v['name'])
                continue

        party_json = json.dumps([{'name': n, 'attending': None} for n in party_names_by_email[v['email']]]) if v['email'] in party_names_by_email else None

        # A household can carry its own block assignment (picked while it was being added
        # to the list); otherwise fall back to the batch-wide "Assign to Block" choice.
        this_role_id = role_by_email.get(v['email']) or assign_role_id
        this_role_name = ''
        this_block_time = ''
        if this_role_id:
            this_role = next((r for r in roles if r['id'] == this_role_id), None)
            this_role_name = this_role['name'] if this_role else ''
            if this_role:
                bt = _fmt_time(this_role.get('block_time'))
                bte = _fmt_time(this_role.get('block_time_end'))
                this_block_time = f'{bt} – {bte}' if bt and bte else (bt or '')
            if not this_role: this_role_id = ''

        if existing:
            token = existing['token']
            if party_json is not None:
                execute(conn, 'UPDATE event_rsvps SET last_invited_at=NOW(), role_id=%s, role_name=%s, party_members=%s WHERE id=%s',
                    (this_role_id or None, this_role_name or None, party_json, existing['id']))
            else:
                execute(conn, 'UPDATE event_rsvps SET last_invited_at=NOW(), role_id=%s, role_name=%s WHERE id=%s',
                    (this_role_id or None, this_role_name or None, existing['id']))
        else:
            token = str(uuid.uuid4())
            execute(conn, '''INSERT INTO event_rsvps (id,event_id,volunteer_id,volunteer_name,volunteer_email,token,role_id,role_name,status,last_invited_at,party_members)
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,'invited',NOW(),%s)''',
                (str(uuid.uuid4()), eid, v['id'], v['name'], v['email'], token, this_role_id or None, this_role_name or None, party_json or ''))
        # Commit immediately — the RSVP link is only useful if this row survives even
        # when something later in this same iteration (template render, SMTP) blows up.
        conn.commit()

        rsvp_url = f"{base_url}/rsvp/{token}"
        date_str = evt.get('event_date','')
        time_str = evt.get('start_time','')
        if time_str:
            try:
                from datetime import datetime as _dt
                t = _dt.strptime(time_str, '%H:%M')
                time_str = t.strftime('%I:%M %p').lstrip('0')
            except Exception:
                pass

        try:
            if is_household_send:
                guest_list_html = ''.join(f'<li style="padding:3px 0;color:#374151">{n}</li>' for n in party_names_by_email.get(v['email'], []))
                guest_list_block = f'''<div style="margin-top:28px">
              <div style="font-family:Helvetica,Arial,sans-serif;font-size:12px;font-weight:600;letter-spacing:0.5px;text-transform:uppercase;color:#6b7280;margin-bottom:8px">This Invitation Includes</div>
              <ul style="font-family:Helvetica,Arial,sans-serif;font-size:14px;margin:0;padding-left:18px;line-height:1.6">{guest_list_html}</ul>
            </div>''' if len(party_names_by_email.get(v['email'], [])) > 1 else ''
                date_row = f'<tr><td style="padding:11px 0;color:#6b7280;font-size:13px;width:110px;vertical-align:top;border-bottom:1px solid #e5e7eb">Date</td><td style="padding:11px 0;color:#1f2937;font-size:14px;font-weight:500;border-bottom:1px solid #e5e7eb">{date_str}</td></tr>'
                display_time = this_block_time or time_str
                time_row = f'<tr><td style="padding:11px 0;color:#6b7280;font-size:13px;vertical-align:top;border-bottom:1px solid #e5e7eb">Time</td><td style="padding:11px 0;color:#1f2937;font-size:14px;font-weight:500;border-bottom:1px solid #e5e7eb">{display_time}</td></tr>' if display_time else ''
                location_row = f'<tr><td style="padding:11px 0;color:#6b7280;font-size:13px;vertical-align:top;border-bottom:1px solid #e5e7eb">Location</td><td style="padding:11px 0;color:#1f2937;font-size:14px;font-weight:500;border-bottom:1px solid #e5e7eb">{evt["location"]}</td></tr>' if evt.get('location') else ''
                address_row = f'<tr><td style="padding:11px 0;color:#6b7280;font-size:13px;vertical-align:top;border-bottom:1px solid #e5e7eb">Address</td><td style="padding:11px 0;color:#1f2937;font-size:14px;font-weight:500;border-bottom:1px solid #e5e7eb">{evt["address"]}</td></tr>' if evt.get('address') else ''
                # keep the paragraphs and line breaks people typed (it used to run together)
                custom_message_block = (f'<div style="font-family:Helvetica,Arial,sans-serif;font-size:14px;line-height:1.7;color:#4b5563;margin:20px 0 0">{message_text_html(custom_msg)}</div>'
                                        if custom_msg else '')
                description_block = (f'<div style="font-family:Helvetica,Arial,sans-serif;font-size:14px;line-height:1.7;color:#4b5563;margin:20px 0 0">{message_text_html(evt["description"])}</div>'
                                     if evt.get('description') else '')
                tmpl_vars = {
                    'recipient_name': v['name'], 'event_name': evt['name'],
                    'details_table': date_row + time_row + location_row + address_row,
                    'time': display_time, 'block_time': this_block_time, 'block_name': this_role_name,
                    'location': evt.get('location') or '', 'address': evt.get('address') or '',
                    'custom_message_block': custom_message_block, 'description_block': description_block,
                    'guest_list_block': guest_list_block, 'rsvp_url': rsvp_url,
                }
                tmpl_body = household_tmpl['body'] if household_tmpl else RSVP_INVITE_HOUSEHOLD_BODY_DEFAULT
                tmpl_subject = household_tmpl['subject'] if household_tmpl else RSVP_INVITE_TEMPLATE_DEFS[0][2]
                body = render_template_vars(tmpl_body, tmpl_vars)
                email_subject = render_template_vars(tmpl_subject, tmpl_vars)
            else:
                date_row = f'<tr style="background:#f0f8fa"><td style="padding:10px 14px;font-weight:700;color:#145466;width:100px"> Date</td><td style="padding:10px 14px;font-weight:600">{date_str}</td></tr>'
                display_time = this_block_time or time_str
                time_row = f'<tr><td style="padding:10px 14px;font-weight:700;color:#145466"> Time</td><td style="padding:10px 14px">{display_time}</td></tr>' if display_time else ''
                location_row = f'<tr style="background:#f0f8fa"><td style="padding:10px 14px;font-weight:700;color:#145466"> Location</td><td style="padding:10px 14px">{evt["location"]}</td></tr>' if evt.get('location') else ''
                address_row = f'<tr><td style="padding:10px 14px;font-weight:700;color:#145466"> Address</td><td style="padding:10px 14px">{evt["address"]}</td></tr>' if evt.get('address') else ''
                custom_message_block = (f'<div style="background:#fff8e7;border-left:3px solid #f59e0b;padding:14px 18px 4px;margin:16px 0;border-radius:0 6px 6px 0;color:#374151;font-size:15px">{message_text_html(custom_msg)}</div>'
                                        if custom_msg else '')
                description_block = (f'<div style="color:#4b5563;font-size:14px;margin:12px 0">{message_text_html(evt["description"])}</div>'
                                     if evt.get('description') else '')
                tmpl_vars = {
                    'recipient_name': v['name'], 'recipient_email': v['email'],
                    'kind_emoji': '' if is_guest else '', 'kind_label': kind_label, 'event_name': evt['name'],
                    'intro_line': intro_line, 'details_table': date_row + time_row + location_row + address_row,
                    'time': display_time, 'block_time': this_block_time, 'block_name': this_role_name,
                    'location': evt.get('location') or '', 'address': evt.get('address') or '',
                    'custom_message_block': custom_message_block, 'description_block': description_block,
                    'roles_block': roles_html, 'rsvp_url': rsvp_url, 'cta_label': cta_label, 'footer_note': footer_note,
                }
                tmpl_body = general_tmpl['body'] if general_tmpl else RSVP_INVITE_GENERAL_BODY_DEFAULT
                tmpl_subject = general_tmpl['subject'] if general_tmpl else RSVP_INVITE_TEMPLATE_DEFS[1][2]
                body = render_template_vars(tmpl_body, tmpl_vars)
                email_subject = render_template_vars(tmpl_subject, tmpl_vars)

            fi = d.get('from_identity') or {}
            send_email([v['email']], email_subject, build_hwtc_email_html(email_subject, body + unsubscribe_footer(v['email'])), fi.get('email') or None, fi.get('name') or None)
            sent += 1
            log_volunteer_comm(conn, v['id'], f'Volunteer Opportunity: {evt["name"]}', 'volunteer_opportunity', session.get('user_name','admin'), v['email'])
            conn.commit()
            # Small delay between emails to avoid rate limiting
            import time as _time
            if sent % 10 == 0:
                _time.sleep(1)
        except Exception as e:
            import traceback
            app.logger.warning(f'RSVP invite email failed for {v["email"]}: {e}\n{traceback.format_exc()}')
            try: conn.rollback()
            except Exception: pass

    conn.close()
    return jsonify({'ok': True, 'sent': sent, 'skipped': skipped, 'skipped_names': skipped_names})

def _role_headcount(conn, role_id):
    """Real attendee headcount for a block/role — counts each individual attending
    guest in a household RSVP, not just one per invite."""
    rows = fetchall(conn, "SELECT party_members FROM event_rsvps WHERE role_id=%s AND status IN ('interested','confirmed')", (role_id,)) or []
    total = 0
    for r in rows:
        pm = r.get('party_members')
        if pm:
            try:
                members = json.loads(pm)
                total += sum(1 for m in members if m.get('attending') is True)
            except Exception:
                total += 1
        else:
            total += 1
    return total

def _role_headcounts_for_event(conn, event_id):
    """Headcounts for every role/block on an event, keyed by role_id — one query pass
    instead of N (used when rendering a role list)."""
    rsvps = fetchall(conn, "SELECT role_id, party_members FROM event_rsvps WHERE event_id=%s AND status IN ('interested','confirmed') AND role_id IS NOT NULL", (event_id,)) or []
    counts = {}
    for r in rsvps:
        rid = r['role_id']
        pm = r.get('party_members')
        if pm:
            try:
                members = json.loads(pm)
                counts[rid] = counts.get(rid, 0) + sum(1 for m in members if m.get('attending') is True)
                continue
            except Exception:
                pass
        counts[rid] = counts.get(rid, 0) + 1
    return counts

def _production_producer_contacts(conn, production_id):
    """Producer(s) on a production's roster, for 'questions? contact...' on sign-up pages.
    Matches any role containing 'producer' (Producer, Associate Producer, Resident
    Producer, Executive Producer, etc.) — director-only shows aren't shown here."""
    if not production_id:
        return []
    rows = fetchall(conn, '''SELECT v.name, v.email, v.phone, pm.role
        FROM production_members pm JOIN volunteers v ON pm.volunteer_id=v.id
        WHERE pm.production_id=%s AND pm.role ILIKE %s
        ORDER BY pm.created_at''', (production_id, '%producer%')) or []
    return rows

def _foh_training_passed(conn, email):
    """Whether this email has a passing Front of House training result on file."""
    if not email:
        return False
    row = fetchone(conn, """SELECT id FROM foh_training_results
        WHERE LOWER(email)=LOWER(%s) AND passed=TRUE ORDER BY created_at DESC LIMIT 1""", (email.strip(),))
    return bool(row)

# ── Front of House Training & Quiz ──────────────────────────────

@app.route('/api/foh-training')
def get_foh_training():
    err = require_permission('foh_training', 'view')
    if err: return err
    conn = get_db()
    training = fetchone(conn, 'SELECT * FROM foh_training ORDER BY updated_at DESC LIMIT 1')
    questions = fetchall(conn, 'SELECT * FROM foh_quiz_questions ORDER BY sort_order, created_at')
    for q in questions:
        try: q['options'] = json.loads(q.get('options') or '[]')
        except Exception: q['options'] = []
    conn.close()
    return jsonify({'training': training, 'questions': questions})

@app.route('/api/foh-training', methods=['PUT'])
def update_foh_training():
    err = require_permission('foh_training', 'edit')
    if err: return err
    d = request.json or {}
    conn = get_db()
    training = fetchone(conn, 'SELECT id FROM foh_training ORDER BY updated_at DESC LIMIT 1')
    if not training:
        conn.close()
        return jsonify({'error': 'Training module not found'}), 404
    execute(conn, '''UPDATE foh_training SET title=%s, description=%s, pass_percent=%s, updated_at=NOW()
        WHERE id=%s''',
        ((d.get('title') or 'Front of House Support Training').strip(),
         (d.get('description') or '').strip(),
         int(d.get('pass_percent') or 80), training['id']))
    conn.commit()
    row = fetchone(conn, 'SELECT * FROM foh_training WHERE id=%s', (training['id'],))
    conn.close()
    return jsonify(row)

@app.route('/api/foh-training/slides/upload', methods=['POST'])
def upload_foh_training_slides():
    err = require_permission('foh_training', 'edit')
    if err: return err
    if 'file' not in request.files: return jsonify({'error': 'No file'}), 400
    f = request.files['file']
    ext = os.path.splitext(secure_filename(f.filename))[1].lower()
    if ext not in ('.ppt', '.pptx', '.pdf'):
        return jsonify({'error': 'Please upload a PowerPoint (.ppt/.pptx) or PDF file'}), 400
    conn = get_db()
    training = fetchone(conn, 'SELECT id, slides_filename FROM foh_training ORDER BY updated_at DESC LIMIT 1')
    if not training:
        conn.close()
        return jsonify({'error': 'Training module not found'}), 404
    filename = f'foh-training-{str(uuid.uuid4())[:8]}{ext}'
    f.save(os.path.join(UPLOAD_FOLDER, filename))
    old_filename = training.get('slides_filename')
    execute(conn, '''UPDATE foh_training SET slides_url=%s, slides_filename=%s, slides_original_name=%s, updated_at=NOW()
        WHERE id=%s''', (f'/api/foh-training/slides', filename, f.filename or filename, training['id']))
    conn.commit()
    if old_filename:
        try: os.remove(os.path.join(UPLOAD_FOLDER, old_filename))
        except Exception: pass
    row = fetchone(conn, 'SELECT * FROM foh_training WHERE id=%s', (training['id'],))
    conn.close()
    return jsonify(row)

@app.route('/api/foh-training/slides')
def download_foh_training_slides():
    conn = get_db()
    training = fetchone(conn, 'SELECT slides_filename, slides_original_name FROM foh_training ORDER BY updated_at DESC LIMIT 1')
    conn.close()
    if not training or not training.get('slides_filename'):
        return jsonify({'error': 'No slides uploaded yet'}), 404
    filepath = os.path.join(UPLOAD_FOLDER, training['slides_filename'])
    if not os.path.exists(filepath):
        return jsonify({'error': 'File not found'}), 404
    return send_file(filepath, as_attachment=True, download_name=training.get('slides_original_name') or training['slides_filename'])

@app.route('/api/foh-training/questions', methods=['POST'])
def create_foh_question():
    err = require_permission('foh_training', 'edit')
    if err: return err
    d = request.json or {}
    options = d.get('options') or []
    if not (d.get('question') or '').strip() or len(options) < 2:
        return jsonify({'error': 'Question and at least 2 options are required'}), 400
    qid = str(uuid.uuid4())
    conn = get_db()
    max_sort = fetchone(conn, 'SELECT COALESCE(MAX(sort_order),-1) as m FROM foh_quiz_questions')
    execute(conn, '''INSERT INTO foh_quiz_questions (id,question,options,correct_index,sort_order)
        VALUES (%s,%s,%s,%s,%s)''',
        (qid, d['question'].strip(), json.dumps(options), int(d.get('correct_index') or 0), (max_sort['m'] if max_sort else -1) + 1))
    conn.commit()
    row = fetchone(conn, 'SELECT * FROM foh_quiz_questions WHERE id=%s', (qid,))
    row['options'] = json.loads(row['options'])
    conn.close()
    return jsonify(row)

@app.route('/api/foh-training/questions/<qid>', methods=['PUT'])
def update_foh_question(qid):
    err = require_permission('foh_training', 'edit')
    if err: return err
    d = request.json or {}
    options = d.get('options') or []
    if not (d.get('question') or '').strip() or len(options) < 2:
        return jsonify({'error': 'Question and at least 2 options are required'}), 400
    conn = get_db()
    execute(conn, '''UPDATE foh_quiz_questions SET question=%s, options=%s, correct_index=%s WHERE id=%s''',
        (d['question'].strip(), json.dumps(options), int(d.get('correct_index') or 0), qid))
    conn.commit()
    row = fetchone(conn, 'SELECT * FROM foh_quiz_questions WHERE id=%s', (qid,))
    row['options'] = json.loads(row['options'])
    conn.close()
    return jsonify(row)

@app.route('/api/foh-training/questions/<qid>', methods=['DELETE'])
def delete_foh_question(qid):
    err = require_permission('foh_training', 'edit')
    if err: return err
    conn = get_db()
    execute(conn, 'DELETE FROM foh_quiz_questions WHERE id=%s', (qid,))
    conn.commit(); conn.close()
    return jsonify({'ok': True})

@app.route('/api/foh-training/results')
def get_foh_training_results():
    """Latest attempt per email, newest first — for admin review of who's cleared to sign up."""
    err = require_permission('foh_training', 'view')
    if err: return err
    conn = get_db()
    rows = fetchall(conn, '''SELECT DISTINCT ON (LOWER(email)) *
        FROM foh_training_results ORDER BY LOWER(email), created_at DESC''')
    rows.sort(key=lambda r: r['created_at'], reverse=True)
    conn.close()
    return jsonify(rows)

@app.route('/foh-training')
def foh_training_page():
    """Public training page: shows the slides + quiz. ?redirect=<url> sends the volunteer
    back to the RSVP link they came from once they pass; ?email=&name= prefill the form."""
    conn = get_db()
    training = fetchone(conn, 'SELECT * FROM foh_training ORDER BY updated_at DESC LIMIT 1')
    questions = fetchall(conn, 'SELECT id, question, options FROM foh_quiz_questions ORDER BY sort_order, created_at')
    conn.close()
    for q in questions:
        try: q['options'] = json.loads(q.get('options') or '[]')
        except Exception: q['options'] = []
    redirect_url = request.args.get('redirect', '').strip()
    prefill_email = (request.args.get('email','') or '').strip()
    prefill_name = (request.args.get('name','') or '').strip()
    slides_url = (training or {}).get('slides_url') or ''
    if slides_url:
        slides_html = ('<div class="gi-details" style="text-align:center">'
          '<div style="font-size:13px;color:#6b6b64;margin-bottom:8px">Step 1: review the training slides</div>'
          '<a href="' + slides_url + '" target="_blank" class="gi-btn-secondary" style="display:inline-block;text-decoration:none;width:auto;padding:10px 22px">Download / View Slides</a>'
          '</div>')
    else:
        slides_html = '<div class="gi-details" style="color:#8a8477;font-size:13px">No slides have been uploaded yet — please check with your producer, then complete the quiz below.</div>'
    question_blocks = []
    for i, q in enumerate(questions):
        qid = q.get('id') or ''
        qtext = q.get('question') or ''
        opts = q.get('options') or []
        option_labels = []
        for oi, opt in enumerate(opts):
            option_labels.append(
                '<label style="display:flex;gap:8px;align-items:center;padding:6px 0;cursor:pointer;font-size:13.5px">'
                '<input type="radio" name="q_' + qid + '" value="' + str(oi) + '" style="accent-color:#145466"/> ' + opt + '</label>'
            )
        question_blocks.append(
            '<div class="gi-details" style="text-align:left;margin-top:12px">'
            '<div style="font-weight:700;font-size:14px;margin-bottom:8px">' + str(i+1) + '. ' + qtext + '</div>'
            + ''.join(option_labels) + '</div>'
        )
    questions_html = ''.join(question_blocks)
    training_title = (training or {}).get('title') or 'Front of House Support Training'
    training_desc = (training or {}).get('description') or ''
    pass_percent_val = (training or {}).get('pass_percent', 80)
    desc_html = ('<p class="gi-desc">' + training_desc + '</p>') if training_desc else ''
    no_questions_html = '<div style="color:#8a8477;font-size:13px">No quiz questions have been set up yet.</div>'
    questions_or_placeholder = questions_html if questions_html else no_questions_html
    return f'''<html><head><title>{training_title}</title>
    <meta name="viewport" content="width=device-width,initial-scale=1">
    {_guest_invite_css()}
    </head>
    <body class="gi-body">
      <div class="gi-wrap">
        <div class="gi-no-image-hero">
          <div class="gi-eyebrow" style="color:rgba(255,255,255,0.85)">Front of House</div>
          <div class="gi-headline-plain">{training_title}</div>
        </div>
        {desc_html}
        {slides_html}
        <div id="foh-alert"></div>
        <div class="gi-card">
          <label class="gi-label">Your Name *</label>
          <input type="text" id="foh-name" required class="gi-input" value="{prefill_name}" placeholder="Full name"/>
          <label class="gi-label">Email *</label>
          <input type="email" id="foh-email" required class="gi-input" value="{prefill_email}" placeholder="you@example.com"/>
          <div style="font-weight:700;font-size:13px;margin:16px 0 4px">Step 2: pass the quiz ({pass_percent_val}% or higher)</div>
          {questions_or_placeholder}
          <button type="button" id="foh-submit-btn" onclick="submitFohQuiz()" class="gi-btn" style="margin-top:14px">Submit</button>
        </div>
        <div class="gi-footer"><img src="https://rolecall.hwtco.org/static/images/hwtc_logo_teal.png" alt="HWTC"/>Horizon West Theater Company</div>
      </div>
      <script>
      async function submitFohQuiz(){{
        var name = document.getElementById('foh-name').value.trim()
        var email = document.getElementById('foh-email').value.trim()
        if(!name || !email){{
          document.getElementById('foh-alert').innerHTML = '<div style="background:#fee2e2;color:#991b1b;border-radius:12px;padding:12px 16px;margin-bottom:14px;font-size:13px">Please fill in your name and email.</div>'
          return
        }}
        var answers = {{}}
        document.querySelectorAll('input[type=radio]:checked').forEach(function(inp){{
          answers[inp.name.replace('q_','')] = parseInt(inp.value)
        }})
        var btn = document.getElementById('foh-submit-btn')
        btn.disabled = true; btn.textContent = 'Grading…'
        var r = await fetch('/api/foh-training/submit', {{method:'POST', headers:{{'Content-Type':'application/json'}},
          body: JSON.stringify({{name:name, email:email, answers:answers}})}})
        var data = await r.json()
        btn.disabled = false; btn.textContent = 'Submit'
        if(data.error){{
          document.getElementById('foh-alert').innerHTML = '<div style="background:#fee2e2;color:#991b1b;border-radius:12px;padding:12px 16px;margin-bottom:14px;font-size:13px">'+data.error+'</div>'
          return
        }}
        if(data.passed){{
          var redirectUrl = {json.dumps(redirect_url)}
          document.body.innerHTML = '<div style="text-align:center;padding:60px 20px;max-width:500px;margin:0 auto;font-family:-apple-system,sans-serif">'
            + '<div style="font-size:48px;margin-bottom:16px">✓</div><h2 style="color:#145466">You passed! ('+data.score+'/'+data.total+')</h2>'
            + '<p style="color:#6b7280">You\\'re all set — you can now sign up for Front of House shifts.</p>'
            + (redirectUrl ? '<p><a href="'+redirectUrl+'" style="color:#145466;font-weight:700">Continue to your shift sign-up →</a></p>' : '')
            + '</div>'
        }} else {{
          document.getElementById('foh-alert').innerHTML = '<div style="background:#fee2e2;color:#991b1b;border-radius:12px;padding:12px 16px;margin-bottom:14px;font-size:13px">Score: '+data.score+'/'+data.total+' — that\\'s below the passing bar. Please review the slides and try again.</div>'
        }}
      }}
      </script>
    </body></html>'''

@app.route('/api/foh-training/submit', methods=['POST'])
def submit_foh_training():
    d = request.json or {}
    name = (d.get('name') or '').strip()
    email = (d.get('email') or '').strip()
    answers = d.get('answers') or {}
    if not name or not email:
        return jsonify({'error': 'Please provide your name and email.'}), 400
    conn = get_db()
    training = fetchone(conn, 'SELECT pass_percent FROM foh_training ORDER BY updated_at DESC LIMIT 1')
    questions = fetchall(conn, 'SELECT id, correct_index FROM foh_quiz_questions')
    if not questions:
        conn.close()
        return jsonify({'error': 'No quiz questions are set up yet — please contact your producer.'}), 400
    score = 0
    for q in questions:
        given = answers.get(q['id'])
        if given is not None and int(given) == int(q['correct_index']):
            score += 1
    total = len(questions)
    pass_percent = (training or {}).get('pass_percent', 80)
    passed = (score / total * 100) >= pass_percent if total else False
    volunteer = fetchone(conn, 'SELECT id FROM volunteers WHERE LOWER(email)=LOWER(%s)', (email,))
    execute(conn, '''INSERT INTO foh_training_results (id,volunteer_id,name,email,score,total,passed)
        VALUES (%s,%s,%s,%s,%s,%s,%s)''',
        (str(uuid.uuid4()), volunteer['id'] if volunteer else None, name, email, score, total, passed))
    conn.commit()
    conn.close()
    return jsonify({'ok': True, 'passed': passed, 'score': score, 'total': total})

def _fmt_time(t):
    """Format a 'HH:MM' 24-hour string as '2:30 PM'. Returns '' if unparseable/empty."""
    if not t:
        return ''
    try:
        return datetime.strptime(t, '%H:%M').strftime('%I:%M %p').lstrip('0')
    except Exception:
        return t

