#  SQUARE INTEGRATION & REGISTRATION SYSTEM
# ═══════════════════════════════════════════════════════════════════════

SQUARE_ACCESS_TOKEN = os.environ.get('SQUARE_ACCESS_TOKEN', '')
SQUARE_LOCATION_ID  = os.environ.get('SQUARE_LOCATION_ID', '')
SQUARE_APPLICATION_ID = os.environ.get('SQUARE_APPLICATION_ID', '')
SQUARE_WEBHOOK_SIG  = os.environ.get('SQUARE_WEBHOOK_SIGNATURE_KEY', '')
SQUARE_ENV          = os.environ.get('SQUARE_ENV', 'sandbox')  # 'sandbox' or 'production'
SQUARE_API_BASE     = 'https://connect.squareup.com' if SQUARE_ENV == 'production' else 'https://connect.squareupsandbox.com'
APP_BASE_URL        = os.environ.get('APP_BASE_URL', 'https://rolecall.hwtco.org')

def square_headers():
    return {'Authorization': f'Bearer {SQUARE_ACCESS_TOKEN}', 'Content-Type': 'application/json', 'Square-Version': '2024-01-18'}


def get_or_create_rolecall_category_id():
    """Find (or create) a Square catalog category that RoleCall-created items
    get tagged with, so the 'Linked Catalog Item' dropdown can filter down to
    just those instead of listing every item in the whole Square account
    (concessions, merch, everything else). Cached in the settings table."""
    if not SQUARE_ACCESS_TOKEN:
        return None
    conn = get_db()
    row = fetchone(conn, "SELECT value FROM settings WHERE key='square_rolecall_category_id'")
    if row and row.get('value'):
        conn.close()
        return row['value']
    try:
        r = requests.post(f'{SQUARE_API_BASE}/v2/catalog/search',
            json={'object_types': ['CATEGORY'],
                  'query': {'exact_query': {'attribute_name': 'name', 'attribute_value': 'RoleCall Programs'}}},
            headers=square_headers(), timeout=10)
        objs = (r.json().get('objects') or []) if r.status_code == 200 else []
        if objs:
            cat_id = objs[0]['id']
        else:
            import uuid as _uuid_cat
            r2 = requests.post(f'{SQUARE_API_BASE}/v2/catalog/object', headers=square_headers(), timeout=10, json={
                'idempotency_key': str(_uuid_cat.uuid4()),
                'object': {'type': 'CATEGORY', 'id': '#category_rolecall', 'category_data': {'name': 'RoleCall Programs'}}
            })
            cat_id = r2.json().get('catalog_object', {}).get('id') if r2.status_code == 200 else None
        if cat_id:
            execute(conn, """INSERT INTO settings (key,value) VALUES ('square_rolecall_category_id',%s)
                ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value""", (cat_id,))
            conn.commit()
        conn.close()
        return cat_id
    except Exception as e:
        app.logger.warning(f'get_or_create_rolecall_category_id failed: {e}')
        conn.close()
        return None


def square_find_or_create_customer(email, name='', phone=''):
    """Find a Square customer by email, or create one. Used for card-on-file holds.
    Returns customer_id or None."""
    if not SQUARE_ACCESS_TOKEN or not email:
        return None
    try:
        r = requests.post(f'{SQUARE_API_BASE}/v2/customers/search',
            json={'query': {'filter': {'email_address': {'exact': email}}}},
            headers=square_headers(), timeout=15)
        data = r.json()
        customers = data.get('customers') or []
        if customers:
            return customers[0]['id']
    except Exception as e:
        app.logger.warning(f'Square customer search failed: {e}')
    try:
        import uuid as _uuidc
        parts = (name or '').strip().split(' ', 1)
        payload = {'idempotency_key': str(_uuidc.uuid4()), 'email_address': email}
        if parts and parts[0]:
            payload['given_name'] = parts[0]
            if len(parts) > 1: payload['family_name'] = parts[1]
        if phone: payload['phone_number'] = phone
        r = requests.post(f'{SQUARE_API_BASE}/v2/customers', json=payload, headers=square_headers(), timeout=15)
        data = r.json()
        if r.status_code == 200 and data.get('customer'):
            return data['customer']['id']
        app.logger.error(f'Square customer create failed {r.status_code}: {data}')
    except Exception as e:
        app.logger.error(f'Square customer create exception: {e}')
    return None


def square_create_order(item_name, amount_cents, reference_id=''):
    """Create a Square order with a single line item for the given amount.
    Required before an invoice can be created — the Invoices API only
    accepts an existing order_id, it can't build one inline like Payment
    Links can. Returns order_id or None."""
    if not SQUARE_ACCESS_TOKEN or not SQUARE_LOCATION_ID:
        return None
    try:
        import uuid as _uuido
        payload = {
            'idempotency_key': str(_uuido.uuid4()),
            'order': {
                'location_id': SQUARE_LOCATION_ID,
                'line_items': [
                    {'name': item_name[:191], 'quantity': '1',
                     'base_price_money': {'amount': amount_cents, 'currency': 'USD'}}
                ],
                'reference_id': (reference_id or '')[:40],
            },
        }
        r = requests.post(f'{SQUARE_API_BASE}/v2/orders', json=payload, headers=square_headers(), timeout=15)
        data = r.json()
        if r.status_code == 200 and data.get('order'):
            return data['order']['id']
        app.logger.error(f'Square create order failed {r.status_code}: {data}')
    except Exception as e:
        app.logger.error(f'Square create order exception: {e}')
    return None


def square_create_and_publish_invoice(order_id, customer_id, amount_cents, due_date, title, description):
    """Create a draft invoice for the given order (single BALANCE payment
    request for the full amount), then publish it so Square emails it to
    the customer and hosts the payment page. Returns
    (invoice_id, public_url, status, error) — error is None on success."""
    if not SQUARE_ACCESS_TOKEN:
        return None, None, None, 'Square is not configured'
    # Square rejects a due date before the day the invoice is sent ("Due on
    # date must be on or after scheduled date"). An installment whose date
    # has already passed is simply due today.
    try:
        if str(due_date or '')[:10] < today_eastern().isoformat():
            due_date = today_eastern().isoformat()
    except Exception:
        pass
    try:
        import uuid as _uuidi
        create_payload = {
            'idempotency_key': str(_uuidi.uuid4()),
            'invoice': {
                'location_id': SQUARE_LOCATION_ID,
                'order_id': order_id,
                'primary_recipient': {'customer_id': customer_id},
                'payment_requests': [
                    {'request_type': 'BALANCE', 'due_date': due_date, 'automatic_payment_source': 'NONE'}
                ],
                'delivery_method': 'EMAIL',
                'title': title[:255],
                'description': description[:2000] if description else '',
                'accepted_payment_methods': {'card': True, 'square_gift_card': False, 'buy_now_pay_later': False},
            },
        }
        r = requests.post(f'{SQUARE_API_BASE}/v2/invoices', json=create_payload, headers=square_headers(), timeout=15)
        data = r.json()
        if r.status_code != 200 or not data.get('invoice'):
            app.logger.error(f'Square create invoice failed {r.status_code}: {data}')
            return None, None, None, f'Could not create invoice: {data}'
        invoice = data['invoice']
        invoice_id = invoice['id']
        version = invoice.get('version', 0)

        publish_payload = {'version': version, 'idempotency_key': str(_uuidi.uuid4())}
        r2 = requests.post(f'{SQUARE_API_BASE}/v2/invoices/{invoice_id}/publish', json=publish_payload, headers=square_headers(), timeout=15)
        data2 = r2.json()
        if r2.status_code != 200 or not data2.get('invoice'):
            app.logger.error(f'Square publish invoice failed {r2.status_code}: {data2}')
            return invoice_id, None, invoice.get('status', 'DRAFT'), f'Invoice created but could not be sent: {data2}'
        published = data2['invoice']
        return invoice_id, published.get('public_url'), published.get('status'), None
    except Exception as e:
        app.logger.error(f'Square create/publish invoice exception: {e}')
        return None, None, None, str(e)


def square_get_invoice(invoice_id):
    """Fetch the current state of an invoice directly from Square — used for
    the manual 'check status' action in case a webhook was missed."""
    if not SQUARE_ACCESS_TOKEN or not invoice_id:
        return None
    try:
        r = requests.get(f'{SQUARE_API_BASE}/v2/invoices/{invoice_id}', headers=square_headers(), timeout=15)
        data = r.json()
        if r.status_code == 200 and data.get('invoice'):
            return data['invoice']
        app.logger.warning(f'Square get invoice failed {r.status_code}: {data}')
    except Exception as e:
        app.logger.warning(f'Square get invoice exception: {e}')
    return None


def square_get_payment(payment_id):
    """Fetch a payment's full detail directly from Square — used by the
    registration invoice PDF to show payment method (card brand/last4)
    and the actual completion timestamp, neither of which is stored
    locally today (only the payment ID is kept on program_registrations)."""
    if not SQUARE_ACCESS_TOKEN or not payment_id:
        return None
    try:
        r = requests.get(f'{SQUARE_API_BASE}/v2/payments/{payment_id}', headers=square_headers(), timeout=15)
        data = r.json()
        if r.status_code == 200 and data.get('payment'):
            return data['payment']
        app.logger.warning(f'Square get payment failed {r.status_code}: {data}')
    except Exception as e:
        app.logger.warning(f'Square get payment exception: {e}')
    return None


def _format_square_timestamp(iso_str):
    """Square timestamps are UTC ISO-8601 — converts to Eastern for display
    on the invoice, matching how the rest of RoleCall shows times."""
    if not iso_str:
        return ''
    try:
        from zoneinfo import ZoneInfo
        dt = datetime.fromisoformat(iso_str.replace('Z', '+00:00'))
        dt_et = dt.astimezone(ZoneInfo('America/New_York'))
        return dt_et.strftime('%B %-d, %Y at %-I:%M %p') + ' ET'
    except Exception:
        return iso_str


def square_get_order_total_cents(order_id):
    """Fetch an order's real total_money.amount directly from Square — used
    to backfill amount_paid_cents on registrations that were confirmed
    before that column existed (the payment.completed webhook only captures
    it going forward; Square doesn't resend that event for old payments)."""
    if not SQUARE_ACCESS_TOKEN or not order_id:
        return None
    try:
        r = requests.get(f'{SQUARE_API_BASE}/v2/orders/{order_id}', headers=square_headers(), timeout=15)
        data = r.json()
        if r.status_code == 200 and data.get('order'):
            total = data['order'].get('total_money', {}).get('amount')
            return total if total is not None else None
        app.logger.warning(f'Square get order failed {r.status_code}: {data}')
    except Exception as e:
        app.logger.warning(f'Square get order exception: {e}')
    return None


def split_order_amount_across_registrations(conn, order_id, total_cents):
    """Set amount_paid_cents on every registration sharing a Square order,
    splitting the order's total proportionally by each registration's
    nominal price instead of writing the full order total onto every row.

    Writing the full total on every row (the old behavior) only gives a
    correct answer when every registration sharing that order belongs to
    the SAME program — e.g. two siblings both enrolling in one class,
    where revenue queries then deduplicate by order to avoid double-
    counting. It silently breaks the moment one Square checkout covers
    TWO DIFFERENT programs (a parent buying two different classes in one
    cart): the per-program revenue dedup can only credit ONE of the two
    programs with the full amount and drops the other to $0, because it
    has no way to know how the order should actually be divided between
    them. Splitting proportionally here means downstream revenue queries
    can just sum each registration's own share directly — no dedup
    trickery needed, and it's correct for both the sibling case and the
    multi-program case."""
    if not order_id or total_cents is None:
        return
    regs = fetchall(conn, '''SELECT pr.id, pr.participant_count, pr.discount_amount, pr.sibling_discount_amount,
        pr.is_comped, COALESCE(yp.price, prod.price, 0) AS price
        FROM program_registrations pr
        LEFT JOIN youth_programs yp ON yp.id=pr.program_id
        LEFT JOIN productions prod ON prod.id=pr.production_id
        WHERE (pr.square_order_id=%s OR pr.square_checkout_id=%s) AND pr.status != 'cancelled'
        ORDER BY pr.id''', (order_id, order_id)) or []
    if not regs:
        return
    if len(regs) == 1:
        execute(conn, 'UPDATE program_registrations SET amount_paid_cents=%s WHERE id=%s', (total_cents, regs[0]['id']))
        return
    nominal = {}
    for r in regs:
        nominal[r['id']] = 0 if r.get('is_comped') else max(0,
            (r.get('price') or 0) * (r.get('participant_count') or 1)
            - (r.get('discount_amount') or 0) - (r.get('sibling_discount_amount') or 0))
    nominal_total = sum(nominal.values())
    if nominal_total <= 0:
        # No price data to split by (e.g. all comped, or free programs) —
        # divide evenly rather than guessing, so nothing is silently zeroed.
        share = total_cents // len(regs)
        for i, r in enumerate(regs):
            amt = share + (total_cents - share * len(regs) if i == len(regs) - 1 else 0)
            execute(conn, 'UPDATE program_registrations SET amount_paid_cents=%s WHERE id=%s', (amt, r['id']))
        return
    allocated = 0
    for i, r in enumerate(regs):
        if i == len(regs) - 1:
            amt = total_cents - allocated  # last one absorbs any rounding remainder
        else:
            amt = round(total_cents * nominal[r['id']] / nominal_total)
            allocated += amt
        execute(conn, 'UPDATE program_registrations SET amount_paid_cents=%s WHERE id=%s', (amt, r['id']))


def square_save_card(customer_id, source_id, cardholder_name=''):
    """Save a tokenized card on file for a customer WITHOUT charging it.
    source_id is the token produced client-side by Square's Web Payments SDK.
    Returns (card_id, brand, last4) — all None on failure."""
    if not SQUARE_ACCESS_TOKEN or not customer_id or not source_id:
        return None, None, None
    try:
        import uuid as _uuidk
        payload = {
            'idempotency_key': str(_uuidk.uuid4()),
            'source_id': source_id,
            'card': {'customer_id': customer_id},
        }
        if cardholder_name:
            payload['card']['cardholder_name'] = cardholder_name[:100]
        r = requests.post(f'{SQUARE_API_BASE}/v2/cards', json=payload, headers=square_headers(), timeout=15)
        data = r.json()
        if r.status_code == 200 and data.get('card'):
            card = data['card']
            return card['id'], card.get('card_brand'), card.get('last_4')
        app.logger.error(f'Square save card failed {r.status_code}: {data}')
        return None, None, None
    except Exception as e:
        app.logger.error(f'Square save card exception: {e}')
        return None, None, None


def square_charge_saved_card(customer_id, card_id, amount_cents, note=''):
    """Charge a previously saved card on file (used when staff clicks 'Charge Now'
    on an overdue Step Up hold). Returns (success, payment_id_or_error_message)."""
    if not SQUARE_ACCESS_TOKEN or not card_id:
        return False, 'Square not configured'
    try:
        import uuid as _uuidp
        payload = {
            'idempotency_key': str(_uuidp.uuid4()),
            'source_id': card_id,
            'customer_id': customer_id,
            'amount_money': {'amount': amount_cents, 'currency': 'USD'},
            'location_id': SQUARE_LOCATION_ID,
            'note': (note or '')[:500],
            'autocomplete': True,
        }
        r = requests.post(f'{SQUARE_API_BASE}/v2/payments', json=payload, headers=square_headers(), timeout=15)
        data = r.json()
        if r.status_code == 200 and data.get('payment'):
            return True, data['payment']['id']
        errors = data.get('errors') or []
        msg = errors[0].get('detail') if errors else f'Square error {r.status_code}'
        app.logger.error(f'Square charge saved card failed {r.status_code}: {data}')
        return False, msg
    except Exception as e:
        app.logger.error(f'Square charge saved card exception: {e}')
        return False, str(e)


def square_verify_card(customer_id, card_id):
    """Run a small $5 authorization on a freshly-saved card, then immediately void it,
    to confirm the card is real and currently chargeable — without capturing any funds.
    ($5 matches HWTC's standard minimum-charge policy; the hold is canceled before it
    ever settles, so no processing fee applies — fees are only assessed on completed payments.)
    Catches expired cards, closed accounts, and typos that pass basic format checks.
    Returns (True, None) if the card checks out, else (False, error_message)."""
    if not SQUARE_ACCESS_TOKEN or not card_id:
        return False, 'Square not configured'
    try:
        import uuid as _uuidv
        payload = {
            'idempotency_key': str(_uuidv.uuid4()),
            'source_id': card_id,
            'customer_id': customer_id,
            'amount_money': {'amount': 500, 'currency': 'USD'},
            'location_id': SQUARE_LOCATION_ID,
            'autocomplete': False,
            'note': 'Card verification (authorization voided immediately)',
        }
        r = requests.post(f'{SQUARE_API_BASE}/v2/payments', json=payload, headers=square_headers(), timeout=15)
        data = r.json()
        if r.status_code != 200 or not data.get('payment'):
            errors = data.get('errors') or []
            msg = errors[0].get('detail') if errors else 'This card could not be verified. Please double-check the details or try a different card.'
            app.logger.warning(f'Square card verification declined {r.status_code}: {data}')
            return False, msg
        payment_id = data['payment']['id']
        try:
            requests.post(f'{SQUARE_API_BASE}/v2/payments/{payment_id}/cancel', headers=square_headers(), timeout=15)
        except Exception as e:
            app.logger.warning(f'Square card verification void failed for payment {payment_id}: {e}')
        return True, None
    except Exception as e:
        app.logger.error(f'Square card verification exception: {e}')
        return False, str(e)

def square_create_payment_link(program, registration_id, guardian_email, guardian_name, amount_cents, note='', redirect_url=None):
    """Create a Square hosted checkout link for a registration."""
    import uuid as _uuid
    if not SQUARE_ACCESS_TOKEN or not SQUARE_LOCATION_ID:
        app.logger.error('Square not configured: SQUARE_ACCESS_TOKEN or SQUARE_LOCATION_ID missing')
        return None, None, None
    if not redirect_url:
        redirect_url = f"{APP_BASE_URL}/register/{program.get('slug') or program['id']}/confirmation?reg={registration_id}"
    payload = {
        'idempotency_key': str(_uuid.uuid4()),
        'order': {
            'location_id': SQUARE_LOCATION_ID,
            'line_items': [
                {
                    'name': program['name'][:191],
                    'quantity': '1',
                    'base_price_money': {'amount': amount_cents, 'currency': 'USD'},
                }
            ],
            'reference_id': registration_id[:40],
        },
        'checkout_options': {
            'redirect_url': redirect_url,
            'ask_for_shipping_address': False,
        },
        'pre_populated_data': {
            'buyer_email': guardian_email or '',
        },
        'description': (note or f'Registration: {registration_id}')[:255],
    }
    try:
        r = requests.post(
            f'{SQUARE_API_BASE}/v2/online-checkout/payment-links',
            json=payload, headers=square_headers(), timeout=15)
        data = r.json()
        app.logger.info(f'Square payment link response {r.status_code}: {str(data)[:300]}')
        if r.status_code == 200 and data.get('payment_link'):
            lnk = data['payment_link']
            return lnk.get('url'), lnk.get('id'), lnk.get('order_id')
        app.logger.error(f'Square payment link failed {r.status_code}: {data}')
        return None, None, None
    except Exception as e:
        app.logger.error(f'Square payment link exception: {e}')
        return None, None, None


def square_setup_card_hold(guardian_email, guardian_name, guardian_phone, card_token):
    """Save a card on file (no charge). Used by Step Up member enrollment.
    Returns (customer_id, card_id, brand, last4, error_message). error_message is None on success."""
    if not card_token:
        return None, None, None, None, 'Card details are required.'
    customer_id = square_find_or_create_customer(guardian_email, guardian_name, guardian_phone)
    if not customer_id:
        return None, None, None, None, 'Could not save your card. Please try again or contact us.'
    card_id, brand, last4 = square_save_card(customer_id, card_token, guardian_name)
    if not card_id:
        return None, None, None, None, 'Could not save your card. Please double-check your card details and try again.'
    return customer_id, card_id, brand, last4, None


@app.route('/api/public/step-up-members/enroll', methods=['POST'])
def step_up_member_enroll():
    """One-time enrollment: save a card on file against a family's Step Up Awards ID.
    Re-enrolling with the same ID replaces the saved card (e.g. their card expired)."""
    d = request.json or {}
    step_up_id = (d.get('step_up_id') or '').strip()
    guardian_email = (d.get('guardian_email') or '').strip().lower()
    guardian_name = (d.get('guardian_name') or '').strip()
    guardian_phone = (d.get('guardian_phone') or '').strip()
    card_token = d.get('card_token')
    if not step_up_id:
        return jsonify({'error': 'Step Up Awards ID is required.'}), 400
    if not guardian_email or not guardian_name:
        return jsonify({'error': 'Name and email are required.'}), 400
    customer_id, card_id, brand, last4, err = square_setup_card_hold(
        guardian_email, guardian_name, guardian_phone, card_token)
    if err:
        return jsonify({'error': err}), 400

    # Verify the card is actually chargeable (catches expired/closed/declined cards
    # that pass basic format checks) with a $1 authorization that's voided immediately —
    # no funds are ever captured.
    verified, verify_err = square_verify_card(customer_id, card_id)
    if not verified:
        square_disable_card(card_id)
        return jsonify({'error': verify_err or "This card couldn't be verified. Please double-check the details or try a different card."}), 400

    conn = get_db()
    import uuid as _usm
    existing = fetchone(conn, 'SELECT id, square_card_id FROM step_up_members WHERE step_up_id=%s', (step_up_id,))
    if existing:
        execute(conn, '''UPDATE step_up_members SET guardian_name=%s, guardian_email=%s, guardian_phone=%s,
            square_customer_id=%s, square_card_id=%s, card_brand=%s, card_last4=%s, updated_at=NOW()
            WHERE step_up_id=%s''',
            (guardian_name, guardian_email, guardian_phone, customer_id, card_id, brand, last4, step_up_id))
        old_card_id = existing.get('square_card_id')
        if old_card_id and old_card_id != card_id:
            square_disable_card(old_card_id)
    else:
        execute(conn, '''INSERT INTO step_up_members
            (id, step_up_id, guardian_name, guardian_email, guardian_phone,
             square_customer_id, square_card_id, card_brand, card_last4)
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s)''',
            (_usm.uuid4().hex, step_up_id, guardian_name, guardian_email, guardian_phone,
             customer_id, card_id, brand, last4))
    conn.commit()
    conn.close()
    return jsonify({'ok': True, 'card_brand': brand, 'card_last4': last4, 'updated': bool(existing)})


@app.route('/api/public/step-up-members/lookup', methods=['POST'])
def step_up_member_lookup():
    """Look up a family's saved card by their Step Up Awards ID (used at registration
    time so they don't have to re-enter card details every show)."""
    d = request.json or {}
    step_up_id = (d.get('step_up_id') or '').strip()
    if not step_up_id:
        return jsonify({'found': False})
    conn = get_db()
    m = fetchone(conn, '''SELECT guardian_name, card_brand, card_last4
        FROM step_up_members WHERE step_up_id=%s''', (step_up_id,))
    conn.close()
    if not m or not m.get('card_brand'):
        return jsonify({'found': False})
    return jsonify({'found': True, 'guardian_name': m['guardian_name'],
                    'card_brand': m['card_brand'], 'card_last4': m['card_last4']})


def find_step_up_member_card(step_up_id):
    """Look up a previously-enrolled Step Up member's saved card by rewards ID.
    Returns (customer_id, card_id, error_message)."""
    step_up_id = (step_up_id or '').strip()
    if not step_up_id:
        return None, None, 'Please enter your Step Up Awards ID.'
    conn = get_db()
    m = fetchone(conn, '''SELECT square_customer_id, square_card_id FROM step_up_members
        WHERE step_up_id=%s''', (step_up_id,))
    conn.close()
    if not m or not m.get('square_card_id'):
        return None, None, "We couldn't find a saved card for that Step Up Awards ID. Please enroll your card first."
    return m['square_customer_id'], m['square_card_id'], None


def square_disable_card(card_id):
    """Disable a card on file — used to clean up a card that failed verification
    so it doesn't linger as a saved (but unverified) card on the customer."""
    if not SQUARE_ACCESS_TOKEN or not card_id:
        return
    try:
        requests.post(f'{SQUARE_API_BASE}/v2/cards/{card_id}/disable', headers=square_headers(), timeout=15)
    except Exception as e:
        app.logger.warning(f'Square disable card failed for {card_id}: {e}')


def resolve_step_up_children(children, total_amount_cents):
    """Validate a list of {name, step_up_id} entries against enrolled Step Up members,
    and prorate total_amount_cents evenly across them (remainder to the first child).
    Returns (resolved_list, error_message). resolved_list items have:
    name, step_up_id, amount, square_customer_id, square_card_id.
    Fails atomically — if any child's ID doesn't resolve, nothing is returned as valid."""
    if not children or not isinstance(children, list):
        return None, 'Please enter a Step Up Awards ID for each participant.'
    n = len(children)
    base = total_amount_cents // n
    remainder = total_amount_cents - base * n
    resolved = []
    for i, c in enumerate(children):
        name = (c.get('name') or '').strip() or f'Participant {i+1}'
        step_up_id = (c.get('step_up_id') or '').strip()
        customer_id, card_id, err = find_step_up_member_card(step_up_id)
        if err:
            return None, f'{name}: {err}'
        amount = base + (1 if i < remainder else 0)
        resolved.append({
            'name': name, 'step_up_id': step_up_id, 'amount': amount,
            'square_customer_id': customer_id, 'square_card_id': card_id,
        })
    return resolved, None


def insert_step_up_child_holds(conn, registration_ids, resolved_children, charge_by_date):
    """registration_ids and resolved_children must be the same length and in the same
    order — each child's hold links to THEIR OWN registration row."""
    import uuid as _uschc
    for rid, c in zip(registration_ids, resolved_children):
        execute(conn, '''INSERT INTO step_up_child_holds
            (id, registration_id, child_name, step_up_id, amount,
             square_customer_id, square_card_id, hold_charge_by_date, hold_status)
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,'pending')''',
            (_uschc.uuid4().hex, rid, c['name'], c['step_up_id'], c['amount'],
             c['square_customer_id'], c['square_card_id'], charge_by_date))


def get_program_by_slug(slug):
    conn = get_db()
    p = fetchone(conn, 'SELECT * FROM youth_programs WHERE slug=%s OR id=%s', (slug, slug))
    conn.close()
    return p


def get_registration_count(conn, program_id):
    r = fetchone(conn, "SELECT COUNT(*) as c FROM program_registrations WHERE program_id=%s AND status IN ('confirmed','pending_payment')", (program_id,))
    return r['c'] if r else 0


def get_waitlist_count(conn, program_id):
    r = fetchone(conn, "SELECT COUNT(*) as c FROM program_registrations WHERE program_id=%s AND status='waitlisted'", (program_id,))
    return r['c'] if r else 0


def next_waitlist_position(conn, program_id):
    r = fetchone(conn, 'SELECT MAX(waitlist_position) as m FROM program_registrations WHERE program_id=%s AND status=%s', (program_id,'waitlisted'))
    return (r['m'] or 0) + 1 if r else 1


def even_split(total_cents, n):
    """Split total_cents evenly across n shares; any leftover pennies go to the first share."""
    n = max(1, n)
    base = total_cents // n
    remainder = total_cents - base * n
    return [base + (1 if i < remainder else 0) for i in range(n)]


def insert_registration_row(conn, cols):
    """Generic parameterized INSERT into program_registrations from a dict of column->value.
    Used to create one row per child when a registration includes siblings, so each child
    is an independent, individually editable/deletable registration."""
    keys = list(cols.keys())
    placeholders = ','.join(['%s'] * len(keys))
    col_list = ','.join(keys)
    execute(conn, f'INSERT INTO program_registrations ({col_list}) VALUES ({placeholders})',
            tuple(cols[k] for k in keys))


def _backfill_custom_field_values():
    """One-time backfill: custom question answers used to only get saved
    into cart_orders.items_json (a payment/order journal, not something
    staff ever see) and never copied onto the actual program_registrations
    row. This pulls them back out for any registration that predates the
    fix. Safe to re-run — only fills in rows that are still empty ('{}' or
    blank), never overwrites an already-populated value.
    Returns (checked_count, updated_count)."""
    conn = get_db()
    orders = fetchall(conn, 'SELECT items_json FROM cart_orders') or []
    checked = 0
    updated = 0
    for o in orders:
        try:
            items = json.loads(o.get('items_json') or '[]')
        except Exception:
            continue
        for it in items:
            rid = it.get('registration_id')
            cfv = it.get('custom_field_values')
            if not rid or not cfv:
                continue
            checked += 1
            reg = fetchone(conn, 'SELECT custom_field_values FROM program_registrations WHERE id=%s', (rid,))
            if not reg:
                continue
            current = (reg.get('custom_field_values') or '').strip()
            if current in ('', '{}'):
                execute(conn, 'UPDATE program_registrations SET custom_field_values=%s WHERE id=%s',
                    (json.dumps(cfv), rid))
                updated += 1
    conn.commit()
    conn.close()
    return checked, updated

@app.route('/api/instructor/dashboard', methods=['GET'])
def instructor_dashboard():
    """Everything an instructor needs in one call: which programs they
    teach, their full session schedule across those programs, and recent
    registrations so new sign-ups are easy to spot. Scoped by matching
    their login email against the volunteer record linked either as a
    program's primary instructor_id, or as a co-instructor in
    program_co_instructors — an instructor only ever sees their own
    programs here, never the full program list."""
    err = require_auth()
    if err: return err
    conn = get_db()
    me = fetchone(conn, 'SELECT email FROM users WHERE id=%s', (session['user_id'],))
    my_email = (me or {}).get('email', '').strip().lower()
    if not my_email:
        conn.close()
        return jsonify({'programs': [], 'schedule': [], 'recent_registrations': []})

    programs = fetchall(conn, '''SELECT DISTINCT yp.id, yp.name, yp.description, yp.status,
        yp.start_date, yp.end_date, yp.program_type, yp.sessions_enabled,
        COALESCE(yp.booking_mode, FALSE) AS booking_mode
        FROM youth_programs yp
        LEFT JOIN volunteers v ON v.id=yp.instructor_id
        LEFT JOIN program_co_instructors pci ON pci.program_id=yp.id
        LEFT JOIN volunteers v2 ON v2.id=pci.volunteer_id
        WHERE lower(v.email)=%s OR lower(v2.email)=%s
        ORDER BY yp.start_date DESC NULLS LAST''', (my_email, my_email)) or []
    prog_ids = [p['id'] for p in programs]
    if not prog_ids:
        conn.close()
        return jsonify({'programs': [], 'schedule': [], 'recent_registrations': []})

    placeholders = ','.join(['%s'] * len(prog_ids))
    schedule = fetchall(conn, f'''SELECT ps.id, ps.name, ps.start_date, ps.start_time, ps.end_time,
        ps.location, ps.capacity, yp.name AS program_name, yp.id AS program_id,
        COALESCE(yp.booking_mode, FALSE) AS booking_mode,
        (SELECT COUNT(*) FROM program_registrations pr
         WHERE pr.program_id=ps.program_id AND pr.session_ids LIKE '%%"' || ps.id || '"%%'
         AND pr.status NOT IN ('cancelled','waitlisted')) AS enrolled_count
        FROM program_sessions ps
        JOIN youth_programs yp ON yp.id=ps.program_id
        WHERE ps.program_id IN ({placeholders}) AND ps.start_date IS NOT NULL AND ps.start_date != ''
        ORDER BY ps.start_date ASC, ps.start_time ASC''', tuple(prog_ids)) or []

    # Booking-mode programs (one-off bookable slots, e.g. a bulk-imported
    # rehearsal/audition schedule) can easily have hundreds of open, empty
    # slots — those aren't useful on an instructor's schedule, only the
    # ones someone actually booked are. Regular classes/camps don't have
    # this "mostly empty slots" problem, so their sessions always show.
    schedule = [s for s in schedule if not s['booking_mode'] or (s.get('enrolled_count') or 0) > 0]
    for s in schedule:
        s['booked_by'] = []
        if s['booking_mode'] and (s.get('enrolled_count') or 0) > 0:
            bookers = fetchall(conn, """SELECT child_first_name, child_last_name, guardian_name
                FROM program_registrations
                WHERE program_id=%s AND session_ids LIKE %s
                AND status NOT IN ('cancelled','waitlisted')""",
                (s['program_id'], '%"' + s['id'] + '"%')) or []
            s['booked_by'] = [
                (f"{b.get('child_first_name','')} {b.get('child_last_name','')}".strip() or b.get('guardian_name',''))
                for b in bookers
            ]

    recent_regs = fetchall(conn, f'''SELECT pr.id, pr.child_first_name, pr.child_last_name,
        pr.guardian_name, pr.guardian_email, pr.status, pr.created_at,
        yp.name AS program_name, yp.id AS program_id
        FROM program_registrations pr
        JOIN youth_programs yp ON yp.id=pr.program_id
        WHERE pr.program_id IN ({placeholders}) AND pr.status IN ('confirmed','pending_payment')
        ORDER BY pr.created_at DESC LIMIT 40''', tuple(prog_ids)) or []

    for p in programs:
        p['registrant_count'] = sum(1 for r in recent_regs if r['program_id'] == p['id'])

    # Simple single-date classes (no sessions_enabled, no program_sessions
    # rows at all) still have a real teaching date — it just lives on the
    # program record itself rather than as a session slot. Without this,
    # they'd never show on the schedule at all even though the instructor
    # is genuinely scheduled to teach them.
    prog_ids_with_sessions = set(s['program_id'] for s in schedule)
    for p in programs:
        if p['id'] not in prog_ids_with_sessions and p.get('start_date'):
            schedule.append({
                'id': 'program_' + p['id'],
                'name': p['name'],
                'start_date': p['start_date'],
                'end_date': p.get('end_date'),
                'start_time': '',
                'end_time': '',
                'location': '',
                'capacity': None,
                'program_id': p['id'],
                'program_name': p['name'],
                'booking_mode': False,
                'enrolled_count': p['registrant_count'],
                'booked_by': [],
            })
    schedule.sort(key=lambda s: (s.get('start_date') or '', s.get('start_time') or ''))

    conn.close()
    return jsonify({'programs': programs, 'schedule': schedule, 'recent_registrations': recent_regs})


@app.route('/api/director/dashboard', methods=['GET'])
def director_dashboard():
    """Same idea as the instructor dashboard, for the 'director' role —
    scoped to whichever production(s) they're listed on in
    production_members with a role containing 'director', matched by
    their login email against the volunteer record."""
    err = require_auth()
    if err: return err
    conn = get_db()
    me = fetchone(conn, 'SELECT email FROM users WHERE id=%s', (session['user_id'],))
    my_email = (me or {}).get('email', '').strip().lower()
    if not my_email:
        conn.close()
        return jsonify({'productions': [], 'schedule': [], 'recent_submissions': []})

    productions = fetchall(conn, '''SELECT DISTINCT p.id, p.name, p.status, p.stage,
        p.start_date, p.end_date, p.production_type
        FROM productions p
        JOIN production_members pm ON pm.production_id=p.id
        JOIN volunteers v ON v.id=pm.volunteer_id
        WHERE lower(v.email)=%s AND pm.role ILIKE %s
        ORDER BY p.start_date DESC NULLS LAST''', (my_email, '%director%')) or []
    prod_ids = [p['id'] for p in productions]
    if not prod_ids:
        conn.close()
        return jsonify({'productions': [], 'schedule': [], 'recent_submissions': []})

    placeholders = ','.join(['%s'] * len(prod_ids))
    schedule = fetchall(conn, f'''SELECT e.id, e.name, e.event_date, e.start_time, e.end_time,
        e.location, p.name AS production_name, p.id AS production_id
        FROM events e JOIN productions p ON p.id=e.production_id
        WHERE e.production_id IN ({placeholders}) AND e.event_date >= %s
        ORDER BY e.event_date ASC, e.start_time ASC NULLS LAST LIMIT 150''',
        tuple(prod_ids) + (today_eastern().isoformat(),)) or []

    recent_submissions = fetchall(conn, f'''SELECT s.id, s.submitter_name, s.submitter_email, s.status,
        s.submitted_at, s.context_id AS production_id, p.name AS production_name
        FROM audition_submissions s JOIN productions p ON p.id=s.context_id
        WHERE s.context_type='production' AND s.context_id IN ({placeholders})
        ORDER BY s.submitted_at DESC LIMIT 40''', tuple(prod_ids)) or []

    for p in productions:
        p['pending_audition_count'] = sum(1 for s in recent_submissions if s['production_id']==p['id'] and s['status']=='pending')

    conn.close()
    return jsonify({'productions': productions, 'schedule': schedule, 'recent_submissions': recent_submissions})


@app.route('/api/admin/backfill-custom-field-values', methods=['POST'])
def backfill_custom_field_values_route():
    err = require_permission('programs')
    if err: return err
    checked, updated = _backfill_custom_field_values()
    return jsonify({'ok': True, 'checked': checked, 'updated': updated})


# Profile fields a returning family saw pre-filled from their record on the
# registration form. For these, whatever they submit (including a cleared
# box or an unchecked consent) replaces what's on file; for anything not
# listed, a blank still means "didn't fill it in" and never erases data.
REVIEWABLE_PROFILE_FIELDS = ('allergies', 'pronouns', 'photo_consent', 'emergency_contact')
FAMILY_LEVEL_REVIEWABLE = ('photo_consent', 'emergency_contact')


def _clean_reviewed_fields(raw):
    if not isinstance(raw, list): return []
    return [f for f in REVIEWABLE_PROFILE_FIELDS if f in raw]


def _reviewed_fields_for_children(d, siblings):
    """One reviewed_fields string per child (primary first, then siblings).
    Family-level fields apply to every child; allergies/pronouns only to the
    primary, plus allergies for a sibling whose block was pre-filled."""
    primary = _clean_reviewed_fields(d.get('reviewed_fields'))
    family = [f for f in primary if f in FAMILY_LEVEL_REVIEWABLE]
    out = [','.join(primary)]
    for sib in (siblings or []):
        sf = list(family)
        if isinstance(sib, dict) and sib.get('reviewed') and 'allergies' in primary:
            sf.append('allergies')
        out.append(','.join(sf))
    return out


def create_grouped_registrations(conn, shared_fields, children, total_amount_cents, status, payment_type, amounts=None):
    """Create one program_registrations row per child (primary + each sibling), all sharing
    a registration_group_id so a single payment/hold can confirm or reference the whole group,
    while each row remains an independent registration for Edit/Delete/Resend purposes.
    shared_fields: dict of columns common to every row (program_id/production_id, guardian info,
    discount_code, etc.) — must NOT include id, child_first_name/last_name/dob/shirt_size, status,
    payment_type, balance_due, participant_count, siblings_json, registration_group_id
    (those are set per-row below). If shared_fields contains 'discount_amount' and/or
    'sibling_discount_amount', those GROUP TOTALS are prorated evenly across children rather
    than duplicated on every row — otherwise summing per-row amounts would double-count them.
    amounts: optional pre-computed list of per-child balance_due values (e.g. from
    resolve_step_up_children) to use instead of auto-splitting total_amount_cents.
    Returns (list_of_registration_ids, group_id) in the same order as `children`.
    """
    import uuid as _ugr
    group_id = str(_ugr.uuid4())
    n = len(children)
    shares = amounts if amounts is not None else even_split(total_amount_cents, n)
    discount_shares = even_split(shared_fields.get('discount_amount') or 0, n)
    sib_discount_shares = even_split(shared_fields.get('sibling_discount_amount') or 0, n)
    ids = []
    for i, child in enumerate(children):
        rid = str(_ugr.uuid4())
        ids.append(rid)
        row = dict(shared_fields)
        row.update({
            'id': rid,
            'registration_group_id': group_id,
            'registration_type': 'registration',
            'child_first_name': (child.get('first_name') or '').strip(),
            'child_last_name': (child.get('last_name') or '').strip(),
            'child_dob': child.get('dob') or None,
            'shirt_size': child.get('shirt_size') or None,
            'status': status,
            'payment_type': payment_type,
            'discount_amount': discount_shares[i],
            'sibling_discount_amount': sib_discount_shares[i],
            'balance_due': shares[i],
            'participant_count': 1,
            'siblings_json': '[]',
        })
        # Per-child health/identity fields: a sibling must never inherit the
        # first child's allergies or pronouns (finalize_registration writes
        # these onto each child's own profile).
        for _k in ('allergies', 'pronouns'):
            if _k in child:
                row[_k] = (child.get(_k) or '').strip() or None
            elif i > 0:
                row[_k] = None
        if 'reviewed_fields' in child:
            row['reviewed_fields'] = child.get('reviewed_fields') or ''
        insert_registration_row(conn, row)
    return ids, group_id


def _welcome_email_adult_aware_blocks(is_adult, program_name):
    """The welcome_email template reads very 'your child'/'family pick-up'
    focused, which makes sense for youth programs but not for someone
    registering for themselves (an adult class, workshop, etc.). These four
    pieces swap wording based on whether the participant is an adult, so the
    same template makes sense either way instead of reading oddly for one
    of the two audiences."""
    if is_adult:
        return {
            'intro_block': (
                f'<p>We are so excited to have you join us for <strong>{program_name}</strong>! '
                'We want to introduce you to <strong>RoleCall</strong>  -  our portal for Horizon West Theater Company.</p>'
                '\n\n    <p>Through RoleCall you can read announcements from your instructor, download program resources, '
                f'sign required waivers, and reach the theater company  -  all in one place. Moving forward, '
                f'<strong>RoleCall will be our primary channel for all {program_name} communication.</strong></p>'
            ),
            'portal_tagline': 'your RoleCall portal',
            'passphrase_reminder_line': 'something you\'ll remember. You\'ll use this passphrase to log in to RoleCall going forward.',
            'closing_line': (
                f'<p>We cannot wait for you to be part of {program_name}. Please reach out through the portal '
                'or email us directly if you have any questions at all.</p>'
            ),
        }
    return {
        'intro_block': (
            f'<p>We are so excited to have your family join us for <strong>{program_name}</strong>! '
            'We want to introduce you to <strong>RoleCall</strong>  -  our family portal for Horizon West Theater Company.</p>'
            '\n\n    <p>Through RoleCall you can read announcements from your child\'s instructor, download program resources, '
            'sign required waivers, set up family carpools, and reach the theater company  -  all in one place. '
            f'Moving forward, <strong>RoleCall will be our primary channel for all {program_name} communication.</strong></p>'
        ),
        'portal_tagline': 'your family portal',
        'passphrase_reminder_line': 'a word your family will remember. This same word is used at afternoon pick-up every day.',
        'closing_line': (
            f'<p>We cannot wait for your family to be part of {program_name}. Please reach out through the portal '
            'or email us directly if you have any questions at all.</p>'
        ),
    }


def _format_registration_schedule(conn, prog, prod, reg):
    """Human-readable description of what a family actually signed up for —
    the specific sessions they picked if the program uses session-based
    scheduling, otherwise whichever schedule type the program/production
    uses (single date, recurring days, or a plain date range). Returns ''
    if there's nothing schedule-worthy on file, so the caller can leave the
    "You're registered for" box out of the email entirely rather than show
    it empty."""
    import json as _jsched

    def fmt_date(d):
        if not d:
            return ''
        try:
            y, m, day = [int(x) for x in d.split('-')]
            return date(y, m, day).strftime('%B %-d, %Y')
        except Exception:
            return d

    def fmt_time(t):
        if not t:
            return ''
        try:
            h, m = t.split(':')
            h = int(h)
            ampm = 'AM' if h < 12 else 'PM'
            h12 = h % 12 or 12
            return f'{h12}:{m} {ampm}' if m != '00' else f'{h12} {ampm}'
        except Exception:
            return t

    # Session-based programs: list the specific session(s) this family chose
    if prog and prog.get('sessions_enabled'):
        try:
            session_ids = _jsched.loads(reg.get('session_ids') or '[]')
        except Exception:
            session_ids = []
        if session_ids:
            all_sessions = fetchall(conn, 'SELECT * FROM program_sessions WHERE program_id=%s', (prog['id'],)) or []
            chosen = [s for s in all_sessions if s['id'] in session_ids]
            lines = []
            for s in chosen:
                bits = [s.get('name', '')]
                detail_bits = []
                if s.get('day_of_week'):
                    detail_bits.append(s['day_of_week'])
                if s.get('start_time'):
                    time_range = fmt_time(s['start_time'])
                    if s.get('end_time'):
                        time_range += '–' + fmt_time(s['end_time'])
                    detail_bits.append(time_range)
                if detail_bits:
                    bits.append('(' + ', '.join(detail_bits) + ')')
                lines.append(' '.join(b for b in bits if b))
            if lines:
                return '<br>'.join(lines)

    # Plain program scheduling (no sessions, or sessions not chosen for some reason)
    if prog:
        schedule_type = prog.get('schedule_type') or 'date_range'
        out = ''
        if schedule_type == 'single' and prog.get('single_date'):
            out = fmt_date(prog['single_date'])
        elif schedule_type == 'recurring':
            try:
                days = _jsched.loads(prog.get('meeting_days') or '[]')
            except Exception:
                days = []
            out = ', '.join(days)
            if prog.get('start_date'):
                out += (' — ' if out else '') + fmt_date(prog['start_date'])
                if prog.get('end_date') and prog['end_date'] != prog['start_date']:
                    out += ' through ' + fmt_date(prog['end_date'])
        else:
            out = fmt_date(prog.get('start_date', ''))
            if prog.get('end_date') and prog['end_date'] != prog.get('start_date'):
                out += ' – ' + fmt_date(prog['end_date'])
        if prog.get('meeting_start_time'):
            time_range = fmt_time(prog['meeting_start_time'])
            if prog.get('meeting_end_time'):
                time_range += '–' + fmt_time(prog['meeting_end_time'])
            out += (', ' if out else '') + time_range
        return out.strip(' ,–')

    # Productions (e.g. Rising Stars): just the run dates, if set
    if prod:
        out = fmt_date(prod.get('start_date', ''))
        if prod.get('end_date') and prod['end_date'] != prod.get('start_date'):
            out += ' – ' + fmt_date(prod['end_date'])
        return out

    return ''


def _registration_amount_summary(conn, reg, base_price):
    """Reconstructs the dollar breakdown for a single registration —
    subtotal, discounts, total after discounts, amount paid, and balance
    due — using the same amount_paid_cents-with-fallback logic already
    used for revenue reporting (see the session/program revenue queries),
    so an invoice always agrees with what the dashboards say was actually
    collected rather than computing its own separate answer.
    'paid_in_full' is comped OR balance_cents <= 0."""
    is_comped = bool(reg.get('is_comped'))
    discount = reg.get('discount_amount') or 0
    sib_discount = reg.get('sibling_discount_amount') or 0
    if is_comped:
        paid_cents = 0
        total_cents = 0
    elif reg.get('amount_paid_cents') is not None:
        paid_cents = reg['amount_paid_cents']
        total_cents = paid_cents + (reg.get('balance_due') or 0)
    else:
        # Older/unbackfilled registration with no webhook-confirmed amount
        # on file yet — best estimate from list price, same fallback used
        # in the revenue reports. Step Up holds are checked first since a
        # charged hold is a firmer number than an estimate off list price.
        step_up = fetchone(conn, """SELECT hold_status, amount FROM step_up_child_holds
            WHERE registration_id=%s ORDER BY created_at DESC LIMIT 1""", (reg['id'],))
        if step_up and step_up.get('hold_status') == 'charged':
            paid_cents = step_up.get('amount') or 0
        else:
            paid_cents = max(0, (base_price or 0) * (reg.get('participant_count') or 1) - discount - sib_discount)
        total_cents = paid_cents + (reg.get('balance_due') or 0)
    balance_cents = reg.get('balance_due') or 0
    return {
        'subtotal_cents': total_cents + discount + sib_discount,
        'discount_cents': discount,
        'sibling_discount_cents': sib_discount,
        'total_cents': total_cents,
        'paid_cents': paid_cents,
        'balance_cents': balance_cents,
        'is_comped': is_comped,
        'paid_in_full': is_comped or balance_cents <= 0,
    }


def _build_registration_invoice_html(reg, entity_name, schedule_info, summary, invoice_number, payment_info=None, memo=''):
    """Letterhead-style invoice/receipt for a single registration — meant
    for a family who wants an official-looking document confirming the
    student's name, what they registered for, and that they're paid in
    full (or what's still owed). payment_info (optional) is
    {'brand','last4','paid_at_display'} pulled live from Square — omitted
    entirely for comped/free/non-card registrations rather than showing
    blank fields."""
    def money(cents):
        return f'${(cents or 0)/100:,.2f}'
    student_name = f"{reg.get('child_first_name','')} {reg.get('child_last_name','')}".strip() or 'Participant'
    guardian_name = reg.get('guardian_name') or ''
    guardian_email = reg.get('guardian_email') or ''
    today_str = date.today().strftime('%B %-d, %Y')
    logo_url = 'https://rolecall.hwtco.org/static/images/hwtc_logo_teal.png'

    rows = ''
    label = 'Comped Registration' if summary['is_comped'] else entity_name
    rows += (f'<tr><td style="padding:8px 0;color:#374151">{label}</td>'
             f'<td style="padding:8px 0;text-align:right;color:#374151">{money(summary["subtotal_cents"])}</td></tr>')
    if summary['discount_cents']:
        rows += (f'<tr><td style="padding:8px 0;color:#6b7280">Discount{" (" + reg["discount_code"] + ")" if reg.get("discount_code") else ""}</td>'
                 f'<td style="padding:8px 0;text-align:right;color:#6b7280">-{money(summary["discount_cents"])}</td></tr>')
    if summary['sibling_discount_cents']:
        rows += (f'<tr><td style="padding:8px 0;color:#6b7280">Sibling Discount</td>'
                 f'<td style="padding:8px 0;text-align:right;color:#6b7280">-{money(summary["sibling_discount_cents"])}</td></tr>')

    status_color = '#0d3d4d' if summary['paid_in_full'] else '#92400e'
    status_bg = '#e1f5ee' if summary['paid_in_full'] else '#fef3c7'
    status_text = 'PAID IN FULL' if summary['paid_in_full'] else f'BALANCE DUE: {money(summary["balance_cents"])}'

    payment_block = ''
    if payment_info and payment_info.get('last4'):
        brand = (payment_info.get('brand') or '').replace('_', ' ').title()
        paid_at = payment_info.get('paid_at_display') or ''
        payment_block = (
            '<table style="margin-top:16px"><tr><td style="vertical-align:top;width:50%">'
            '<div class="info-label">Payment Method</div>'
            f'<div style="font-size:13px;color:#374151">{brand} ending in {payment_info["last4"]}</div>'
            '</td><td style="vertical-align:top;width:50%">'
            '<div class="info-label">Payment Date</div>'
            f'<div style="font-size:13px;color:#374151">{paid_at or "&mdash;"}</div>'
            '</td></tr></table>'
        )

    memo_block = ''
    if memo and memo.strip():
        memo_block = (
            '<div style="margin-top:20px;padding:12px 14px;background:#f8fafc;border-left:3px solid #d1d5db;border-radius:0 8px 8px 0">'
            '<div class="info-label" style="margin-bottom:4px">Memo</div>'
            f'<div style="font-size:12.5px;color:#374151;white-space:pre-wrap;line-height:1.5">{memo.strip()}</div>'
            '</div>'
        )

    return f'''<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"/>
<title>Invoice - {student_name}</title>
<style>
@page {{ margin: 50px }}
* {{ box-sizing: border-box }}
body {{ font-family: Helvetica, Arial, sans-serif; color: #1a1a18; font-size: 13px }}
.brand {{ font-size: 18px; font-weight: 700; color: #0d3d4d }}
.brand-sub {{ font-size: 11px; color: #6b7280; margin-top: 2px }}
h1 {{ font-size: 22px; font-weight: 700; color: #0d3d4d; text-align: right; margin: 0 }}
.meta {{ text-align: right; font-size: 11.5px; color: #6b7280; margin-top: 4px }}
.rule {{ border: none; border-top: 2px solid #145466; margin: 20px 0 }}
table {{ width: 100%; border-collapse: collapse }}
.info-label {{ font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px; color: #9ca3af; margin-bottom: 3px }}
.info-value {{ font-size: 14px; font-weight: 600; color: #1a1a18 }}
.total-row td {{ padding-top: 14px; border-top: 1.5px solid #d1d5db; font-weight: 700; font-size: 15px; color: #0d3d4d }}
.status-box {{ margin-top: 24px; padding: 14px 18px; border-radius: 8px; background: {status_bg}; color: {status_color}; font-weight: 700; font-size: 15px; text-align: center; letter-spacing: 0.5px }}
.footer {{ margin-top: 40px; padding-top: 16px; border-top: 1px solid #e8e6e0; font-size: 10.5px; color: #9ca3af; text-align: center }}
</style></head>
<body>
<table><tr>
<td style="vertical-align:top;width:60%">
  <img src="{logo_url}" alt="Horizon West Theater Company" style="height:44px;width:158px;margin-bottom:6px"/>
  <div class="brand">Horizon West Theater Company</div>
  <div class="brand-sub">1220 Winter Garden Vineland Rd, Suite 108, Winter Garden, FL 34787</div>
  <div class="brand-sub">hwtco.org &middot; info@hwtco.org</div>
</td>
<td style="vertical-align:top;width:40%">
  <h1>INVOICE</h1>
  <div class="meta">Invoice #{invoice_number}<br/>{today_str}</div>
</td>
</tr></table>

<hr class="rule"/>

<table><tr>
<td style="vertical-align:top;width:50%">
  <div class="info-label">Billed To</div>
  <div class="info-value">{guardian_name or student_name}</div>
  {f'<div style="font-size:12px;color:#6b7280;margin-top:2px">{guardian_email}</div>' if guardian_email else ''}
</td>
<td style="vertical-align:top;width:50%">
  <div class="info-label">Participant</div>
  <div class="info-value">{student_name}</div>
  {f'<div style="font-size:12px;color:#6b7280;margin-top:2px">{schedule_info}</div>' if schedule_info else ''}
</td>
</tr></table>

<table style="margin-top:28px">
<tr><td style="padding-bottom:8px;border-bottom:1.5px solid #d1d5db;font-size:10.5px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#9ca3af">Description</td>
<td style="padding-bottom:8px;border-bottom:1.5px solid #d1d5db;font-size:10.5px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#9ca3af;text-align:right">Amount</td></tr>
{rows}
<tr class="total-row"><td>Total</td><td style="text-align:right">{money(summary["total_cents"])}</td></tr>
<tr><td style="padding-top:4px;color:#6b7280">Amount Paid</td><td style="padding-top:4px;text-align:right;color:#6b7280">{money(summary["paid_cents"])}</td></tr>
</table>

{payment_block}

<div class="status-box">{status_text}</div>

{memo_block}

<div class="footer">
Horizon West Theater Company is an all-volunteer 501(c)(3) nonprofit community theater. Thank you for your support!
</div>
</body></html>'''


@app.route('/api/registrations/<rid>/invoice', methods=['GET'])
def download_registration_invoice(rid):
    """Official invoice/receipt PDF for a single confirmed registration —
    student name, program/class, amount breakdown, payment method (fetched
    live from Square when a payment ID is on file), and a clear PAID IN
    FULL / balance due stamp. Works for both youth_programs registrations
    and production (Rising Stars) registrations, since program_registrations
    covers both via program_id/production_id."""
    err = require_auth()
    if err: return err
    conn = get_db()
    reg = fetchone(conn, 'SELECT * FROM program_registrations WHERE id=%s', (rid,))
    if not reg:
        conn.close()
        return jsonify({'error': 'Registration not found'}), 404
    section = 'rising_stars' if reg.get('production_id') else 'programs'
    perm_err = require_permission(section, 'view')
    if perm_err:
        conn.close()
        return perm_err
    prog = fetchone(conn, 'SELECT * FROM youth_programs WHERE id=%s', (reg['program_id'],)) if reg.get('program_id') else None
    prod = fetchone(conn, 'SELECT * FROM productions WHERE id=%s', (reg['production_id'],)) if reg.get('production_id') else None
    if not prog and not prod:
        conn.close()
        return jsonify({'error': 'The program or production for this registration no longer exists'}), 404
    entity_name = (prog or prod).get('name', 'Registration')
    base_price = (prog or prod).get('price', 0)
    schedule_info = _format_registration_schedule(conn, prog, prod, reg)
    summary = _registration_amount_summary(conn, reg, base_price)
    conn.close()

    payment_info = None
    if reg.get('square_payment_id'):
        sp = square_get_payment(reg['square_payment_id'])
        if sp:
            card = (sp.get('card_details') or {}).get('card') or {}
            if card.get('last_4'):
                payment_info = {
                    'brand': card.get('card_brand', ''),
                    'last4': card.get('last_4', ''),
                    'paid_at_display': _format_square_timestamp(sp.get('created_at', '')),
                }

    invoice_number = rid[:8].upper()
    html = _build_registration_invoice_html(reg, entity_name, schedule_info, summary, invoice_number,
        payment_info=payment_info, memo=reg.get('invoice_memo', ''))
    pdf_b64 = _html_to_pdf_b64(html)
    student_name = f"{reg.get('child_first_name','')} {reg.get('child_last_name','')}".strip() or 'Participant'
    return _rental_pdf_response(pdf_b64, f'Invoice - {student_name} - {entity_name}')


def split_registration_by_session(conn, reg_id):
    """One registration that booked several sessions becomes one registration
    per session (same person, same payment), with the amounts divided by each
    session's price. Returns the ids of all resulting registrations."""
    reg = fetchone(conn, 'SELECT * FROM program_registrations WHERE id=%s', (reg_id,))
    if not reg:
        return []
    try:
        sids = [x for x in json.loads(reg.get('session_ids') or '[]') if x]
    except Exception:
        sids = []
    if len(sids) < 2:
        return [reg_id]
    prog = fetchone(conn, 'SELECT price FROM youth_programs WHERE id=%s', (reg['program_id'],)) or {}
    sess = {r['id']: r for r in fetchall(conn, 'SELECT id, price_override FROM program_sessions WHERE id = ANY(%s)', (sids,)) or []}
    weights = []
    for sid in sids:
        po = (sess.get(sid) or {}).get('price_override')
        weights.append(float(po) if po not in (None, '') else float(prog.get('price') or 1) or 1.0)
    total_w = sum(weights) or float(len(sids))
    money_cols = ['amount_paid', 'amount_paid_cents', 'discount_amount', 'balance_due', 'sibling_discount_amount', 'refund_amount_cents']
    def shares(v):
        if v in (None, ''):
            return [v] * len(sids)
        v = int(v); out, given = [], 0
        for i, w in enumerate(weights):
            part = v - given if i == len(weights) - 1 else int(round(v * w / total_w))
            out.append(part); given += part
        return out
    split = {c: shares(reg.get(c)) for c in money_cols if c in reg}
    group = reg.get('registration_group_id') or uuid.uuid4().hex
    cols = [c for c in reg.keys() if c not in ('id',)]
    ids = [reg_id]
    for i, sid in enumerate(sids):
        vals = dict(reg)
        vals['session_ids'] = json.dumps([sid])
        vals['registration_group_id'] = group
        for c, parts in split.items():
            vals[c] = parts[i]
        if i == 0:
            sets = ', '.join(c + '=%s' for c in ['session_ids', 'registration_group_id'] + list(split.keys()))
            execute(conn, 'UPDATE program_registrations SET ' + sets + ', updated_at=NOW() WHERE id=%s',
                    tuple([vals['session_ids'], group] + [vals[c] for c in split.keys()] + [reg_id]))
        else:
            nid = str(uuid.uuid4())
            vals['id'] = nid
            # keep the welcome-email stamp so nobody gets a second welcome
            use = ['id'] + cols
            execute(conn, 'INSERT INTO program_registrations (' + ', '.join(use) + ') VALUES (' + ', '.join(['%s'] * len(use)) + ')',
                    tuple(vals[c] for c in use))
            ids.append(nid)
    conn.commit()
    return ids


@app.route('/api/registrations/<rid>/add-session', methods=['POST'])
def api_registration_add_session(rid):
    """Give the same person another booked date as its own registration,
    e.g. a family that paid for two lessons but only one date was recorded.
    split_payment divides what they already paid between the two dates;
    otherwise the new date is added with nothing paid toward it."""
    err = require_auth()
    if err: return err
    d = request.json or {}
    sid = d.get('session_id')
    conn = get_db()
    try:
        reg = fetchone(conn, 'SELECT * FROM program_registrations WHERE id=%s', (rid,))
        if not reg or not sid:
            return jsonify({'error': 'Pick a session.'}), 400
        sess = fetchone(conn, 'SELECT id FROM program_sessions WHERE id=%s AND program_id=%s', (sid, reg['program_id']))
        if not sess:
            return jsonify({'error': 'That session isn\'t part of this program.'}), 400
        try:
            cur = [x for x in json.loads(reg.get('session_ids') or '[]') if x]
        except Exception:
            cur = []
        if sid in cur:
            return jsonify({'error': 'They\'re already booked in that session.'}), 400
        execute(conn, 'UPDATE program_registrations SET session_ids=%s WHERE id=%s', (json.dumps(cur + [sid]), rid))
        conn.commit()
        ids = split_registration_by_session(conn, rid)
        new_id = next((i for i in ids if i != rid), None)
        if new_id and not d.get('split_payment'):
            # put the original's amounts back; the added date has nothing paid
            for col in ('amount_paid', 'amount_paid_cents', 'discount_amount', 'balance_due', 'sibling_discount_amount', 'refund_amount_cents'):
                if col in reg:
                    execute(conn, 'UPDATE program_registrations SET ' + col + '=%s WHERE id=%s', (reg.get(col), rid))
                    execute(conn, 'UPDATE program_registrations SET ' + col + '=%s WHERE id=%s', (None if reg.get(col) is None else 0, new_id))
            conn.commit()
        try:
            ensure_session_events(conn, reg['program_id'])
        except Exception as e:
            app.logger.warning(f'ensure_session_events after add-session failed: {e}')
        return jsonify({'ok': True, 'registration_ids': ids})
    finally:
        conn.close()


@app.route('/api/registrations/<rid>/split-sessions', methods=['POST'])
def api_split_registration_sessions(rid):
    err = require_auth()
    if err: return err
    conn = get_db()
    try:
        ids = split_registration_by_session(conn, rid)
        if not ids:
            return jsonify({'error': 'Registration not found'}), 404
        try:
            r0 = fetchone(conn, 'SELECT program_id FROM program_registrations WHERE id=%s', (rid,)) or {}
            ensure_session_events(conn, r0.get('program_id'))
        except Exception as e:
            app.logger.warning(f'ensure_session_events after split failed: {e}')
        return jsonify({'ok': True, 'registration_ids': ids, 'count': len(ids)})
    finally:
        conn.close()


def finalize_registration(conn, reg_id, payment_id=None, order_id=None):
    """Mark registration confirmed and create participant records."""
    reg = fetchone(conn, 'SELECT * FROM program_registrations WHERE id=%s', (reg_id,))
    if not reg: return
    prog = fetchone(conn, 'SELECT * FROM youth_programs WHERE id=%s', (reg.get('program_id'),)) if reg.get('program_id') else None
    prod = fetchone(conn, 'SELECT * FROM productions WHERE id=%s', (reg.get('production_id'),)) if reg.get('production_id') else None

    # Update registration status
    execute(conn, '''UPDATE program_registrations SET status='confirmed',
        square_payment_id=%s, square_order_id=%s, updated_at=NOW() WHERE id=%s''',
        (payment_id or reg.get('square_payment_id'), order_id or reg.get('square_order_id'), reg_id))

    reg_reviewed = set(f for f in (reg.get('reviewed_fields') or '').split(',') if f)

    def get_or_create_participant(first, last, dob, shirt, own_email=None, sibling=None):
        """Find existing participant by guardian email + name, or create new one.
        own_email, when given, is the *participant's own* email (used for
        adult self-registrants) — stored directly on youth_participants,
        separate from any youth_guardians record."""
        if not first:
            return None
        existing = fetchone(conn, '''SELECT yp.* FROM youth_participants yp
            JOIN youth_guardians yg ON yg.youth_id=yp.id
            WHERE LOWER(yg.email)=LOWER(%s)
            AND LOWER(yp.first_name)=LOWER(%s)
            AND LOWER(yp.last_name)=LOWER(%s)''',
            (reg['guardian_email'], first, last or ''))

        medical_notes = reg.get('notes') or ''
        allergies = reg.get('allergies') or ''
        pronouns = reg.get('pronouns') or ''
        photo_consent = 1 if reg.get('photo_consent') else 0
        reviewed = set(reg_reviewed)
        if sibling is not None:
            # A child from siblings_json (cart flow): never take the first
            # child's allergies/pronouns — only what was entered for them.
            allergies = (sibling.get('allergies') or '').strip()
            pronouns = ''
            reviewed.discard('pronouns')
            if not sibling.get('reviewed'):
                reviewed.discard('allergies')

        if existing:
            # Update existing participant with any new info from registration.
            # Fields the family reviewed pre-filled are taken exactly as
            # submitted (so clearing allergies or unchecking photo consent
            # sticks); everything else only fills in, never erases.
            allergies_sql = '%s' if 'allergies' in reviewed else "COALESCE(NULLIF(%s,''), allergies)"
            pronouns_sql = '%s' if 'pronouns' in reviewed else "COALESCE(NULLIF(%s,''), pronouns)"
            consent_sql = '%s' if 'photo_consent' in reviewed else 'GREATEST(photo_consent, %s)'
            try:
                execute(conn, '''UPDATE youth_participants SET
                    shirt_size=COALESCE(NULLIF(%s,''), shirt_size),
                    dob=COALESCE(dob, %s),
                    medical_notes=COALESCE(NULLIF(%s,''), medical_notes),
                    allergies=''' + allergies_sql + ''',
                    pronouns=''' + pronouns_sql + ''',
                    photo_consent=''' + consent_sql + ''',
                    email=COALESCE(NULLIF(%s,''), email)
                    WHERE id=%s''',
                    (shirt or '', dob or None, medical_notes, allergies, pronouns, photo_consent,
                     own_email or '', existing['id']))
            except Exception as eu:
                app.logger.warning(f'Participant update from reg: {eu}')
            # Emergency contact: add if none on file; if the family reviewed
            # it and changed it, update the most recent one in place.
            if reg.get('emergency_contact_name'):
                try:
                    ec_exists = fetchone(conn, '''SELECT id, name, phone FROM youth_emergency_contacts
                        WHERE youth_id=%s ORDER BY created_at DESC LIMIT 1''', (existing['id'],))
                    if ec_exists and 'emergency_contact' in reviewed:
                        new_ec_name = reg.get('emergency_contact_name') or ''
                        new_ec_phone = reg.get('emergency_contact_phone') or ''
                        if new_ec_name != (ec_exists.get('name') or '') or new_ec_phone != (ec_exists.get('phone') or ''):
                            execute(conn, 'UPDATE youth_emergency_contacts SET name=%s, phone=%s WHERE id=%s',
                                    (new_ec_name, new_ec_phone, ec_exists['id']))
                    if not ec_exists:
                        import uuid as _uec
                        execute(conn, '''INSERT INTO youth_emergency_contacts
                            (id, youth_id, name, relationship, phone)
                            VALUES (%s,%s,%s,%s,%s) ON CONFLICT DO NOTHING''',
                            (str(_uec.uuid4()), existing['id'],
                             reg.get('emergency_contact_name',''),
                             'Emergency Contact',
                             reg.get('emergency_contact_phone','') or ''))
                except Exception as ece:
                    app.logger.warning(f'Emergency contact insert: {ece}')
            if not existing.get('passphrase'):
                pp = default_passphrase(existing.get('first_name') or first, existing.get('last_name') or last)
                execute(conn, 'UPDATE youth_participants SET passphrase=%s WHERE id=%s', (pp, existing['id']))
                existing['passphrase'] = pp
            return existing

        import uuid as _u
        yid = str(_u.uuid4())
        passphrase = default_passphrase(first, last)
        try:
            execute(conn, '''INSERT INTO youth_participants
                (id, first_name, last_name, dob, shirt_size, medical_notes, allergies, pronouns, photo_consent, passphrase, email)
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)''',
                (yid, first, last or '', dob or None, shirt or '',
                 medical_notes, allergies, pronouns, photo_consent, passphrase, own_email or ''))
        except Exception:
            # Fallback if columns don't exist yet
            execute(conn, '''INSERT INTO youth_participants (id, first_name, last_name, dob, shirt_size, passphrase)
                VALUES (%s,%s,%s,%s,%s,%s)''',
                (yid, first, last or '', dob or None, shirt or '', passphrase))
        # Add emergency contact
        if reg.get('emergency_contact_name'):
            try:
                import uuid as _uec2
                execute(conn, '''INSERT INTO youth_emergency_contacts
                    (id, youth_id, name, relationship, phone)
                    VALUES (%s,%s,%s,%s,%s) ON CONFLICT DO NOTHING''',
                    (str(_uec2.uuid4()), yid,
                     reg.get('emergency_contact_name',''),
                     'Emergency Contact',
                     reg.get('emergency_contact_phone','') or ''))
            except Exception as ece2:
                app.logger.warning(f'Emergency contact insert: {ece2}')
        return fetchone(conn, 'SELECT * FROM youth_participants WHERE id=%s', (yid,))

    def ensure_guardian(youth_id):
        existing = fetchone(conn, 'SELECT id, phone FROM youth_guardians WHERE youth_id=%s AND LOWER(email)=LOWER(%s)',
            (youth_id, reg['guardian_email']))
        if existing and reg.get('guardian_phone') and reg.get('guardian_phone') != (existing.get('phone') or ''):
            execute(conn, 'UPDATE youth_guardians SET phone=%s WHERE id=%s', (reg['guardian_phone'], existing['id']))
        if not existing and reg.get('guardian_name'):
            import uuid as _ug
            # Programs that don't require a guardian are adults registering
            # themselves — the "guardian_email" field just holds their own
            # contact info in that case, so label it as such rather than
            # calling them their own "Parent/Guardian".
            relationship = 'Self' if (prog and not prog.get('requires_guardian')) else 'Parent/Guardian'
            execute(conn, '''INSERT INTO youth_guardians
                (id, youth_id, name, relationship, email, phone, is_primary)
                VALUES (%s,%s,%s,%s,%s,%s,1) ON CONFLICT DO NOTHING''',
                (str(_ug.uuid4()), youth_id,
                 reg.get('guardian_name') or '',
                 relationship,
                 reg['guardian_email'], reg.get('guardian_phone') or ''))

    def enroll(youth_id):
        if not prog and not prod: return
        try:
            import uuid as _ue
            if prog:
                execute(conn, '''INSERT INTO youth_program_enrollments
                    (id, youth_id, program_id, enrolled_date, notes)
                    VALUES (%s,%s,%s,NOW()::TEXT,%s)
                    ON CONFLICT (youth_id, program_id) DO NOTHING''',
                    (str(_ue.uuid4()), youth_id, prog['id'], f'Online registration #{reg_id[:8]}'))
            elif prod:
                execute(conn, '''INSERT INTO youth_program_enrollments
                    (id, youth_id, production_id, enrolled_date, notes)
                    VALUES (%s,%s,%s,NOW()::TEXT,%s)
                    ON CONFLICT (youth_id, production_id) WHERE production_id IS NOT NULL DO NOTHING''',
                    (str(_ue.uuid4()), youth_id, prod['id'], f'Online registration #{reg_id[:8]}'))
                # Youth productions (Rising Stars or Teen Show): the Cast tab is driven
                # by youth_production_members, not youth_program_enrollments — auto-add
                # confirmed registrants there too so staff don't have to manually
                # "+ Enroll" everyone who registers.
                if prod.get('stage') in ('rising_stars', 'teen_show'):
                    existing_member = fetchone(conn, '''SELECT id FROM youth_production_members
                        WHERE production_id=%s AND youth_id=%s''', (prod['id'], youth_id))
                    if not existing_member:
                        execute(conn, '''INSERT INTO youth_production_members (id, production_id, youth_id, role)
                            VALUES (%s,%s,%s,%s)''', (str(_ue.uuid4()), prod['id'], youth_id, ''))
        except Exception as e:
            app.logger.warning(f'Enrollment insert: {e}')

    # Primary participant
    is_adult_registrant = bool(prog and not prog.get('requires_guardian'))
    youth = get_or_create_participant(
        reg.get('child_first_name'), reg.get('child_last_name'),
        reg.get('child_dob'), reg.get('shirt_size'),
        own_email=reg.get('guardian_email') if is_adult_registrant else None)
    if youth:
        # For adult self-registrants, their email now lives directly on their
        # own profile (above) — a "guardian" record calling them their own
        # parent/guardian never made sense, so skip creating one.
        if not is_adult_registrant:
            ensure_guardian(youth['id'])
        enroll(youth['id'])
        try:
            execute(conn, 'UPDATE program_registrations SET youth_id=%s WHERE id=%s', (youth['id'], reg_id))
        except Exception as e:
            app.logger.warning(f'Could not link youth_id to registration {reg_id}: {e}')

    # Siblings
    import json as _json_sib
    try:
        siblings = _json_sib.loads(reg.get('siblings_json') or '[]')
    except Exception:
        siblings = []
    for sib in (siblings or []):
        sib_youth = get_or_create_participant(
            (sib.get('first_name') or '').strip(),
            (sib.get('last_name') or '').strip(),
            sib.get('dob'), sib.get('shirt_size'),
            sibling=sib if isinstance(sib, dict) else {})
        if sib_youth:
            ensure_guardian(sib_youth['id'])
            enroll(sib_youth['id'])

    conn.commit()

    # Welcome email — sent once per family, the first time a registration is
    # confirmed. Sibling sign-ups created together via create_grouped_registrations
    # share a registration_group_id (one row per child) — finalize_registration
    # runs once per row in that case, so we check/mark the whole group, not just
    # this one row, or a 2-kid signup would send two duplicate welcome emails.
    # Adults get this email too now — just with adult-appropriate wording (no
    # "your child"/pick-up framing) driven by age, not registration_form_type,
    # since age is the more directly meaningful signal for whether pick-up/
    # family language actually makes sense for this specific registrant.
    if youth:
        try:
            group_id = reg.get('registration_group_id')
            if group_id:
                already_sent = fetchone(conn, '''SELECT id FROM program_registrations
                    WHERE registration_group_id=%s AND welcome_email_sent_at IS NOT NULL''', (group_id,))
            else:
                already_sent = fetchone(conn, '''SELECT id FROM program_registrations
                    WHERE id=%s AND welcome_email_sent_at IS NOT NULL''', (reg_id,))
            if not already_sent:
                tmpl = get_system_template(conn, 'welcome_email')
                if tmpl and reg.get('guardian_email'):
                    program_name = (prog or {}).get('name') or (prod or {}).get('name') or 'your program'
                    schedule_info = _format_registration_schedule(conn, prog, prod, reg)
                    schedule_block = ''
                    if schedule_info:
                        schedule_block = (
                            '<div class="callout" style="background:#f1efe8;border-left-color:#0d4a38">'
                            '<p style="color:#04342C"><strong>You\'re registered for:</strong><br>' + schedule_info + '</p></div>'
                        )
                    age = calc_age_from_dob(youth.get('dob') or reg.get('child_dob'))
                    if age is not None:
                        is_adult = age >= 18
                    else:
                        # No real birthdate on file — fall back to what they told us on
                        # the form (adult/open-age programs ask this directly). Only
                        # trust an explicit "no" (18+); anything else (unanswered, or
                        # genuinely under 18 with no dob somehow) defaults to the safer
                        # "not confirmed adult" treatment.
                        is_adult = reg.get('reported_under_18') == 'no'
                    passphrase_block = ''
                    if not is_adult:
                        passphrase_block = (
                            '<div class="callout"><p><strong>Important  -  your passphrase is your child\'s pick-up password.</strong> '
                            'Once you set it, our staff will ask for this word whenever you pick up your child. '
                            'Choose something only you and approved pick-up adults know.</p></div>'
                        )
                    merge = {
                        'program_name': program_name,
                        'family_greeting': reg.get('guardian_name') or 'Family',
                        'passphrase': ensure_youth_passphrase(conn, youth),
                        'schedule_block': schedule_block,
                        'passphrase_block': passphrase_block,
                    }
                    merge.update(_welcome_email_adult_aware_blocks(is_adult, program_name))
                    subject = render_template_vars(tmpl['subject'], merge)
                    body = render_template_vars(tmpl['body'], merge)
                    send_email(reg['guardian_email'], subject, build_hwtc_email_html(subject, body), source='welcome_email')
                    if group_id:
                        execute(conn, 'UPDATE program_registrations SET welcome_email_sent_at=NOW() WHERE registration_group_id=%s', (group_id,))
                    else:
                        execute(conn, 'UPDATE program_registrations SET welcome_email_sent_at=NOW() WHERE id=%s', (reg_id,))
                    conn.commit()
        except Exception as e:
            app.logger.error(f'Welcome email send error for registration {reg_id}: {e}')
            import traceback; traceback.print_exc()

    # Make sure any session(s) this registration covers have a real, loggable
    # event — see _auto_create_events_for_registration for why this matters.
    _auto_create_events_for_registration(conn, reg, prog)

    # Booking-style programs (private lessons and other dated slots): someone
    # who books several slots at once gets one registration per slot, so each
    # date can be managed, moved or cancelled on its own. Done after the
    # confirmation/welcome emails so they still get one email listing all.
    try:
        if prog and prog.get('booking_mode') and prog.get('sessions_enabled'):
            split_registration_by_session(conn, reg_id)
    except Exception as e:
        app.logger.warning(f'Auto-split by session failed for {reg_id}: {e}')
        try: conn.rollback()
        except Exception: pass


def _auto_create_events_for_registration(conn, reg, prog):
    """Best-effort: as soon as a registration is confirmed, make sure a real
    event exists for each session it covers, so an instructor can log paid
    time against it right away — instead of only the lightweight synthetic
    calendar entry existing until a staff member notices it and clicks
    'Create Event' by hand. Safe to call repeatedly: skips any session that
    already has a linked event, and never raises (a failure here should
    never block the registration itself)."""
    if not prog or not reg.get('session_ids'):
        return
    try:
        session_ids = json.loads(reg.get('session_ids') or '[]')
    except Exception:
        session_ids = []
    for sid in session_ids:
        try:
            already = fetchone(conn, 'SELECT id FROM events WHERE linked_session_id=%s', (sid,))
            if already:
                continue
            s = fetchone(conn, 'SELECT * FROM program_sessions WHERE id=%s', (sid,))
            if not s or not s.get('start_date'):
                continue
            eid = str(uuid.uuid4())
            pname = (prog.get('name') if prog else '') or ''
            sname = s.get('name') or ''
            # "Private Vocal Workshops — Tue 4 PM" rather than just the slot
            # name, so the event is findable by the class name everywhere
            ename = (pname + ' — ' + sname) if (pname and sname and pname.lower() not in sname.lower()) else (sname or pname or 'Class Session')
            execute(conn, '''INSERT INTO events
                (id,name,event_date,start_time,end_time,location,program_id,linked_session_id,status,auto_log_hours)
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,'draft',TRUE)''',
                (eid, ename[:200],
                 s['start_date'], s.get('start_time') or None, s.get('end_time') or None,
                 s.get('location') or '', prog['id'], sid))
            conn.commit()
        except Exception as e:
            app.logger.warning(f'Auto-create event for session {sid} (registration {reg.get("id")}) failed: {e}')

def ensure_session_events(conn, program_id=None):
    """Catch-up for _auto_create_events_for_registration: registrations that
    were confirmed some other way (added by staff, marked paid by hand,
    split into one per date, moved to another slot) never got their
    session's event, so instructors had nothing to log time against.
    Creates any missing event for sessions with a confirmed registration,
    from a week ago onward. Returns how many were created."""
    q = '''SELECT DISTINCT pr.id, pr.session_ids, pr.program_id FROM program_registrations pr
        JOIN youth_programs yp ON yp.id=pr.program_id
        WHERE yp.sessions_enabled=TRUE AND pr.status IN ('confirmed','paid','active')
          AND COALESCE(pr.session_ids,'[]') NOT IN ('[]','')'''
    params = []
    if program_id:
        q += ' AND pr.program_id=%s'; params.append(program_id)
    regs = fetchall(conn, q, tuple(params)) or []
    cutoff = (today_eastern() - __import__('datetime').timedelta(days=7)).isoformat()
    before = (fetchone(conn, 'SELECT COUNT(*) AS n FROM events WHERE linked_session_id IS NOT NULL') or {}).get('n') or 0
    progs = {}
    for r in regs:
        try:
            sids = [x for x in json.loads(r.get('session_ids') or '[]') if x]
        except Exception:
            continue
        keep = []
        for sid in sids:
            srow = fetchone(conn, 'SELECT start_date FROM program_sessions WHERE id=%s', (sid,))
            if srow and str(srow.get('start_date') or '')[:10] >= cutoff:
                keep.append(sid)
        if not keep:
            continue
        if r['program_id'] not in progs:
            progs[r['program_id']] = fetchone(conn, 'SELECT * FROM youth_programs WHERE id=%s', (r['program_id'],))
        _auto_create_events_for_registration(conn, {'id': r['id'], 'session_ids': json.dumps(keep)}, progs[r['program_id']])
    after = (fetchone(conn, 'SELECT COUNT(*) AS n FROM events WHERE linked_session_id IS NOT NULL') or {}).get('n') or 0
    return int(after) - int(before)


@app.route('/api/youth-programs/<pid>/ensure-session-events', methods=['POST'])
def api_ensure_session_events(pid):
    err = require_auth()
    if err: return err
    conn = get_db()
    try:
        n = ensure_session_events(conn, pid)
    finally:
        conn.close()
    return jsonify({'ok': True, 'created': n})


def _registration_not_yet_open(prog):
    """Return (True, message) if this program/production has a scheduled open
    date/time still in the future, else (False, None). Time is optional; a bare
    date opens at 00:00 that day. All comparisons in America/New_York."""
    open_date = (prog.get('registration_open_date') or '').strip()
    if not open_date:
        return False, None
    open_time = ((prog.get('registration_open_time') or '').strip() or '00:00')[:5]
    try:
        from zoneinfo import ZoneInfo as _ZIno
        import datetime as _dtno
        open_dt = _dtno.datetime.fromisoformat(f'{open_date}T{open_time}:00').replace(tzinfo=_ZIno('America/New_York'))
        now = _dtno.datetime.now(_ZIno('America/New_York'))
        if now < open_dt:
            try:
                friendly = open_dt.strftime('%A, %B %-d at %-I:%M %p')
            except Exception:
                friendly = open_dt.strftime('%Y-%m-%d %H:%M')
            return True, f'Registration opens {friendly}.'
    except Exception:
        return False, None
    return False, None


def _check_age_eligibility(dob_str, min_age, max_age, grace_days, ref_date_str):
    """Checks one participant's age against a program/production's age
    range — as of the program's own start date, not today, since what
    matters is how old they'll actually be when it happens. Returns a
    tuple of (action, message):
      'ok'       — no restriction, or restriction met. message is None.
      'waitlist' — under min_age today but turns min_age within
                   grace_days of the start date (e.g. turns 18 two weeks
                   after a program that starts before their birthday) —
                   close enough that we don't want to hard-block, so
                   route to the waitlist instead with an explanation.
      'reject'   — outside the age range with no grace period saving it.
    A program/production with neither min_age nor max_age set always
    returns 'ok' — this is opt-in per program, not a global restriction.
    A missing/unparseable date of birth also returns 'ok' rather than
    blocking, since we can't check what we don't have."""
    if not min_age and not max_age:
        return ('ok', None)
    if not dob_str:
        return ('ok', None)
    try:
        dob = datetime.strptime(dob_str[:10], '%Y-%m-%d').date()
    except Exception:
        return ('ok', None)
    ref_date = date.today()
    if ref_date_str:
        try:
            ref_date = datetime.strptime(ref_date_str[:10], '%Y-%m-%d').date()
        except Exception:
            pass

    def age_on(d):
        return d.year - dob.year - ((d.month, d.day) < (dob.month, dob.day))

    age_on_ref = age_on(ref_date)

    if max_age and age_on_ref > max_age:
        return ('reject', f'This program is for ages up to {max_age} — the participant will be {age_on_ref} by the program start date.')

    if min_age and age_on_ref < min_age:
        try:
            turn_date = dob.replace(year=dob.year + min_age)
        except ValueError:
            # Feb 29 birthday landing on a non-leap turning year
            turn_date = dob.replace(year=dob.year + min_age, month=3, day=1)
        days_short = (turn_date - ref_date).days
        if grace_days and 0 <= days_short <= grace_days:
            return ('waitlist',
                f"This program requires participants to be {min_age}+ by the start date. The participant turns "
                f"{min_age} shortly after — rather than turning them away outright, we've added them to the "
                f"waitlist in case there's flexibility closer to the date.")
        return ('reject', f'This program requires participants to be at least {min_age} years old by the start date.')

    return ('ok', None)

