@app.route('/api/refund-requests/<rid>/process-square', methods=['POST'])
def process_square_refund(rid):
    err = require_permission('refund_requests')
    if err: return err
    conn = get_db()
    rr = fetchone(conn, 'SELECT * FROM refund_requests WHERE id=%s', (rid,))
    if not rr: conn.close(); return jsonify({'error': 'Not found'}), 404
    if rr.get('status') != 'approved':
        conn.close()
        return jsonify({'error': 'This request needs to go through "Begin Approval Process" before it can be signed off and processed.'}), 400
    if not rr.get('president_approved_by') or not rr.get('treasurer_approved_by'):
        conn.close()
        return jsonify({'error': 'This needs sign-off from both the President and Treasurer before it can be processed.'}), 400
    if not rr.get('square_order_id'): conn.close(); return jsonify({'error': 'No Square order ID on file'}), 400
    if not SQUARE_ACCESS_TOKEN: conn.close(); return jsonify({'error': 'Square not configured'}), 400
    d = request.json or {}
    amount_cents = d.get('amount_cents') or rr.get('refund_amount_cents')
    if not amount_cents: conn.close(); return jsonify({'error': 'No refund amount specified'}), 400
    try:
        import requests as _req
        # Get payment ID from order
        order_resp = _req.get(f'{SQUARE_API_BASE}/v2/orders/{rr["square_order_id"]}', headers=square_headers())
        order_data = order_resp.json()
        tenders = order_data.get('order', {}).get('tenders', [])
        if not tenders: conn.close(); return jsonify({'error': 'No payment found for this order'}), 400
        payment_id = tenders[0].get('payment_id') or tenders[0].get('id')
        # Issue refund
        refund_resp = _req.post(f'{SQUARE_API_BASE}/v2/refunds', headers=square_headers(), json={
            'idempotency_key': str(uuid.uuid4()),
            'payment_id': payment_id,
            'amount_money': {'amount': int(amount_cents), 'currency': 'USD'},
            'reason': f'HWTC Refund Request {rr["ref_number"]} — {rr["reason_category"]}'
        })
        refund_data = refund_resp.json()
        if 'refund' in refund_data:
            sq_refund_id = refund_data['refund']['id']
            execute(conn, '''UPDATE refund_requests SET status='processed',
                square_refund_id=%s, reviewed_at=NOW() WHERE id=%s''', (sq_refund_id, rid))
            conn.commit()
            # Mark the registration as refunded — this happens regardless
            # of whether they're also unenrolled, since "got money back"
            # and "no longer in the program" are two separate facts. This
            # is what makes revenue totals and the roster reflect the
            # refund; the unenroll step below is a separate, optional
            # choice staff make per-refund, not automatic.
            if rr.get('registration_id'):
                try:
                    execute(conn, '''UPDATE program_registrations
                        SET refunded_at=NOW(), refund_amount_cents=COALESCE(refund_amount_cents,0)+%s
                        WHERE id=%s''', (int(amount_cents), rr['registration_id']))
                    if d.get('unenroll'):
                        execute(conn, "UPDATE program_registrations SET status='cancelled' WHERE id=%s", (rr['registration_id'],))
                    conn.commit()
                except Exception: pass
            # This is the real "good news" moment — the refund has actually
            # happened, not just been reviewed — so this is where the
            # requester email belongs now, not at "Begin Approval Process".
            try:
                if rr.get('requester_email'):
                    send_email(rr['requester_email'], f'Your Refund Has Been Processed — {rr["ref_number"]}',
                        f'''<div style="font-family:sans-serif;max-width:600px;margin:0 auto">
                        <div style="background:#145466;padding:20px 24px">
                          <img src="https://rolecall.hwtco.org/static/images/hwtc_logo_white.png" height="40" style="height:40px"/>
                        </div>
                        <div style="padding:28px 24px">
                          <div style="background:#dcfce7;border:1.5px solid #86efac;border-radius:8px;padding:14px 16px;margin-bottom:20px">
                            <div style="font-size:16px;font-weight:700;color:#166534">Your refund has been processed</div>
                          </div>
                          <p style="color:#374151;font-size:15px;line-height:1.6">Dear {rr.get('requester_name','')},</p>
                          <p style="color:#374151;font-size:14px;line-height:1.6">Your refund (Ref: <strong>{rr["ref_number"]}</strong>) for <strong>{rr.get('participant_name','')}</strong> in <strong>{rr.get('program_name','')}</strong> has been issued to your original payment method.</p>
                          <p style="color:#374151;font-size:14px;line-height:1.6">Please allow <strong>5–10 business days</strong> for it to appear, depending on your bank or card issuer.</p>
                          <p style="color:#374151;font-size:14px;line-height:1.6">If you have any questions, please contact us at <a href="mailto:info@hwtco.org">info@hwtco.org</a> and reference your request number <strong>{rr["ref_number"]}</strong>.</p>
                          <p style="color:#374151;font-size:14px">Thank you,<br><strong>Horizon West Theater Company</strong></p>
                        </div>
                      </div>''', source='refund_status')
            except Exception as e:
                app.logger.warning(f'Refund processed email failed: {e}')
            conn.close()
            return jsonify({'ok': True, 'refund_id': sq_refund_id, 'amount_cents': amount_cents})
        else:
            errors = refund_data.get('errors', [])
            conn.close()
            return jsonify({'error': errors[0].get('detail','Square refund failed') if errors else 'Square refund failed'}), 400
    except Exception as e:
        app.logger.error(f'Square refund error: {e}')
        try: conn.rollback(); conn.close()
        except Exception: pass
        return jsonify({'error': str(e)}), 500

# ─────────────────────────────────────────────
#  SHOW LICENSING REQUESTS (internal)
# ─────────────────────────────────────────────

def _cents(v):
    """Parse a dollars value (e.g. 12.5, '12.50') into integer cents, or None."""
    if v in (None, ''):
        return None
    try:
        return int(round(float(v) * 100))
    except (TypeError, ValueError):
        return None

def _licensing_contract_status(row):
    """Derive a simple contract-tracking status for a licensing request:
    not_requested -> requested -> contract_on_file -> approved_to_produce -> expiring_soon -> expired
    approved_to_produce sits ahead of contract_on_file once the board has signed off on
    moving forward — it's the point BloomBooks watches to build out the production/budget."""
    if row.get('contract_received'):
        exp = row.get('contract_expires_date')
        if exp:
            try:
                exp_date = exp if isinstance(exp, date) else datetime.strptime(str(exp), '%Y-%m-%d').date()
                days_left = (exp_date - date.today()).days
                if days_left < 0:
                    return 'expired'
                if days_left <= 60:
                    return 'expiring_soon'
            except Exception:
                pass
        if row.get('approved_to_produce'):
            return 'approved_to_produce'
        return 'contract_on_file'
    if row.get('licensor_requested'):
        return 'requested'
    return 'not_requested'

def _attach_contract_status(rows):
    single = not isinstance(rows, list)
    items = [rows] if single else rows
    for r in items:
        r['contract_status'] = _licensing_contract_status(r)
    return items[0] if single else items

@app.route('/api/licensing-requests', methods=['GET'])
def get_licensing_requests():
    err = require_permission('licensing', 'view')
    if err: return err
    conn = get_db()
    status = request.args.get('status', '')
    if status:
        rows = fetchall(conn, 'SELECT * FROM licensing_requests WHERE status=%s ORDER BY submitted_at DESC', (status,)) or []
    else:
        rows = fetchall(conn, 'SELECT * FROM licensing_requests ORDER BY submitted_at DESC') or []
    conn.close()
    rows = _attach_contract_status(rows)
    return jsonify(rows)

@app.route('/api/licensing-requests/<lid>', methods=['GET'])
def get_licensing_request(lid):
    err = require_permission('licensing', 'view')
    if err: return err
    conn = get_db()
    row = fetchone(conn, 'SELECT * FROM licensing_requests WHERE id=%s', (lid,))
    conn.close()
    if not row: return jsonify({'error': 'Not found'}), 404
    row = _attach_contract_status(row)
    return jsonify(row)

@app.route('/licensing-request')
def licensing_request_page():
    return send_from_directory('static', 'licensing-request.html')

@app.route('/api/public/licensing-request', methods=['POST'])
def submit_licensing_request():
    """Standalone shareable form — anyone with the link can submit one or more show
    licensing requests at once. Shared fields (contact info, venue, orchestra,
    shipping, and show defaults) apply to every show in the `shows` array unless
    a show overrides a specific field itself."""
    d = request.json or {}
    requester_name  = (d.get('requester_name') or '').strip()
    requester_email = (d.get('requester_email') or '').strip().lower()
    shows_in = d.get('shows') or []
    if not requester_name or not requester_email:
        return jsonify({'error': 'Name and email are required'}), 400
    if not isinstance(shows_in, list) or not shows_in:
        return jsonify({'error': 'At least one production is required'}), 400
    for s in shows_in:
        if not (s.get('production_name') or '').strip():
            return jsonify({'error': 'Every production needs a name'}), 400

    conn = get_db()
    try:
        import random, string

        # Link to a staff account if the submitter happens to be logged in / matches a user
        matched_user = fetchone(conn, 'SELECT id FROM users WHERE LOWER(email)=%s', (requester_email,))
        requested_by = matched_user['id'] if matched_user else session.get('user_id')

        batch_id = str(uuid.uuid4())
        created = []  # [{id, ref_number, production_name}]

        for s in shows_in:
            lid = str(uuid.uuid4())
            ref_number = 'LIC-' + ''.join(random.choices(string.ascii_uppercase + string.digits, k=8))

            lowest_cents  = _cents(s.get('lowest_ticket_price'))
            highest_cents = _cents(s.get('highest_ticket_price'))
            if lowest_cents is not None and highest_cents is not None:
                avg_cents = round((lowest_cents + highest_cents) / 2)
            else:
                avg_cents = lowest_cents or highest_cents

            show_rehearsal_tracks = s.get('needs_rehearsal_tracks', None)
            show_rehearsal_tracks = bool(d.get('needs_rehearsal_tracks')) if show_rehearsal_tracks is None else bool(show_rehearsal_tracks)

            show_streaming = s.get('addon_streaming_license', None)
            show_streaming = bool(d.get('addon_streaming_license')) if show_streaming is None else bool(show_streaming)

            show_video = s.get('addon_video_recording_license', None)
            show_video = bool(d.get('addon_video_recording_license')) if show_video is None else bool(show_video)

            show_marketing = s.get('addon_marketing_package', None)
            show_marketing = bool(d.get('addon_marketing_package')) if show_marketing is None else bool(show_marketing)

            execute(conn, '''INSERT INTO licensing_requests
                (id, ref_number, batch_id, production_id, requested_by, requester_name, requester_email,
                 production_name, production_type, production_type_other, production_edition, licensor, licensor_other,
                 production_start_date, production_end_date, venue_name, venue_address,
                 venue_capacity, audience_capacity, performance_dates, number_of_shows,
                 lowest_ticket_price_cents, highest_ticket_price_cents, average_ticket_price_cents,
                 expected_performers, scripts_needed, additional_scripts,
                 has_live_orchestra, needs_full_score, orchestra_size, orchestra_instruments,
                 needs_rehearsal_tracks, needs_performance_tracks,
                 ship_to_name, ship_to_address, ship_to_phone, materials_needed_by,
                 addon_streaming_license, addon_video_recording_license, addon_marketing_package,
                 addon_marketing_notes, addon_logo_choice, addon_youth_production,
                 addon_choreography_guides, addon_directors_guide, addon_broadway_media_scenic,
                 additional_requests)
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)''',
                (lid, ref_number, batch_id, s.get('production_id') or None, requested_by,
                 requester_name, requester_email,
                 (s.get('production_name') or '').strip(), s.get('production_type', ''), s.get('production_type_other', ''),
                 s.get('production_edition', ''),
                 s.get('licensor', ''), s.get('licensor_other', ''),
                 s.get('production_start_date', ''), s.get('production_end_date', ''),
                 d.get('venue_name', ''), d.get('venue_address', ''),
                 d.get('venue_capacity') or None, d.get('audience_capacity') or None,
                 json.dumps(s.get('performance_dates') or []), s.get('number_of_shows') or None,
                 lowest_cents, highest_cents, avg_cents,
                 s.get('expected_performers') or None, s.get('scripts_needed') or None,
                 json.dumps(d.get('additional_scripts') or []),
                 bool(d.get('has_live_orchestra')), bool(d.get('needs_full_score')),
                 d.get('orchestra_size') or None, d.get('orchestra_instruments', ''),
                 show_rehearsal_tracks, bool(d.get('needs_performance_tracks')),
                 d.get('ship_to_name', ''), d.get('ship_to_address', ''), d.get('ship_to_phone', ''),
                 d.get('materials_needed_by', ''),
                 show_streaming, show_video,
                 show_marketing, d.get('addon_marketing_notes', ''),
                 d.get('addon_logo_choice', ''), False,
                 bool(d.get('addon_choreography_guides')), False,
                 bool(d.get('addon_broadway_media_scenic')), s.get('additional_requests', '')))

            created.append({'id': lid, 'ref_number': ref_number, 'production_name': (s.get('production_name') or '').strip()})

        conn.commit()

        show_rows_html = ''.join(
            f'<li><b>{c["production_name"]}</b> — Ref {c["ref_number"]}</li>' for c in created
        )

        # Notify the President and Resident Producer only — they're the ones who action
        # licensing requests, not every admin login.
        try:
            es = get_email_settings()
            notify_emails = []
            president_name = _rc_current_officer_name(conn, 'president')
            if president_name:
                pres = fetchone(conn, "SELECT email FROM board_members WHERE name=%s AND status='active'", (president_name,))
                if pres and pres.get('email'):
                    notify_emails.append(pres['email'])
            rp_rows = fetchall(conn, "SELECT email FROM board_members WHERE role ILIKE '%%resident producer%%' AND status='active'") or []
            notify_emails += [r['email'] for r in rp_rows if r.get('email')]
            notify_emails = list(set(notify_emails))
            if notify_emails and es.get('resend_api_key'):
                subject = f'New Show Licensing Request{"s" if len(created) > 1 else ""} — {len(created)} production{"s" if len(created) > 1 else ""}'
                send_email(
                    ','.join(notify_emails),
                    subject,
                    build_hwtc_email_html(subject, f'''
                        <h3>New show licensing request{"s" if len(created) > 1 else ""} received</h3>
                        <p><b>Requested by:</b> {requester_name} ({requester_email})<br>
                        <b>Venue:</b> {d.get("venue_name","")}</p>
                        <ul>{show_rows_html}</ul>
                        <p><a href="https://rolecall.hwtco.org" style="background:#145466;color:#fff;padding:10px 20px;border-radius:6px;text-decoration:none;display:inline-block;margin-top:8px">Review in RoleCall</a></p>
                      '''),
                    source='licensing_request_admin')
        except Exception as e:
            app.logger.warning(f'Licensing request admin notification failed: {e}')

        # Confirmation email to the submitter
        try:
            es = get_email_settings()
            if es.get('resend_api_key'):
                send_email(
                    requester_email,
                    f'Licensing Request{"s" if len(created) > 1 else ""} Received',
                    f'''<div style="font-family:sans-serif;max-width:600px;margin:0 auto">
                        <div style="background:#145466;padding:20px 24px">
                          <img src="https://rolecall.hwtco.org/static/images/hwtc_logo_white.png" height="40" style="height:40px"/>
                        </div>
                        <div style="padding:28px 24px">
                          <h2 style="color:#111;margin-bottom:8px">Licensing Request{"s" if len(created) > 1 else ""} Received</h2>
                          <p style="color:#374151;font-size:15px;line-height:1.6">Thanks, {requester_name}. We've received the following licensing request{"s" if len(created) > 1 else ""}:</p>
                          <ul style="color:#374151;font-size:14px;line-height:1.8">{show_rows_html}</ul>
                          <p style="color:#374151;font-size:14px;line-height:1.6">Our team will review these and follow up with next steps.</p>
                        </div>
                      </div>''',
                    source='licensing_request_confirmation')
        except Exception as e:
            app.logger.warning(f'Licensing request confirmation email failed: {e}')

        conn.close()
        return jsonify({'ok': True, 'batch_id': batch_id, 'requests': created})
    except Exception as e:
        app.logger.error(f'Licensing request error: {e}')
        try: conn.rollback(); conn.close()
        except Exception: pass
        return jsonify({'error': str(e)}), 500

@app.route('/api/licensing-requests/<lid>', methods=['PUT'])
def update_licensing_request(lid):
    """Action a licensing request — used by whoever handles licensing (e.g. producer/admin)."""
    err = require_permission('licensing')
    if err: return err
    d = request.json or {}
    conn = get_db()
    lr = fetchone(conn, 'SELECT * FROM licensing_requests WHERE id=%s', (lid,))
    if not lr:
        conn.close()
        return jsonify({'error': 'Not found'}), 404

    new_status = d.get('status', lr.get('status'))
    admin_notes = d.get('admin_notes', lr.get('admin_notes', ''))
    reviewer = d.get('reviewed_by') or session.get('user_name', '')

    # Contract tracking fields — only touched when explicitly provided so partial
    # updates (e.g. just toggling status) don't clobber existing tracking data.
    licensor_requested = d.get('licensor_requested', lr.get('licensor_requested', False))
    licensor_requested_date = d.get('licensor_requested_date', lr.get('licensor_requested_date'))
    if d.get('licensor_requested') and not lr.get('licensor_requested') and not d.get('licensor_requested_date'):
        licensor_requested_date = date.today().isoformat()
    contract_received = d.get('contract_received', lr.get('contract_received', False))
    contract_received_date = d.get('contract_received_date', lr.get('contract_received_date'))
    if d.get('contract_received') and not lr.get('contract_received') and not d.get('contract_received_date'):
        contract_received_date = date.today().isoformat()
    contract_expires_date = d.get('contract_expires_date', lr.get('contract_expires_date'))

    execute(conn, '''UPDATE licensing_requests SET status=%s, admin_notes=%s,
        reviewed_by=%s, reviewed_at=NOW(), updated_at=NOW(),
        licensor_requested=%s, licensor_requested_date=%s,
        contract_received=%s, contract_received_date=%s,
        contract_expires_date=%s WHERE id=%s''',
        (new_status, admin_notes, reviewer,
         licensor_requested, licensor_requested_date or None,
         contract_received, contract_received_date or None,
         contract_expires_date or None, lid))
    conn.commit()
    row = fetchone(conn, 'SELECT * FROM licensing_requests WHERE id=%s', (lid,))
    conn.close()
    row = _attach_contract_status(row)
    return jsonify(row)

@app.route('/api/licensing-requests/<lid>/approve-to-produce', methods=['POST'])
def approve_licensing_request_to_produce(lid):
    """Board sign-off to move forward and produce this show. Requires the
    signed contract to already be on file. Approving automatically creates
    the real RoleCall production (if one isn't already linked) — its
    rehearsal schedule gets built out afterward on the production itself
    (Production detail → Schedule & Conflicts), which is what BloomBooks pulls from."""
    err = require_permission('licensing')
    if err: return err
    d = request.json or {}
    conn = get_db()
    lr = fetchone(conn, 'SELECT * FROM licensing_requests WHERE id=%s', (lid,))
    if not lr:
        conn.close()
        return jsonify({'error': 'Not found'}), 404
    if not lr.get('contract_received'):
        conn.close()
        return jsonify({'error': 'Contract must be on file before approving to produce'}), 400
    approved = bool(d.get('approved', True))
    approver = session.get('user_name', '')

    execute(conn, '''UPDATE licensing_requests SET approved_to_produce=%s,
        approved_to_produce_date=%s, approved_to_produce_by=%s,
        updated_at=NOW() WHERE id=%s''',
        (approved, date.today().isoformat() if approved else None, approver if approved else '', lid))

    created_production_id = None
    if approved and not lr.get('production_id'):
        created_production_id = str(uuid.uuid4())
        execute(conn, '''INSERT INTO productions
            (id,name,production_type,stage,start_date,end_date,description,status)
            VALUES (%s,%s,%s,%s,%s,%s,%s,'upcoming')''',
            (created_production_id, lr.get('production_name') or '', lr.get('production_type') or 'show',
             'mainstage', lr.get('production_start_date') or None, lr.get('production_end_date') or None,
             f"Auto-created from licensing request {lr.get('ref_number','')}"))
        execute(conn, 'UPDATE licensing_requests SET production_id=%s WHERE id=%s', (created_production_id, lid))

    conn.commit()
    row = fetchone(conn, 'SELECT * FROM licensing_requests WHERE id=%s', (lid,))
    conn.close()
    row = _attach_contract_status(row)
    if created_production_id:
        row['created_production_id'] = created_production_id
    return jsonify(row)

@app.route('/api/licensing-requests/<lid>/contract-file', methods=['POST'])
def upload_licensing_contract_file(lid):
    """Attach the signed/returned contract document to a licensing request."""
    err = require_permission('licensing')
    if err: return err
    conn = get_db()
    lr = fetchone(conn, 'SELECT * FROM licensing_requests WHERE id=%s', (lid,))
    if not lr:
        conn.close()
        return jsonify({'error': 'Not found'}), 404
    if 'file' not in request.files:
        conn.close()
        return jsonify({'error': 'No file provided'}), 400
    f = request.files['file']
    if not f or not f.filename:
        conn.close()
        return jsonify({'error': 'No file selected'}), 400
    ext = os.path.splitext(secure_filename(f.filename))[1].lower()
    if ext not in ['.pdf', '.doc', '.docx', '.jpg', '.jpeg', '.png']:
        conn.close()
        return jsonify({'error': 'Invalid file type — use PDF, Word, or an image'}), 400
    filename = f'licensing-contract-{lid[:8]}-{str(uuid.uuid4())[:8]}{ext}'
    f.save(os.path.join(UPLOAD_FOLDER, filename))
    # Remove any previously-attached file for this request
    old_filename = lr.get('contract_file_name')
    if old_filename:
        try: os.remove(os.path.join(UPLOAD_FOLDER, old_filename))
        except Exception: pass
    contract_received_date = lr.get('contract_received_date') or date.today().isoformat()
    execute(conn, '''UPDATE licensing_requests SET contract_file_name=%s, contract_file_original_name=%s,
        contract_received=TRUE, contract_received_date=%s, updated_at=NOW() WHERE id=%s''',
        (filename, f.filename, contract_received_date, lid))
    conn.commit()
    row = fetchone(conn, 'SELECT * FROM licensing_requests WHERE id=%s', (lid,))
    conn.close()
    row = _attach_contract_status(row)
    return jsonify(row)

@app.route('/api/licensing-requests/<lid>/contract-file', methods=['GET'])
def download_licensing_contract_file(lid):
    err = require_permission('licensing', 'view')
    if err: return err
    conn = get_db()
    lr = fetchone(conn, 'SELECT * FROM licensing_requests WHERE id=%s', (lid,))
    conn.close()
    if not lr or not lr.get('contract_file_name'):
        return jsonify({'error': 'No file attached'}), 404
    filepath = os.path.join(UPLOAD_FOLDER, lr['contract_file_name'])
    if not os.path.exists(filepath):
        return jsonify({'error': 'File not found on disk'}), 404
    return send_file(filepath, as_attachment=True, download_name=lr.get('contract_file_original_name') or lr['contract_file_name'])

@app.route('/api/licensing-requests/<lid>/contract-file', methods=['DELETE'])
def delete_licensing_contract_file(lid):
    err = require_permission('licensing')
    if err: return err
    conn = get_db()
    lr = fetchone(conn, 'SELECT * FROM licensing_requests WHERE id=%s', (lid,))
    if lr and lr.get('contract_file_name'):
        try: os.remove(os.path.join(UPLOAD_FOLDER, lr['contract_file_name']))
        except Exception: pass
    execute(conn, '''UPDATE licensing_requests SET contract_file_name='', contract_file_original_name='',
        updated_at=NOW() WHERE id=%s''', (lid,))
    conn.commit()
    conn.close()
    return jsonify({'ok': True})

# ── Returning-family registration prefill ─────────────────────────────────────
# A parent who has registered before types their email on the public
# registration form; if that email is on a youth_guardians record (or is an
# adult self-registrant's own email on youth_participants), we email them a
# signed, time-limited link back to the same form. Opening the link loads what
# we already have on file (guardian contact, each child's details, emergency
# contact, last pickup list) into the form for them to review.
#
# The email alone never returns data; clicking the emailed link is what proves
# the person controls that inbox. Tokens are stateless (itsdangerous, signed
# with app.secret_key), so there's no table/migration. They're reusable until
# they expire, so a page refresh doesn't strand the parent.
from itsdangerous import URLSafeTimedSerializer, BadSignature, SignatureExpired

RETURNING_PREFILL_SALT = 'returning-family-prefill-v1'
RETURNING_PREFILL_MAX_AGE = 2 * 60 * 60   # link valid for 2 hours
RETURNING_LINK_COOLDOWN = 120             # seconds between emails to one address
_returning_link_last_sent = {}            # email -> epoch seconds (per worker; best-effort)


def program_hidden_from_request(p):
    """True if p is a private class and this request didn't bring its link key.
    Private classes don't appear in any listing and can only be opened with
    /register/<slug>?k=<key>. Logged-in staff can always preview."""
    if not p or not p.get('is_private'):
        return False
    if 'user_id' in session:
        return False
    k = request.args.get('k') or ''
    if not k:
        body = request.get_json(silent=True) or {}
        if isinstance(body, dict):
            k = body.get('k') or ''
    return not (p.get('private_key') and hmac.compare_digest(str(k), str(p['private_key'])))


def _returning_serializer():
    return URLSafeTimedSerializer(app.secret_key, salt=RETURNING_PREFILL_SALT)


def _returning_prefill_enabled():
    # Never issue signed links with the fallback dev key — anyone reading the
    # repo could forge them.
    return bool(app.secret_key) and app.secret_key != 'rollcall-dev-key'


def _returning_family_known(conn, email):
    g = fetchone(conn, 'SELECT id FROM youth_guardians WHERE LOWER(email)=%s LIMIT 1', (email,))
    if g: return True
    y = fetchone(conn, "SELECT id FROM youth_participants WHERE LOWER(email)=%s LIMIT 1", (email,))
    return bool(y)


@app.route('/api/public/returning-family/request-link', methods=['POST'])
def public_returning_family_request_link():
    """Email a prefill link to a returning family. Always answers the same way,
    whether or not the email is on file, so this can't be used to check who
    has registered with HWTC."""
    d = request.json or {}
    email = (d.get('email') or '').strip().lower()
    slug = (d.get('slug') or '').strip()
    is_production = bool(d.get('is_production'))
    generic = {'ok': True, 'message': "If that email is on file with us, we've sent you a link. It's good for 2 hours."}

    if not email or '@' not in email or not slug or not _returning_prefill_enabled():
        return jsonify(generic)

    import time as _t
    now = _t.time()
    last = _returning_link_last_sent.get(email) or 0
    if now - last < RETURNING_LINK_COOLDOWN:
        return jsonify(generic)

    conn = get_db()
    try:
        # Only build links to real registration pages
        if slug == 'cart':
            target = {'name': 'your HWTC programs', 'slug': 'cart'}
            if not _returning_family_known(conn, email):
                return jsonify(generic)
        elif is_production:
            target = fetchone(conn, 'SELECT id, name, slug FROM productions WHERE slug=%s OR id=%s', (slug, slug))
        else:
            target = fetchone(conn, 'SELECT id, name, slug, is_private, private_key FROM youth_programs WHERE slug=%s OR id=%s', (slug, slug))
            if target and program_hidden_from_request(target):
                target = None
        if slug != 'cart' and (not target or not _returning_family_known(conn, email)):
            return jsonify(generic)
    finally:
        conn.close()

    _returning_link_last_sent[email] = now
    token = _returning_serializer().dumps({'e': email})
    path_prefix = 'production/' if (is_production and slug != 'cart') else ''
    link = 'https://rolecall.hwtco.org/register/' + path_prefix + (target.get('slug') or slug) + '?rt=' + token
    if target.get('is_private') and target.get('private_key'):
        link += '&k=' + target['private_key']
    prog_name = target.get('name') or 'HWTC'
    body = (
        '<p>Hi there,</p>'
        '<p>Here is your link to register for <strong>' + prog_name + '</strong> using the information we already have on file for your family:</p>'
        '<p style="text-align:center;margin:24px 0"><a href="' + link + '" '
        'style="display:inline-block;background:#145466;color:#fff;text-decoration:none;padding:12px 28px;border-radius:8px;font-weight:700">'
        'Continue my registration</a></p>'
        '<p>Please look everything over before you submit, especially allergies, emergency contacts, and who is allowed to pick up.</p>'
        '<p style="color:#6b7280;font-size:13px">This link works for 2 hours. If you didn\'t ask for it, you can ignore this email.</p>'
    )
    try:
        send_email([email], 'Your HWTC registration link: ' + prog_name,
                   build_hwtc_email_html('Your registration link', body),
                   source='returning_family_prefill')
    except Exception as e:
        app.logger.warning(f'Returning-family link email failed: {e}')
    return jsonify(generic)


@app.route('/api/public/returning-family/prefill')
def public_returning_family_prefill():
    """Exchange a valid prefill token for the family's on-file details."""
    token = (request.args.get('rt') or '').strip()
    if not token or not _returning_prefill_enabled():
        return jsonify({'error': 'Invalid link'}), 400
    try:
        data = _returning_serializer().loads(token, max_age=RETURNING_PREFILL_MAX_AGE)
    except SignatureExpired:
        return jsonify({'error': 'This link has expired. Request a new one from the registration page.', 'expired': True}), 400
    except BadSignature:
        return jsonify({'error': 'Invalid link'}), 400
    email = (data.get('e') or '').strip().lower()
    if not email:
        return jsonify({'error': 'Invalid link'}), 400

    conn = get_db()
    try:
        guardian = fetchone(conn, '''SELECT name, phone FROM youth_guardians
            WHERE LOWER(email)=%s ORDER BY is_primary DESC, created_at DESC LIMIT 1''', (email,))

        kids = fetchall(conn, '''SELECT DISTINCT yp.id, yp.first_name, yp.last_name, yp.dob,
                yp.shirt_size, yp.allergies, yp.pronouns, yp.photo_consent, yp.created_at
            FROM youth_participants yp
            JOIN youth_guardians yg ON yg.youth_id=yp.id
            WHERE LOWER(yg.email)=%s AND COALESCE(yp.status,'active')='active'
            ORDER BY yp.created_at''', (email,)) or []

        # Adult self-registrant whose own email is on their participant record
        self_rec = fetchone(conn, '''SELECT id, first_name, last_name, dob, shirt_size,
                allergies, pronouns, photo_consent
            FROM youth_participants
            WHERE LOWER(email)=%s AND COALESCE(status,'active')='active'
            ORDER BY created_at DESC LIMIT 1''', (email,))

        people = []
        for k in kids:
            people.append(dict(k, is_self=False))
        if self_rec and not any(p['id'] == self_rec['id'] for p in people):
            people.append(dict(self_rec, is_self=True))

        for p in people:
            ec = fetchone(conn, '''SELECT name, phone FROM youth_emergency_contacts
                WHERE youth_id=%s ORDER BY created_at DESC LIMIT 1''', (p['id'],))
            p['emergency_contact_name'] = (ec or {}).get('name') or ''
            p['emergency_contact_phone'] = (ec or {}).get('phone') or ''
            last_reg = fetchone(conn, '''SELECT pickup_contacts FROM program_registrations
                WHERE LOWER(guardian_email)=%s AND LOWER(child_first_name)=LOWER(%s)
                  AND LOWER(COALESCE(child_last_name,''))=LOWER(%s)
                  AND COALESCE(pickup_contacts,'')<>''
                ORDER BY created_at DESC LIMIT 1''', (email, p['first_name'] or '', p['last_name'] or ''))
            p['pickup_contacts'] = (last_reg or {}).get('pickup_contacts') or ''
            p['photo_consent'] = bool(p.get('photo_consent'))
            p.pop('created_at', None)
            p.pop('id', None)   # the form doesn't need internal ids

        self_name = ''
        if self_rec:
            self_name = ((self_rec.get('first_name') or '') + ' ' + (self_rec.get('last_name') or '')).strip()
        return jsonify({
            'ok': True,
            'email': email,
            'guardian_name': (guardian or {}).get('name') or self_name,
            'guardian_phone': (guardian or {}).get('phone') or '',
            'people': people,
        })
    finally:
        conn.close()


@app.route('/api/portal/registration-link', methods=['POST'])
def portal_registration_link():
    """Signed prefill token for a family already logged into the portal, so
    'Register' in the portal opens the public form with their info filled in.
    The portal passphrase is the proof here (no email round-trip), and the
    form only receives what the portal already shows this family."""
    d = request.json or {}
    passphrase = (d.get('passphrase') or '').strip().lower()
    if not passphrase:
        return jsonify({'error': 'Please log in again.'}), 401
    if not _returning_prefill_enabled():
        return jsonify({'error': 'Online re-registration is not available right now.'}), 503
    conn = get_db()
    try:
        member_ids = []
        family = fetchone(conn, 'SELECT id, email FROM families WHERE LOWER(passphrase)=%s', (passphrase,))
        if family:
            member_ids = [m['id'] for m in (fetchall(conn,
                'SELECT id FROM youth_participants WHERE family_id=%s', (family['id'],)) or [])]
        else:
            youth = fetchone(conn, 'SELECT id FROM youth_participants WHERE LOWER(passphrase)=%s', (passphrase,))
            if youth:
                member_ids = [youth['id']]
        if not member_ids:
            return jsonify({'error': 'Please log in again.'}), 401

        email = ''
        for yid in member_ids:
            g = fetchone(conn, '''SELECT email FROM youth_guardians
                WHERE youth_id=%s AND COALESCE(email,'')<>''
                ORDER BY is_primary DESC, created_at LIMIT 1''', (yid,))
            if g:
                email = g['email']
                break
        if not email:
            for yid in member_ids:
                y = fetchone(conn, "SELECT email FROM youth_participants WHERE id=%s AND COALESCE(email,'')<>''", (yid,))
                if y:
                    email = y['email']
                    break
        if not email and family and family.get('email'):
            email = family['email']
        if not email:
            return jsonify({'error': "We don't have an email on file for your family yet. Please register from the program page, or contact HWTC staff."}), 400
        token = _returning_serializer().dumps({'e': email.strip().lower()})
        return jsonify({'ok': True, 'token': token})
    finally:
        conn.close()


def program_spots_remaining(conn, p):
    """Spots left. For programs with sessions, that's what's left across the
    sessions people can still book (open, not cancelled, not already past),
    not the program's own capacity field. None means no limit."""
    if not p.get('sessions_enabled'):
        if not p.get('capacity'):
            return None
        return max(0, (p.get('capacity') or 0) - get_registration_count(conn, p['id']))
    rows = fetchall(conn, '''SELECT ps.id, ps.capacity, ps.start_date,
            (SELECT COUNT(*) FROM program_registrations WHERE program_id=%s AND session_ids LIKE '%%"' || ps.id || '"%%'
             AND status NOT IN ('cancelled','waitlisted')) AS enrolled
        FROM program_sessions ps WHERE ps.program_id=%s AND COALESCE(ps.status,'open') NOT IN ('cancelled','closed')''',
        (p['id'], p['id'])) or []
    today = today_eastern().isoformat()
    rows = [r for r in rows if not r.get('start_date') or str(r['start_date'])[:10] >= today]
    if not rows:
        return 0
    if any(r.get('capacity') in (None, 0) for r in rows):
        return None
    return sum(max(0, int(r['capacity']) - int(r['enrolled'] or 0)) for r in rows)


@app.route('/api/public/program/<slug>')
def public_program_info(slug):
    """Public program info — no auth needed."""
    conn = get_db()
    p = fetchone(conn, 'SELECT * FROM youth_programs WHERE slug=%s OR id=%s', (slug, slug))
    if not p or program_hidden_from_request(p):
        conn.close()
        return jsonify({'error': 'Program not found'}), 404
    # Attach counts
    p['registration_count'] = get_registration_count(conn, p['id'])
    p['waitlist_count'] = get_waitlist_count(conn, p['id'])
    p['spots_remaining'] = program_spots_remaining(conn, p)
    # Attach instructor name
    if p.get('instructor_id'):
        v = fetchone(conn, 'SELECT name, bio, photo_url FROM volunteers WHERE id=%s', (p['instructor_id'],))
        if v:
            p['instructor_name'] = v['name']
            p['instructor_bio'] = v.get('bio') or ''
            p['instructor_photo'] = v.get('photo_url') or ''
    conn.close()
    # Remove internal fields
    # Parse JSON fields
    for k in ['custom_fields','program_images','interest_list_fields','meeting_days']:
        if p.get(k):
            try: p[k] = json.loads(p[k])
            except: p[k] = []
    if p.get('form_fields'):
        try: p['form_fields'] = json.loads(p['form_fields'])
        except: p['form_fields'] = {}
    for k in ['default_elic_id','created_by','updated_by','square_catalog_item_id','private_key']:
        p.pop(k, None)
    return jsonify(p)


@app.route('/api/public/program/<slug>/register', methods=['POST'])
def public_submit_registration(slug):
    """Submit a registration or interest list entry."""
    d = request.json or {}
    conn = get_db()
    p = fetchone(conn, 'SELECT * FROM youth_programs WHERE slug=%s OR id=%s', (slug, slug))
    if not p or program_hidden_from_request(p):
        conn.close()
        return jsonify({'error': 'Program not found'}), 404

    reg_type = d.get('type', 'registration')  # 'registration' or 'interest'
    email = (d.get('guardian_email') or d.get('email') or '').strip().lower()
    if not email:
        conn.close()
        return jsonify({'error': 'Email is required'}), 400

    # ── Interest list ──────────────────────────────────────────────────
    if reg_type == 'interest' or p.get('registration_status') == 'interest_list':
        try:
            import uuid as _u
            execute(conn, '''INSERT INTO interest_list_entries
                (id, program_id, name, email, phone, child_name, child_age, notes)
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s)
                ON CONFLICT (program_id, email) DO UPDATE SET
                    name=EXCLUDED.name, phone=EXCLUDED.phone,
                    child_name=EXCLUDED.child_name, child_age=EXCLUDED.child_age,
                    notes=EXCLUDED.notes''',
                (_u.uuid4().hex, p['id'], d.get('name','').strip(), email,
                 d.get('phone','').strip() or None,
                 d.get('child_name','').strip() or None,
                 d.get('child_age','').strip() or None,
                 d.get('notes','').strip() or None))
            conn.commit()
            # Notify admin
            try:
                s = get_email_settings(conn)
                recipients = list(get_recipient_emails(s))
                if recipients:
                    send_email(recipients, f'Interest List: {p["name"]} — {d.get("name","")}',
                        build_hwtc_email_html(f'Interest List: {p["name"]} — {d.get("name","")}',
                        f'<p><strong>{d.get("name","")}</strong> ({email}) joined the interest list for <strong>{p["name"]}</strong>.</p>'))
            except Exception: pass
            # Thank-you email to the family
            try:
                submitter_name = (d.get('name') or '').strip().split()[0] or 'there'
                child_name = (d.get('child_name') or '').strip()
                send_email([email], f'You\'re on the interest list — {p["name"]}',
                    f'<div style="font-family:-apple-system,\'DM Sans\',sans-serif;max-width:560px;margin:0 auto;color:#1a2332">'
                    f'<div style="background:linear-gradient(135deg,#0d3d4d,#1b708d);padding:28px 24px;text-align:center;border-radius:12px 12px 0 0">'
                    f'<img src="https://rolecall.hwtco.org/static/images/hwtc_logo_white.png" alt="HWTC" style="height:48px;margin-bottom:10px;display:block;margin-left:auto;margin-right:auto"/>'
                    f'</div>'
                    f'<div style="background:#fff;padding:28px 28px 24px;border-radius:0 0 12px 12px;border:1px solid #e5e7eb">'
                    f'<h2 style="color:#0d3d4d;font-size:20px;margin:0 0 12px">You\'re on the list!</h2>'
                    f'<p style="color:#374151;line-height:1.6;margin:0 0 14px">Hi {submitter_name},</p>'
                    f'<p style="color:#374151;line-height:1.6;margin:0 0 14px">'
                    f'Thanks for your interest in <strong>{p["name"]}</strong>{"!" if not child_name else f" for <strong>{child_name}</strong>!"} '
                    f'We\'ve added you to our interest list and will reach out as soon as registration opens.</p>'
                    f'<p style="color:#374151;line-height:1.6;margin:0 0 24px">'
                    f'We\'ll also send you a direct link to register when the time comes, so keep an eye on your inbox.</p>'
                    f'<div style="background:#f0f9ff;border-left:4px solid #145466;padding:14px 16px;border-radius:0 8px 8px 0;margin-bottom:24px">'
                    f'<div style="font-size:13px;color:#145466;font-weight:700;margin-bottom:4px">Program</div>'
                    f'<div style="font-size:15px;font-weight:700;color:#0d3d4d">{p["name"]}</div>'
                    f'</div>'
                    f'<p style="color:#6b7280;font-size:13px;margin:0">Questions? Reply to this email or visit '
                    f'<a href="https://hwtco.org" style="color:#145466">hwtco.org</a>.</p>'
                    f'<hr style="border:none;border-top:1px solid #e5e7eb;margin:20px 0"/>'
                    f'<p style="color:#9ca3af;font-size:12px;margin:0;text-align:center">'
                    f'Horizon West Theater Company &nbsp;&middot;&nbsp; Horizon West, FL</p>'
                    f'</div></div>')
            except Exception as e:
                app.logger.warning(f'Interest list thank-you email failed: {e}')
            conn.close()
            return jsonify({'ok': True, 'type': 'interest'})
        except Exception as e:
            conn.close()
            return jsonify({'error': str(e)}), 500

    # ── Registration ───────────────────────────────────────────────────
    if p.get('registration_status') not in ('open',):
        conn.close()
        return jsonify({'error': 'Registrations are not currently open for this program'}), 400

    # For "Adult / open age" programs, the form asks the registrant whether
    # they're under 18 — if so, a real birthdate is required (used for
    # age-appropriate wording elsewhere, e.g. the welcome email). If they're
    # 18+, it's optional. Mirrors the same check on the registration form
    # itself — this exists so it can't be skipped by calling the API directly.
    if (p.get('registration_form_type') == 'adult'):
        reported_under_18 = (d.get('reported_under_18') or '').strip()
        if reported_under_18 == 'yes' and not (d.get('child_dob') or '').strip():
            conn.close()
            return jsonify({'error': 'Date of birth is required for participants under 18.'}), 400

    _not_yet, _opens_msg = _registration_not_yet_open(p)
    if _not_yet:
        conn.close()
        return jsonify({'error': _opens_msg, 'not_open_yet': True}), 400

    # Age eligibility — opt-in per program via min_age/max_age in Registration
    # Settings, with an optional per-session override (e.g. a program like
    # "Private Vocal Workshops" might only want an age gate on certain
    # session slots — a teen-only time, say — while leaving the program
    # itself open). A session only overrides a field it has its own value
    # for; anything left blank on the session falls back to the program's
    # setting. Checked against the program's start date, or the specific
    # session's start date when a session overrides, and before the
    # capacity check, so an age-ineligible child sees the age-specific
    # message rather than a generic "full"/waitlist message if both apply.
    _age_session_ids = d.get('session_ids') or []
    if not isinstance(_age_session_ids, list): _age_session_ids = []
    age_check_specs = []  # (min_age, max_age, grace_days, ref_date, session_label)
    if _age_session_ids:
        for _sid in _age_session_ids:
            _sr = fetchone(conn, '''SELECT name, start_date, min_age, max_age, age_grace_days
                FROM program_sessions WHERE id=%s AND program_id=%s''', (_sid, p['id']))
            if not _sr:
                continue
            _s_min = _sr['min_age'] if _sr.get('min_age') is not None else p.get('min_age')
            _s_max = _sr['max_age'] if _sr.get('max_age') is not None else p.get('max_age')
            _s_grace = _sr['age_grace_days'] if _sr.get('age_grace_days') is not None else p.get('age_grace_days')
            _s_ref = _sr.get('start_date') or p.get('start_date')
            age_check_specs.append((_s_min, _s_max, _s_grace, _s_ref, _sr.get('name') or ''))
    else:
        age_check_specs.append((p.get('min_age'), p.get('max_age'), p.get('age_grace_days'), p.get('start_date'), ''))

    # A self-registering adult (registration_form_type='adult') only has to give
    # an exact birthdate if they say they're under 18 — otherwise DOB is
    # optional, since most programs don't need it. But that means a plain "no,
    # I'm 18+" with no DOB would otherwise sail straight through any age gate
    # below (an empty DOB is treated as "can't check, allow it" — see
    # _check_age_eligibility). So for that specific case, stand in the
    # youngest DOB consistent with what they told us (exactly 18 today) —
    # correctly clears any minimum up to 18, and correctly still catches a
    # kids-only maximum, without requiring/assuming an exact age beyond that.
    primary_dob = d.get('child_dob')
    if (not primary_dob and p.get('registration_form_type') == 'adult'
            and (d.get('reported_under_18') or '').strip() == 'no' and age_check_specs
            and any(spec[0] or spec[1] for spec in age_check_specs)):
        _today = date.today()
        try:
            primary_dob = _today.replace(year=_today.year - 18).isoformat()
        except ValueError:
            primary_dob = _today.replace(year=_today.year - 18, day=28).isoformat()

    age_children = [{'first_name': (d.get('child_first_name') or '').strip(), 'dob': primary_dob}]
    for s in (d.get('siblings') or []):
        if isinstance(s, dict):
            age_children.append({'first_name': (s.get('first_name') or '').strip(), 'dob': s.get('dob')})
    age_grace_note = None
    needs_age_waitlist = False
    for c in age_children:
        for (_c_min, _c_max, _c_grace, _c_ref, _c_label) in age_check_specs:
            _action, _msg = _check_age_eligibility(c['dob'], _c_min, _c_max, _c_grace, _c_ref)
            if _action == 'reject':
                conn.close()
                prefix = (f"{c['first_name']}: " if c['first_name'] else '')
                suffix = f' (session: {_c_label})' if _c_label else ''
                return jsonify({'error': prefix + _msg + suffix}), 400
            if _action == 'waitlist':
                needs_age_waitlist = True
                age_grace_note = _msg

    if needs_age_waitlist:
        # Same per-child waitlist pattern as the capacity-full path below,
        # just with an age-specific note on each row so staff can see why
        # (distinct from a capacity waitlist) when reviewing the queue.
        siblings_agewl = d.get('siblings') or []
        if not isinstance(siblings_agewl, list): siblings_agewl = []
        agewl_children = [{'first_name': d.get('child_first_name','').strip(), 'last_name': d.get('child_last_name','').strip(),
                            'dob': d.get('child_dob'), 'shirt_size': d.get('shirt_size')}]
        for s in siblings_agewl:
            agewl_children.append({'first_name': (s.get('first_name') or '').strip(), 'last_name': (s.get('last_name') or '').strip(),
                                    'dob': s.get('dob'), 'shirt_size': s.get('shirt_size')})
        import uuid as _uwlage
        agewl_group_id = str(_uwlage.uuid4())
        agewl_ids = []
        agewl_positions = []
        for child in agewl_children:
            wpos = next_waitlist_position(conn, p['id'])
            wrid = str(_uwlage.uuid4())
            agewl_ids.append(wrid)
            agewl_positions.append(wpos)
            execute(conn, '''INSERT INTO program_registrations
                (id, program_id, registration_type, status, waitlist_position, registration_group_id,
                 child_first_name, child_last_name, child_dob, shirt_size,
                 guardian_name, guardian_email, guardian_phone,
                 emergency_contact_name, emergency_contact_phone, notes, participant_count, siblings_json)
                VALUES (%s,%s,'registration','waitlisted',%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,1,'[]')''',
                (wrid, p['id'], wpos, agewl_group_id,
                 child['first_name'], child['last_name'], child['dob'] or None, child['shirt_size'] or None,
                 d.get('guardian_name','').strip(), email, d.get('guardian_phone','').strip() or None,
                 d.get('emergency_contact_name','').strip() or None,
                 d.get('emergency_contact_phone','').strip() or None,
                 ('Age eligibility: ' + age_grace_note) if age_grace_note else None))
        conn.commit()
        try:
            pos_desc = f'#{agewl_positions[0]}' if len(agewl_positions) == 1 else ', '.join(f'#{wp}' for wp in agewl_positions)
            send_email([email], f'You\'re on the waitlist — {p["name"]}',
                build_waitlist_email_html(d.get('guardian_name',''), p['name'], pos_desc, is_plural=len(agewl_positions) > 1))
        except Exception: pass
        conn.close()
        return jsonify({'ok': True, 'type': 'waitlisted', 'position': agewl_positions[0],
                        'registration_id': agewl_ids[0], 'age_note': age_grace_note})

    # Check capacity. Programs with sessions are full only when the
    # session(s) being booked are full (or nothing bookable is left), not
    # when the program-level capacity number is reached.
    reg_count = get_registration_count(conn, p['id'])
    cap = p.get('capacity')
    if p.get('sessions_enabled'):
        _sel = [x for x in (d.get('session_ids') or []) if x] if isinstance(d.get('session_ids'), list) else []
        if _sel:
            is_full = False
            for _sid in _sel:
                _sr = fetchone(conn, '''SELECT ps.capacity, (SELECT COUNT(*) FROM program_registrations WHERE program_id=%s
                        AND session_ids LIKE '%%"' || ps.id || '"%%' AND status NOT IN ('cancelled','waitlisted')) AS enrolled
                    FROM program_sessions ps WHERE ps.id=%s AND ps.program_id=%s''', (p['id'], _sid, p['id']))
                if _sr and _sr.get('capacity') and int(_sr['enrolled'] or 0) >= int(_sr['capacity']):
                    is_full = True
        else:
            is_full = program_spots_remaining(conn, p) == 0
    else:
        is_full = cap and reg_count >= cap

    if is_full:
        # Waitlist — each child (primary + siblings) gets their own independent
        # waitlist entry and position, sharing a registration_group_id.
        siblings_wl = d.get('siblings') or []
        if not isinstance(siblings_wl, list): siblings_wl = []
        wl_children = [{'first_name': d.get('child_first_name','').strip(), 'last_name': d.get('child_last_name','').strip(),
                         'dob': d.get('child_dob'), 'shirt_size': d.get('shirt_size')}]
        for s in siblings_wl:
            wl_children.append({'first_name': (s.get('first_name') or '').strip(), 'last_name': (s.get('last_name') or '').strip(),
                                 'dob': s.get('dob'), 'shirt_size': s.get('shirt_size')})
        import uuid as _uwl
        wl_group_id = str(_uwl.uuid4())
        wl_ids = []
        wl_positions = []
        for child in wl_children:
            wpos = next_waitlist_position(conn, p['id'])
            wrid = str(_uwl.uuid4())
            wl_ids.append(wrid)
            wl_positions.append(wpos)
            execute(conn, '''INSERT INTO program_registrations
                (id, program_id, registration_type, status, waitlist_position, registration_group_id,
                 child_first_name, child_last_name, child_dob, shirt_size,
                 guardian_name, guardian_email, guardian_phone,
                 emergency_contact_name, emergency_contact_phone, notes, participant_count, siblings_json)
                VALUES (%s,%s,'registration','waitlisted',%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,1,'[]')''',
                (wrid, p['id'], wpos, wl_group_id,
                 child['first_name'], child['last_name'], child['dob'] or None, child['shirt_size'] or None,
                 d.get('guardian_name','').strip(), email, d.get('guardian_phone','').strip() or None,
                 d.get('emergency_contact_name','').strip() or None,
                 d.get('emergency_contact_phone','').strip() or None,
                 d.get('notes','').strip() or None))
        conn.commit()
        # Email confirmation
        try:
            pos_desc = f'#{wl_positions[0]}' if len(wl_positions) == 1 else ', '.join(f'#{wp}' for wp in wl_positions)
            send_email([email], f'You\'re on the waitlist — {p["name"]}',
                build_waitlist_email_html(d.get('guardian_name',''), p['name'], pos_desc, is_plural=len(wl_positions) > 1))
        except Exception: pass
        conn.close()
        return jsonify({'ok': True, 'type': 'waitlisted', 'position': wl_positions[0], 'registration_id': wl_ids[0]})

    # Available spot
    price = p.get('price') or 0

    # Sessions
    import json as _json2
    session_ids = d.get('session_ids') or []
    if not isinstance(session_ids, list): session_ids = []
    sessions_enabled = bool(p.get('sessions_enabled'))
    session_rows = []
    session_price_total = 0  # price per participant from sessions
    if sessions_enabled and session_ids:
        import datetime as _dtsess
        today_str = _dtsess.date.today().isoformat()
        # Check if bundle price override is being used
        bundle_price_override = d.get('bundle_price_override')
        if d.get('is_bundle') and bundle_price_override:
            # Validate all session IDs belong to program and aren't past
            for sid in session_ids:
                sr = fetchone(conn, 'SELECT * FROM program_sessions WHERE id=%s AND program_id=%s', (sid, p['id']))
                if sr:
                    session_rows.append(sr)
            session_price_total = int(bundle_price_override)
            price = session_price_total
        else:
            # Block if all sessions have passed
            all_sessions = fetchall(conn, "SELECT * FROM program_sessions WHERE program_id=%s AND status='open'", (p['id'],)) or []
            if all_sessions and all(s.get('start_date','') < today_str for s in all_sessions if s.get('start_date')):
                conn.close()
                return jsonify({'error': 'Registration is closed — all sessions for this program have already taken place.'}), 400
            for sid in session_ids:
                sr = fetchone(conn, 'SELECT * FROM program_sessions WHERE id=%s AND program_id=%s AND status=%s',
                    (sid, p['id'], 'open'))
                if sr:
                    if sr.get('start_date') and sr['start_date'] < today_str:
                        conn.close()
                        return jsonify({'error': f'Session "{sr.get("name","")}" has already passed and is no longer available.'}), 400
                    session_rows.append(sr)
                    sp = sr.get('price_override') if sr.get('price_override') is not None else price
                    session_price_total += sp
            price = session_price_total

    # Siblings (additional children in same order)
    siblings = d.get('siblings') or []
    if not isinstance(siblings, list):
        siblings = []
    participant_count = 1 + len(siblings)
    basket = price * participant_count

    # Apply promo discount code
    discount_amount = 0
    discount_code = (d.get('discount_code') or '').strip().upper()
    if discount_code and price > 0:
        dc, dc_table = find_discount_code(conn, discount_code, 'program_id', p['id'])
        if dc and (not dc.get('max_uses') or dc.get('uses', 0) < dc['max_uses']):
            min_spend = dc.get('min_spend') or 0
            if not (min_spend > 0 and basket < min_spend):
                is_sib_code = bool(dc.get('is_sibling_discount'))
                if is_sib_code and participant_count >= 2:
                    per_child = int(price * dc['discount_value'] / 100) if dc['discount_type'] == 'percent' else min(dc['discount_value'], price)
                    discount_amount = per_child * (participant_count - 1)
                elif not is_sib_code:
                    if dc['discount_type'] == 'percent':
                        discount_amount = int(price * capped_participants(dc, participant_count) * dc['discount_value'] / 100)
                    else:
                        discount_amount = min(dc['discount_value'] * participant_count, basket)
                execute(conn, f'UPDATE {dc_table} SET uses=uses+1 WHERE id=%s', (dc['id'],))
                mark_benefit_cart_code_used(conn, dc, p.get('name') or '')
        else:
            discount_code = ''  # invalid, ignore

    # Program-level automatic sibling discount
    sibling_discount_amount = 0
    if p.get('sibling_discount_enabled') and participant_count >= 2 and price > 0:
        sib_type = p.get('sibling_discount_type') or 'percent'
        sib_val = p.get('sibling_discount_value') or 0
        if (p.get('sibling_discount_basis') or 'per_child') == 'cart_total':
            sibling_discount_amount = int(basket * sib_val / 100) if sib_type == 'percent' else min(sib_val, basket)
        else:
            per_sib = int(price * sib_val / 100) if sib_type == 'percent' else min(sib_val, price)
            sibling_discount_amount = per_sib * (participant_count - 1)

    # Deposit payment plan
    deposit = p.get('deposit_amount') or 0
    effective_price = max(0, basket - discount_amount - sibling_discount_amount)
    use_deposit = deposit > 0 and effective_price > deposit and d.get('payment_type') == 'deposit'
    charge_now = deposit if use_deposit else effective_price
    balance_due = max(0, effective_price - deposit) if use_deposit else 0

    # Build the list of children (primary + siblings) and the fields shared by every
    # row in the group — each child becomes their own independent registration row.
    reg_children = [{'first_name': d.get('child_first_name','').strip(), 'last_name': d.get('child_last_name','').strip(),
                      'dob': d.get('child_dob'), 'shirt_size': d.get('shirt_size'),
                      'allergies': d.get('allergies') or '', 'pronouns': d.get('pronouns') or ''}]
    for s in siblings:
        reg_children.append({'first_name': (s.get('first_name') or '').strip(), 'last_name': (s.get('last_name') or '').strip(),
                              'dob': s.get('dob'), 'shirt_size': s.get('shirt_size'),
                              'allergies': s.get('allergies') or ''})
    for _c, _rf in zip(reg_children, _reviewed_fields_for_children(d, siblings)):
        _c['reviewed_fields'] = _rf
    shared_fields = {
        'program_id': p['id'],
        'registration_form_type': d.get('registration_form_type') or p.get('registration_form_type') or 'youth',
        'guardian_name': d.get('guardian_name','').strip(),
        'guardian_email': email,
        'guardian_phone': d.get('guardian_phone','').strip() or None,
        'emergency_contact_name': d.get('emergency_contact_name','').strip() or None,
        'emergency_contact_phone': d.get('emergency_contact_phone','').strip() or None,
        'notes': d.get('notes','').strip() or None,
        'allergies': d.get('allergies','').strip() or None,
        'pickup_contacts': d.get('pickup_contacts','').strip() or None,
        'photo_consent': bool(d.get('photo_consent')),
        'pronouns': d.get('pronouns','').strip() or None,
        'discount_code': discount_code or None,
        'discount_amount': discount_amount,
        'sibling_discount_amount': sibling_discount_amount,
        'session_ids': _json2.dumps(session_ids),
        'reported_under_18': (d.get('reported_under_18') or '').strip(),
        'custom_field_values': json.dumps(d.get('custom_field_values') or {}),
    }

    # Step Up (or similar third-party subsidy) hold — save a card on file now,
    # charge nothing. Staff reviews and charges later from the Step Up Holds queue
    # if the subsidy payment hasn't shown up by the charge-by date.
    if d.get('payment_type') == 'step_up_hold' and p.get('step_up_hold_enabled') and effective_price > 0:
        resolved_children, hold_err = resolve_step_up_children(d.get('step_up_children'), effective_price)
        if hold_err:
            conn.close()
            return jsonify({'error': hold_err}), 400
        from datetime import timedelta as _tdsu
        charge_by = (date.today() + _tdsu(days=int(p.get('step_up_hold_days') or 14))).isoformat()
        reg_ids, group_id = create_grouped_registrations(conn, shared_fields, reg_children, effective_price,
            'confirmed', 'step_up_hold', amounts=[c['amount'] for c in resolved_children])
        insert_step_up_child_holds(conn, reg_ids, resolved_children, charge_by)
        for gid in reg_ids:
            finalize_registration(conn, gid)
        conn.commit()
        conn.close()
        return jsonify({'ok': True, 'type': 'step_up_hold', 'registration_id': reg_ids[0],
                        'charge_by_date': charge_by, 'amount_held': effective_price})

    if charge_now == 0:
        reg_ids, group_id = create_grouped_registrations(conn, shared_fields, reg_children, 0, 'confirmed', 'full')
        for gid in reg_ids:
            finalize_registration(conn, gid)
        conn.commit()
        conn.close()
        return jsonify({'ok': True, 'type': 'confirmed_free', 'registration_id': reg_ids[0]})

    pending_amount = balance_due if use_deposit else 0
    reg_ids, group_id = create_grouped_registrations(conn, shared_fields, reg_children, pending_amount,
        'pending_payment', 'deposit' if use_deposit else 'full')
    conn.commit()

    note = f'{d.get("child_first_name","")} {d.get("child_last_name","")} — {p["name"]}'
    if session_rows:
        note += ' (' + ', '.join(sr['name'] for sr in session_rows) + ')'
    if participant_count > 1:
        note += f' x{participant_count} participants'
    if use_deposit:
        note += f' (deposit ${deposit/100:.2f})'
    pay_url, link_id, order_id = square_create_payment_link(
        p, reg_ids[0], email, d.get('guardian_name',''), charge_now, note=note)

    if not pay_url:
        conn.close()
        return jsonify({'error': 'Could not create payment link. Please try again.'}), 500

    for gid in reg_ids:
        execute(conn, 'UPDATE program_registrations SET square_checkout_id=%s, square_order_id=%s WHERE id=%s',
            (link_id, order_id, gid))
    conn.commit()
    conn.close()
    return jsonify({'ok': True, 'type': 'payment_required', 'payment_url': pay_url,
                    'registration_id': reg_ids[0], 'charge_now': charge_now,
                    'balance_due': balance_due, 'use_deposit': use_deposit})


@app.route('/api/square/webhook', methods=['POST'])
def square_webhook():
    """Handle Square payment webhooks."""
    # Verify signature
    sig = request.headers.get('X-Square-Hmacsha256-Signature', '')
    body = request.get_data(as_text=True)
    if SQUARE_WEBHOOK_SIG:
        import base64 as _b64
        notification_url = f'https://rolecall.hwtco.org/api/square/webhook'
        payload = notification_url + body
        expected = hmac.new(SQUARE_WEBHOOK_SIG.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).digest()
        expected_b64 = _b64.b64encode(expected).decode()
        if not hmac.compare_digest(sig, expected_b64):
            app.logger.warning(f'Webhook signature mismatch. Got: {sig[:20]}... Expected: {expected_b64[:20]}...')
            return jsonify({'error': 'Invalid signature'}), 401

    event = request.json or {}
    event_type = event.get('type', '')
    app.logger.info(f'Square webhook: {event_type}')

    if event_type in ('payment.completed', 'payment.updated'):
        try:
            obj = event.get('data', {}).get('object', {}).get('payment', {})
            payment_id = obj.get('id')
            order_id = obj.get('order_id')
            status = obj.get('status')
            amount_cents = obj.get('amount_money', {}).get('amount', 0)
            if status == 'COMPLETED' and order_id:
                conn = get_db()
                # Check registrations first — a group registration (siblings) has multiple
                # rows sharing the same square_order_id/checkout_id, so confirm all of them.
                regs = fetchall(conn, 'SELECT * FROM program_registrations WHERE square_order_id=%s OR square_checkout_id=%s',
                    (order_id, order_id)) or []
                reg = regs[0] if regs else None
                if regs and amount_cents:
                    # Split proportionally across every registration sharing
                    # this order — see split_order_amount_across_registrations
                    # for why writing the full amount to every row is wrong
                    # once an order can span more than one program.
                    split_order_amount_across_registrations(conn, order_id, amount_cents)
                    conn.commit()
                if regs and any(r['status'] == 'pending_payment' for r in regs):
                    for r in regs:
                        if r['status'] == 'pending_payment':
                            finalize_registration(conn, r['id'], payment_id, order_id)
                elif regs and any(r['status'] == 'waitlisted' for r in regs):
                    for r in regs:
                        if r['status'] == 'waitlisted':
                            execute(conn, "UPDATE program_registrations SET status='confirmed', square_payment_id=%s, updated_at=NOW() WHERE id=%s",
                                (payment_id, r['id']))
                            finalize_registration(conn, r['id'], payment_id, order_id)
                    conn.commit()
                else:
                    # Check hours store balance payments
                    hour_red = fetchone(conn, "SELECT * FROM hour_redemptions WHERE (square_order_id=%s OR square_checkout_id=%s) AND status='awaiting_payment'",
                        (order_id, order_id))
                    if hour_red:
                        item = fetchone(conn, 'SELECT * FROM store_items WHERE id=%s', (hour_red['store_item_id'],)) if hour_red['store_item_id'] else None
                        new_reg_id = _enroll_from_hours_redemption(conn, hour_red, item)
                        execute(conn, "UPDATE hour_redemptions SET status='approved', square_payment_id=%s WHERE id=%s",
                            (payment_id, hour_red['id']))
                        conn.commit()
                        try:
                            vol = fetchone(conn, 'SELECT * FROM volunteers WHERE id=%s', (hour_red['volunteer_id'],))
                            if vol and vol.get('email'):
                                send_email([vol['email']], 'Payment received — Hours Store',
                                    build_hwtc_email_html('Payment received — Hours Store',
                                    f'<h2 style="color:#145466">Payment Received!</h2>'
                                    f'<p>Hi {vol.get("name","there")},</p>'
                                    f'<p>Thanks — we received your balance payment for <strong>{hour_red.get("item_name_snapshot") or (item["name"] if item else "your item")}</strong>.'
                                    f'{" You have been enrolled." if new_reg_id else " We will follow up with next steps."}</p>'))
                        except Exception as e:
                            app.logger.warning(f'Hours store balance-paid email failed: {e}')
                    else:
                        # Check cart orders
                        import json as _jw
                        cart = fetchone(conn, "SELECT * FROM cart_orders WHERE (square_order_id=%s OR square_checkout_id=%s) AND status='pending'",
                            (order_id, order_id))
                        if cart:
                            execute(conn, "UPDATE cart_orders SET status='completed' WHERE id=%s", (cart['id'],))
                            try:
                                items = _jw.loads(cart.get('items_json') or '[]')
                            except Exception:
                                items = []
                            for it in items:
                                rid = it.get('registration_id')
                                if rid:
                                    reg2 = fetchone(conn, 'SELECT status FROM program_registrations WHERE id=%s', (rid,))
                                    if reg2 and reg2['status'] == 'pending_payment':
                                        finalize_registration(conn, rid, payment_id, order_id)
                            # finalize_registration doesn't touch amount_paid_cents — split it
                            # proportionally across every registration sharing this cart's
                            # order (same helper the direct/single-registration path uses),
                            # so a multi-program cart doesn't leave each item at $0 even
                            # though the cart total was genuinely charged.
                            split_order_amount_across_registrations(conn, order_id, cart.get('total_cents'))
                            conn.commit()
                        else:
                            # Check ticket orders — a multi-performance cart
                            # has multiple sibling rows sharing this same
                            # square_order_id/checkout_id (one per
                            # performance), same as a multi-program
                            # registration cart, so confirm all of them.
                            tords = fetchall(conn, "SELECT * FROM ticket_orders WHERE (square_order_id=%s OR square_checkout_id=%s) AND status IN ('pending','superseded')",
                                (order_id, order_id)) or []
                            for tord in tords:
                                _finalize_ticket_order(conn, tord['id'], payment_id, order_id)
                            # A ticket checkout can also carry an optional
                            # add-on donation sharing this SAME order/
                            # checkout id, so this isn't exclusive with the
                            # tickets above anymore — a standalone donation
                            # (no ticket_orders match) still lands here too.
                            don = fetchone(conn, "SELECT * FROM pending_donations WHERE (square_order_id=%s OR square_checkout_id=%s) AND status='pending'",
                                (order_id, order_id))
                            if don:
                                finalize_donation(conn, don['id'])
                            for _cart in set(t.get('cart_id') for t in tords if t.get('cart_id')):
                                notify_ticket_sale(conn, _cart)
                            # Playbill ads / well wishes / cast grams
                            pbs = fetchall(conn, "SELECT DISTINCT cart_id FROM playbill_orders WHERE (square_order_id=%s OR square_checkout_id=%s) AND status='pending'",
                                (order_id, order_id)) or []
                            for pb in pbs:
                                execute(conn, "UPDATE playbill_orders SET status='paid', paid_at=NOW() WHERE cart_id=%s AND status='pending'", (pb['cart_id'],))
                                conn.commit()
                                finalize_playbill_cart(conn, pb['cart_id'])
                conn.close()
            elif status in ('FAILED', 'CANCELED') and order_id:
                conn = get_db()
                reg = fetchone(conn, 'SELECT * FROM program_registrations WHERE square_order_id=%s OR square_checkout_id=%s',
                    (order_id, order_id))
                if reg and reg['status'] in ('pending_payment', 'waitlisted'):
                    card_details = obj.get('card_details', {}) or {}
                    errors = obj.get('errors') or []
                    reason = ''
                    if errors:
                        reason = '; '.join((e.get('detail') or e.get('code') or '') for e in errors if isinstance(e, dict))
                    elif card_details.get('status'):
                        reason = f"Card {card_details['status'].lower()}"
                    execute(conn, '''UPDATE program_registrations SET
                        payment_attempt_failed_at=NOW(),
                        payment_failure_reason=%s,
                        payment_attempt_count=COALESCE(payment_attempt_count,0)+1
                        WHERE id=%s''', (reason or 'Payment attempt failed', reg['id']))
                    conn.commit()
                    app.logger.info(f'Payment attempt failed for registration {reg["id"]}: {reason}')
                conn.close()
        except Exception as e:
            app.logger.error(f'Webhook processing error: {e}', exc_info=True)

    elif event_type == 'invoice.payment_made':
        try:
            invoice = event.get('data', {}).get('object', {}).get('invoice', {})
            invoice_id = invoice.get('id')
            if invoice_id:
                conn = get_db()
                payment = fetchone(conn, 'SELECT * FROM rental_payments WHERE square_invoice_id=%s', (invoice_id,))
                if payment:
                    _apply_rental_invoice_update(conn, payment, invoice)
                    conn.commit()
                conn.close()
        except Exception as e:
            app.logger.error(f'Rental invoice webhook error: {e}', exc_info=True)

    return jsonify({'ok': True})


