@app.route('/api/programs/<pid>/sessions', methods=['GET'])
def get_program_sessions(pid):
    conn = get_db()
    sessions = fetchall(conn, '''SELECT ps.*,
        (SELECT COUNT(*) FROM program_registrations
         WHERE program_id=%s AND session_ids LIKE '%%"' || ps.id || '"%%'
         AND status NOT IN ('cancelled','waitlisted')) AS enrolled_count,
        (SELECT e.id FROM events e WHERE e.linked_session_id=ps.id LIMIT 1) AS linked_event_id
        FROM program_sessions ps WHERE ps.program_id=%s
        ORDER BY ps.sort_order, ps.day_of_week, ps.start_time''', (pid, pid))
    conn.close()
    return jsonify(sessions or [])

@app.route('/api/programs/<pid>/sessions', methods=['POST'])
def create_program_session(pid):
    err = require_own_program(pid)
    if err: return err
    d = request.json or {}
    conn = get_db()
    prog = fetchone(conn, 'SELECT id FROM youth_programs WHERE id=%s', (pid,))
    if not prog:
        conn.close()
        return jsonify({'error': 'Program not found'}), 404
    sid = str(uuid.uuid4())
    price_override = d.get('price_override')
    if price_override is not None:
        try: price_override = int(price_override)
        except Exception: price_override = None
    capacity = d.get('capacity')
    if capacity is not None:
        try: capacity = int(capacity)
        except Exception: capacity = None
    min_age = d.get('min_age')
    min_age = int(min_age) if min_age not in (None, '') else None
    max_age = d.get('max_age')
    max_age = int(max_age) if max_age not in (None, '') else None
    age_grace_days = d.get('age_grace_days')
    age_grace_days = int(age_grace_days) if age_grace_days not in (None, '') else None
    # Get next sort order
    max_sort = fetchone(conn, 'SELECT COALESCE(MAX(sort_order),0) as m FROM program_sessions WHERE program_id=%s', (pid,))
    sort_order = (max_sort.get('m') or 0) + 1
    execute(conn, '''INSERT INTO program_sessions
        (id, program_id, name, day_of_week, start_time, end_time,
         start_date, end_date, location, capacity, price_override, status, sort_order,
         min_age, max_age, age_grace_days)
        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)''',
        (sid, pid,
         (d.get('name') or '').strip(),
         d.get('day_of_week') or None,
         d.get('start_time') or None,
         d.get('end_time') or None,
         d.get('start_date') or None,
         d.get('end_date') or None,
         d.get('location') or None,
         capacity,
         price_override,
         d.get('status') or 'open',
         sort_order,
         min_age, max_age, age_grace_days))
    conn.commit()
    sync_hours_store_for_program(conn, pid)
    conn.close()
    return jsonify({'ok': True, 'id': sid})


@app.route('/api/programs/<pid>/sessions/generate', methods=['POST'])
def generate_program_sessions(pid):
    """Generate multiple time slots at once for booking mode."""
    err = require_own_program(pid)
    if err: return err
    import uuid as _usg
    import datetime as _dt
    d = request.json or {}
    conn = get_db()
    prog = fetchone(conn, 'SELECT id FROM youth_programs WHERE id=%s', (pid,))
    if not prog:
        conn.close()
        return jsonify({'error': 'Program not found'}), 404

    start_date = d.get('start_date')
    end_date = d.get('end_date')
    days_of_week = d.get('days_of_week') or []  # e.g. ['Monday', 'Wednesday']
    open_time = d.get('open_time')    # e.g. '10:00'
    close_time = d.get('close_time')  # e.g. '16:00'
    slot_duration = int(d.get('slot_duration_minutes') or 45)
    gap_minutes = int(d.get('gap_minutes') or 0)
    capacity = int(d.get('capacity') or 1)
    price_override = d.get('price_override')
    location = (d.get('location') or '').strip()

    if not start_date or not open_time or not close_time:
        conn.close()
        return jsonify({'error': 'start_date, open_time and close_time are required'}), 400

    DAY_MAP = {'Monday':0,'Tuesday':1,'Wednesday':2,'Thursday':3,'Friday':4,'Saturday':5,'Sunday':6}
    allowed_days = set(DAY_MAP[d] for d in days_of_week if d in DAY_MAP) if days_of_week else set(range(7))

    try:
        cur = _dt.date.fromisoformat(start_date)
        end = _dt.date.fromisoformat(end_date) if end_date else cur
        ot = _dt.time.fromisoformat(open_time)
        ct = _dt.time.fromisoformat(close_time)
    except Exception as e:
        conn.close()
        return jsonify({'error': f'Invalid date/time: {e}'}), 400

    slot_td = _dt.timedelta(minutes=slot_duration)
    gap_td = _dt.timedelta(minutes=gap_minutes)
    created = 0
    sort_order = 0

    while cur <= end:
        if cur.weekday() in allowed_days:
            day_name = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][cur.weekday()]
            slot_start = _dt.datetime.combine(cur, ot)
            slot_end_limit = _dt.datetime.combine(cur, ct)
            while slot_start + slot_td <= slot_end_limit:
                s_end = slot_start + slot_td
                label = f'{cur.strftime("%A, %B %-d")} · {slot_start.strftime("%-I:%M %p")} – {s_end.strftime("%-I:%M %p")}'
                execute(conn, '''INSERT INTO program_sessions
                    (id, program_id, name, day_of_week, start_time, end_time,
                     start_date, end_date, location, capacity, price_override, status, sort_order)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,'open',%s)''',
                    (str(_usg.uuid4()), pid, label, day_name,
                     slot_start.strftime('%H:%M'), s_end.strftime('%H:%M'),
                     cur.isoformat(), cur.isoformat(),
                     location or None,
                     capacity,
                     int(price_override) if price_override is not None else None,
                     sort_order))
                sort_order += 1
                created += 1
                slot_start = s_end + gap_td
        cur += _dt.timedelta(days=1)

    conn.commit(); conn.close()
    return jsonify({'ok': True, 'created': created})


@app.route('/api/programs/<pid>/sessions/bulk-import', methods=['POST'])
def bulk_import_program_sessions(pid):
    """Creates many one-off session rows at once from a pre-expanded list
    of {start_date, start_time, end_time} slots. Unlike /generate (which
    assumes one uniform daily window repeated across matching weekdays),
    this is for genuinely irregular schedules — different times on
    different days, multiple blocks per day, etc. — pasted in and split
    into individual slots client-side (so the UI can show a live preview/
    count before committing). This route just validates and bulk-inserts
    in one transaction."""
    err = require_own_program(pid)
    if err: return err
    d = request.json or {}
    slots = d.get('sessions') or []
    if not isinstance(slots, list) or not slots:
        return jsonify({'error': 'No sessions provided'}), 400
    if len(slots) > 1000:
        return jsonify({'error': 'Too many sessions in one batch (max 1000) — split into smaller batches'}), 400
    conn = get_db()
    prog = fetchone(conn, 'SELECT id FROM youth_programs WHERE id=%s', (pid,))
    if not prog:
        conn.close()
        return jsonify({'error': 'Program not found'}), 404
    location = (d.get('location') or '').strip() or None
    capacity = d.get('capacity')
    try: capacity = int(capacity) if capacity is not None else None
    except Exception: capacity = None
    price_override = d.get('price_override')
    try: price_override = int(price_override) if price_override is not None else None
    except Exception: price_override = None
    max_sort = fetchone(conn, 'SELECT COALESCE(MAX(sort_order),0) as m FROM program_sessions WHERE program_id=%s', (pid,))
    sort_order = (max_sort.get('m') or 0) + 1
    created = 0
    DAY_NAMES = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday']
    for slot in slots:
        sdate = (slot.get('start_date') or '').strip()
        stime = (slot.get('start_time') or '').strip()
        etime = (slot.get('end_time') or '').strip()
        if not sdate or not stime or not etime:
            continue
        try:
            day_name = DAY_NAMES[date.fromisoformat(sdate).weekday()]
        except Exception:
            day_name = ''
        name = (slot.get('name') or '').strip()
        if not name:
            try:
                dt_s = datetime.strptime(sdate + ' ' + stime, '%Y-%m-%d %H:%M')
                dt_e = datetime.strptime(sdate + ' ' + etime, '%Y-%m-%d %H:%M')
                name = f'{dt_s.strftime("%A, %B %-d")} \u00b7 {dt_s.strftime("%-I:%M %p")} \u2013 {dt_e.strftime("%-I:%M %p")}'
            except Exception:
                name = f'{sdate} {stime}-{etime}'
        execute(conn, '''INSERT INTO program_sessions
            (id, program_id, name, day_of_week, start_time, end_time,
             start_date, end_date, location, capacity, price_override, status, sort_order)
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,'open',%s)''',
            (str(uuid.uuid4()), pid, name, day_name, stime, etime,
             sdate, sdate, location, capacity, price_override, sort_order))
        sort_order += 1
        created += 1
    conn.commit()
    sync_hours_store_for_program(conn, pid)
    conn.close()
    return jsonify({'ok': True, 'created': created})



