_DATE_LIKE_EVENT_NAME = re.compile(
    r'^\s*((mon|tue|wed|thu|fri|sat|sun)[a-z]*\.?(,|\s+(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec|\d))|'
    r'(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.?\s+\d|'
    r'\d{4}-\d{2}-\d{2}|\d{1,2}/\d{1,2})', re.IGNORECASE)


def lobby_event_title(name, program_name):
    """Class sessions are often named by their date/time (e.g. "Thursday,
    October 1 · 5:00 PM – 6:00 PM"), which reads as noise on a schedule that
    already shows the date and time. For those, show the class name instead."""
    name = (name or '').strip()
    if program_name and (not name or _DATE_LIKE_EVENT_NAME.match(name)):
        return program_name
    return name


@app.route('/api/public/lobby-data', methods=['GET'])
def public_lobby_data():
    # Was using the server's own clock (UTC on Railway), which rolls over to
    # the next calendar day hours before it's actually midnight in Florida —
    # during that window "today" here would already be tomorrow, silently
    # shifting every relative date downstream by a day.
    today = today_eastern().isoformat()
    upcoming_events = []
    announcements = []
    lobby_images = []

    try:
        conn = get_db()
        upcoming_events = fetchall(conn, '''SELECT e.name, e.event_date, e.start_time, e.end_time, e.location,
                yp.name AS program_name
            FROM events e
            LEFT JOIN youth_programs yp ON yp.id = e.program_id
            WHERE e.event_date >= %s AND COALESCE(e.status,'active') != 'cancelled'
            AND COALESCE(e.show_on_lobby, TRUE) = TRUE
            ORDER BY e.event_date, e.start_time LIMIT 12''', (today,)) or []
        conn.close()
        for ev in upcoming_events:
            ev['name'] = lobby_event_title(ev.get('name'), ev.pop('program_name', None))
    except Exception as e:
        app.logger.warning(f'Lobby events query failed: {e}')
        try: conn.close()
        except Exception: pass

    try:
        conn = get_db()
        row = fetchone(conn, "SELECT value FROM settings WHERE key=%s", ('lobby_images',))
        lobby_images = json.loads((row or {}).get('value') or '[]')
        conn.close()
    except Exception as e:
        app.logger.warning(f'Lobby images query failed: {e}')
        try: conn.close()
        except Exception: pass

    lobby_theme = 'none'
    try:
        conn = get_db()
        row = fetchone(conn, "SELECT value FROM settings WHERE key=%s", ('lobby_theme',))
        lobby_theme = (row or {}).get('value') or 'none'
        conn.close()
    except Exception as e:
        app.logger.warning(f'Lobby theme query failed: {e}')
        try: conn.close()
        except Exception: pass

    lobby_banner = ''
    lobby_banner_pos = '50% 50%'
    lobby_banner_zoom = 100
    lobby_banner_fit = 'cover'
    try:
        conn = get_db()
        row = fetchone(conn, "SELECT value FROM settings WHERE key=%s", ('lobby_banner',))
        lobby_banner = (row or {}).get('value') or ''
        row2 = fetchone(conn, "SELECT value FROM settings WHERE key=%s", ('lobby_banner_pos',))
        lobby_banner_pos = (row2 or {}).get('value') or '50% 50%'
        row3 = fetchone(conn, "SELECT value FROM settings WHERE key=%s", ('lobby_banner_zoom',))
        lobby_banner_zoom = int((row3 or {}).get('value') or 100)
        row4 = fetchone(conn, "SELECT value FROM settings WHERE key=%s", ('lobby_banner_fit',))
        lobby_banner_fit = (row4 or {}).get('value') or 'cover'
        conn.close()
    except Exception as e:
        app.logger.warning(f'Lobby banner query failed: {e}')
        try: conn.close()
        except Exception: pass

    lobby_sched_bg = ''
    lobby_sched_bg_pos = '50% 50%'
    lobby_sched_bg_zoom = 100
    lobby_sched_bg_fit = 'cover'
    try:
        conn = get_db()
        row = fetchone(conn, "SELECT value FROM settings WHERE key=%s", ('lobby_sched_bg',))
        lobby_sched_bg = (row or {}).get('value') or ''
        row2 = fetchone(conn, "SELECT value FROM settings WHERE key=%s", ('lobby_sched_bg_pos',))
        lobby_sched_bg_pos = (row2 or {}).get('value') or '50% 50%'
        row3 = fetchone(conn, "SELECT value FROM settings WHERE key=%s", ('lobby_sched_bg_zoom',))
        lobby_sched_bg_zoom = int((row3 or {}).get('value') or 100)
        row4 = fetchone(conn, "SELECT value FROM settings WHERE key=%s", ('lobby_sched_bg_fit',))
        lobby_sched_bg_fit = (row4 or {}).get('value') or 'cover'
        conn.close()
    except Exception as e:
        app.logger.warning(f'Lobby schedule bg query failed: {e}')
        try: conn.close()
        except Exception: pass

    lobby_carousel_header = ''
    try:
        conn = get_db()
        row = fetchone(conn, "SELECT value FROM settings WHERE key=%s", ('lobby_carousel_header',))
        lobby_carousel_header = (row or {}).get('value') or ''
        conn.close()
    except Exception as e:
        app.logger.warning(f'Lobby carousel header query failed: {e}')
        try: conn.close()
        except Exception: pass

    return jsonify({'events': upcoming_events, 'announcements': announcements, 'lobby_images': lobby_images, 'lobby_theme': lobby_theme, 'lobby_banner': lobby_banner, 'lobby_banner_pos': lobby_banner_pos, 'lobby_banner_zoom': lobby_banner_zoom, 'lobby_banner_fit': lobby_banner_fit, 'lobby_sched_bg': lobby_sched_bg, 'lobby_sched_bg_pos': lobby_sched_bg_pos, 'lobby_sched_bg_zoom': lobby_sched_bg_zoom, 'lobby_sched_bg_fit': lobby_sched_bg_fit, 'lobby_carousel_header': lobby_carousel_header})

