@app.route('/api/twilio/callback', methods=['POST'])
def twilio_callback_bridge():
    """Initiate a masked outbound call — calls the agent first, then bridges to the target."""
    d = request.get_json(silent=True) or {}
    to_number = (d.get('to') or '').strip()
    agent_number = (d.get('agent') or '').strip()
    if not to_number or not agent_number:
        return jsonify({'error': 'Missing to or agent number'}), 400
    ts = get_twilio_settings()
    if not ts['account_sid'] or not ts['auth_token'] or not ts['from_phone']:
        return jsonify({'error': 'Twilio not configured'}), 400
    # Normalize phone numbers — strip spaces, ensure +1 prefix
    def norm_phone(p):
        p = ''.join(c for c in p if c.isdigit() or c=='+')
        if not p.startswith('+'): p = '+1' + p
        return p
    to_number = norm_phone(to_number)
    agent_number = norm_phone(agent_number)
    hwtc_phone = norm_phone(ts['from_phone'])
    try:
        from twilio.rest import Client as _TwCb
        from urllib.parse import quote as _q
        client = _TwCb(ts['account_sid'], ts['auth_token'])
        host = 'https://rolecall.hwtco.org'
        bridge_url = f'{host}/twilio/bridge-twiml?target={_q(to_number)}&hwtc={_q(hwtc_phone)}'
        call = client.calls.create(
            to=agent_number,
            from_=hwtc_phone,
            url=bridge_url,
            status_callback=f'{host}/twilio/call-status',
            status_callback_method='POST'
        )
        return jsonify({'ok': True, 'sid': call.sid})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/twilio/voicemail-play')
def twilio_voicemail_play():
    """Proxy Twilio recording so callers don't need to log into Twilio."""
    url = request.args.get('url','').strip()
    if not url or 'twilio.com' not in url:
        return 'Invalid URL', 400
    ts = get_twilio_settings()
    if not ts['account_sid'] or not ts['auth_token']:
        return 'Twilio not configured', 500
    try:
        import requests as _rvm
        resp = _rvm.get(url, auth=(ts['account_sid'], ts['auth_token']), timeout=15, stream=True)
        from flask import Response as _Resp, stream_with_context
        return _Resp(
            stream_with_context(resp.iter_content(chunk_size=8192)),
            content_type=resp.headers.get('Content-Type','audio/mpeg'),
            status=resp.status_code
        )
    except Exception as e:
        app.logger.error(f'Voicemail proxy error: {e}')
        return 'Error fetching recording', 500

@app.route('/twilio/voicemail', methods=['POST'])
def twilio_voicemail():
    """Fires after voicemail recording completes."""
    call_sid = request.form.get('CallSid','')
    recording_url = request.form.get('RecordingUrl','')
    duration = int(request.form.get('RecordingDuration', 0) or 0)
    caller = request.form.get('From','')
    import datetime as _dtvm
    now_str = _dtvm.datetime.now(__import__('zoneinfo').ZoneInfo('America/New_York')).strftime('%b %d, %Y at %I:%M %p ET')
    try:
        conn = get_db()
        row = fetchone(conn, 'SELECT * FROM call_log WHERE call_sid=%s', (call_sid,))
        from_num = (row or {}).get('from_number', caller)
        thread_ts = (row or {}).get('slack_thread_ts') or None
        execute(conn, "UPDATE call_log SET status='voicemail', duration=%s, notes=%s, updated_at=NOW() WHERE call_sid=%s",
            (duration, recording_url, call_sid))
        conn.commit(); conn.close()
    except Exception as e:
        app.logger.warning(f'Voicemail log error: {e}')
        from_num = caller; thread_ts = None
    play_url = recording_url + '.mp3' if recording_url else ''
    host = 'https://rolecall.hwtco.org'
    post_to_slack_calls([
        {'type':'section','text':{'type':'mrkdwn','text':
            f' *Voicemail* — {duration}s\n<{host}/twilio/voicemail-play?url={play_url}| Play Recording>'}},
        {'type':'actions','elements':[
            {'type':'button','text':{'type':'plain_text','text':' Call Back via HWTC'},'url':f'{host}/callback?to={from_num}','action_id':'callback'}
        ]}
    ], text=f' Voicemail ({duration}s)', thread_ts=thread_ts)
    return '', 204

@app.route('/twilio/voicemail-transcript', methods=['POST'])
def twilio_voicemail_transcript():
    """Fires when Twilio finishes transcribing a voicemail."""
    transcript = request.form.get('TranscriptionText','').strip()
    call_sid = request.form.get('CallSid','')
    recording_url = request.form.get('RecordingUrl','')
    caller = request.form.get('From','')
    if not transcript: return '', 204
    try:
        conn = get_db()
        row = fetchone(conn, 'SELECT * FROM call_log WHERE call_sid=%s', (call_sid,))
        conn.close()
        from_num = (row or {}).get('from_number', caller)
        thread_ts = (row or {}).get('slack_thread_ts') or None
    except Exception:
        from_num = caller; thread_ts = None
    play_url = recording_url + '.mp3' if recording_url else ''
    host = 'https://rolecall.hwtco.org'
    post_to_slack_calls([
        {'type':'section','text':{'type':'mrkdwn','text':
            f' *Transcript:* {transcript}\n<{host}/twilio/voicemail-play?url={play_url}| Play Recording>'}}
    ], text=f'Transcript: {transcript[:100]}', thread_ts=thread_ts)
    return '', 204

@app.route('/twilio/bridge-twiml', methods=['GET','POST'])
def twilio_bridge_twiml():
    """TwiML served to the agent once they pick up — bridges them to the target caller."""
    target = request.args.get('target','')
    hwtc_num = request.args.get('hwtc','')
    twiml = f'''<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say voice="Polly.Joanna">Connecting you now. You are calling back via the H W T C number.</Say>
  <Dial callerId="{hwtc_num}" answerOnBridge="true">
    <Number>{target}</Number>
  </Dial>
</Response>'''
    return twiml, 200, {'Content-Type': 'text/xml'}

@app.route('/api/twilio/send-sms', methods=['POST'])
def send_twilio_sms():
    """Send an outbound SMS to a phone number."""
    err = require_auth()
    if err: return err
    d = request.get_json(silent=True) or {}
    to_phone = (d.get('to') or '').strip()
    body = (d.get('body') or '').strip()
    if not to_phone or not body:
        return jsonify({'error': 'Missing to or body'}), 400
    ts = get_twilio_settings()
    if not ts['account_sid'] or not ts['auth_token'] or not ts['from_phone']:
        return jsonify({'error': 'Twilio not configured in Settings'}), 400
    try:
        from twilio.rest import Client as _TwClient
        client = _TwClient(ts['account_sid'], ts['auth_token'])
        msg = client.messages.create(body=body, from_=ts['from_phone'], to=to_phone)
        return jsonify({'ok': True, 'sid': msg.sid})
    except Exception as e:
        return jsonify({'error': str(e)}), 500


