@app.route('/api/public/partnership-interest', methods=['POST'])
def public_partnership_interest_submit():
    import uuid as _upi
    import json as _jpi2
    d = request.json or {}
    org_name = (d.get('organization_name') or '').strip()
    contact_name = (d.get('contact_name') or '').strip()
    contact_email = (d.get('contact_email') or '').strip()
    purpose = (d.get('purpose') or '').strip()
    if not org_name or not contact_name or not contact_email or not purpose:
        return jsonify({'error': 'Please fill in all required fields.'}), 400
    if not d.get('policy_agreed'):
        return jsonify({'error': 'Please confirm you have read and understand our general policy.'}), 400

    # Specific dates are optional — a prospective partner may already know
    # a date or two even without formal approval yet. Each entry is
    # {date, start_time, end_time}, matching the admin-side format so staff
    # can turn this straight into a scheduled request without re-entering
    # anything.
    raw_specific = d.get('specific_dates') or []
    specific_dates = []
    for item in raw_specific:
        if not isinstance(item, dict) or not item.get('date'):
            continue
        try:
            datetime.strptime(item['date'], '%Y-%m-%d')
        except Exception:
            continue
        specific_dates.append({
            'date': item['date'],
            'start_time': (item.get('start_time') or '').strip(),
            'end_time': (item.get('end_time') or '').strip(),
        })
    date_mode = 'specific' if specific_dates else 'range'
    earliest_date = min((s['date'] for s in specific_dates), default='')

    conn = get_db()
    # Find existing partner by email, or create a new one
    partner = fetchone(conn, 'SELECT * FROM rental_partners WHERE LOWER(contact_email)=LOWER(%s)', (contact_email,))
    if partner:
        partner_id = partner['id']
    else:
        partner_id = str(_upi.uuid4())
        execute(conn, '''INSERT INTO rental_partners
            (id, name, contact_name, contact_email, contact_phone, organization_type, organization_website, notes, status)
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,'active')''',
            (partner_id, org_name, contact_name, contact_email,
             (d.get('contact_phone') or '').strip(),
             (d.get('organization_type') or '').strip(),
             (d.get('organization_website') or '').strip(),
             'Submitted via Partnership Interest Form'))
    rid = str(_upi.uuid4())
    portal_token = str(_upi.uuid4())
    execute(conn, '''INSERT INTO rental_requests
        (id, partner_id, title, purpose, start_date, desired_frequency, source, status, notes,
         portal_token, date_mode, specific_dates)
        VALUES (%s,%s,%s,%s,%s,%s,'interest_form','pending',%s,%s,%s,%s)''',
        (rid, partner_id, f'{org_name} — Partnership Interest', purpose, earliest_date,
         (d.get('desired_frequency') or '').strip(),
         (d.get('additional_notes') or '').strip(), portal_token, date_mode,
         _jpi2.dumps(specific_dates)))
    # optional "Costumes, props & equipment" section of the interest form
    if (d.get('asset_items') or (d.get('asset_wish_list') or '').strip()) and d.get('asset_pickup_date'):
        try:
            create_item_rental_request(conn, partner_id, org_name, {
                'pickup_date': d.get('asset_pickup_date'), 'return_date': d.get('asset_return_date') or d.get('asset_pickup_date'),
                'items': d.get('asset_items') or [], 'wish_list': d.get('asset_wish_list') or '', 'purpose': purpose}, 'interest_form')
        except Exception as e:
            app.logger.warning(f'Asset part of interest form failed: {e}')
    elif (d.get('asset_wish_list') or '').strip():
        _save_wish(conn, rid, org_name, d['asset_wish_list'])
    conn.commit()
    try:
        es = fetchone(conn, 'SELECT rental_approver_emails, rental_approval_levels FROM email_settings WHERE id=1') or {}
        approver_emails = []
        try:
            import json as _jpi
            levels = _jpi.loads(es.get('rental_approval_levels') or '[]')
            if levels and levels[0].get('emails'):
                approver_emails = [e.strip() for e in levels[0]['emails'].replace(',', '\n').splitlines() if e.strip()]
        except Exception:
            pass
        if not approver_emails:
            raw = (es.get('rental_approver_emails') or '').strip()
            approver_emails = [e.strip() for e in raw.replace(',', '\n').splitlines() if e.strip()]
        dates_line = ''
        if specific_dates:
            date_bits = []
            for s in specific_dates:
                bit = s['date']
                if s['start_time']:
                    bit += f' ({s["start_time"]}' + (f'–{s["end_time"]})' if s['end_time'] else ')')
                date_bits.append(bit)
            dates_line = f'<strong>Specific dates they have in mind:</strong> {", ".join(date_bits)}<br>'
        subject = f'New Artistic Partnership Interest — {org_name}'
        body = (f'A new partnership interest form has been submitted.<br><br>'
                f'<strong>Organization:</strong> {org_name}<br>'
                f'<strong>Contact:</strong> {contact_name} ({contact_email})<br>'
                f'<strong>Wants to use the space for:</strong> {purpose}<br>'
                f'<strong>How often:</strong> {(d.get("desired_frequency") or "Not specified")}<br>'
                f'{dates_line}<br>'
                f'Please log in to RoleCall → Artistic Partnership to review and follow up.')
        for email_addr in approver_emails:
            try:
                send_email(email_addr, subject, build_hwtc_email_html(subject, body))
            except Exception as email_err:
                app.logger.warning(f'Partnership interest notify to {email_addr} failed: {email_err}')
    except Exception as e:
        app.logger.warning(f'Partnership interest notification error: {e}')
    conn.close()
    return jsonify({'ok': True})

@app.route('/api/rental/requests', methods=['GET'])
def get_rental_requests():
    err = require_permission('rentals', 'view')
    if err: return err
    conn = get_db()
    # Ensure new columns exist
    for col_def in [
        "approval_level INTEGER DEFAULT 0",
        "approval_history TEXT DEFAULT '[]'",
        "denial_reason TEXT DEFAULT ''"
    ]:
        try:
            execute(conn, f'ALTER TABLE rental_requests ADD COLUMN IF NOT EXISTS {col_def}')
            conn.commit()
        except Exception:
            # Without this rollback, a failed statement here leaves the
            # connection's transaction aborted — Postgres then refuses to
            # run the SELECT below at all, and the route would raise on a
            # perfectly good request. Roll back so one bad statement can't
            # take down everything that follows on this connection.
            conn.rollback()
    try:
        requests_data = fetchall(conn, '''SELECT rr.*, rp.name AS partner_name,
            rp.contact_email AS partner_email, rp.contact_name AS partner_contact,
            rp.contact_phone AS partner_phone, rp.organization_type AS partner_org_type,
            rp.organization_website AS partner_website,
            rs.name AS space_name,
            ra.id AS agreement_id, ra.status AS agreement_status,
            ra.partner_signed_at, ra.partner_signed_name, ra.signing_token,
            ra.hwtc_signed_name, ra.hwtc_signed_title,
            COALESCE(rr.approval_level, 0) AS approval_level,
            COALESCE(rr.approval_history, '[]') AS approval_history,
            COALESCE(rr.denial_reason, '') AS denial_reason,
            (SELECT COUNT(*) FROM rental_messages rm WHERE rm.request_id=rr.id
                AND rm.direction='inbound' AND rm.read_at IS NULL) AS unread_message_count,
            (SELECT id FROM rental_payments WHERE agreement_id=ra.id AND payment_type='deposit' ORDER BY created_at DESC LIMIT 1) AS deposit_payment_id,
            (SELECT amount_cents FROM rental_payments WHERE agreement_id=ra.id AND payment_type='deposit' ORDER BY created_at DESC LIMIT 1) AS deposit_amount_cents,
            (SELECT square_invoice_status FROM rental_payments WHERE agreement_id=ra.id AND payment_type='deposit' ORDER BY created_at DESC LIMIT 1) AS deposit_invoice_status,
            (SELECT paid_at FROM rental_payments WHERE agreement_id=ra.id AND payment_type='deposit' ORDER BY created_at DESC LIMIT 1) AS deposit_paid_at,
            (SELECT public_url FROM rental_payments WHERE agreement_id=ra.id AND payment_type='deposit' ORDER BY created_at DESC LIMIT 1) AS deposit_public_url,
            (SELECT due_date FROM rental_payments WHERE agreement_id=ra.id AND payment_type='deposit' ORDER BY created_at DESC LIMIT 1) AS deposit_due_date,
            (SELECT id FROM rental_payments WHERE agreement_id=ra.id AND payment_type='final' ORDER BY created_at DESC LIMIT 1) AS final_payment_id,
            (SELECT amount_cents FROM rental_payments WHERE agreement_id=ra.id AND payment_type='final' ORDER BY created_at DESC LIMIT 1) AS final_amount_cents,
            (SELECT square_invoice_status FROM rental_payments WHERE agreement_id=ra.id AND payment_type='final' ORDER BY created_at DESC LIMIT 1) AS final_invoice_status,
            (SELECT paid_at FROM rental_payments WHERE agreement_id=ra.id AND payment_type='final' ORDER BY created_at DESC LIMIT 1) AS final_paid_at,
            (SELECT public_url FROM rental_payments WHERE agreement_id=ra.id AND payment_type='final' ORDER BY created_at DESC LIMIT 1) AS final_public_url,
            (SELECT due_date FROM rental_payments WHERE agreement_id=ra.id AND payment_type='final' ORDER BY created_at DESC LIMIT 1) AS final_due_date,
            (SELECT COUNT(*) FROM rental_payments WHERE agreement_id=ra.id AND payment_type='installment') AS installment_count,
            (SELECT COUNT(*) FROM rental_payments WHERE agreement_id=ra.id AND payment_type='installment' AND square_invoice_status='PAID') AS installment_paid_count,
            (SELECT COALESCE(SUM(amount_cents),0) FROM rental_payments WHERE agreement_id=ra.id AND payment_type='installment') AS installment_total_cents,
            (SELECT COALESCE(SUM(amount_cents),0) FROM rental_payments WHERE agreement_id=ra.id AND payment_type='installment' AND square_invoice_status='PAID') AS installment_paid_cents,
            (SELECT COUNT(*) FROM rental_payments WHERE agreement_id=ra.id AND payment_type='installment' AND sent_at IS NULL) AS installment_unsent_count,
            (SELECT MIN(due_date) FROM rental_payments WHERE agreement_id=ra.id AND payment_type='installment' AND sent_at IS NULL) AS installment_next_unsent_due_date,
            (SELECT MIN(due_date) FROM rental_payments WHERE agreement_id=ra.id AND payment_type='installment' AND square_invoice_status!='PAID') AS installment_next_due_date
            FROM rental_requests rr
            LEFT JOIN rental_partners rp ON rp.id=rr.partner_id
            LEFT JOIN rental_spaces rs ON rs.id=rr.space_id
            LEFT JOIN rental_agreements ra ON ra.request_id=rr.id
            ORDER BY rr.start_date DESC, rr.created_at DESC''') or []
    except Exception as e:
        conn.rollback()
        conn.close()
        app.logger.error(f'get_rental_requests query failed: {e}')
        return jsonify({'error': f'Could not load Artistic Partnership requests: {e}'}), 500
    conn.close()
    return jsonify(requests_data)

@app.route('/api/rental/requests', methods=['POST'])
def create_rental_request():
    err = require_permission('rentals')
    if err: return err
    import uuid as _urr
    import json as _jcrr
    d = request.json or {}
    conn = get_db()
    rid = str(_urr.uuid4())
    portal_token = str(_urr.uuid4())
    specific_dates = d.get('specific_dates') or []
    execute(conn, '''INSERT INTO rental_requests
        (id, partner_id, space_id, title, purpose, start_date, end_date,
         start_time, end_time, recurring, recurrence_pattern, recurrence_end_date,
         date_mode, specific_dates, portal_token,
         estimated_attendance, rate_type, rate_amount, total_amount, status, notes,
         partnership_category, revenue_split_notes)
        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,'pending',%s,%s,%s)''',
        (rid, d.get('partner_id') or None, d.get('space_id') or None,
         (d.get('title') or '').strip(),
         (d.get('purpose') or '').strip(),
         (d.get('start_date') or '').strip(),
         (d.get('end_date') or '').strip(),
         (d.get('start_time') or '').strip(),
         (d.get('end_time') or '').strip(),
         bool(d.get('recurring')),
         (d.get('recurrence_pattern') or '').strip(),
         (d.get('recurrence_end_date') or '').strip(),
         (d.get('date_mode') or 'range').strip(),
         _jcrr.dumps(specific_dates),
         portal_token,
         d.get('estimated_attendance') or None,
         d.get('rate_type') or 'Hour',
         int(d.get('rate_amount') or 0),
         int(d.get('total_amount') or 0),
         (d.get('notes') or '').strip(),
         (d.get('partnership_category') or 'open_partnership').strip(),
         (d.get('revenue_split_notes') or '').strip()))
    # Nothing is added to the calendar yet — occurrences are only generated
    # once this request is fully approved (see approve_rental_request).
    conn.commit()
    # Send approval notification — use Level 1 emails from approval_levels, fallback to rental_approver_emails
    try:
        import json as _jen
        es = fetchone(conn, 'SELECT rental_approver_emails, rental_approval_levels FROM email_settings WHERE id=1') or {}
        approver_emails = []
        # Try Level 1 from approval levels first
        try:
            levels = _jen.loads(es.get('rental_approval_levels') or '[]')
            if levels and levels[0].get('emails'):
                approver_emails = [e.strip() for e in levels[0]['emails'].replace(',','\n').splitlines() if e.strip()]
        except Exception:
            pass
        # Fall back to flat approver list
        if not approver_emails:
            raw = (es.get('rental_approver_emails') or '').strip()
            approver_emails = [e.strip() for e in raw.replace(',','\n').splitlines() if e.strip()]
        subject = f'New Artistic Partnership Request Pending Approval: {d.get("title","")}'
        body = f'A new Artistic Partnership request has been submitted and requires approval.<br><br><strong>Title:</strong> {d.get("title","")}<br><strong>Start:</strong> {d.get("start_date","")}<br><strong>Purpose:</strong> {d.get("purpose","")}<br><br>Please log in to RoleCall → Artistic Partnership to review and approve.'
        for email_addr in approver_emails:
            try:
                send_email(email_addr, subject, build_hwtc_email_html(subject, body))
            except Exception as email_err:
                app.logger.warning(f'Rental approver email to {email_addr} failed: {email_err}')
        if not approver_emails:
            app.logger.warning('Artistic Partnership request created but no approver emails configured — check Settings → Email Settings → Artistic Partnership Approvals')
    except Exception as e:
        app.logger.warning(f'Rental approval notification error: {e}')
    conn.close()
    return jsonify({'ok': True, 'id': rid})

def _get_live_installments_plan(conn, agreement_id):
    """Exhibit A (the itemized payment schedule in the contract document)
    should always match what's actually been scheduled/invoiced in
    rental_payments — not the frozen snapshot taken at the moment the
    contract was first generated, which silently drifts out of sync the
    first time an installment is added, removed, or corrected afterward
    (exactly the bug that left an already-added installment missing from
    a downloaded PDF). Returns None (rather than an empty list) when there
    are no installment rows yet, so callers know to fall back to whatever
    was submitted at generation time instead of rendering an empty table."""
    rows = fetchall(conn, """SELECT amount_cents, due_date, installment_label FROM rental_payments
        WHERE agreement_id=%s AND payment_type='installment' ORDER BY due_date""", (agreement_id,)) or []
    if not rows:
        return None
    return [{'amount': (r.get('amount_cents') or 0) / 100.0, 'due_date': r.get('due_date') or '',
             'label': r.get('installment_label') or ''} for r in rows]

def _get_or_create_event_type(conn, name, color='violet'):
    row = fetchone(conn, 'SELECT id FROM event_types WHERE LOWER(name)=LOWER(%s)', (name,))
    if row:
        return row['id']
    tid = str(uuid.uuid4())
    execute(conn, 'INSERT INTO event_types (id,name,color) VALUES (%s,%s,%s)', (tid, name, color))
    conn.commit()
    return tid

def _sync_rental_events_for_request(conn, request_id):
    """Keep real `events` rows in sync with an Artistic Partnership
    request's active occurrences, so rental bookings get the same opening
    /closing checklist, kiosk open/close, and ELIC-assignment support as
    every other event on the calendar — rental dates used to only exist as
    a display-only overlay with nothing behind them to open or close.

    Reconciles both directions: creates an event for any active occurrence
    that doesn't have one yet, and removes the event for any occurrence
    that's no longer active (date edited away, request denied/sent back).
    Safe to call repeatedly — this is also how the one-time backfill for
    already-approved requests works.
    """
    req = fetchone(conn, '''SELECT rr.*, rp.name AS partner_name, rp.contact_name AS partner_contact,
        rs.name AS space_name FROM rental_requests rr
        LEFT JOIN rental_partners rp ON rp.id=rr.partner_id
        LEFT JOIN rental_spaces rs ON rs.id=rr.space_id
        WHERE rr.id=%s''', (request_id,))
    if not req:
        return
    occurrences = fetchall(conn, """SELECT * FROM rental_occurrences
        WHERE request_id=%s AND status!='cancelled'""", (request_id,)) or []
    active_occurrence_ids = {o['id'] for o in occurrences}
    linked_events = fetchall(conn, """SELECT id, rental_occurrence_id FROM events
        WHERE rental_request_id=%s AND rental_occurrence_id IS NOT NULL""", (request_id,)) or []
    linked_by_occurrence = {e['rental_occurrence_id']: e['id'] for e in linked_events}

    # Remove events for occurrences that are no longer active.
    for occurrence_id, event_id in linked_by_occurrence.items():
        if occurrence_id not in active_occurrence_ids:
            try:
                _delete_event_cascade(conn, event_id)
            except Exception as e:
                app.logger.warning(f'Rental event cleanup error for occurrence {occurrence_id}: {e}')

    # Create events for active occurrences that don't have one yet.
    to_create = [o for o in occurrences if o['id'] not in linked_by_occurrence]
    if not to_create:
        return
    event_type_id = _get_or_create_event_type(conn, 'Artistic Partnership', 'violet')
    partner_label = req.get('partner_name') or 'Partner'
    for o in to_create:
        eid = str(uuid.uuid4())
        execute(conn, '''INSERT INTO events
            (id, name, event_date, start_time, end_time, event_type_id, location, room, status,
             description, auto_log_hours, kiosk_signin_mode, rental_occurrence_id, rental_request_id)
            VALUES (%s,%s,%s,%s,%s,%s,'HWTC',%s,'draft',%s,TRUE,'auto',%s,%s)
            ON CONFLICT (rental_occurrence_id) WHERE rental_occurrence_id IS NOT NULL DO NOTHING''', (
            eid, f"{req.get('title','')} – {partner_label}", o.get('occurrence_date'),
            o.get('start_time') or req.get('start_time'), o.get('end_time') or req.get('end_time'),
            event_type_id, req.get('space_name') or '',
            f"Artistic Partnership booking with {partner_label}."
            + (f" On-site contact: {req['partner_contact']}." if req.get('partner_contact') else ''),
            o['id'], request_id))
    conn.commit()

def _dedupe_rental_events():
    """Fixes the fallout of a startup race: with multiple gunicorn workers,
    two processes could each run the backfill at the same moment, both see
    'no event for this occurrence yet' (since neither had committed), and
    both insert one — leaving every affected rental with 2 duplicate
    events. For each rental_occurrence_id with more than one event, keeps
    the earliest (oldest created_at, then lowest id as a tiebreaker) and
    cascade-deletes the rest. Safe to run every startup: a no-op once
    there's nothing left to dedupe.

    Also (re)creates the unique index on rental_occurrence_id here, in
    Python, right after cleanup — rather than relying solely on the SQL
    migration list, whose ordering can't guarantee dedup happens first.
    The plain migration-list attempt is left in place too as a harmless
    best-effort for the common case where there's nothing to clean up."""
    try:
        conn = get_db()
        dupes = fetchall(conn, """SELECT rental_occurrence_id FROM events
            WHERE rental_occurrence_id IS NOT NULL
            GROUP BY rental_occurrence_id HAVING COUNT(*) > 1""") or []
        for row in dupes:
            occ_id = row['rental_occurrence_id']
            rows = fetchall(conn, """SELECT id FROM events WHERE rental_occurrence_id=%s
                ORDER BY created_at ASC, id ASC""", (occ_id,)) or []
            for extra in rows[1:]:
                try:
                    _delete_event_cascade(conn, extra['id'])
                except Exception as e:
                    app.logger.warning(f'Rental event dedupe error for {extra["id"]}: {e}')
        try:
            execute(conn, """CREATE UNIQUE INDEX IF NOT EXISTS ux_events_rental_occurrence
                ON events(rental_occurrence_id) WHERE rental_occurrence_id IS NOT NULL""")
            conn.commit()
        except Exception as e:
            conn.rollback()
            app.logger.warning(f'Rental event unique index creation deferred: {e}')
        conn.close()
    except Exception as e:
        app.logger.warning(f'Rental event dedupe failed: {e}')

def _fix_rental_event_locations():
    """One-time (but safely repeatable) correction for rental-linked
    events created before this fix: they had the studio name written into
    `location` (e.g. 'Studio A'), which the checklist system reads as
    'this is happening somewhere other than our own building' and filters
    down to a generic reduced checklist. The studio name belongs in
    `room` instead — `location` should read 'HWTC', exactly like a normal
    in-house event, so the full studio checklist applies."""
    try:
        conn = get_db()
        execute(conn, """UPDATE events SET room=location, location='HWTC'
            WHERE rental_occurrence_id IS NOT NULL AND location IS NOT NULL AND location!='HWTC'
            AND (room IS NULL OR room='')""")
        # Edge case: a rental event that already has a room set for some
        # other reason — still fix location, just don't clobber room.
        execute(conn, """UPDATE events SET location='HWTC'
            WHERE rental_occurrence_id IS NOT NULL AND location IS NOT NULL AND location!='HWTC'
            AND room IS NOT NULL AND room!=''""")
        conn.commit(); conn.close()
    except Exception as e:
        app.logger.warning(f'Rental event location fix failed: {e}')

def _backfill_rental_calendar_events():
    """One-time (but safely repeatable) backfill: give every already
    approved/signed/active/completed rental request real calendar events,
    matching what now happens automatically going forward at approval
    time. Runs once at startup; _sync_rental_events_for_request is a
    no-op for requests that are already synced, so re-running this on
    every deploy is cheap and self-healing."""
    try:
        conn = get_db()
        request_ids = fetchall(conn, """SELECT DISTINCT request_id FROM rental_occurrences
            WHERE status != 'cancelled'""") or []
        for row in request_ids:
            try:
                _sync_rental_events_for_request(conn, row['request_id'])
            except Exception as e:
                app.logger.warning(f'Rental event backfill error for {row["request_id"]}: {e}')
        conn.close()
    except Exception as e:
        app.logger.warning(f'Rental event backfill failed: {e}')

def _backfill_session_registration_events():
    """One-time (but safely repeatable) backfill: give every already-confirmed
    registration with sessions a real event, matching what now happens
    automatically going forward via _auto_create_events_for_registration
    (called from finalize_registration). Skips anything that already has a
    linked event, so re-running this on every deploy is cheap and self-healing."""
    try:
        conn = get_db()
        regs = fetchall(conn, """SELECT * FROM program_registrations
            WHERE status='confirmed' AND session_ids IS NOT NULL
            AND session_ids != '[]' AND session_ids != ''""") or []
        for reg in regs:
            try:
                prog = fetchone(conn, 'SELECT * FROM youth_programs WHERE id=%s', (reg.get('program_id'),)) if reg.get('program_id') else None
                _auto_create_events_for_registration(conn, reg, prog)
            except Exception as e:
                app.logger.warning(f'Session registration event backfill error for {reg.get("id")}: {e}')
        conn.close()
    except Exception as e:
        app.logger.warning(f'Session registration event backfill failed: {e}')

_dedupe_rental_events()
_backfill_rental_calendar_events()
_backfill_session_registration_events()
_fix_rental_event_locations()

def _generate_rental_occurrences(conn, request_id, d):
    """Schedule dates from the partnership's pattern, plus any extra dates
    added on top (rental_requests.extra_dates), so approved add-on dates
    survive later edits to the pattern."""
    cat = (fetchone(conn, 'SELECT partnership_category FROM rental_requests WHERE id=%s', (request_id,)) or {}).get('partnership_category')
    if cat == 'item_rental':
        return   # lending items: pickup/return live on the reservations, not studio dates
    _generate_rental_occurrences_base(conn, request_id, d)
    try:
        row = fetchone(conn, 'SELECT extra_dates, start_time, end_time FROM rental_requests WHERE id=%s', (request_id,)) or {}
        extras = json.loads(row.get('extra_dates') or '[]')
    except Exception:
        extras = []
    for x in extras:
        dt = (x.get('date') or '')[:10]
        if len(dt) != 10 or fetchone(conn, 'SELECT 1 AS y FROM rental_occurrences WHERE request_id=%s AND occurrence_date=%s', (request_id, dt)):
            continue
        execute(conn, '''INSERT INTO rental_occurrences (id, request_id, occurrence_date, start_time, end_time, status, notes)
            VALUES (%s,%s,%s,%s,%s,'scheduled','Added date')''',
            (str(uuid.uuid4()), request_id, dt, x.get('start_time') or d.get('start_time') or row.get('start_time') or '',
             x.get('end_time') or d.get('end_time') or row.get('end_time') or ''))


def _generate_rental_occurrences_base(conn, request_id, d):
    """Create one rental_occurrences row per day this request covers, so it
    shows up on the calendar (via the synthetic-event merge in get_events).
    Only called once a request reaches 'approved' status — see
    approve_rental_request — and re-run (after clearing old rows) whenever
    an approved request's dates are edited, denied, or sent back.

    Three scheduling modes, driven by date_mode:
      'specific'  — an explicit list of individual dates (specific_dates,
                    JSON-encoded), for irregular bookings like "every other
                    Friday except spring break"
      'recurring' — start_date stepping by recurrence_pattern to
                    recurrence_end_date
      'range' (default, or single date) — every day from start_date to
                    end_date inclusive (same day for both = a single date)
    """
    import uuid as _uro2
    import datetime as _dto2
    import json as _jro2

    def _insert(date_str, stime, etime):
        execute(conn, '''INSERT INTO rental_occurrences
            (id, request_id, occurrence_date, start_time, end_time, status)
            VALUES (%s,%s,%s,%s,%s,'scheduled')''',
            (str(_uro2.uuid4()), request_id, date_str, stime, etime))

    mode = (d.get('date_mode') or '').strip()
    stime, etime = d.get('start_time', ''), d.get('end_time', '')

    if mode == 'specific':
        raw_dates = d.get('specific_dates') or []
        if isinstance(raw_dates, str):
            try:
                raw_dates = _jro2.loads(raw_dates)
            except Exception:
                raw_dates = []
        for item in raw_dates:
            if isinstance(item, dict):
                date_str = item.get('date', '')
                row_stime = item.get('start_time') or stime
                row_etime = item.get('end_time') or etime
            else:
                date_str = item
                row_stime, row_etime = stime, etime
            try:
                _dto2.date.fromisoformat(date_str)
            except Exception:
                continue
            _insert(date_str, row_stime, row_etime)
        return

    start_raw = (d.get('start_date') or '').strip()
    if not start_raw:
        return
    try:
        start = _dto2.date.fromisoformat(start_raw)
    except Exception:
        return

    is_recurring = (mode == 'recurring') or (not mode and d.get('recurring'))
    if is_recurring and (d.get('recurrence_end_date') or '').strip():
        pattern = d.get('recurrence_pattern') or 'weekly'
        try:
            end = _dto2.date.fromisoformat(d.get('recurrence_end_date').strip())
        except Exception:
            return
        cur = start
        while cur <= end:
            _insert(cur.isoformat(), stime, etime)
            if pattern == 'weekly':
                cur += _dto2.timedelta(days=7)
            elif pattern == 'biweekly':
                cur += _dto2.timedelta(days=14)
            elif pattern == 'daily':
                cur += _dto2.timedelta(days=1)
            elif pattern == 'monthly':
                month = cur.month + 1 if cur.month < 12 else 1
                year = cur.year + (1 if cur.month == 12 else 0)
                try:
                    cur = cur.replace(year=year, month=month)
                except Exception:
                    break
            else:
                break
        return

    # 'range' mode (or legacy rows with no date_mode set): a single date, or
    # a contiguous multi-day span via end_date
    end_raw = (d.get('end_date') or '').strip()
    try:
        end = _dto2.date.fromisoformat(end_raw) if end_raw else start
    except Exception:
        end = start
    if end < start:
        end = start
    cur = start
    while cur <= end:
        _insert(cur.isoformat(), stime, etime)
        cur += _dto2.timedelta(days=1)

@app.route('/api/rental/requests/<rid>', methods=['PUT'])
def update_rental_request(rid):
    err = require_auth()
    if err: return err
    import json as _jurr
    d = request.json or {}
    conn = get_db()
    existing = fetchone(conn, 'SELECT status FROM rental_requests WHERE id=%s', (rid,))
    if not existing:
        conn.close()
        return jsonify({'error': 'Not found'}), 404
    specific_dates = d.get('specific_dates') or []
    # Note: status is intentionally NOT updated here — it only changes
    # through the approve/deny/sendback routes, so editing a request's
    # details never silently reverts its approval progress.
    execute(conn, '''UPDATE rental_requests SET partner_id=%s, space_id=%s, title=%s,
        purpose=%s, start_date=%s, end_date=%s, start_time=%s, end_time=%s,
        recurring=%s, recurrence_pattern=%s, recurrence_end_date=%s,
        date_mode=%s, specific_dates=%s,
        estimated_attendance=%s, rate_type=%s, rate_amount=%s, total_amount=%s,
        notes=%s, partnership_category=%s, revenue_split_notes=%s, updated_at=NOW() WHERE id=%s''',
        (d.get('partner_id') or None, d.get('space_id') or None,
         (d.get('title') or '').strip(), (d.get('purpose') or '').strip(),
         (d.get('start_date') or '').strip(), (d.get('end_date') or '').strip(),
         (d.get('start_time') or '').strip(), (d.get('end_time') or '').strip(),
         bool(d.get('recurring')), (d.get('recurrence_pattern') or '').strip(),
         (d.get('recurrence_end_date') or '').strip(),
         (d.get('date_mode') or 'range').strip(), _jurr.dumps(specific_dates),
         d.get('estimated_attendance') or None,
         d.get('rate_type') or 'Hour',
         int(d.get('rate_amount') or 0), int(d.get('total_amount') or 0),
         (d.get('notes') or '').strip(),
         (d.get('partnership_category') or 'open_partnership').strip(),
         (d.get('revenue_split_notes') or '').strip(), rid))
    # Only an already-approved request has anything on the calendar to keep
    # in sync — clear and regenerate its occurrences so an edited date/time
    # is reflected rather than the original. A still-pending request has no
    # occurrences yet (those aren't created until approval), so there's
    # nothing to touch.
    # Only a request that's already on the calendar has occurrences to keep
    # in sync — clear and regenerate them so an edited date/time is
    # reflected rather than the original. A still-pending request has no
    # occurrences yet (those aren't created until approval). Signed/active
    # requests are included here too: this is purely the operational
    # calendar (dates, checklist, kiosk) — it doesn't touch the contract
    # document or the existing signature. For actually correcting the
    # signed document's terms, see /correct-signed below.
    if existing.get('status') in ('approved', 'signed', 'active'):
        execute(conn, 'DELETE FROM rental_occurrences WHERE request_id=%s', (rid,))
        _generate_rental_occurrences(conn, rid, d)
        _sync_rental_events_for_request(conn, rid)
    conn.commit(); conn.close()
    return jsonify({'ok': True})

@app.route('/api/rental/requests/<rid>/correct-signed', methods=['POST'])
def correct_signed_rental_request(rid):
    """Fix a mistake on an already-signed contract (wrong date, fee, space,
    etc.) without restarting the approve → generate → send → sign
    workflow. Updates the request's details and calendar the same as a
    normal edit, then regenerates the contract document's terms in place —
    same agreement row, same signing link, same recorded signature/date —
    so nothing needs to be re-sent or re-signed. Requires a short note
    explaining the correction, which gets appended to the agreement's
    internal notes as an audit trail."""
    err = require_permission('rentals')
    if err: return err
    import json as _jcsr
    d = request.json or {}
    reason = (d.get('correction_note') or '').strip()
    if not reason:
        return jsonify({'error': 'A short note explaining the correction is required, for the record'}), 400
    conn = get_db()
    agr = fetchone(conn, 'SELECT * FROM rental_agreements WHERE request_id=%s ORDER BY created_at DESC LIMIT 1', (rid,))
    if not agr or not agr.get('partner_signed_at'):
        conn.close()
        return jsonify({'error': 'This request has no signed agreement — use the regular Edit and Regenerate Contract instead'}), 400

    specific_dates = d.get('specific_dates') or []
    execute(conn, '''UPDATE rental_requests SET partner_id=%s, space_id=%s, title=%s,
        purpose=%s, start_date=%s, end_date=%s, start_time=%s, end_time=%s,
        recurring=%s, recurrence_pattern=%s, recurrence_end_date=%s,
        date_mode=%s, specific_dates=%s,
        estimated_attendance=%s, rate_type=%s, rate_amount=%s, total_amount=%s,
        notes=%s, partnership_category=%s, revenue_split_notes=%s, updated_at=NOW() WHERE id=%s''',
        (d.get('partner_id') or None, d.get('space_id') or None,
         (d.get('title') or '').strip(), (d.get('purpose') or '').strip(),
         (d.get('start_date') or '').strip(), (d.get('end_date') or '').strip(),
         (d.get('start_time') or '').strip(), (d.get('end_time') or '').strip(),
         bool(d.get('recurring')), (d.get('recurrence_pattern') or '').strip(),
         (d.get('recurrence_end_date') or '').strip(),
         (d.get('date_mode') or 'range').strip(), _jcsr.dumps(specific_dates),
         d.get('estimated_attendance') or None,
         d.get('rate_type') or 'Hour',
         int(d.get('rate_amount') or 0), int(d.get('total_amount') or 0),
         (d.get('notes') or '').strip(),
         (d.get('partnership_category') or 'open_partnership').strip(),
         (d.get('revenue_split_notes') or '').strip(), rid))

    execute(conn, 'DELETE FROM rental_occurrences WHERE request_id=%s', (rid,))
    _generate_rental_occurrences(conn, rid, d)
    _sync_rental_events_for_request(conn, rid)

    # Rebuild the contract *terms* using the same inputs the original
    # generation used (persisted on the agreement row) unless this request
    # explicitly overrides one — the signature itself is never touched,
    # since it's stored separately (partner_signed_name/at) and combined
    # with contract_html only at view/download time.
    req = fetchone(conn, '''SELECT rr.*, rp.name AS partner_name,
        rp.contact_name, rp.contact_email, rp.contact_phone,
        rp.organization_type, rs.name AS space_name, rs.amenities
        FROM rental_requests rr
        LEFT JOIN rental_partners rp ON rp.id=rr.partner_id
        LEFT JOIN rental_spaces rs ON rs.id=rr.space_id
        WHERE rr.id=%s''', (rid,))
    custom_terms = d.get('custom_terms') if d.get('custom_terms') is not None else (agr.get('custom_terms') or '')
    poc_name = d.get('poc_name') if d.get('poc_name') is not None else (agr.get('poc_name') or '')
    poc_email = d.get('poc_email') if d.get('poc_email') is not None else (agr.get('poc_email') or '')
    poc_phone = d.get('poc_phone') if d.get('poc_phone') is not None else (agr.get('poc_phone') or '')
    additional_terms = d.get('additional_terms') if d.get('additional_terms') is not None else (agr.get('additional_terms') or '')
    deposit = (d.get('deposit') or '').strip()
    revenue_split_notes = (d.get('revenue_split_notes') or req.get('revenue_split_notes') or '').strip()
    billing_frequency = (req.get('billing_frequency') or 'deposit_final')
    installments_plan = _get_live_installments_plan(conn, agr['id'])
    if installments_plan is None:
        try:
            installments_plan = json.loads(req.get('billing_installments_plan') or '[]')
        except Exception:
            installments_plan = []
    try:
        equipment_selections = json.loads(req.get('equipment_selections') or '[]')
    except Exception:
        equipment_selections = []
    occurrences = fetchall(conn, 'SELECT occurrence_date, start_time, end_time FROM rental_occurrences WHERE request_id=%s ORDER BY occurrence_date', (rid,)) or []
    # Carry the org's own signature forward unchanged — it was stamped
    # directly into contract_html at generation time (unlike the
    # partner's, which is layered on at view/download time), so rebuilding
    # the terms would otherwise silently blank it out.
    hwtc_signer_name = agr.get('hwtc_signed_name') or ''
    hwtc_signer_title = agr.get('hwtc_signed_title') or ''
    _hwtc_signed_dt = parse_db_datetime(agr.get('hwtc_signed_at'))
    hwtc_signed_at_str = _hwtc_signed_dt.strftime('%B %-d, %Y') if _hwtc_signed_dt else ''
    contract_html = _build_rental_contract_html(conn, req, custom_terms, poc_name, poc_email, poc_phone,
        deposit, revenue_split_notes, billing_frequency, occurrences, installments_plan, additional_terms, equipment_selections,
        hwtc_signer_name, hwtc_signer_title, hwtc_signed_at_str)

    staff = fetchone(conn, 'SELECT name FROM users WHERE id=%s', (session.get('user_id'),))
    staff_name = (staff or {}).get('name', 'Staff')
    signed_note = f"{agr.get('partner_signed_name','')} on {str(agr.get('partner_signed_at',''))[:10]}"
    audit_line = f"[{date.today().isoformat()}] Contract corrected by {staff_name}: {reason} (original signature by {signed_note} retained — no re-signature required)"
    new_notes = ((agr.get('admin_notes') or '') + ('\n' if agr.get('admin_notes') else '') + audit_line)

    execute(conn, '''UPDATE rental_agreements SET contract_html=%s, custom_terms=%s, poc_name=%s,
        poc_email=%s, poc_phone=%s, additional_terms=%s, admin_notes=%s, updated_at=NOW() WHERE id=%s''',
        (contract_html, custom_terms, poc_name, poc_email, poc_phone, additional_terms, new_notes, agr['id']))
    conn.commit(); conn.close()
    return jsonify({'ok': True})

def _rebuild_rental_contract_html(conn, agr, req, hwtc_name=None, hwtc_title=None, hwtc_signed_at_dt=None):
    """Shared rebuild logic used by every action that needs to regenerate
    a contract's terms in place (correcting a signed contract, adding
    HWTC's signature, adding an installment, or a plain resync) — keeps
    all of them pulling installments from the same live source and
    passing the same signature fields, so they can't drift apart from
    each other the way the Exhibit A bug did."""
    installments_plan = _get_live_installments_plan(conn, agr['id'])
    if installments_plan is None:
        try:
            installments_plan = json.loads(req.get('billing_installments_plan') or '[]')
        except Exception:
            installments_plan = []
    try:
        equipment_selections = json.loads(req.get('equipment_selections') or '[]')
    except Exception:
        equipment_selections = []
    occurrences = fetchall(conn, 'SELECT occurrence_date, start_time, end_time FROM rental_occurrences WHERE request_id=%s ORDER BY occurrence_date', (agr['request_id'],)) or []
    if hwtc_name is None:
        hwtc_name = agr.get('hwtc_signed_name') or ''
        hwtc_title = agr.get('hwtc_signed_title') or ''
        _hwtc_dt = parse_db_datetime(agr.get('hwtc_signed_at'))
        hwtc_signed_at_str = _hwtc_dt.strftime('%B %-d, %Y') if _hwtc_dt else ''
    else:
        hwtc_signed_at_str = (hwtc_signed_at_dt or datetime.now()).strftime('%B %-d, %Y')
    return _build_rental_contract_html(conn, req, agr.get('custom_terms') or '', agr.get('poc_name') or '',
        agr.get('poc_email') or '', agr.get('poc_phone') or '', '', req.get('revenue_split_notes') or '',
        req.get('billing_frequency') or 'deposit_final', occurrences, installments_plan, agr.get('additional_terms') or '',
        equipment_selections, hwtc_name or '', hwtc_title or '', hwtc_signed_at_str)

@app.route('/api/rental/agreements/<aid>/resync-document', methods=['POST'])
def resync_rental_agreement_document(aid):
    """Refreshes a contract's document from current live data — dates,
    total, installment schedule, both signatures — without requiring a
    correction reason, for whenever the document's just out of sync with
    RoleCall's records rather than an actual mistake being fixed (e.g. an
    installment added before Exhibit A auto-refreshed on that action)."""
    err = require_permission('rentals')
    if err: return err
    conn = get_db()
    agr = fetchone(conn, 'SELECT * FROM rental_agreements WHERE id=%s', (aid,))
    if not agr:
        conn.close()
        return jsonify({'error': 'Agreement not found'}), 404
    req = fetchone(conn, '''SELECT rr.*, rp.name AS partner_name,
        rp.contact_name, rp.contact_email, rp.contact_phone,
        rp.organization_type, rs.name AS space_name, rs.amenities
        FROM rental_requests rr
        LEFT JOIN rental_partners rp ON rp.id=rr.partner_id
        LEFT JOIN rental_spaces rs ON rs.id=rr.space_id
        WHERE rr.id=%s''', (agr['request_id'],))
    if not req:
        conn.close()
        return jsonify({'error': 'Rental request not found'}), 404
    contract_html = _rebuild_rental_contract_html(conn, agr, req)
    execute(conn, 'UPDATE rental_agreements SET contract_html=%s, updated_at=NOW() WHERE id=%s', (contract_html, aid))
    conn.commit(); conn.close()
    return jsonify({'ok': True})

@app.route('/api/rental/agreements/<aid>/sign-hwtc', methods=['POST'])
def sign_hwtc_rental_agreement(aid):
    """Adds (or replaces) HWTC's own signature on an agreement that
    doesn't have one recorded yet — most commonly a contract generated
    before the HWTC-signature feature existed, where the line was left
    blank. Works regardless of whether the partner has already signed:
    the two signatures are independent, so this never disturbs theirs."""
    err = require_permission('rentals')
    if err: return err
    d = request.json or {}
    hwtc_signer_name = (d.get('hwtc_signatory_name') or '').strip()
    if not hwtc_signer_name:
        return jsonify({'error': 'A signer name is required'}), 400
    hwtc_signer_title = (d.get('hwtc_signatory_title') or '').strip()
    conn = get_db()
    agr = fetchone(conn, 'SELECT * FROM rental_agreements WHERE id=%s', (aid,))
    if not agr:
        conn.close()
        return jsonify({'error': 'Agreement not found'}), 404
    req = fetchone(conn, '''SELECT rr.*, rp.name AS partner_name,
        rp.contact_name, rp.contact_email, rp.contact_phone,
        rp.organization_type, rs.name AS space_name, rs.amenities
        FROM rental_requests rr
        LEFT JOIN rental_partners rp ON rp.id=rr.partner_id
        LEFT JOIN rental_spaces rs ON rs.id=rr.space_id
        WHERE rr.id=%s''', (agr['request_id'],))
    if not req:
        conn.close()
        return jsonify({'error': 'Rental request not found'}), 404
    hwtc_signed_at_dt = datetime.now()
    contract_html = _rebuild_rental_contract_html(conn, agr, req, hwtc_signer_name, hwtc_signer_title, hwtc_signed_at_dt)
    execute(conn, '''UPDATE rental_agreements SET contract_html=%s, hwtc_signed_name=%s,
        hwtc_signed_title=%s, hwtc_signed_at=%s, updated_at=NOW() WHERE id=%s''',
        (contract_html, hwtc_signer_name, hwtc_signer_title, hwtc_signed_at_dt, aid))
    conn.commit(); conn.close()
    return jsonify({'ok': True})

@app.route('/api/rental/requests/<rid>/approve', methods=['POST'])
def approve_rental_request(rid):
    err = require_auth()
    if err: return err
    import json as _jra
    import datetime as _dtra
    d = request.get_json(silent=True) or {}
    conn = get_db()
    user = fetchone(conn, 'SELECT name, email FROM users WHERE id=%s', (session['user_id'],))
    req = fetchone(conn, 'SELECT * FROM rental_requests WHERE id=%s', (rid,))
    if not req:
        conn.close()
        return jsonify({'error': 'Not found'}), 404
    # Load approval levels config
    es = fetchone(conn, 'SELECT rental_approval_levels FROM email_settings WHERE id=1') or {}
    try:
        levels = _jra.loads(es.get('rental_approval_levels') or '[]')
    except Exception:
        levels = []
    # Load current approval history
    try:
        history = _jra.loads(req.get('approval_history') or '[]')
    except Exception:
        history = []
    current_level = int(req.get('approval_level') or 0)
    next_level = current_level + 1
    approver_name = (user or {}).get('name', 'Admin')
    approver_email = (user or {}).get('email', '')
    # Add to history
    history.append({
        'level': next_level,
        'approved_by': approver_name,
        'approved_by_email': approver_email,
        'approved_at': _dtra.datetime.now().isoformat(),
        'notes': (d.get('notes') or '').strip()
    })
    # Check if all levels complete
    total_levels = len(levels) if levels else 1
    fully_approved = next_level >= total_levels
    new_status = 'approved' if fully_approved else 'pending'
    execute(conn, '''UPDATE rental_requests SET
        approval_level=%s, approval_history=%s, status=%s,
        approved_by=%s, approved_at=NOW(), updated_at=NOW() WHERE id=%s''',
        (next_level, _jra.dumps(history), new_status,
         approver_name, rid))
    # This is the point where a rental actually goes on the calendar —
    # fully approved and awaiting the partner's signature. `req` still has
    # this request's original dates/pattern/specific_dates since nothing
    # here changed them.
    if fully_approved:
        _generate_rental_occurrences(conn, rid, req)
        _sync_rental_events_for_request(conn, rid)
    # Notify next level approvers if not fully approved
    if not fully_approved and levels and next_level < len(levels):
        next_level_config = levels[next_level]
        emails_raw = (next_level_config.get('emails') or '').strip()
        emails = [e.strip() for e in emails_raw.replace(',', '\n').splitlines() if e.strip()]
        for em in emails:
            try:
                send_email(em,
                    f'Artistic Partnership Request Needs Your Approval (Level {next_level+1}): {req.get("title","")}',
                    build_hwtc_email_html(f'Artistic Partnership Request Needs Your Approval (Level {next_level+1}): {req.get("title","")}',
                    f'<p>{approver_name} has approved this request at Level {next_level}.</p><p>Title: {req.get("title","")}</p><p>Please log in to RoleCall to review and approve at Level {next_level+1}: {next_level_config.get("label","")}.</p>'))
            except Exception: pass
    conn.commit(); conn.close()
    return jsonify({'ok': True, 'fully_approved': fully_approved, 'level': next_level})


@app.route('/api/rental/requests/<rid>/deny', methods=['POST'])
def deny_rental_request(rid):
    err = require_auth()
    if err: return err
    import json as _jrd
    import datetime as _dtrd
    d = request.json or {}
    reason = (d.get('reason') or '').strip()
    conn = get_db()
    user = fetchone(conn, 'SELECT name FROM users WHERE id=%s', (session['user_id'],))
    req = fetchone(conn, 'SELECT * FROM rental_requests WHERE id=%s', (rid,))
    if not req:
        conn.close()
        return jsonify({'error': 'Not found'}), 404
    try:
        history = _jrd.loads(req.get('approval_history') or '[]')
    except Exception:
        history = []
    history.append({
        'action': 'denied',
        'by': (user or {}).get('name', 'Admin'),
        'at': _dtrd.datetime.now().isoformat(),
        'reason': reason
    })
    execute(conn, '''UPDATE rental_requests SET status='denied', denial_reason=%s,
        approval_history=%s, updated_at=NOW() WHERE id=%s''',
        (reason, _jrd.dumps(history), rid))
    # If this had already been approved (and put on the calendar), take it back off.
    execute(conn, "UPDATE inventory_reservations SET status='cancelled' WHERE request_id=%s AND status='reserved'", (rid,))
    execute(conn, 'DELETE FROM rental_occurrences WHERE request_id=%s', (rid,))
    _sync_rental_events_for_request(conn, rid)
    # Notify partner if we have their email
    partner = fetchone(conn, '''SELECT rp.contact_email, rp.contact_name, rp.name AS pname
        FROM rental_requests rr JOIN rental_partners rp ON rp.id=rr.partner_id
        WHERE rr.id=%s''', (rid,))
    if partner and partner.get('contact_email'):
        try:
            send_email(partner['contact_email'],
                f'Artistic Partnership Request Update: {req.get("title","")}',
                build_hwtc_email_html(f'Artistic Partnership Request Update: {req.get("title","")}',
                f'<p>Dear {partner.get("contact_name") or partner.get("pname","")},</p><p>We regret to inform you that your Artistic Partnership request "{req.get("title","")}" has not been approved at this time.</p><p>{("Reason: "+reason) if reason else ""}</p><p>Please contact us if you have questions.</p>'))
        except Exception: pass
    conn.commit(); conn.close()
    return jsonify({'ok': True})


# ══ Inventory & item rentals (costumes, props, equipment) ═════════════════
# A catalog of what HWTC owns, and a fourth Artistic Partnership category,
# "item_rental", for lending it out: pickup and return dates instead of
# studio dates, a list of items instead of rooms, check-out and check-in
# instead of opening and closing an event. Reservations keep the same item
# from being promised twice, including holds for HWTC's own productions.
INVENTORY_CATEGORIES = ('costume', 'prop', 'equipment')
INVENTORY_RATE_UNITS = ('day', 'week', 'run')


def _inv_item_out(r, avail=None):
    r = dict(r)
    for k in ('created_at', 'updated_at'):
        if r.get(k) is not None:
            r[k] = str(r[k])[:19]
    r['photo_url'] = ('/api/inventory/' + r['id'] + '/photo?v=' + str(r.get('updated_at') or '')[:19].replace(' ', '')) if r.get('photo_filename') else ''
    r.pop('photo_filename', None)
    if avail is not None:
        r['available'] = avail
    return r


def inventory_available(conn, item_id, start, end, exclude_request_id=None, exclude_res_id=None):
    """How many of an item are free for every day from start to end
    (inclusive). Counts reservations that overlap and aren't cancelled or
    already returned. A package is as available as its scarcest part."""
    item = fetchone(conn, 'SELECT quantity, status, kind FROM inventory_items WHERE id=%s', (item_id,))
    if not item or item.get('status') in ('retired',):
        return 0
    if item.get('kind') == 'package':
        if item.get('status') == 'repair':
            return 0
        parts = fetchall(conn, 'SELECT item_id, quantity FROM inventory_package_items WHERE package_id=%s', (item_id,)) or []
        if not parts:
            return 0
        return min(inventory_available(conn, p['item_id'], start, end, exclude_request_id, exclude_res_id) // max(1, int(p['quantity'] or 1))
                   for p in parts)
    q = '''SELECT COALESCE(SUM(quantity - COALESCE(returned_qty,0)),0) AS n FROM inventory_reservations
        WHERE item_id=%s AND status IN ('reserved','out') AND start_date <= %s AND end_date >= %s'''
    params = [item_id, end or start, start]
    if exclude_request_id:
        q += ' AND COALESCE(request_id,\'\') <> %s'; params.append(exclude_request_id)
    if exclude_res_id:
        q += ' AND id <> %s'; params.append(exclude_res_id)
    used = int((fetchone(conn, q, tuple(params)) or {}).get('n') or 0)
    owned = int(item.get('quantity') or 0)
    if item.get('status') == 'repair':
        return 0
    return max(0, owned - used)


def _rate_units(rate_unit, start, end):
    import datetime as _dti
    try:
        days = (_dti.date.fromisoformat(str(end)[:10]) - _dti.date.fromisoformat(str(start)[:10])).days + 1
    except Exception:
        days = 1
    days = max(1, days)
    if rate_unit == 'week':
        return -(-days // 7)
    if rate_unit == 'run':
        return 1
    return days


@app.route('/api/inventory', methods=['GET', 'POST'])
def inventory_list():
    err = require_permission('rentals', 'view' if request.method == 'GET' else 'edit')
    if err: return err
    conn = get_db()
    try:
        if request.method == 'POST':
            d = request.json or {}
            iid = str(uuid.uuid4())
            _inv_save(conn, iid, d, new=True)
            conn.commit()
            return jsonify(_inv_item_out(fetchone(conn, 'SELECT * FROM inventory_items WHERE id=%s', (iid,))))
        start, end = request.args.get('start') or '', request.args.get('end') or ''
        rows = fetchall(conn, '''SELECT i.*,
                (SELECT COALESCE(SUM(r.quantity - COALESCE(r.returned_qty,0)),0) FROM inventory_reservations r
                  WHERE r.item_id=i.id AND r.status='out') AS out_now
            FROM inventory_items i ORDER BY i.category, i.name''') or []
        out = []
        for r in rows:
            a = inventory_available(conn, r['id'], start, end or start) if start else None
            out.append(_inv_item_out(r, a))
        return jsonify(out)
    finally:
        conn.close()


def _inv_save(conn, iid, d, new=False):
    cat = d.get('category') if d.get('category') in INVENTORY_CATEGORIES else 'prop'
    unit = d.get('rate_unit') if d.get('rate_unit') in INVENTORY_RATE_UNITS else 'run'
    def cents(v):
        try: return int(round(float(v) * 100)) if str(v).strip() != '' else 0
        except Exception: return 0
    vals = ((d.get('name') or '').strip()[:160] or 'Untitled item', cat, 'set' if d.get('kind') == 'set' else 'piece',
            (d.get('description') or '').strip()[:2000], (d.get('sizes') or '').strip()[:200], max(0, int(d.get('quantity') or 1)),
            cents(d.get('replacement_value')), cents(d.get('rate')), unit, (d.get('location') or '').strip()[:160],
            d.get('status') if d.get('status') in ('available', 'repair', 'retired') else 'available',
            (d.get('set_contents') or '').strip()[:2000], bool(d.get('partner_visible', True)), (d.get('notes') or '').strip()[:2000],
            (d.get('tags') or '').strip()[:300])
    kind = d.get('kind') if d.get('kind') in ('piece', 'set', 'package') else 'piece'
    vals = vals[:2] + (kind,) + vals[3:]
    extra = ('quote' if d.get('pricing') == 'quote' else 'flat', bool(d.get('rentable_alone', True)), (d.get('show_name') or '').strip()[:120])
    if new:
        execute(conn, '''INSERT INTO inventory_items (id, name, category, kind, description, sizes, quantity, replacement_value_cents,
            rate_cents, rate_unit, location, status, set_contents, partner_visible, notes, tags)
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)''', (iid,) + vals)
    else:
        execute(conn, '''UPDATE inventory_items SET name=%s, category=%s, kind=%s, description=%s, sizes=%s, quantity=%s,
            replacement_value_cents=%s, rate_cents=%s, rate_unit=%s, location=%s, status=%s, set_contents=%s, partner_visible=%s,
            notes=%s, tags=%s, updated_at=NOW() WHERE id=%s''', vals + (iid,))
    execute(conn, 'UPDATE inventory_items SET pricing=%s, rentable_alone=%s, show_name=%s WHERE id=%s', extra + (iid,))
    if kind == 'package' and 'components' in d:
        execute(conn, 'DELETE FROM inventory_package_items WHERE package_id=%s', (iid,))
        for c in d.get('components') or []:
            if c.get('item_id') and c['item_id'] != iid:
                execute(conn, '''INSERT INTO inventory_package_items (package_id, item_id, quantity) VALUES (%s,%s,%s)
                    ON CONFLICT (package_id, item_id) DO UPDATE SET quantity=EXCLUDED.quantity''', (iid, c['item_id'], max(1, int(c.get('quantity') or 1))))


@app.route('/api/inventory/<iid>', methods=['GET', 'PUT', 'DELETE'])
def inventory_item(iid):
    err = require_permission('rentals', 'view' if request.method == 'GET' else 'edit')
    if err: return err
    conn = get_db()
    try:
        row = fetchone(conn, 'SELECT * FROM inventory_items WHERE id=%s', (iid,))
        if not row:
            return jsonify({'error': 'Item not found'}), 404
        if request.method == 'DELETE':
            if fetchone(conn, "SELECT 1 AS x FROM inventory_reservations WHERE item_id=%s AND status IN ('reserved','out')", (iid,)):
                return jsonify({'error': 'This item is reserved or out right now. Mark it Retired instead, or finish those first.'}), 400
            execute(conn, 'DELETE FROM inventory_items WHERE id=%s', (iid,))
            conn.commit()
            return jsonify({'ok': True})
        if request.method == 'PUT':
            _inv_save(conn, iid, request.json or {})
            conn.commit()
            row = fetchone(conn, 'SELECT * FROM inventory_items WHERE id=%s', (iid,))
        res = fetchall(conn, '''SELECT r.*, rr.title AS request_title, rp.name AS partner_name, p.name AS production_name
            FROM inventory_reservations r LEFT JOIN rental_requests rr ON rr.id=r.request_id
            LEFT JOIN rental_partners rp ON rp.id=rr.partner_id LEFT JOIN productions p ON p.id=r.production_id
            WHERE r.item_id=%s ORDER BY r.start_date DESC LIMIT 60''', (iid,)) or []
        for x in res:
            for k in ('checked_out_at', 'returned_at', 'created_at'):
                if x.get(k) is not None: x[k] = str(x[k])[:16]
        out = _inv_item_out(row)
        out['reservations'] = res
        out['components'] = fetchall(conn, '''SELECT pi.item_id, pi.quantity, i.name, i.category, i.rentable_alone FROM inventory_package_items pi
            JOIN inventory_items i ON i.id=pi.item_id WHERE pi.package_id=%s ORDER BY i.name''', (iid,)) or []
        out['in_packages'] = fetchall(conn, '''SELECT p.id, p.name, pi.quantity FROM inventory_package_items pi JOIN inventory_items p ON p.id=pi.package_id
            WHERE pi.item_id=%s ORDER BY p.name''', (iid,)) or []
        return jsonify(out)
    finally:
        conn.close()


@app.route('/api/inventory/<iid>/photo', methods=['GET', 'POST'])
def inventory_photo(iid):
    if request.method == 'GET':
        conn = get_db()
        try:
            r = fetchone(conn, 'SELECT photo_filename FROM inventory_items WHERE id=%s', (iid,))
        finally:
            conn.close()
        if not r or not r.get('photo_filename') or not os.path.exists(os.path.join(UPLOAD_FOLDER, r['photo_filename'])):
            return 'Not found', 404
        resp = send_from_directory(UPLOAD_FOLDER, r['photo_filename'], conditional=True)
        resp.headers['Cache-Control'] = 'public, max-age=86400'
        return resp
    err = require_permission('rentals', 'edit')
    if err: return err
    f = request.files.get('file')
    ext = os.path.splitext(secure_filename(f.filename if f else ''))[1].lower()
    if not f or ext not in ('.jpg', '.jpeg', '.png', '.webp', '.gif'):
        return jsonify({'error': 'Choose a JPG, PNG, WebP or GIF photo'}), 400
    name = 'inv-' + uuid.uuid4().hex + ext
    f.save(os.path.join(UPLOAD_FOLDER, name))
    conn = get_db()
    try:
        old = fetchone(conn, 'SELECT photo_filename FROM inventory_items WHERE id=%s', (iid,)) or {}
        execute(conn, 'UPDATE inventory_items SET photo_filename=%s, updated_at=NOW() WHERE id=%s', (name, iid))
        conn.commit()
        if old.get('photo_filename'):
            try: os.remove(os.path.join(UPLOAD_FOLDER, old['photo_filename']))
            except Exception: pass
    finally:
        conn.close()
    return jsonify({'ok': True})


@app.route('/api/inventory/import', methods=['POST'])
def inventory_import():
    """CSV with a header row: name, category, kind, quantity, sizes, rate,
    rate_unit, replacement_value, location, description, set_contents, tags."""
    err = require_permission('rentals', 'edit')
    if err: return err
    import csv, io
    f = request.files.get('file')
    if not f:
        return jsonify({'error': 'Choose a CSV file'}), 400
    text = f.read().decode('utf-8-sig', errors='replace')
    rows = list(csv.DictReader(io.StringIO(text)))
    conn = get_db()
    added = 0
    try:
        for r in rows:
            r = {(k or '').strip().lower().replace(' ', '_'): (v or '').strip() for k, v in r.items()}
            if not r.get('name'):
                continue
            r['category'] = (r.get('category') or 'prop').lower().rstrip('s')
            r['rate'] = (r.get('rate') or '').replace('$', '')
            r['replacement_value'] = (r.get('replacement_value') or '').replace('$', '')
            try: r['quantity'] = int(float(r.get('quantity') or 1))
            except Exception: r['quantity'] = 1
            _inv_save(conn, str(uuid.uuid4()), r, new=True)
            added += 1
        conn.commit()
    finally:
        conn.close()
    return jsonify({'ok': True, 'added': added})


@app.route('/api/inventory/holds', methods=['POST'])
def inventory_hwtc_hold():
    """Hold items for one of HWTC's own productions so they can't be rented out."""
    err = require_permission('rentals', 'edit')
    if err: return err
    d = request.json or {}
    start, end = (d.get('start_date') or '')[:10], (d.get('end_date') or '')[:10] or (d.get('start_date') or '')[:10]
    if not start:
        return jsonify({'error': 'Pick the dates'}), 400
    conn = get_db()
    try:
        qty = max(1, int(d.get('quantity') or 1))
        left = inventory_available(conn, d.get('item_id'), start, end)
        if qty > left and not d.get('over_ok'):
            return jsonify({'error': f'Only {left} free for those dates. Hold anyway?', 'over': True}), 409
        hid = str(uuid.uuid4())
        execute(conn, '''INSERT INTO inventory_reservations (id, item_id, quantity, start_date, end_date, kind, production_id, note, status, created_by)
            VALUES (%s,%s,%s,%s,%s,'hwtc',%s,%s,'reserved',%s)''', (hid, d.get('item_id'), qty, start, end,
            d.get('production_id') or None, (d.get('note') or '').strip()[:300], session.get('name') or ''))
        _sync_package_parts(conn, hid)
        conn.commit()
        return jsonify({'ok': True})
    finally:
        conn.close()


@app.route('/api/inventory/reservations/<res_id>', methods=['PUT', 'DELETE'])
def inventory_reservation(res_id):
    """Check out, check in, change quantity, or release a reservation."""
    err = require_permission('rentals', 'edit')
    if err: return err
    conn = get_db()
    try:
        r = fetchone(conn, 'SELECT * FROM inventory_reservations WHERE id=%s', (res_id,))
        if not r:
            return jsonify({'error': 'Not found'}), 404
        if request.method == 'DELETE':
            execute(conn, "UPDATE inventory_reservations SET status='cancelled' WHERE id=%s OR parent_id=%s", (res_id, res_id))
            conn.commit()
            return jsonify({'ok': True})
        d = request.json or {}
        who = session.get('name') or 'Staff'
        act = d.get('action')
        if 'price' in d:
            # a negotiated price for this line (blank = back to the standard rate)
            try:
                pc = int(round(float(d['price']) * 100)) if str(d['price']).strip() != '' else None
            except Exception:
                return jsonify({'error': 'Enter a price like 75 or 75.50'}), 400
            execute(conn, 'UPDATE inventory_reservations SET price_cents=%s WHERE id=%s', (pc, res_id))
            conn.commit()
            return jsonify({'ok': True})
        if act == 'checkout':
            execute(conn, '''UPDATE inventory_reservations SET status='out', checked_out_at=NOW(), checked_out_by=%s,
                checkout_condition=%s WHERE id=%s OR parent_id=%s''', (who, (d.get('condition') or '').strip()[:500], res_id, res_id))
        elif act == 'checkin':
            qty = int(r.get('quantity') or 1)
            back = max(0, min(qty, int(d.get('returned_qty') if d.get('returned_qty') is not None else qty)))
            execute(conn, '''UPDATE inventory_reservations SET status='returned', returned_at=NOW(), returned_by=%s, returned_qty=%s,
                return_condition=%s, damage_note=%s WHERE id=%s''', (who, back, (d.get('condition') or 'good')[:40],
                (d.get('note') or '').strip()[:1000], res_id))
            if d.get('condition') == 'needs_repair':
                execute(conn, "UPDATE inventory_items SET status='repair', updated_at=NOW() WHERE id=%s", (r['item_id'],))
            if back < qty:
                # what didn't come back is no longer owned
                execute(conn, 'UPDATE inventory_items SET quantity=GREATEST(0, quantity-%s), updated_at=NOW() WHERE id=%s', (qty - back, r['item_id']))
            # a package's parts come back with it (record individual missing parts on the part itself)
            execute(conn, '''UPDATE inventory_reservations SET status='returned', returned_at=NOW(), returned_by=%s,
                returned_qty=COALESCE(returned_qty, quantity) WHERE parent_id=%s AND status <> 'returned' ''', (who, res_id))
        elif act == 'quantity':
            qty = max(1, int(d.get('quantity') or 1))
            left = inventory_available(conn, r['item_id'], r['start_date'], r['end_date'], exclude_res_id=res_id)
            if qty > left and not d.get('over_ok'):
                return jsonify({'error': f'Only {left} free for those dates. Use {qty} anyway?', 'over': True}), 409
            execute(conn, 'UPDATE inventory_reservations SET quantity=%s WHERE id=%s', (qty, res_id))
            _sync_package_parts(conn, res_id)
        conn.commit()
        return jsonify({'ok': True})
    finally:
        conn.close()


def _request_items(conn, rid):
    rows = fetchall(conn, '''SELECT r.*, i.name, i.category, i.kind, i.sizes, i.rate_cents, i.rate_unit, i.replacement_value_cents, i.pricing,
            i.photo_filename IS NOT NULL AND i.photo_filename <> '' AS has_photo, i.updated_at AS item_updated
        FROM inventory_reservations r JOIN inventory_items i ON i.id=r.item_id
        WHERE r.request_id=%s AND r.status NOT IN ('cancelled','archived_hold') AND r.parent_id IS NULL ORDER BY i.category, i.name''', (rid,)) or []
    for x in rows:
        units = _rate_units(x.get('rate_unit'), x['start_date'], x['end_date'])
        x['units'] = units
        x['standard_cents'] = int(x.get('rate_cents') or 0) * units * int(x.get('quantity') or 1)
        x['needs_price'] = x.get('price_cents') is None and (x.get('pricing') == 'quote' or not x.get('rate_cents'))
        x['line_cents'] = int(x['price_cents']) if x.get('price_cents') is not None else (0 if x['needs_price'] else x['standard_cents'])
        x['negotiated'] = x.get('price_cents') is not None
        if x.get('kind') == 'package':
            x['parts'] = fetchall(conn, '''SELECT i.name, r.quantity FROM inventory_reservations r JOIN inventory_items i ON i.id=r.item_id
                WHERE r.parent_id=%s ORDER BY i.name''', (x['id'],)) or []
            # replacement value of a package = its parts
            pv = (fetchone(conn, '''SELECT COALESCE(SUM(i.replacement_value_cents * pi.quantity),0) AS v FROM inventory_package_items pi
                JOIN inventory_items i ON i.id=pi.item_id WHERE pi.package_id=%s''', (x['item_id'],)) or {}).get('v') or 0
            x['replacement_value_cents'] = int(pv) or int(x.get('replacement_value_cents') or 0)
        x['photo_url'] = ('/api/inventory/' + x['item_id'] + '/photo') if x.get('has_photo') else ''
        for k in ('checked_out_at', 'returned_at', 'created_at', 'item_updated'):
            if x.get(k) is not None: x[k] = str(x[k])[:16]
    return rows


def _sync_package_parts(conn, res_id):
    """A reservation on a package also holds each of its parts (so they
    can't be rented separately at the same time). Parts follow the
    package's quantity, dates and status."""
    r = fetchone(conn, '''SELECT r.*, i.kind AS item_kind FROM inventory_reservations r JOIN inventory_items i ON i.id=r.item_id WHERE r.id=%s''', (res_id,))
    if not r or r.get('item_kind') != 'package':
        return
    execute(conn, 'DELETE FROM inventory_reservations WHERE parent_id=%s', (res_id,))
    if r['status'] == 'cancelled':
        return
    for p in fetchall(conn, 'SELECT item_id, quantity FROM inventory_package_items WHERE package_id=%s', (r['item_id'],)) or []:
        execute(conn, '''INSERT INTO inventory_reservations (id, item_id, quantity, start_date, end_date, kind, request_id, production_id,
                note, status, created_by, parent_id) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)''',
            (str(uuid.uuid4()), p['item_id'], int(p['quantity'] or 1) * int(r['quantity'] or 1), r['start_date'], r['end_date'], r.get('kind') or 'partner',
             r.get('request_id'), r.get('production_id'), 'Part of a package', r['status'], r.get('created_by'), res_id))


def _add_items_to_request(conn, rid, items, start, end, who, allow_over=False):
    """items: [{item_id, quantity, note}]. Returns (added, problems)."""
    added, problems = 0, []
    for it in items:
        try: qty = max(1, int(it.get('quantity') or 1))
        except Exception: qty = 1
        item = fetchone(conn, 'SELECT id, name FROM inventory_items WHERE id=%s', (it.get('item_id'),))
        if not item:
            continue
        left = inventory_available(conn, item['id'], start, end, exclude_request_id=rid)
        if qty > left and not allow_over:
            problems.append(f'{item["name"]}: only {left} free for those dates')
            continue
        ex = fetchone(conn, "SELECT id, quantity FROM inventory_reservations WHERE request_id=%s AND item_id=%s AND status <> 'cancelled' AND parent_id IS NULL", (rid, item['id']))
        if ex:
            res_id = ex['id']
            execute(conn, 'UPDATE inventory_reservations SET quantity=%s, start_date=%s, end_date=%s WHERE id=%s', (qty, start, end, res_id))
        else:
            res_id = str(uuid.uuid4())
            execute(conn, '''INSERT INTO inventory_reservations (id, item_id, quantity, start_date, end_date, kind, request_id, note, status, created_by)
                VALUES (%s,%s,%s,%s,%s,'partner',%s,%s,'reserved',%s)''', (res_id, item['id'], qty, start, end, rid,
                (it.get('note') or '').strip()[:300], who))
        _sync_package_parts(conn, res_id)
        added += 1
    return added, problems


@app.route('/api/rental/requests/<rid>/items', methods=['GET', 'POST'])
def rental_request_items(rid):
    err = require_permission('rentals', 'view' if request.method == 'GET' else 'edit')
    if err: return err
    conn = get_db()
    try:
        req = fetchone(conn, 'SELECT * FROM rental_requests WHERE id=%s', (rid,))
        if not req:
            return jsonify({'error': 'Request not found'}), 404
        if request.method == 'POST':
            d = request.json or {}
            added, problems = _add_items_to_request(conn, rid, d.get('items') or [], req['start_date'], req.get('end_date') or req['start_date'],
                                                    session.get('name') or 'Staff', bool(d.get('over_ok')))
            if problems and not d.get('over_ok') and not added:
                conn.rollback()
                return jsonify({'error': '; '.join(problems) + '. Add anyway?', 'over': True}), 409
            conn.commit()
        items = _request_items(conn, rid)
        total = sum(x['line_cents'] for x in items)
        repl = sum(int(x.get('replacement_value_cents') or 0) * int(x.get('quantity') or 1) for x in items)
        wishes = fetchall(conn, 'SELECT id, text, status FROM inventory_wishes WHERE request_id=%s ORDER BY created_at', (rid,)) or []
        return jsonify({'items': items, 'quote_cents': total, 'replacement_total_cents': repl, 'needs_price': sum(1 for x in items if x['needs_price']),
                        'wishes': wishes,
                        'pickup': req['start_date'], 'return': req.get('end_date') or req['start_date']})
    finally:
        conn.close()


@app.route('/api/rental/requests/<rid>/items/apply-quote', methods=['POST'])
def rental_request_apply_quote(rid):
    """Use the items' total as the partnership fee."""
    err = require_permission('rentals', 'edit')
    if err: return err
    conn = get_db()
    try:
        total = sum(x['line_cents'] for x in _request_items(conn, rid))
        execute(conn, "UPDATE rental_requests SET total_amount=%s, rate_amount=%s, rate_type='Rental', updated_at=NOW() WHERE id=%s", (total, total, rid))
        conn.commit()
        return jsonify({'ok': True, 'total_cents': total})
    finally:
        conn.close()


@app.route('/api/inventory/out', methods=['GET'])
def inventory_out_now():
    """Everything out or due back, for the Inventory tab's "Out now" list."""
    err = require_permission('rentals', 'view')
    if err: return err
    conn = get_db()
    try:
        rows = fetchall(conn, '''SELECT r.*, i.name, i.category, rr.title AS request_title, rp.name AS partner_name, p.name AS production_name
            FROM inventory_reservations r JOIN inventory_items i ON i.id=r.item_id
            LEFT JOIN rental_requests rr ON rr.id=r.request_id LEFT JOIN rental_partners rp ON rp.id=rr.partner_id
            LEFT JOIN productions p ON p.id=r.production_id
            WHERE r.status IN ('reserved','out') AND r.end_date >= %s
               OR (r.status='out')
            ORDER BY r.end_date''', ((today_eastern() - __import__('datetime').timedelta(days=60)).isoformat(),)) or []
        today = today_eastern().isoformat()
        for x in rows:
            x['late'] = x['status'] == 'out' and str(x['end_date'])[:10] < today
            for k in ('checked_out_at', 'returned_at', 'created_at'):
                if x.get(k) is not None: x[k] = str(x[k])[:16]
        return jsonify(rows)
    finally:
        conn.close()


# ── Partner portal: browse and request items ──
def public_inventory_catalog(conn, start, end):
    """What outside groups can see: packages, and items that can be rented
    on their own (parts that only go out with their package are hidden)."""
    rows = fetchall(conn, '''SELECT * FROM inventory_items WHERE partner_visible=TRUE AND status <> 'retired'
        AND (rentable_alone=TRUE OR kind='package') ORDER BY (kind='package') DESC, show_name, category, name''') or []
    out = []
    for r in rows:
        x = _inv_item_out(r, inventory_available(conn, r['id'], start, end or start) if start else None)
        for k in ('notes', 'location', 'replacement_value_cents', 'created_at', 'updated_at'):
            x.pop(k, None)
        if r.get('kind') == 'package':
            x['components'] = [{'name': c['name'], 'quantity': c['quantity']} for c in (fetchall(conn, '''SELECT i.name, pi.quantity
                FROM inventory_package_items pi JOIN inventory_items i ON i.id=pi.item_id WHERE pi.package_id=%s ORDER BY i.name''', (r['id'],)) or [])]
        out.append(x)
    return out


