    if err: return err
    conn = get_db()
    docs = fetchall(conn, '''SELECT id, doc_type, filename, uploaded_at, LENGTH(extracted_text) AS char_count
        FROM rental_compliance_docs ORDER BY uploaded_at DESC''') or []
