@app.route('/api/marquee/backfill-payment-amounts', methods=['POST'])
def backfill_payment_amounts():
    """One-time (or repeatable) catch-up for registrations confirmed before
    amount_paid_cents existed. Pulls each order's real total directly from
    Square and stores it, so revenue reporting reflects what was actually
    charged instead of falling back to the price × spots estimate. Batched —
    call it again if orders_remaining comes back > 0.

    Also backfills Step Up-paid registrations — those charges have no Square
    order attached at all (a direct saved-card charge, not a checkout), so
    they never went through the order-based capture above. No Square API
    call needed for those: the amount is already known precisely from the
    hold record itself."""
    err = require_permission('marquee')
    if err: return err
    conn = get_db()
    step_up_count_row = fetchone(conn, '''SELECT COUNT(*) as c FROM program_registrations pr
        JOIN step_up_child_holds h ON h.registration_id = pr.id
        WHERE h.hold_status = 'charged' AND pr.status = 'confirmed' AND pr.amount_paid_cents IS NULL''')
    step_up_updated = step_up_count_row['c'] if step_up_count_row else 0
    execute(conn, '''UPDATE program_registrations pr SET amount_paid_cents = h.amount
        FROM step_up_child_holds h
        WHERE h.registration_id = pr.id AND h.hold_status = 'charged'
        AND pr.status = 'confirmed' AND pr.amount_paid_cents IS NULL''')
    conn.commit()

    orders = fetchall(conn, '''SELECT DISTINCT COALESCE(square_order_id, square_checkout_id) as oid
        FROM program_registrations
        WHERE status='confirmed' AND amount_paid_cents IS NULL
        AND (square_order_id IS NOT NULL OR square_checkout_id IS NOT NULL)
        LIMIT 200''') or []
    updated = 0
    failed = 0
    for row in orders:
        oid = row.get('oid')
        if not oid:
            continue
        total_cents = square_get_order_total_cents(oid)
        if total_cents is not None:
            split_order_amount_across_registrations(conn, oid, total_cents)
            updated += 1
        else:
            failed += 1
    conn.commit()
    remaining_row = fetchone(conn, '''SELECT COUNT(DISTINCT COALESCE(square_order_id, square_checkout_id)) as c
        FROM program_registrations
        WHERE status='confirmed' AND amount_paid_cents IS NULL
        AND (square_order_id IS NOT NULL OR square_checkout_id IS NOT NULL)''')
    orders_remaining = remaining_row['c'] if remaining_row else 0
    conn.close()
    return jsonify({'ok': True, 'orders_updated': updated, 'orders_failed': failed,
        'orders_remaining': orders_remaining, 'step_up_updated': step_up_updated})


@app.route('/api/marquee/resplit-shared-orders', methods=['POST'])
def resplit_shared_orders():
    """One-time repair for registrations written before the proportional
    split existed: any order shared by more than one registration currently
    has the FULL order total duplicated on every row (the old behavior).
    That's only correct for same-program siblings, where per-program
    revenue queries used to deduplicate by order to compensate — but it
    silently misattributes revenue whenever one order spans two different
    programs (see split_order_amount_across_registrations for the full
    explanation). This re-derives each affected order's true total from
    whatever's currently stored (they should all currently match, under
    the old bug) and re-splits it proportionally, same as new payments now
    get from the start. Safe to run more than once — it's idempotent."""
    err = require_permission('marquee')
    if err: return err
    conn = get_db()
    orders = fetchall(conn, '''SELECT COALESCE(square_order_id, square_checkout_id) AS oid,
        COUNT(*) AS reg_count, MAX(amount_paid_cents) AS amt,
        COUNT(DISTINCT amount_paid_cents) AS distinct_amts
        FROM program_registrations
        WHERE status != 'cancelled' AND amount_paid_cents IS NOT NULL
        AND (square_order_id IS NOT NULL OR square_checkout_id IS NOT NULL)
        GROUP BY COALESCE(square_order_id, square_checkout_id)
        HAVING COUNT(*) > 1''') or []
    fixed = 0
    skipped = 0
    for row in orders:
        oid = row.get('oid')
        amt = row.get('amt')
        if not oid or amt is None:
            skipped += 1
            continue
        # If every row sharing this order already has a DIFFERENT amount,
        # it's already been split (either by this repair or the new write
        # path) — leave it alone rather than re-splitting an already-split
        # order using just one row's partial amount as if it were the total.
        if row.get('distinct_amts', 1) > 1:
            skipped += 1
            continue
        split_order_amount_across_registrations(conn, oid, amt)
        fixed += 1
    conn.commit()
    conn.close()
    return jsonify({'ok': True, 'orders_fixed': fixed, 'orders_skipped_already_split': skipped})

def program_instruction_cost(conn, program_id, start=None, end=None):
    """Planned instructor cost for a paid-instruction program, so Marquee can
    show what the program actually nets. Uses the same pay rules as the
    BloomBooks payroll report: 'per_class' pays the rate once per scheduled
    class; 'hourly' pays the rate x each class's scheduled length (the
    event's own times, else the program's meeting times). Scheduled classes
    are the program's non-cancelled events. With no rate or no classes on
    the calendar yet, falls back to the program's lump-sum
    instructor_expected_pay estimate. Returns None if not paid instruction.
    With start/end (dates, end exclusive), only classes dated in that window
    count, and the lump-sum estimate only counts if the program starts in it."""
    p = fetchone(conn, '''SELECT is_paid_instruction, pay_rate_type, pay_rate_amount, instructor_expected_pay,
        meeting_start_time, meeting_end_time FROM youth_programs WHERE id=%s''', (program_id,))
    if not p or not p.get('is_paid_instruction'):
        return None
    rate_type = p.get('pay_rate_type') or 'hourly'
    rate = float(p.get('pay_rate_amount') or 0)
    default_hours = _hours_between(p.get('meeting_start_time') or '', p.get('meeting_end_time') or '')
    events = fetchall(conn, """SELECT id, start_time, end_time, event_date FROM events
        WHERE program_id=%s AND COALESCE(status,'active') != 'cancelled'""", (program_id,)) or []
    if start and end:
        _s, _e = start.isoformat(), end.isoformat()
        events = [e for e in events if e.get('event_date') and _s <= str(e['event_date'])[:10] < _e]
    classes = len(events)
    hours = 0.0
    for e in events:
        h = _hours_between(e.get('start_time') or '', e.get('end_time') or '')
        hours += h if h > 0 else default_hours
    if rate > 0 and classes:
        cost = rate * classes if rate_type == 'per_class' else rate * hours
        basis = rate_type
    else:
        cost = float(p.get('instructor_expected_pay') or 0)
        basis = 'estimate' if cost > 0 else 'not_set'
        if start and end and cost:
            ps = fetchone(conn, 'SELECT start_date FROM youth_programs WHERE id=%s', (program_id,)) or {}
            sd = str(ps.get('start_date') or '')[:10]
            if not (sd and start.isoformat() <= sd < end.isoformat()):
                cost = 0.0
    paid_classes = 0
    if events:
        try:
            row = fetchone(conn, """SELECT COUNT(DISTINCT cpe.rolecall_event_id) AS c
                FROM bb_contractor_payment_events cpe
                JOIN bb_contractor_payments cp ON cp.id = cpe.payment_id
                WHERE cp.status != 'void' AND cpe.rolecall_event_id = ANY(%s)""", ([e['id'] for e in events],))
            paid_classes = int((row or {}).get('c') or 0)
        except Exception:
            try: conn.rollback()
            except Exception: pass
    return {
        'instruction_cost_cents': int(round(cost * 100)),
        'instruction_basis': basis,
        'instruction_rate': rate,
        'instruction_rate_type': rate_type,
        'instruction_classes': classes,
        'instruction_hours': round(hours, 2),
        'instruction_classes_paid': paid_classes,
    }


# ── Marquee dashboard summary: three revenue buckets + a period filter ────
# Buckets: Programs & Classes (youth_programs), Ticket Sales (audience
# tickets), Enrollment (Rising Stars / Teen Show fees). Donations are shown
# alongside but kept out of the bucket total.
#
# Periods count money by WHEN IT CAME IN (registration paid_at, Step Up
# charged_at, ticket completed_at, donation_date), so they line up with
# deposits. "active" instead shows everything for what's currently
# enrolling/running/upcoming, whenever it was paid.
MARQUEE_PERIODS = ('active', 'month', 'last_month', 'quarter', 'year', 'last_year', 'custom')


def _marquee_period_bounds(period, start_s='', end_s=''):
    import datetime as _d
    t = today_eastern()
    def first_of_month(y, m): return _d.date(y, m, 1)
    def add_months(dt, n):
        m = dt.month - 1 + n
        return _d.date(dt.year + m // 12, m % 12 + 1, 1)
    if period == 'month':
        s = first_of_month(t.year, t.month); return s, add_months(s, 1)
    if period == 'last_month':
        e = first_of_month(t.year, t.month); return add_months(e, -1), e
    if period == 'quarter':
        s = first_of_month(t.year, 3 * ((t.month - 1) // 3) + 1); return s, add_months(s, 3)
    if period == 'year':
        return _d.date(t.year, 1, 1), _d.date(t.year + 1, 1, 1)
    if period == 'last_year':
        return _d.date(t.year - 1, 1, 1), _d.date(t.year, 1, 1)
    if period == 'custom':
        try:
            s = _d.date.fromisoformat(start_s[:10]); e = _d.date.fromisoformat(end_s[:10]) + _d.timedelta(days=1)
            if e > s:
                return s, e
        except Exception:
            pass
    return None, None


def _eastern_date(ts):
    """DB timestamps are naive UTC (NOW()); convert to an Eastern date."""
    if not ts:
        return None
    import datetime as _d
    from zoneinfo import ZoneInfo
    if isinstance(ts, str):
        if len(ts.strip()) == 10:   # plain date, no time to convert
            try: return _d.date.fromisoformat(ts.strip())
            except Exception: return None
        try:
            ts = _d.datetime.fromisoformat(ts.replace('Z', '+00:00'))
        except Exception:
            try: return _d.date.fromisoformat(ts[:10])
            except Exception: return None
    if isinstance(ts, _d.datetime):
        if ts.tzinfo is None:
            ts = ts.replace(tzinfo=_d.timezone.utc)
        return ts.astimezone(ZoneInfo('America/New_York')).date()
    return ts


def _date_str(d):
    return str(d)[:10] if d else ''


@app.route('/api/marquee/summary', methods=['GET'])
def marquee_summary():
    err = require_permission('marquee', 'view')
    if err: return err
    period = request.args.get('period') or 'active'
    if period not in MARQUEE_PERIODS:
        period = 'active'
    start, end = _marquee_period_bounds(period, request.args.get('start') or '', request.args.get('end') or '')
    if period != 'active' and not start:
        period = 'active'
    today = today_eastern()
    today_s = today.isoformat()
    in_window = (lambda d: d is not None and start <= d < end) if start else (lambda d: True)

    conn = get_db()
    try:
        progs = fetchall(conn, '''SELECT id, name, status, registration_status, start_date, end_date, capacity,
            is_paid_instruction, sessions_enabled, price FROM youth_programs
            WHERE COALESCE(registration_status,'draft') != 'draft' ''') or []
        prods = fetchall(conn, """SELECT id, name, stage, status, registration_status, start_date, end_date, capacity, price
            FROM productions WHERE stage IN ('rising_stars','teen_show')
            AND COALESCE(registration_status,'draft') != 'draft'""") or []
        regs = fetchall(conn, '''SELECT pr.id, pr.program_id, pr.production_id, pr.status, pr.is_comped,
                pr.amount_paid_cents, pr.refund_amount_cents, pr.participant_count, pr.discount_amount,
                pr.sibling_discount_amount, COALESCE(pr.paid_at, pr.created_at) AS paid_at,
                COALESCE(yp.price, prod.price, 0) AS program_price,
                su.hold_status AS step_up_hold_status, su.amount AS step_up_amount,
                COALESCE(su.charged_at, su.updated_at) AS step_up_charged_at
            FROM program_registrations pr
            LEFT JOIN youth_programs yp ON yp.id = pr.program_id
            LEFT JOIN productions prod ON prod.id = pr.production_id
            LEFT JOIN step_up_child_holds su ON su.registration_id = pr.id
            WHERE pr.status IN ('confirmed','waitlisted','pending_payment')''') or []

        def is_active(row):
            if (row.get('status') or '') in ('completed', 'archived', 'cancelled'):
                return False
            if (row.get('registration_status') or '') == 'cancelled':
                return False
            if (row.get('registration_status') or '') == 'open':
                return True
            ed = _date_str(row.get('end_date'))
            return (not ed) or ed >= today_s

        def blank(row, kind):
            return {'id': row['id'], 'name': row['name'], 'kind': kind,
                    'registration_status': row.get('registration_status'), 'status': row.get('status'),
                    'start_date': _date_str(row.get('start_date')), 'end_date': _date_str(row.get('end_date')),
                    'capacity': row.get('capacity'), 'active': is_active(row),
                    'enrolled': 0, 'waitlisted': 0, 'pending_payment': 0, 'comped': 0,
                    'gross_cents': 0, 'pending_step_up_cents': 0, 'waitlist_value_cents': 0}

        prog_rows = {p['id']: dict(blank(p, 'program'), paid_instruction=bool(p.get('is_paid_instruction'))) for p in progs}
        prod_rows = {p['id']: dict(blank(p, 'enrollment'), stage=p.get('stage')) for p in prods}

        for r in regs:
            row = prog_rows.get(r.get('program_id')) or prod_rows.get(r.get('production_id'))
            if not row:
                continue
            st = r['status']
            if st == 'waitlisted':
                row['waitlisted'] += 1
                if not r.get('is_comped'):
                    row['waitlist_value_cents'] += max(0, (r.get('program_price') or 0) * (r.get('participant_count') or 1)
                        - (r.get('discount_amount') or 0) - (r.get('sibling_discount_amount') or 0))
                continue
            if st == 'pending_payment':
                row['pending_payment'] += 1
                continue
            row['enrolled'] += 1
            if r.get('is_comped'):
                row['comped'] += 1
            amount, source = compute_registration_amount(r)
            if source == 'step_up_pending':
                row['pending_step_up_cents'] += int(r.get('step_up_amount') or 0)
                continue
            when = _eastern_date(r.get('step_up_charged_at') if source == 'step_up' else r.get('paid_at'))
            if start:
                if in_window(when):
                    row['gross_cents'] += int(amount or 0)
            else:
                row['gross_cents'] += int(amount or 0)

        # which rows belong in this view
        def keep(row):
            if start:
                return row['gross_cents'] != 0 or row.get('instructor_cost_cents', 0) != 0
            return row['active']

        # instructor pay for paid-instruction programs
        for row in prog_rows.values():
            row['instructor_cost_cents'] = 0
            if not row['paid_instruction']:
                continue
            if not start and not row['active']:
                continue
            try:
                ic = program_instruction_cost(conn, row['id'], start, end)
            except Exception as e:
                app.logger.warning(f'Instruction cost failed for {row["name"]}: {e}')
                try: conn.rollback()
                except Exception: pass
                ic = None
            if ic:
                row.update(ic)
                row['instructor_cost_cents'] = ic['instruction_cost_cents']
        for row in prog_rows.values():
            row['net_cents'] = row['gross_cents'] - row['instructor_cost_cents']

        programs = sorted([r for r in prog_rows.values() if keep(r)], key=lambda r: (-r['gross_cents'], r['name']))
        enrollment = sorted([r for r in prod_rows.values() if keep(r)], key=lambda r: (-r['gross_cents'], r['name']))

        # ── ticket sales ──
        torders = fetchall(conn, '''SELECT o.id, o.total_cents, o.service_fee_cents, o.seats_json,
                COALESCE(o.completed_at, o.created_at) AS paid_at,
                pf.id AS performance_id, pf.performance_date, pf.performance_time, pf.production_id,
                p.name AS production_name
            FROM ticket_orders o JOIN performances pf ON pf.id = o.performance_id
            JOIN productions p ON p.id = pf.production_id
            WHERE o.status = 'completed' ''') or []
        perfs = fetchall(conn, '''SELECT pf.id, pf.production_id, pf.performance_date, pf.performance_time, pf.status,
                p.name AS production_name FROM performances pf JOIN productions p ON p.id=pf.production_id
            WHERE COALESCE(pf.status,'draft') != 'draft' ''') or []
        shows = {}
        def show_for(pid, name):
            if pid not in shows:
                shows[pid] = {'id': pid, 'name': name, 'gross_cents': 0, 'fee_cents': 0, 'tickets': 0,
                              'orders': 0, 'performances': {}, 'upcoming_performances': 0}
            return shows[pid]
        def perf_for(sh, pf):
            if pf['id'] not in sh['performances']:
                sh['performances'][pf['id']] = {'id': pf['id'], 'date': _date_str(pf.get('performance_date')),
                    'time': pf.get('performance_time') or '', 'tickets': 0, 'gross_cents': 0}
            return sh['performances'][pf['id']]
        for pf in perfs:
            upcoming = _date_str(pf.get('performance_date')) >= today_s
            if not start and upcoming:
                sh = show_for(pf['production_id'], pf['production_name'])
                sh['upcoming_performances'] += 1
                perf_for(sh, pf)
        for o in torders:
            pdate = _date_str(o.get('performance_date'))
            if start:
                if not in_window(_eastern_date(o.get('paid_at'))):
                    continue
            elif pdate < today_s:
                continue
            sh = show_for(o['production_id'], o['production_name'])
            n = _order_ticket_count(o)
            sh['gross_cents'] += int(o.get('total_cents') or 0)
            sh['fee_cents'] += int(o.get('service_fee_cents') or 0)
            sh['tickets'] += n
            sh['orders'] += 1
            pr = perf_for(sh, {'id': o['performance_id'], 'performance_date': o.get('performance_date'),
                               'performance_time': o.get('performance_time')})
            pr['tickets'] += n
            pr['gross_cents'] += int(o.get('total_cents') or 0)
        # donations added at ticket checkout, credited to the show(s) bought
        _dtot, don_by_show, _dc = ticket_checkout_donations(conn, start, end,
                                                            None if start else set(shows.keys()))
        for pid, cents in don_by_show.items():
            if pid in shows or start:
                if pid not in shows:
                    nm = fetchone(conn, 'SELECT name FROM productions WHERE id=%s', (pid,)) or {}
                    show_for(pid, nm.get('name') or 'Show')
                shows[pid]['donation_cents'] = shows[pid].get('donation_cents', 0) + cents
        ticket_shows = []
        for sh in shows.values():
            sh.setdefault('donation_cents', 0)
            sh['performances'] = sorted(sh['performances'].values(), key=lambda x: (x['date'], x['time']))
            ticket_shows.append(sh)
        ticket_shows.sort(key=lambda x: (-x['gross_cents'], x['name']))

        # ── donations (not part of the bucket total) ──
        if start:
            don = fetchone(conn, '''SELECT COALESCE(SUM(amount),0) AS t, COUNT(*) AS c FROM donor_donations
                WHERE donation_date >= %s AND donation_date < %s''', (start.isoformat(), end.isoformat())) or {}
            donations_label = 'in this period'
        else:
            don = fetchone(conn, '''SELECT COALESCE(SUM(amount),0) AS t, COUNT(*) AS c FROM donor_donations
                WHERE donation_date >= %s''', (today.replace(month=1, day=1).isoformat(),)) or {}
            donations_label = 'this year'
    finally:
        conn.close()

    def total(rows, key): return sum(int(r.get(key) or 0) for r in rows)
    instructed = [r for r in programs if r['paid_instruction']]
    uninstructed = [r for r in programs if not r['paid_instruction']]
    buckets = {
        'programs': {
            'gross_cents': total(programs, 'gross_cents'),
            'instructor_cost_cents': total(programs, 'instructor_cost_cents'),
            'net_cents': total(programs, 'net_cents'),
            'pending_step_up_cents': total(programs, 'pending_step_up_cents'),
            'waitlist_value_cents': total(programs, 'waitlist_value_cents'),
            'enrolled': total(programs, 'enrolled'), 'count': len(programs),
            'instructed': {'count': len(instructed), 'gross_cents': total(instructed, 'gross_cents'),
                           'instructor_cost_cents': total(instructed, 'instructor_cost_cents'),
                           'net_cents': total(instructed, 'net_cents')},
            'not_instructed': {'count': len(uninstructed), 'gross_cents': total(uninstructed, 'gross_cents')},
        },
        'tickets': {
            'gross_cents': total(ticket_shows, 'gross_cents'), 'fee_cents': total(ticket_shows, 'fee_cents'),
            'donation_cents': total(ticket_shows, 'donation_cents'),
            'tickets': total(ticket_shows, 'tickets'), 'orders': total(ticket_shows, 'orders'),
            'count': len(ticket_shows),
        },
        'enrollment': {
            'gross_cents': total(enrollment, 'gross_cents'),
            'pending_step_up_cents': total(enrollment, 'pending_step_up_cents'),
            'waitlist_value_cents': total(enrollment, 'waitlist_value_cents'),
            'enrolled': total(enrollment, 'enrolled'), 'count': len(enrollment),
        },
    }
    gross_all = (buckets['programs']['gross_cents'] + buckets['tickets']['gross_cents']
                 + buckets['tickets']['donation_cents'] + buckets['enrollment']['gross_cents'])
    return jsonify({
        'period': period,
        'start': start.isoformat() if start else None,
        'end_inclusive': (end - __import__('datetime').timedelta(days=1)).isoformat() if end else None,
        'buckets': buckets,
        'total': {'gross_cents': gross_all,
                  'instructor_cost_cents': buckets['programs']['instructor_cost_cents'],
                  'net_cents': gross_all - buckets['programs']['instructor_cost_cents']},
        'donations': {'amount': float(don.get('t') or 0), 'count': int(don.get('c') or 0), 'label': donations_label},
        'programs': programs,
        'ticket_shows': ticket_shows,
        'enrollment': enrollment,
    })


@app.route('/api/marquee/overview', methods=['GET'])
def marquee_overview():
    err = require_permission('marquee', 'view')
    if err: return err
    conn = get_db()
    # Registration counts across programs and productions
    reg_counts = fetchone(conn, '''SELECT
        COUNT(*) FILTER (WHERE status='confirmed') AS confirmed,
        COUNT(*) FILTER (WHERE status='pending_payment') AS pending,
        COUNT(*) FILTER (WHERE status='waitlisted') AS waitlisted,
        COUNT(*) AS total
        FROM program_registrations WHERE status != 'cancelled' ''')
    # Revenue: cart orders are the payment mechanism, not additional revenue —
    # counting both would double-count. Includes both program registrations and
    # production (e.g. Rising Stars) registrations, since both live in the same
    # program_registrations table.
    #
    # Split into two figures, since they mean different things:
    #  - confirmed_revenue: money we actually have. Prefers the real Square-
    #    confirmed amount (amount_paid_cents) over recomputing price × count —
    #    the two can drift apart (promo codes, price changes after the fact).
    #    A Step Up hold only counts here once it's actually been charged
    #    (hold_status='charged') — a pending hold is a promise, not money in
    #    hand yet. Comp'd enrollments are $0 by design, not an unpaid gap.
    #    Any amount refunded (pr.refund_amount_cents) is subtracted back out
    #    regardless of how the registration was priced, since a refund can
    #    happen without unenrolling (status stays 'confirmed').
    #  - expected_revenue: confirmed_revenue plus what's still outstanding —
    #    pending (uncharged) Step Up holds, and waitlisted registrations that
    #    could still convert. This is the optimistic "if everything comes
    #    through" number, not what's actually collected.
    # Each registration now carries its own correctly-split share of
    # whatever order it belongs to (see split_order_amount_across_
    # registrations) rather than the full order total duplicated across
    # every row sharing it, so this sums each registration's own amount
    # directly — no order-based dedup needed or wanted here anymore.
    revenue_row = fetchone(conn, '''WITH reg_revenue AS (
        SELECT
            pr.status,
            CASE WHEN pr.is_comped THEN 0
                WHEN su.hold_status = 'charged' THEN su.amount
                WHEN su.hold_status = 'pending' THEN 0
                ELSE COALESCE(pr.amount_paid_cents,
                    COALESCE(yp.price, prod.price, 0) * COALESCE(pr.participant_count,1)
                    - COALESCE(pr.discount_amount,0) - COALESCE(pr.sibling_discount_amount,0))
            END - COALESCE(pr.refund_amount_cents,0) AS confirmed_amount,
            CASE WHEN NOT pr.is_comped AND su.hold_status = 'pending' THEN su.amount ELSE 0 END AS pending_step_up_amount
        FROM program_registrations pr
        LEFT JOIN youth_programs yp ON yp.id=pr.program_id
        LEFT JOIN productions prod ON prod.id=pr.production_id
        LEFT JOIN step_up_child_holds su ON su.registration_id = pr.id
        WHERE pr.status IN (\'confirmed\', \'waitlisted\')
    ),
    waitlist_estimate AS (
        SELECT pr.id,
            CASE WHEN pr.is_comped THEN 0 ELSE
                COALESCE(yp.price, prod.price, 0) * COALESCE(pr.participant_count,1)
                - COALESCE(pr.discount_amount,0) - COALESCE(pr.sibling_discount_amount,0)
            END AS amount
        FROM program_registrations pr
        LEFT JOIN youth_programs yp ON yp.id=pr.program_id
        LEFT JOIN productions prod ON prod.id=pr.production_id
        WHERE pr.status = \'waitlisted\'
    )
    SELECT
        COALESCE(SUM(confirmed_amount) FILTER (WHERE status=\'confirmed\'), 0) AS confirmed_total,
        COALESCE(SUM(pending_step_up_amount) FILTER (WHERE status=\'confirmed\'), 0) AS pending_step_up_total,
        (SELECT COALESCE(SUM(amount), 0) FROM waitlist_estimate) AS waitlist_total
    FROM reg_revenue''') or {}
    confirmed_revenue = int((revenue_row or {}).get('confirmed_total', 0))
    pending_step_up_total = int((revenue_row or {}).get('pending_step_up_total', 0))
    waitlist_total = int((revenue_row or {}).get('waitlist_total', 0))
    expected_revenue = confirmed_revenue + pending_step_up_total + waitlist_total
    # total_revenue kept for anything still reading the old field name —
    # it's the confirmed figure, which is what should be treated as
    # authoritative (e.g. if this number is ever referenced in BloomBooks).
    total_revenue = confirmed_revenue
    # Donations this year
    import datetime as _dt
    year = _dt.date.today().year
    donations_ytd = fetchone(conn, f"SELECT COALESCE(SUM(amount),0) AS total FROM donor_donations WHERE donation_date >= '{year}-01-01' AND type='square'")
    # Recent orders: cart orders + direct registrations (excluding those paid via cart)
    try:
        cart_orders = fetchall(conn, '''
            SELECT id, guardian_name, guardian_email, total_cents, status, created_at,
                COALESCE((SELECT COUNT(*) FROM json_array_elements(items_json::json)), 1) AS item_count,
                'cart' AS order_type, NULL AS program_name
            FROM cart_orders
            UNION ALL
            SELECT pr.id, pr.guardian_name, pr.guardian_email,
                (COALESCE(yp.price,0)*COALESCE(pr.participant_count,1)
                 - COALESCE(pr.discount_amount,0) - COALESCE(pr.sibling_discount_amount,0)) AS total_cents,
                pr.status, pr.created_at,
                1 AS item_count, 'direct' AS order_type, yp.name AS program_name
            FROM program_registrations pr
            JOIN youth_programs yp ON yp.id=pr.program_id
            WHERE pr.status != 'cancelled'
            AND pr.square_order_id NOT IN (SELECT square_order_id FROM cart_orders WHERE square_order_id IS NOT NULL)
            AND (pr.square_checkout_id IS NULL OR pr.square_checkout_id NOT IN (SELECT square_order_id FROM cart_orders WHERE square_order_id IS NOT NULL))
            UNION ALL
            SELECT pr.id, pr.guardian_name, pr.guardian_email,
                (COALESCE(prod.price,0)*COALESCE(pr.participant_count,1)
                 - COALESCE(pr.discount_amount,0) - COALESCE(pr.sibling_discount_amount,0)) AS total_cents,
                pr.status, pr.created_at,
                1 AS item_count, 'direct' AS order_type, prod.name AS program_name
            FROM program_registrations pr
            JOIN productions prod ON prod.id=pr.production_id
            WHERE pr.status != 'cancelled'
            AND pr.square_order_id NOT IN (SELECT square_order_id FROM cart_orders WHERE square_order_id IS NOT NULL)
            AND (pr.square_checkout_id IS NULL OR pr.square_checkout_id NOT IN (SELECT square_order_id FROM cart_orders WHERE square_order_id IS NOT NULL))
            ORDER BY created_at DESC LIMIT 10''') or []
    except Exception as e:
        app.logger.warning(f'Recent orders union query failed: {e}')
        # Fallback to cart orders only
        try:
            cart_orders = fetchall(conn, 'SELECT id, guardian_name, guardian_email, total_cents, status, created_at, 1 AS item_count, \'cart\' AS order_type, NULL AS program_name FROM cart_orders ORDER BY created_at DESC LIMIT 10') or []
        except Exception:
            cart_orders = []
    # Open products in catalog
    open_programs = (fetchone(conn, "SELECT COUNT(*) AS c FROM youth_programs WHERE registration_status='open'") or {}).get('c', 0)
    open_productions = (fetchone(conn, "SELECT COUNT(*) AS c FROM productions WHERE registration_status='open'") or {}).get('c', 0)
    # Recent donations
    recent_donations = fetchall(conn, '''SELECT pd.name, pd.email, pd.amount_cents, pd.created_at
        FROM pending_donations pd WHERE pd.status='completed'
        ORDER BY pd.created_at DESC LIMIT 5''') or []
    # Program breakdown with session stats. Splits revenue into confirmed
    # (money we actually have) vs expected (confirmed + pending Step Up +
    # waitlist) — see the overview total above for the full reasoning.
    # Comp'd enrollments are $0 by design, not an unpaid gap, and a pending
    # (uncharged) Step Up hold isn't money in hand yet even though the
    # registration itself shows as confirmed.
    program_breakdown = fetchall(conn, '''WITH dedup_regs AS (
        SELECT
            pr.id, pr.program_id, pr.status,
            CASE WHEN pr.is_comped THEN 0
                WHEN su.hold_status = 'charged' THEN su.amount
                WHEN su.hold_status = 'pending' THEN 0
                ELSE COALESCE(pr.amount_paid_cents,
                    COALESCE(yp.price,0) * COALESCE(pr.participant_count,1)
                    - COALESCE(pr.discount_amount,0) - COALESCE(pr.sibling_discount_amount,0))
            END - COALESCE(pr.refund_amount_cents,0) AS confirmed_amount,
            CASE WHEN NOT pr.is_comped AND su.hold_status = 'pending' THEN su.amount ELSE 0 END AS pending_step_up_amount,
            CASE WHEN pr.is_comped THEN 'comped'
                WHEN su.hold_status = 'charged' THEN 'step_up'
                WHEN su.hold_status = 'pending' THEN 'step_up_pending'
                WHEN pr.amount_paid_cents IS NOT NULL THEN 'square'
                ELSE 'estimate'
            END AS amount_source
        FROM program_registrations pr
        JOIN youth_programs yp ON yp.id = pr.program_id
        LEFT JOIN step_up_child_holds su ON su.registration_id = pr.id
        WHERE pr.status != \'cancelled\'
    ),
    waitlist_amt AS (
        SELECT pr.id, pr.program_id,
            CASE WHEN pr.is_comped THEN 0 ELSE
                COALESCE(yp.price,0) * COALESCE(pr.participant_count,1)
                - COALESCE(pr.discount_amount,0) - COALESCE(pr.sibling_discount_amount,0)
            END AS amount
        FROM program_registrations pr JOIN youth_programs yp ON yp.id=pr.program_id
        WHERE pr.status = \'waitlisted\'
    )
    SELECT
        yp.id, yp.name, yp.price, yp.capacity, yp.registration_status,
        yp.sessions_enabled,
        COUNT(pr.id) FILTER (WHERE pr.status=\'confirmed\') AS confirmed_count,
        COUNT(pr.id) FILTER (WHERE pr.status=\'pending_payment\') AS pending_count,
        COUNT(pr.id) FILTER (WHERE pr.status=\'waitlisted\') AS waitlisted_count,
        COUNT(pr.id) FILTER (WHERE pr.status=\'confirmed\' AND pr.is_comped) AS comped_count,
        COALESCE((SELECT SUM(dr.confirmed_amount) FROM dedup_regs dr
            WHERE dr.program_id=yp.id AND dr.status=\'confirmed\'), 0) AS confirmed_revenue_cents,
        COALESCE((SELECT SUM(dr.confirmed_amount) FROM dedup_regs dr
            WHERE dr.program_id=yp.id AND dr.status=\'confirmed\'), 0)
          + COALESCE((SELECT SUM(dr.pending_step_up_amount) FROM dedup_regs dr
              WHERE dr.program_id=yp.id AND dr.status=\'confirmed\'), 0)
          + COALESCE((SELECT SUM(w.amount) FROM waitlist_amt w WHERE w.program_id=yp.id), 0) AS expected_revenue_cents,
        COALESCE((SELECT SUM(dr.confirmed_amount) FROM dedup_regs dr
            WHERE dr.program_id=yp.id AND dr.status=\'confirmed\' AND dr.amount_source=\'square\'), 0) AS square_revenue_cents,
        COALESCE((SELECT SUM(dr.confirmed_amount) FROM dedup_regs dr
            WHERE dr.program_id=yp.id AND dr.status=\'confirmed\' AND dr.amount_source=\'step_up\'), 0) AS step_up_revenue_cents,
        COALESCE((SELECT SUM(dr.pending_step_up_amount) FROM dedup_regs dr
            WHERE dr.program_id=yp.id AND dr.status=\'confirmed\'), 0) AS step_up_pending_cents,
        COALESCE((SELECT SUM(dr.confirmed_amount) FROM dedup_regs dr
            WHERE dr.program_id=yp.id AND dr.status=\'confirmed\' AND dr.amount_source=\'estimate\'), 0) AS estimate_revenue_cents,
        COALESCE((SELECT SUM(w.amount) FROM waitlist_amt w WHERE w.program_id=yp.id), 0) AS waitlist_revenue_cents
    FROM youth_programs yp
    LEFT JOIN program_registrations pr ON pr.program_id=yp.id AND pr.status != \'cancelled\'
    WHERE yp.registration_status != \'draft\'
    GROUP BY yp.id, yp.name, yp.price, yp.capacity, yp.registration_status, yp.sessions_enabled
    ORDER BY confirmed_count DESC, yp.name''') or []
    for row in program_breakdown:
        row['type'] = 'program'
        row['revenue_cents'] = row['confirmed_revenue_cents']  # kept for anything still reading the old field name
        # Paid instruction: subtract the planned instructor cost so the
        # program's figure reflects what HWTC actually keeps.
        try:
            ic = program_instruction_cost(conn, row['id'])
        except Exception as e:
            app.logger.warning(f'Instruction cost failed for {row.get("name")}: {e}')
            try: conn.rollback()
            except Exception: pass
            ic = None
        row['paid_instruction'] = bool(ic)
        if ic:
            row.update(ic)
            row['net_confirmed_cents'] = int(row['confirmed_revenue_cents'] or 0) - ic['instruction_cost_cents']
            row['net_expected_cents'] = int(row['expected_revenue_cents'] or 0) - ic['instruction_cost_cents']

    # Rising Stars production breakdown — same shape as program_breakdown so the
    # dashboard can render both in one list. Only Rising Stars productions carry
    # paid registrations; regular mainstage productions use cast sign-up, not this.
    production_breakdown = fetchall(conn, '''WITH dedup_regs AS (
        SELECT
            pr.id, pr.production_id, pr.status,
            CASE WHEN pr.is_comped THEN 0
                WHEN su.hold_status = 'charged' THEN su.amount
                WHEN su.hold_status = 'pending' THEN 0
                ELSE COALESCE(pr.amount_paid_cents,
                    COALESCE(prod.price,0) * COALESCE(pr.participant_count,1)
                    - COALESCE(pr.discount_amount,0) - COALESCE(pr.sibling_discount_amount,0))
            END - COALESCE(pr.refund_amount_cents,0) AS confirmed_amount,
            CASE WHEN NOT pr.is_comped AND su.hold_status = 'pending' THEN su.amount ELSE 0 END AS pending_step_up_amount,
            CASE WHEN pr.is_comped THEN 'comped'
                WHEN su.hold_status = 'charged' THEN 'step_up'
                WHEN su.hold_status = 'pending' THEN 'step_up_pending'
                WHEN pr.amount_paid_cents IS NOT NULL THEN 'square'
                ELSE 'estimate'
            END AS amount_source
        FROM program_registrations pr
        JOIN productions prod ON prod.id = pr.production_id
        LEFT JOIN step_up_child_holds su ON su.registration_id = pr.id
        WHERE pr.status != \'cancelled\'
    ),
    waitlist_amt AS (
        SELECT pr.id, pr.production_id,
            CASE WHEN pr.is_comped THEN 0 ELSE
                COALESCE(prod.price,0) * COALESCE(pr.participant_count,1)
                - COALESCE(pr.discount_amount,0) - COALESCE(pr.sibling_discount_amount,0)
            END AS amount
        FROM program_registrations pr JOIN productions prod ON prod.id=pr.production_id
        WHERE pr.status = \'waitlisted\'
    )
    SELECT
        prod.id, prod.name, prod.price, prod.capacity, prod.registration_status,
        FALSE AS sessions_enabled,
        COUNT(pr.id) FILTER (WHERE pr.status=\'confirmed\') AS confirmed_count,
        COUNT(pr.id) FILTER (WHERE pr.status=\'pending_payment\') AS pending_count,
        COUNT(pr.id) FILTER (WHERE pr.status=\'waitlisted\') AS waitlisted_count,
        COUNT(pr.id) FILTER (WHERE pr.status=\'confirmed\' AND pr.is_comped) AS comped_count,
        COALESCE((SELECT SUM(dr.confirmed_amount) FROM dedup_regs dr
            WHERE dr.production_id=prod.id AND dr.status=\'confirmed\'), 0) AS confirmed_revenue_cents,
        COALESCE((SELECT SUM(dr.confirmed_amount) FROM dedup_regs dr
            WHERE dr.production_id=prod.id AND dr.status=\'confirmed\'), 0)
          + COALESCE((SELECT SUM(dr.pending_step_up_amount) FROM dedup_regs dr
              WHERE dr.production_id=prod.id AND dr.status=\'confirmed\'), 0)
          + COALESCE((SELECT SUM(w.amount) FROM waitlist_amt w WHERE w.production_id=prod.id), 0) AS expected_revenue_cents,
        COALESCE((SELECT SUM(dr.confirmed_amount) FROM dedup_regs dr
            WHERE dr.production_id=prod.id AND dr.status=\'confirmed\' AND dr.amount_source=\'square\'), 0) AS square_revenue_cents,
        COALESCE((SELECT SUM(dr.confirmed_amount) FROM dedup_regs dr
            WHERE dr.production_id=prod.id AND dr.status=\'confirmed\' AND dr.amount_source=\'step_up\'), 0) AS step_up_revenue_cents,
        COALESCE((SELECT SUM(dr.pending_step_up_amount) FROM dedup_regs dr
            WHERE dr.production_id=prod.id AND dr.status=\'confirmed\'), 0) AS step_up_pending_cents,
        COALESCE((SELECT SUM(dr.confirmed_amount) FROM dedup_regs dr
            WHERE dr.production_id=prod.id AND dr.status=\'confirmed\' AND dr.amount_source=\'estimate\'), 0) AS estimate_revenue_cents,
        COALESCE((SELECT SUM(w.amount) FROM waitlist_amt w WHERE w.production_id=prod.id), 0) AS waitlist_revenue_cents
    FROM productions prod
    LEFT JOIN program_registrations pr ON pr.production_id=prod.id AND pr.status != \'cancelled\'
    WHERE prod.registration_status != \'draft\' AND prod.stage IN (\'rising_stars\',\'teen_show\')
    GROUP BY prod.id, prod.name, prod.price, prod.capacity, prod.registration_status
    ORDER BY confirmed_count DESC, prod.name''') or []
    for row in production_breakdown:
        row['type'] = 'production'
        row['revenue_cents'] = row['confirmed_revenue_cents']

    program_breakdown = program_breakdown + production_breakdown

    # Session breakdown for programs with sessions. Headcount/capacity/fill
    # per session still comes from the SQL join below (that part was never
    # wrong — someone registered for 4 sessions genuinely shows up in all 4).
    # Revenue is different: if a family paid one bundle price for multiple
    # sessions, attributing that full price to *each* session they're in
    # would badly over-count the program's real total (this was the actual
    # bug — a $70 bundle covering 4 sessions was showing as $100 × 4 = $400).
    # Fixed below by computing each registration's real confirmed amount
    # once, then dividing it evenly across however many sessions it covers.
    try:
        session_breakdown = fetchall(conn, '''SELECT
            ps.id, ps.program_id, ps.name, ps.capacity, ps.price_override, ps.start_date, ps.start_time, ps.end_time,
            yp.name AS program_name, yp.price AS program_price,
            COUNT(pr.id) FILTER (WHERE pr.status=\'confirmed\') AS confirmed_count,
            COUNT(pr.id) FILTER (WHERE pr.status=\'pending_payment\') AS pending_count,
            COUNT(pr.id) FILTER (WHERE pr.status=\'waitlisted\') AS waitlisted_count
            FROM program_sessions ps
            JOIN youth_programs yp ON yp.id=ps.program_id
            LEFT JOIN program_registrations pr ON pr.program_id=ps.program_id
                AND pr.session_ids IS NOT NULL
                AND pr.session_ids != \'[]\'
                AND pr.session_ids LIKE ('%%"' || ps.id || '"%%')
                AND pr.status != \'cancelled\'
            WHERE yp.registration_status != \'draft\'
            GROUP BY ps.id, ps.program_id, ps.name, ps.capacity, ps.price_override,
                     ps.start_date, ps.start_time, ps.end_time, ps.sort_order, yp.name, yp.price
            ORDER BY ps.program_id, ps.sort_order, ps.start_date, ps.start_time''') or []
        for s in session_breakdown:
            s['revenue_cents'] = 0  # filled in below, per-registration, fairly divided

        import json as _json_srb
        try: conn.rollback()
        except Exception: pass
        session_rev_regs = fetchall(conn, '''SELECT pr.id, pr.session_ids, pr.square_order_id,
            pr.amount_paid_cents, pr.is_comped, pr.participant_count, pr.discount_amount, pr.sibling_discount_amount,
            pr.refund_amount_cents,
            yp.price AS program_price, yp.bundle_price,
            su.hold_status AS step_up_hold_status, su.amount AS step_up_amount
            FROM program_registrations pr
            JOIN youth_programs yp ON yp.id = pr.program_id
            LEFT JOIN step_up_child_holds su ON su.registration_id = pr.id
            WHERE pr.status = \'confirmed\' AND pr.session_ids IS NOT NULL AND pr.session_ids != \'[]\' ''') or []
        seen_orders = set()
        session_rev_by_id = {}
        for r in session_rev_regs:
            try: sids = _json_srb.loads(r.get('session_ids') or '[]')
            except Exception: sids = []
            if not sids:
                continue
            order_key = r.get('square_order_id') or r['id']
            if order_key in seen_orders:
                continue  # sibling sharing this same order already counted
            seen_orders.add(order_key)
            if r.get('is_comped'):
                amount = 0
            elif r.get('step_up_hold_status') == 'charged':
                amount = r.get('step_up_amount') or 0
            elif r.get('step_up_hold_status') == 'pending':
                amount = 0  # not money in hand yet — excluded here same as the program-level figure
            elif r.get('amount_paid_cents') is not None:
                amount = r['amount_paid_cents']
            else:
                # Estimate fallback: a bundle price if this registration spans
                # multiple sessions and one's set, otherwise the plain per-
                # session price.
                base_price = r.get('bundle_price') if (len(sids) > 1 and r.get('bundle_price')) else r.get('program_price')
                amount = ((base_price or 0) * (r.get('participant_count') or 1)
                    - (r.get('discount_amount') or 0) - (r.get('sibling_discount_amount') or 0))
            amount = max(0, amount - (r.get('refund_amount_cents') or 0))
            per_session_share = amount / len(sids)
            for sid in sids:
                session_rev_by_id[sid] = session_rev_by_id.get(sid, 0) + per_session_share
        for s in session_breakdown:
            s['revenue_cents'] = int(round(session_rev_by_id.get(s['id'], 0)))
    except Exception as e:
        app.logger.warning(f'Session breakdown query failed: {e}')
        session_breakdown = []

    # Fetch registrant names per session - use Python-side JSON parsing (reliable)
    try:
        try: conn.rollback()
        except Exception: pass
        import json as _jsr
        all_sess_regs = fetchall(conn, """SELECT
            pr.program_id, pr.child_first_name, pr.child_last_name,
            pr.guardian_name, pr.status, pr.session_ids
            FROM program_registrations pr
            WHERE pr.status != 'cancelled'
            AND pr.session_ids IS NOT NULL
            AND pr.session_ids != '[]'
            ORDER BY pr.child_last_name, pr.child_first_name""") or []
        regs_by_session = {}
        for r in all_sess_regs:
            try: sids = _jsr.loads(r.get('session_ids') or '[]')
            except Exception: sids = []
            for sid in sids:
                if sid not in regs_by_session: regs_by_session[sid] = []
                regs_by_session[sid].append({k:v for k,v in r.items() if k!='session_ids'})
        for s in session_breakdown:
            s['registrants'] = regs_by_session.get(s['id'], [])
        app.logger.info(f'Session regs attached: {sum(len(s.get("registrants",[])) for s in session_breakdown)} total across {len(session_breakdown)} sessions')
    except Exception as e:
        app.logger.warning(f'Session registrants query failed: {e}')

    # Fetch registrant names for non-session programs and productions
    regs_by_program = {}
    try:
        try: conn.rollback()
        except Exception: pass
        flat_registrants = fetchall(conn, '''SELECT
            pr.id,
            COALESCE(pr.program_id, pr.production_id) AS group_id,
            pr.child_first_name, pr.child_last_name,
            pr.guardian_name, pr.status, pr.amount_paid_cents, pr.is_comped,
            pr.participant_count, pr.discount_amount, pr.sibling_discount_amount,
            pr.refund_amount_cents,
            COALESCE(yp.price, prod.price, 0) AS list_price,
            (SELECT h.amount FROM step_up_child_holds h
                WHERE h.registration_id = pr.id ORDER BY h.created_at DESC LIMIT 1) AS step_up_amount,
            (SELECT h.hold_status FROM step_up_child_holds h
                WHERE h.registration_id = pr.id ORDER BY h.created_at DESC LIMIT 1) AS step_up_hold_status
            FROM program_registrations pr
            LEFT JOIN youth_programs yp ON yp.id = pr.program_id
            LEFT JOIN productions prod ON prod.id = pr.production_id
            WHERE pr.status != 'cancelled'
            AND (pr.session_ids IS NULL OR pr.session_ids = '[]')
            ORDER BY pr.child_last_name, pr.child_first_name''') or []
        for r in flat_registrants:
            pid2 = r.get('group_id')
            if pid2 not in regs_by_program: regs_by_program[pid2] = []
            estimate = ((r.get('list_price') or 0) * (r.get('participant_count') or 1)
                - (r.get('discount_amount') or 0) - (r.get('sibling_discount_amount') or 0))
            # Comp'd takes priority over everything — it's $0 by design, not
            # an unpaid gap. Then a charged Step Up hold, then a pending one
            # (real amount, but not money we have yet), then a real Square
            # payment, then finally the plain estimate as a last resort.
            if r.get('is_comped'):
                r['effective_amount_cents'] = 0
                r['amount_source'] = 'comped'
            elif r.get('step_up_hold_status') == 'charged':
                r['effective_amount_cents'] = r.get('step_up_amount') or 0
                r['amount_source'] = 'step_up'
            elif r.get('step_up_hold_status') == 'pending':
                r['effective_amount_cents'] = r.get('step_up_amount') or 0
                r['amount_source'] = 'step_up_pending'
            elif r.get('amount_paid_cents') is not None:
                r['effective_amount_cents'] = r['amount_paid_cents']
                r['amount_source'] = 'square'
            else:
                r['effective_amount_cents'] = estimate
                r['amount_source'] = 'estimate'
            # A refund can land on any of the above without changing status
            # (see process_square_refund) — net it out here so the roster's
            # per-registrant figure and the dashboard totals always agree.
            if r.get('refund_amount_cents'):
                r['effective_amount_cents'] = max(0, r['effective_amount_cents'] - r['refund_amount_cents'])
                if r['amount_source'] != 'comped': r['amount_source'] = 'refunded'
            regs_by_program[pid2].append({k:v for k,v in r.items() if k!='group_id'})
    except Exception as e:
        app.logger.warning(f'Flat program registrants query failed: {e}')

    instruction_cost_total = sum(int(r.get('instruction_cost_cents') or 0) for r in program_breakdown if r.get('paid_instruction'))
    conn.close()
    return jsonify({
        'instruction_cost_total': instruction_cost_total,
        'net_confirmed_revenue': (confirmed_revenue or 0) - instruction_cost_total,
        'net_expected_revenue': (expected_revenue or 0) - instruction_cost_total,
        'reg_counts': reg_counts,
        'cart_revenue': total_revenue,
        'confirmed_revenue': confirmed_revenue,
        'expected_revenue': expected_revenue,
        'pending_step_up_revenue': pending_step_up_total,
        'waitlist_revenue': waitlist_total,
        'donations_ytd': float((donations_ytd or {}).get('total', 0)),
        'open_products': int(open_programs) + int(open_productions),
        'recent_orders': cart_orders,
        'recent_donations': recent_donations,
        'program_breakdown': program_breakdown,
        'session_breakdown': session_breakdown,
        'regs_by_program': regs_by_program,
    })


def compute_registration_amount(reg):
    """Single source of truth for 'how much did this registration bring
    in' — mirrors the CASE logic already used in the dashboard's SQL
    aggregates (comped > charged Step Up > pending Step Up > direct Square
    payment > price-based estimate). Used anywhere a registration's amount
    is shown, so it can't drift out of sync with the dashboard totals like
    it previously did here."""
    if reg.get('is_comped'):
        return 0, 'comped'
    if reg.get('step_up_hold_status') == 'charged':
        return reg.get('step_up_amount') or 0, 'step_up'
    if reg.get('step_up_hold_status') == 'pending':
        return 0, 'step_up_pending'
    refunded = reg.get('refund_amount_cents') or 0
    if reg.get('amount_paid_cents') is not None:
        return max(0, reg['amount_paid_cents'] - refunded), 'square'
    price = reg.get('program_price') or 0
    count = reg.get('participant_count') or 1
    discount = (reg.get('discount_amount') or 0) + (reg.get('sibling_discount_amount') or 0)
    return max(0, price * count - discount - refunded), 'estimate'


@app.route('/api/marquee/registrations', methods=['GET'])
def marquee_all_registrations():
    err = require_permission('marquee', 'view')
    if err: return err
    import json as _jmq
    conn = get_db()
    program_id = request.args.get('program_id')
    production_id = request.args.get('production_id')
    status = request.args.get('status')
    q1 = '''SELECT pr.*, yp.name AS program_name, yp.registration_form_type,
        yp.sessions_enabled, yp.price AS program_price, 'program' AS context_type,
        su.hold_status AS step_up_hold_status, su.amount AS step_up_amount
        FROM program_registrations pr
        JOIN youth_programs yp ON yp.id=pr.program_id
        LEFT JOIN step_up_child_holds su ON su.registration_id=pr.id
        WHERE pr.program_id IS NOT NULL'''
    p1 = []
    if program_id:
        q1 += ' AND pr.program_id=%s'; p1.append(program_id)
    if status:
        q1 += ' AND pr.status=%s'; p1.append(status)
    q2 = '''SELECT pr.*, p.name AS program_name, p.registration_form_type,
        FALSE AS sessions_enabled, p.price AS program_price, 'production' AS context_type,
        su.hold_status AS step_up_hold_status, su.amount AS step_up_amount
        FROM program_registrations pr
        JOIN productions p ON p.id=pr.production_id
        LEFT JOIN step_up_child_holds su ON su.registration_id=pr.id
        WHERE pr.production_id IS NOT NULL'''
    p2 = []
    if production_id:
        q2 += ' AND pr.production_id=%s'; p2.append(production_id)
    if status:
        q2 += ' AND pr.status=%s'; p2.append(status)
    regs1 = fetchall(conn, q1 + ' ORDER BY pr.created_at DESC LIMIT 200', p1) or []
    regs2 = (fetchall(conn, q2 + ' ORDER BY pr.created_at DESC LIMIT 200', p2) or []) if not program_id else []
    regs = sorted(regs1 + regs2, key=lambda r: str(r.get('created_at') or ''), reverse=True)[:200]
    for r in regs:
        r['amount_cents'], r['amount_source'] = compute_registration_amount(r)
    # Resolve session names for all program registrations
    sessions_by_program = {}
    for r in regs:
        pid = r.get('program_id')
        if pid and r.get('sessions_enabled') and pid not in sessions_by_program:
            rows = fetchall(conn, 'SELECT id, name FROM program_sessions WHERE program_id=%s', (pid,)) or []
            sessions_by_program[pid] = {s['id']: s['name'] for s in rows}
    for r in regs:
        pid = r.get('program_id')
        smap = sessions_by_program.get(pid, {})
        try:
            sids = _jmq.loads(r.get('session_ids') or '[]')
            r['session_names'] = [smap[sid] for sid in sids if sid in smap]
        except Exception:
            r['session_names'] = []
    programs = fetchall(conn, "SELECT id, name, start_date FROM youth_programs WHERE registration_status != 'draft' ORDER BY start_date ASC NULLS LAST, name ASC")
    productions_rs = fetchall(conn, "SELECT id, name FROM productions WHERE stage IN ('rising_stars','teen_show') AND registration_status IS NOT NULL AND registration_status != 'draft' ORDER BY name")
    conn.close()
    return jsonify({'registrations': regs, 'programs': programs, 'productions': productions_rs or []})


@app.route('/api/rising-stars/live-stats', methods=['GET'])
def rising_stars_live_stats():
    """Real-time Rising Stars enrollment snapshot for the live tracker screen.
    Intentionally public (no login) so it can run unattended on a lobby TV/tablet."""
    conn = get_db()
    shows = fetchall(conn, '''SELECT
        prod.id, prod.name, prod.price, prod.capacity, prod.registration_status,
        prod.image_url, prod.portal_color, prod.registration_open_date, prod.registration_open_time,
        COUNT(pr.id) FILTER (WHERE pr.status='confirmed') AS confirmed_count,
        COUNT(pr.id) FILTER (WHERE pr.status='pending_payment') AS pending_count,
        COUNT(pr.id) FILTER (WHERE pr.status='waitlisted') AS waitlisted_count
        FROM productions prod
        LEFT JOIN program_registrations pr ON pr.production_id=prod.id AND pr.status != 'cancelled'
        WHERE prod.stage IN ('rising_stars','teen_show') AND prod.registration_status IS NOT NULL AND prod.registration_status != 'draft'
        GROUP BY prod.id, prod.name, prod.price, prod.capacity, prod.registration_status, prod.image_url,
                 prod.portal_color, prod.registration_open_date, prod.registration_open_time
        ORDER BY prod.name''') or []

    # Diagnostic: list every production tagged Rising Stars regardless of status,
    # so we can tell "wrong status" apart from "not tagged rising_stars" at a glance.
    debug_all_rs = fetchall(conn, '''SELECT id, name, stage, registration_status
        FROM productions WHERE stage IN ('rising_stars','teen_show') ORDER BY name''') or []

    from zoneinfo import ZoneInfo as _ZIls
    for s in shows:
        s['opened_at'] = None
        s['opens_at'] = None
        open_date = (s.pop('registration_open_date', None) or '').strip()
        open_time = (s.pop('registration_open_time', None) or '').strip()
        if open_date:
            try:
                open_dt = datetime.fromisoformat(f'{open_date}T{(open_time or "00:00")[:5]}:00').replace(tzinfo=_ZIls('America/New_York'))
                open_utc_iso = open_dt.astimezone(_ZIls('UTC')).isoformat()
                if datetime.now(_ZIls('America/New_York')) >= open_dt:
                    s['opened_at'] = open_utc_iso
                else:
                    s['opens_at'] = open_utc_iso
            except Exception:
                pass

    recent = fetchall(conn, '''SELECT pr.id, pr.child_first_name, pr.child_last_name, pr.status,
        pr.created_at, pr.production_id, p.name AS production_name
        FROM program_registrations pr
        JOIN productions p ON p.id = pr.production_id
        WHERE p.stage IN ('rising_stars','teen_show') AND pr.status != 'cancelled'
        ORDER BY pr.created_at DESC LIMIT 25''') or []
    conn.close()

    for r in recent:
        first = (r.get('child_first_name') or '').strip()
        last = (r.get('child_last_name') or '').strip()
        r['display_name'] = (first + (' ' + last[0] + '.' if last else '')).strip() or 'A new star'
        r.pop('child_first_name', None)
        r.pop('child_last_name', None)

    total_confirmed = sum(s.get('confirmed_count') or 0 for s in shows)
    total_pending = sum(s.get('pending_count') or 0 for s in shows)
    total_waitlisted = sum(s.get('waitlisted_count') or 0 for s in shows)
    total_capacity = sum(s.get('capacity') or 0 for s in shows if s.get('capacity'))

    return jsonify({
        'shows': shows,
        'recent': recent,
        'totals': {
            'confirmed': total_confirmed,
            'pending': total_pending,
            'waitlisted': total_waitlisted,
            'capacity': total_capacity or None,
        },
        'debug_productions': debug_all_rs,
        'server_time': datetime.utcnow().isoformat(),
    })


@app.route('/api/programs/<pid>/sessions/summary', methods=['GET'])
def program_sessions_summary(pid):
    """Return each session with its registered participants."""
    err = require_auth()
    if err: return err
    import json as _jss
    conn = get_db()
    sessions = fetchall(conn, '''SELECT ps.*,
        (SELECT COUNT(*) FROM program_registrations
         WHERE program_id=%s AND session_ids LIKE '%%"' || ps.id || '"%%'
         AND status NOT IN ('cancelled','waitlisted')) AS confirmed_count,
        (SELECT COUNT(*) FROM program_registrations
         WHERE program_id=%s AND session_ids LIKE '%%"' || ps.id || '"%%'
         AND status='waitlisted') AS waitlisted_count
        FROM program_sessions ps WHERE ps.program_id=%s
        ORDER BY ps.sort_order, ps.day_of_week, ps.start_time''', (pid, pid, pid))
    regs = fetchall(conn, '''SELECT pr.*, yp.registration_form_type
        FROM program_registrations pr
        JOIN youth_programs yp ON yp.id=pr.program_id
        WHERE pr.program_id=%s AND pr.session_ids != '[]'
        AND pr.status NOT IN ('cancelled')
        ORDER BY pr.child_last_name, pr.child_first_name''', (pid,)) or []
    # Group registrations by session
    reg_by_session = {}
    for r in regs:
        try:
            sids = _jss.loads(r.get('session_ids') or '[]')
        except Exception:
            sids = []
        for sid in sids:
            if sid not in reg_by_session:
                reg_by_session[sid] = []
            reg_by_session[sid].append(r)
    conn.close()
    return jsonify({'sessions': sessions or [], 'reg_by_session': reg_by_session})


@app.route('/api/public/program/<slug>/registration/<rid>', methods=['GET'])
def get_registration_status(slug, rid):
    """Check registration status — called from confirmation page."""
    conn = get_db()
    reg = fetchone(conn, 'SELECT status, waitlist_position, child_first_name, child_last_name, guardian_email FROM program_registrations WHERE id=%s', (rid,))
    conn.close()
    if not reg:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(reg)


# ── Admin registration management ────────────────────────────────────────────

@app.route('/api/programs/<pid>/registrations', methods=['GET'])
def get_program_registrations(pid):
    err = require_auth()
    if err: return err
    if session.get('role') == 'instructor':
        err = require_own_program(pid)
        if err: return err
    import json as _jreg
    conn = get_db()
    regs = fetchall(conn, '''SELECT pr.*, yp.registration_form_type, yp.price AS program_price,
        su.hold_status AS step_up_hold_status, su.amount AS step_up_amount
        FROM program_registrations pr
        JOIN youth_programs yp ON yp.id=pr.program_id
        LEFT JOIN step_up_child_holds su ON su.registration_id=pr.id
        WHERE pr.program_id=%s ORDER BY pr.created_at DESC''', (pid,))
    # Resolve session names, and work out — the same way the financial
    # dashboard does — what a registration actually counts as revenue-wise
    # and why, so it's visible right here instead of a mystery elsewhere.
    sessions_map = {}
    session_rows = fetchall(conn, 'SELECT id, name FROM program_sessions WHERE program_id=%s', (pid,)) or []
    for sr in session_rows:
        sessions_map[sr['id']] = sr['name']
    for r in (regs or []):
        try:
            sids = _jreg.loads(r.get('session_ids') or '[]')
            r['session_names'] = [sessions_map.get(sid, sid) for sid in sids if sid in sessions_map]
        except Exception:
            r['session_names'] = []
        r['amount_cents'], r['amount_source'] = compute_registration_amount(r)
    interest = fetchall(conn, '''SELECT * FROM interest_list_entries
        WHERE program_id=%s ORDER BY created_at DESC''', (pid,))
    counts = {
        'confirmed': sum(1 for r in (regs or []) if r['status'] == 'confirmed'),
        'pending_payment': sum(1 for r in (regs or []) if r['status'] == 'pending_payment'),
        'waitlisted': sum(1 for r in (regs or []) if r['status'] == 'waitlisted'),
        'interest': len(interest or []),
    }
    conn.close()
    return jsonify({'registrations': regs or [], 'interest_list': interest or [], 'counts': counts})


@app.route('/api/programs/<pid>/registrations/<rid>', methods=['PUT'])
def update_registration(pid, rid):
    err = require_auth()
    if err: return err
    if session.get('role') == 'instructor':
        err = require_own_program(pid)
        if err: return err
    import json as _jur
    d = request.json or {}
    conn = get_db()
    execute(conn, '''UPDATE program_registrations SET
        status=%s, notes=%s, shirt_size=%s, guardian_name=%s,
        guardian_email=%s, guardian_phone=%s,
        emergency_contact_name=%s, emergency_contact_phone=%s,
        session_ids=%s, child_dob=%s, child_first_name=%s, child_last_name=%s,
        invoice_memo=%s, custom_field_values=%s, updated_at=NOW() WHERE id=%s AND program_id=%s''',
        (d.get('status'), d.get('notes',''), d.get('shirt_size',''),
         d.get('guardian_name',''), d.get('guardian_email',''),
         d.get('guardian_phone',''), d.get('emergency_contact_name',''),
         d.get('emergency_contact_phone',''),
         _jur.dumps(d.get('session_ids') or []),
         d.get('child_dob') or None,
         (d.get('child_first_name') or '').strip(),
         (d.get('child_last_name') or '').strip(),
         (d.get('invoice_memo') or '').strip(),
         _jur.dumps(d.get('custom_field_values') or {}),
         rid, pid))
    conn.commit()
    # moved to another session / confirmed by hand: make sure that session has an event
    try:
        ensure_session_events(conn, pid)
    except Exception as e:
        app.logger.warning(f'ensure_session_events after registration edit failed: {e}')
        try: conn.rollback()
        except Exception: pass
    conn.close()
    return jsonify({'ok': True})


@app.route('/api/programs/<pid>/registrations/<rid>/promote-waitlist', methods=['POST'])
def promote_waitlist(pid, rid):
    err = require_auth()
    if err: return err
    import uuid as _upw
    d = request.json or {}
    hold_hours = int(d.get('hold_hours') or 48)
    conn = get_db()
    reg = fetchone(conn, 'SELECT * FROM program_registrations WHERE id=%s AND program_id=%s', (rid, pid))
    prog = fetchone(conn, 'SELECT * FROM youth_programs WHERE id=%s', (pid,))
    if not reg or not prog:
        conn.close()
        return jsonify({'error': 'Not found'}), 404
    price = prog.get('price') or 0
    # If free, just confirm
    if price == 0:
        execute(conn, "UPDATE program_registrations SET status='confirmed', waitlist_position=NULL WHERE id=%s", (rid,))
        conn.commit()
        try:
            name = reg.get('guardian_name') or reg.get('child_first_name') or 'there'
            child = ((reg.get('child_first_name') or '') + ' ' + (reg.get('child_last_name') or '')).strip()
            send_email([reg['guardian_email']], f'Great news — you\'re in! {prog["name"]}',
                build_waitlist_promoted_email_html(name, child, prog['name']))
        except Exception as e:
            app.logger.warning(f'Waitlist confirm email failed: {e}')
        conn.close()
        return jsonify({'ok': True, 'type': 'confirmed_free'})
    # Paid — send payment link and notify of hold window
    execute(conn, "UPDATE program_registrations SET status='pending_payment', waitlist_position=NULL WHERE id=%s", (rid,))
    pay_url, link_id, order_id = square_create_payment_link(
        prog, rid, reg['guardian_email'], reg.get('guardian_name',''), price,
        note=f'Waitlist promotion — {reg.get("child_first_name","")} {reg.get("child_last_name","")} — {prog["name"]}')
    if pay_url:
        execute(conn, 'UPDATE program_registrations SET square_checkout_id=%s, square_order_id=%s WHERE id=%s',
            (link_id, order_id, rid))
    conn.commit()
    # Email family
    try:
        name = reg.get('guardian_name') or reg.get('child_first_name') or 'there'
        child = ((reg.get('child_first_name') or '') + ' ' + (reg.get('child_last_name') or '')).strip()
        send_email([reg['guardian_email']], f'A spot opened up for you — {prog["name"]}',
            build_waitlist_promoted_email_html(name, child, prog['name'], pay_url=pay_url, hold_hours=hold_hours))
    except Exception as e:
        app.logger.warning(f'Waitlist promote email failed: {e}')
    conn.close()
    return jsonify({'ok': True, 'type': 'payment_link_sent', 'hold_hours': hold_hours})


@app.route('/api/programs/<pid>/notify-interest-list', methods=['POST'])
def notify_interest_list(pid):
    err = require_auth()
    if err: return err
    conn = get_db()
    prog = fetchone(conn, 'SELECT * FROM youth_programs WHERE id=%s', (pid,))
    if not prog:
        conn.close()
        return jsonify({'error': 'Program not found'}), 404
    entries = fetchall(conn, 'SELECT * FROM interest_list_entries WHERE program_id=%s', (pid,))
    conn.close()
    if not entries:
        return jsonify({'ok': True, 'sent': 0})
    slug = prog.get('slug') or pid
    reg_url = f'{APP_BASE_URL}/register/{slug}'
    sent = 0
    for e in entries:
        email = e.get('email')
        name = (e.get('name') or '').strip().split()[0] or 'there'
        if not email:
            continue
        try:
            send_email([email], f'Registration is now open — {prog["name"]}',
                f'<div style="font-family:-apple-system,sans-serif;max-width:560px;margin:0 auto;color:#1a2332">'
                f'<div style="background:linear-gradient(135deg,#0d3d4d,#1b708d);padding:28px 24px;text-align:center;border-radius:12px 12px 0 0">'
                f'<img src="https://rolecall.hwtco.org/static/images/hwtc_logo_white.png" alt="HWTC" style="height:48px;display:block;margin:0 auto 10px;mix-blend-mode:screen"/>'
                f'</div>'
                f'<div style="background:#fff;padding:28px;border-radius:0 0 12px 12px;border:1px solid #e5e7eb">'
                f'<h2 style="color:#0d3d4d;font-size:20px;margin:0 0 12px">Registration is now open!</h2>'
                f'<p style="color:#374151;line-height:1.6;margin:0 0 14px">Hi {name},</p>'
                f'<p style="color:#374151;line-height:1.6;margin:0 0 20px">'
                f'Great news — registration for <strong>{prog["name"]}</strong> is now open. '
                f'You signed up for our interest list and we wanted to make sure you\'re first to know!</p>'
                f'<p style="margin:0 0 24px;text-align:center">'
                f'<a href="{reg_url}" style="background:#145466;color:#fff;padding:13px 28px;border-radius:8px;'
                f'text-decoration:none;font-weight:700;font-size:15px;display:inline-block">Register Now &rarr;</a></p>'
                f'<p style="color:#6b7280;font-size:13px;margin:0">Or copy this link: <a href="{reg_url}" style="color:#145466">{reg_url}</a></p>'
                f'<hr style="border:none;border-top:1px solid #e5e7eb;margin:20px 0"/>'
                f'<p style="color:#9ca3af;font-size:12px;margin:0;text-align:center">Horizon West Theater Company &nbsp;&middot;&nbsp; Horizon West, FL</p>'
                f'</div></div>')
            # Stamp notified_at so the UI reflects the notification
            conn2 = get_db()
            execute(conn2, 'UPDATE interest_list_entries SET notified_at=NOW() WHERE id=%s', (e['id'],))
            conn2.commit(); conn2.close()
            sent += 1
        except Exception as ex:
            app.logger.warning(f'Interest list notify failed for {email}: {ex}')
    return jsonify({'ok': True, 'sent': sent})


