# ─────────────────────────────────────────────────────────────────────────
#  Small helper — permission gate that also lets producers manage tickets
#  for their own show. Falls back to the generic 'ticketing' permission.
# ─────────────────────────────────────────────────────────────────────────
def _require_ticketing():
    """Admin/treasurer/president/staff with ticketing perm may manage tickets."""
    return require_permission('ticketing')

@app.route('/api/productions/<pid>/ticketing-settings', methods=['PUT'])
def update_ticketing_settings(pid):
    err = _require_ticketing()
    if err: return err
    d = request.json or {}
    limit = d.get('max_tickets_per_performance')
    if limit is not None:
        try:
            limit = int(limit)
            if limit < 1: raise ValueError()
        except (TypeError, ValueError):
            return jsonify({'error': 'Enter a whole number of 1 or more, or leave it blank'}), 400
    charge_fee = bool(d.get('charge_service_fee', False))
    try:
        fee_percent = float(d.get('service_fee_percent', 3.0))
        fee_flat_cents = int(d.get('service_fee_flat_cents', 30))
        if fee_percent < 0 or fee_flat_cents < 0: raise ValueError()
    except (TypeError, ValueError):
        return jsonify({'error': 'Service fee percent and flat amount must be zero or more'}), 400
    public_sale_at = (d.get('public_sale_at') or '').strip()[:16] or None
    share_name = (d.get('share_name') or '').strip()[:60] or None
    presale_opens_at = (d.get('presale_opens_at') or '').strip()[:16] or None
    try:
        companion_days = max(0, int(d.get('companion_release_days'))) if d.get('companion_release_days') not in (None, '') else 2
    except (TypeError, ValueError):
        companion_days = 2
    try:
        kbyg_hours = max(1, min(240, int(d.get('kbyg_hours_before')))) if d.get('kbyg_hours_before') not in (None, '') else 24
    except (TypeError, ValueError):
        kbyg_hours = 24
    if presale_opens_at and not _presale_parse(presale_opens_at):
        return jsonify({'error': 'Pre-sale open time isn\'t a valid date/time'}), 400
    if presale_opens_at and public_sale_at and presale_opens_at >= public_sale_at:
        return jsonify({'error': 'The pre-sale needs to open before the public on-sale time.'}), 400
    if public_sale_at and not _presale_parse(public_sale_at):
        return jsonify({'error': 'On-sale time isn\'t a valid date/time'}), 400
    try:
        default_donation = int(d.get('default_donation_cents') or 0)
    except (TypeError, ValueError):
        default_donation = 0
    if default_donation not in (0, 500, 1000, 1500, 2000):
        return jsonify({'error': 'Pick one of the donation amounts shown'}), 400
    conn = get_db()
    execute(conn, '''UPDATE productions SET max_tickets_per_performance=%s,
        charge_service_fee=%s, service_fee_percent=%s, service_fee_flat_cents=%s,
        default_donation_cents=%s WHERE id=%s''',
        (limit, charge_fee, fee_percent, fee_flat_cents, default_donation, pid))
    execute(conn, 'UPDATE productions SET public_sale_at=%s, share_name=%s, presale_opens_at=%s, companion_release_days=%s WHERE id=%s',
            (public_sale_at, share_name, presale_opens_at, companion_days, pid))
    if 'kbyg_enabled' in d:
        execute(conn, 'UPDATE productions SET kbyg_enabled=%s, kbyg_hours_before=%s, kbyg_text=%s WHERE id=%s',
                (bool(d.get('kbyg_enabled')), kbyg_hours, (d.get('kbyg_text') or '')[:3000], pid))
    if d.get('presale') == 'new':
        execute(conn, 'UPDATE productions SET presale_key=%s WHERE id=%s', (secrets.token_urlsafe(9), pid))
    elif d.get('presale') == 'off':
        execute(conn, 'UPDATE productions SET presale_key=NULL WHERE id=%s', (pid,))
    conn.commit()
    saved = fetchone(conn, 'SELECT public_sale_at, presale_key, slug, presale_opens_at FROM productions WHERE id=%s', (pid,)) or {}
    conn.close()
    return jsonify({'ok': True, 'max_tickets_per_performance': limit,
        'charge_service_fee': charge_fee, 'service_fee_percent': fee_percent, 'service_fee_flat_cents': fee_flat_cents,
        'default_donation_cents': default_donation,
        'public_sale_at': saved.get('public_sale_at'), 'presale_key': saved.get('presale_key'), 'slug': saved.get('slug'),
        'share_name': share_name, 'presale_opens_at': saved.get('presale_opens_at'), 'companion_release_days': companion_days,
        'kbyg_enabled': bool(d.get('kbyg_enabled', True)), 'kbyg_hours_before': kbyg_hours, 'kbyg_text': (d.get('kbyg_text') or '')[:3000]})


