@app.route('/api/house/<fid>', methods=['GET'])
def house_manager_data(fid):
    err = _require_house()
    if err: return err
    import datetime as _dt
    conn = get_db()
    try:
        perf = fetchone(conn, '''SELECT pf.*, p.name AS production_name, v.name AS venue_name FROM performances pf
            JOIN productions p ON p.id=pf.production_id LEFT JOIN venues v ON v.id=pf.venue_id WHERE pf.id=%s''', (fid,))
        if not perf:
            return jsonify({'error': 'Performance not found'}), 404
        tix = fetchall(conn, '''SELECT t.id, t.seat_id, t.seat_label, t.section, t.price_cents, t.confirmation_code, t.checked_in_by,
                t.checked_in_at, EXTRACT(EPOCH FROM (NOW() - t.checked_in_at))::int AS in_ago_s,
                o.id AS order_id, o.guardian_name, o.guardian_email, o.guardian_phone, COALESCE(o.sale_channel,'public') AS sale_channel,
                o.view_token, tt.name AS type_name
            FROM tickets t JOIN ticket_orders o ON o.id=t.ticket_order_id LEFT JOIN ticket_types tt ON tt.id=t.ticket_type_id
            WHERE t.performance_id=%s AND o.status='completed' ORDER BY o.guardian_name, t.seat_label''', (fid,)) or []
        seats = []
        if perf.get('seat_map_id'):
            seats = fetchall(conn, '''SELECT id, seat_label, section, x, y, accessible FROM seat_map_seats
                WHERE seat_map_id=%s AND COALESCE(active,TRUE)=TRUE''', (perf['seat_map_id'],)) or []
            _clear_expired_holds(conn, fid)
            carts = {r['seat_id'] for r in fetchall(conn, 'SELECT seat_id FROM seat_holds WHERE performance_id=%s', (fid,)) or []}
            blocks = active_seat_blocks(conn, fid)
            by_seat = {t['seat_id']: t for t in tix if t.get('seat_id')}
            for s in seats:
                t = by_seat.get(s['id'])
                if t:
                    s['status'] = 'in' if t['checked_in_at'] else 'sold'
                    s['ticket_id'] = t['id']; s['who'] = t['guardian_name']
                elif s['id'] in blocks:
                    s['status'] = 'held'; s['who'] = blocks[s['id']]['holder_name']
                elif s['id'] in carts:
                    s['status'] = 'cart'
                else:
                    s['status'] = 'open'
        sold = len(tix)
        inside = sum(1 for t in tix if t['checked_in_at'])
        comps = sum(1 for t in tix if not t['price_cents'])
        # arrivals per 5 minutes over the last hour
        buckets = [0] * 12
        for t in tix:
            a = t.get('in_ago_s')
            if a is not None and 0 <= a < 3600:
                buckets[11 - int(a // 300)] += 1
        # parties: who's here, who isn't
        parties = {}
        for t in tix:
            p = parties.setdefault(t['order_id'], {'order_id': t['order_id'], 'name': t['guardian_name'], 'email': t['guardian_email'],
                                                   'phone': t['guardian_phone'], 'channel': t['sale_channel'], 'tickets': []})
            p['tickets'].append({'id': t['id'], 'seat_label': t['seat_label'] or 'GA', 'checked_in': bool(t['checked_in_at']),
                                 'code': t['confirmation_code'], 'type': t['type_name']})
        for p in parties.values():
            p['in'] = sum(1 for x in p['tickets'] if x['checked_in'])
        not_arrived = sorted([p for p in parties.values() if p['in'] < len(p['tickets'])], key=lambda p: (p['in'] > 0, (p['name'] or '').lower()))
        log = fetchall(conn, '''SELECT code, result, message, scanned_by, ticket_id,
                EXTRACT(EPOCH FROM (NOW() - created_at))::int AS ago_s FROM door_scan_log
            WHERE performance_id=%s ORDER BY created_at DESC LIMIT 40''', (fid,)) or []
        names = {t['id']: (t['guardian_name'], t['seat_label']) for t in tix}
        for l in log:
            if l.get('ticket_id') in names:
                l['name'], l['seat_label'] = names[l['ticket_id']]
        # time to curtain
        try:
            d = _dt.date.fromisoformat(str(perf['performance_date'])[:10])
            tm = (perf.get('performance_time') or '19:00')[:5]
            start = _dt.datetime.combine(d, _dt.time(int(tm[:2]), int(tm[3:5])))
            to_curtain = int((start - now_eastern()).total_seconds())
        except Exception:
            to_curtain = None
        wheel_sold = sum(1 for s in seats if s.get('accessible') and s.get('status') in ('in', 'sold'))
        return jsonify({
            'performance': {'id': perf['id'], 'production_name': perf['production_name'], 'venue_name': perf.get('venue_name'),
                            'date': str(perf['performance_date'])[:10], 'time': perf.get('performance_time') or '',
                            'doors_time': perf.get('doors_time') or '', 'reserved': bool(perf.get('seat_map_id')),
                            'seconds_to_curtain': to_curtain},
            'metrics': {'sold': sold, 'checked_in': inside, 'not_arrived': sold - inside, 'comps': comps,
                        'box_office': sum(1 for t in tix if t['sale_channel'] == 'box_office'),
                        'parties': len(parties), 'parties_waiting': len(not_arrived),
                        'capacity': len(seats) if seats else (perf.get('ga_capacity') or 0),
                        'open_seats': sum(1 for s in seats if s.get('status') == 'open'),
                        'wheelchair_sold': wheel_sold, 'wheelchair_total': sum(1 for s in seats if s.get('accessible'))},
            'arrivals': buckets, 'seats': seats, 'not_arrived': not_arrived[:200], 'scan_log': log,
            'all_parties': list(parties.values())})
    finally:
        conn.close()


# ── Door sales (House Manager) ────────────────────────────────────────────
# Selling at the door on show day: cash, card on your own reader, check or
# comp. Works for general seating (a quantity) and reserved seating (seats
# picked on the map). Counts toward capacity, can check the party in on
# the spot, emails tickets if an address is given, and keeps a per-night
# total by payment method for counting the cash box.
DOOR_PAYMENT_METHODS = {'cash': 'Cash', 'card': 'Card (door reader)', 'check': 'Check', 'comp': 'Comp'}


@app.route('/api/house/<fid>/door', methods=['GET'])
def house_door_info(fid):
    err = require_permission('house_manager', 'view')
    if err: return err
    conn = get_db()
    try:
        perf = fetchone(conn, 'SELECT * FROM performances WHERE id=%s', (fid,))
        if not perf:
            return jsonify({'error': 'Performance not found'}), 404
        types = fetchall(conn, '''SELECT tt.id, tt.name, tt.price_cents FROM ticket_types tt
            JOIN performance_ticket_types ptt ON ptt.ticket_type_id=tt.id
            WHERE ptt.performance_id=%s AND tt.active=TRUE ORDER BY tt.sort_order, tt.price_cents DESC''', (fid,)) or []
        totals = fetchall(conn, '''SELECT COALESCE(payment_method,'cash') AS method, COUNT(*) AS orders, SUM(total_cents) AS cents,
                SUM(jsonb_array_length(COALESCE(NULLIF(seats_json,''),'[]')::jsonb)) AS tickets
            FROM ticket_orders WHERE performance_id=%s AND sale_channel='door' AND status='completed'
            GROUP BY 1''', (fid,)) or []
        return jsonify({'reserved': bool(perf.get('reserved_seating') and perf.get('seat_map_id')),
                        'ga_remaining': ga_remaining(conn, perf), 'ticket_types': types,
                        'methods': DOOR_PAYMENT_METHODS,
                        'totals': [{'method': t['method'], 'label': DOOR_PAYMENT_METHODS.get(t['method'], t['method']),
                                    'orders': int(t['orders'] or 0), 'tickets': int(t['tickets'] or 0), 'cents': int(t['cents'] or 0)} for t in totals]})
    finally:
        conn.close()


@app.route('/api/house/<fid>/door-sale', methods=['POST'])
def house_door_sale(fid):
    err = require_permission('house_manager', 'edit')
    if err: return err
    d = request.json or {}
    method = d.get('payment_method') if d.get('payment_method') in DOOR_PAYMENT_METHODS else None
    if not method:
        return jsonify({'error': 'Pick how they paid.'}), 400
    name = (d.get('name') or '').strip()[:120] or 'Door sale'
    email = (d.get('email') or '').strip().lower()[:200]
    conn = get_db()
    try:
        perf = fetchone(conn, 'SELECT * FROM performances WHERE id=%s FOR UPDATE', (fid,))
        if not perf:
            return jsonify({'error': 'Performance not found'}), 404
        # one sale can mix ticket types (2 adults + 1 child):
        #   reserved: seat_types {seat_id: ticket_type_id}
        #   general:  quantities {ticket_type_id: n}
        # (older single-type form: ticket_type_id + seat_ids / quantity)
        types = {t['id']: t for t in (fetchall(conn, '''SELECT tt.id, tt.name, tt.price_cents FROM ticket_types tt
            JOIN performance_ticket_types ptt ON ptt.ticket_type_id=tt.id WHERE ptt.performance_id=%s''', (fid,)) or [])}
        def price_of(tid):
            return 0 if method == 'comp' else int((types.get(tid) or {}).get('price_cents') or 0)
        seat_types = dict(d.get('seat_types') or {})
        if not seat_types and d.get('seat_ids') and d.get('ticket_type_id'):
            seat_types = {sid: d['ticket_type_id'] for sid in d['seat_ids']}
        quantities = dict(d.get('quantities') or {})
        if not quantities and d.get('ticket_type_id') and not d.get('seat_ids'):
            quantities = {d['ticket_type_id']: d.get('quantity') or 1}
        if any(t not in types for t in list(seat_types.values()) + list(quantities.keys())):
            return jsonify({'error': 'Pick a ticket type.'}), 400
        items = []
        if perf.get('reserved_seating') and perf.get('seat_map_id'):
            ids = [x for x in seat_types.keys() if x]
            if not ids:
                return jsonify({'error': 'Pick seats first.'}), 400
            _clear_expired_holds(conn, fid)
            taken = fetchall(conn, '''SELECT s.seat_label FROM seat_map_seats s WHERE s.id = ANY(%s) AND (
                    EXISTS (SELECT 1 FROM tickets t JOIN ticket_orders o ON o.id=t.ticket_order_id
                            WHERE t.performance_id=%s AND t.seat_id=s.id AND o.status NOT IN ('refunded','cancelled'))
                    OR EXISTS (SELECT 1 FROM seat_holds h WHERE h.performance_id=%s AND h.seat_id=s.id AND h.expires_at > NOW()))''', (ids, fid, fid)) or []
            if taken:
                return jsonify({'error': 'Already sold or in someone\'s cart: ' + ', '.join(t['seat_label'] or '?' for t in taken)}), 409
            for r in fetchall(conn, 'SELECT id, seat_label, section, obstructed_view, view_note FROM seat_map_seats WHERE id = ANY(%s)', (ids,)) or []:
                tid = seat_types[r['id']]
                items.append({'seat_id': r['id'], 'ticket_type_id': tid, 'seat_label': r['seat_label'], 'price_cents': price_of(tid),
                              'section': r.get('section') or '', 'obstructed_view': bool(r.get('obstructed_view')), 'view_note': r.get('view_note') or ''})
        else:
            for tid, n in quantities.items():
                try: n = max(0, min(50, int(n or 0)))
                except Exception: n = 0
                items += [{'seat_id': None, 'ticket_type_id': tid, 'seat_label': types[tid]['name'], 'price_cents': price_of(tid)} for _ in range(n)]
            if not items:
                return jsonify({'error': 'Pick how many.'}), 400
            left = ga_remaining(conn, perf)
            if left is not None and len(items) > left and not d.get('over_capacity_ok'):
                return jsonify({'error': ('Sold out.' if left <= 0 else f'Only {left} left.') + ' Sell anyway?', 'over_capacity': True, 'remaining': left}), 409
        oid = str(uuid.uuid4())
        execute(conn, '''INSERT INTO ticket_orders (id, performance_id, guardian_name, guardian_email, guardian_phone, seats_json,
                total_cents, service_fee_cents, status, cart_id, sale_channel, buyer_email_key, payment_method, notes)
            VALUES (%s,%s,%s,%s,%s,%s,%s,0,'pending',%s,'door',%s,%s,%s)''',
            (oid, fid, name, email or None, (d.get('phone') or '').strip()[:40] or None, json.dumps(items), sum(i['price_cents'] for i in items),
             uuid.uuid4().hex, ticket_email_key(email) if email else None, method,
             f'Door sale by {session.get("name") or "house manager"}' + (f' · {d.get("note")}' if d.get('note') else '')))
        conn.commit()
        _finalize_ticket_order(conn, oid, None, None)
        if d.get('check_in', True):
            execute(conn, '''UPDATE tickets SET checked_in_at=NOW(), checked_in_by=%s WHERE ticket_order_id=%s''',
                    (session.get('name') or 'Door sale', oid))
            conn.commit()
        sent = False
        if email:
            try: sent = send_ticket_email(conn, oid, 'confirmation')
            except Exception as e: app.logger.warning(f'Door sale ticket email failed: {e}')
        labels = [i['seat_label'] for i in items]
        return jsonify({'ok': True, 'order_id': oid, 'tickets': len(items), 'total_cents': sum(i['price_cents'] for i in items),
                        'seats': labels if items and items[0].get('seat_id') else [], 'emailed': sent})
    finally:
        conn.close()


# ── House Manager → Volunteers ────────────────────────────────────────────
# The volunteers who signed up (event sign-up / RSVP roles) for this
# performance's calendar event(s): the production's events on the same date.
# Signing someone in starts their volunteer timer for that event (the same
# as tapping Start volunteering at the kiosk); signing out stops it and
# sends the hours for approval.
def _house_events_for_perf(conn, perf):
    """The sign-up event(s) for a performance: one picked by hand for it, or
    the show's events that day, or a sign-up event that day named after the
    show (events aren't always linked to the production)."""
    day = str(perf['performance_date'])[:10]
    picked = _setting(conn, 'house_event_link:' + perf['id'])
    if picked:
        ids = [x for x in picked.split(',') if x]
        rows = fetchall(conn, 'SELECT id, name, start_time, end_time FROM events WHERE id = ANY(%s) ORDER BY start_time', (ids,)) or []
        if rows:
            return rows
    rows = fetchall(conn, '''SELECT id, name, start_time, end_time FROM events
        WHERE production_id=%s AND event_date=%s AND COALESCE(status,'') <> 'cancelled'
        ORDER BY start_time''', (perf['production_id'], day)) or []
    if rows:
        return _closest_events(rows, perf)
    prod = fetchone(conn, 'SELECT name FROM productions WHERE id=%s', (perf['production_id'],)) or {}
    if prod.get('name'):
        rows = fetchall(conn, '''SELECT id, name, start_time, end_time FROM events
            WHERE event_date=%s AND COALESCE(status,'') <> 'cancelled' AND rsvp_enabled=TRUE AND LOWER(name) LIKE %s
            ORDER BY start_time''', (day, '%' + prod['name'].lower()[:40] + '%')) or []
    return _closest_events(rows, perf) if rows else rows


def _closest_events(rows, perf):
    """Two shows the same day (matinee + evening) each have their own
    sign-up event: keep the one(s) starting closest to this performance's
    curtain, so the 2 PM show doesn't list the 7 PM volunteers too."""
    if len(rows) < 2 or not perf.get('performance_time'):
        return rows
    def mins(t):
        try:
            t = str(t)[:5]; return int(t[:2]) * 60 + int(t[3:5])
        except Exception:
            return None
    curtain = mins(perf['performance_time'])
    if curtain is None:
        return rows
    scored = [(abs((mins(r.get('start_time')) if mins(r.get('start_time')) is not None else curtain) - curtain), r) for r in rows]
    best = min(sc for sc, _ in scored)
    # events with no time, or within 30 min of the best match, stay together
    return [r for sc, r in scored if sc <= best + 30 or not r.get('start_time')]


@app.route('/api/house/<fid>/volunteers', methods=['GET'])
def house_volunteers(fid):
    err = require_permission('house_manager', 'view')
    if err: return err
    conn = get_db()
    try:
        perf = fetchone(conn, 'SELECT * FROM performances WHERE id=%s', (fid,))
        if not perf:
            return jsonify({'error': 'Performance not found'}), 404
        evs = _house_events_for_perf(conn, perf)
        ids = [e['id'] for e in evs]
        people = []
        if ids:
            rows = fetchall(conn, '''SELECT r.id, r.event_id, r.volunteer_id, COALESCE(v.name, r.volunteer_name) AS name,
                    COALESCE(v.phone,'') AS phone, r.role_name, r.status, er.block_time, er.block_time_end, er.sort_order,
                    ks.id AS session_id, EXTRACT(EPOCH FROM (NOW() - ks.started_at)) AS secs_in,
                    (SELECT hours FROM pending_hours ph WHERE ph.volunteer_id=r.volunteer_id AND ph.event_id=r.event_id AND ph.status IN ('pending','approved') LIMIT 1) AS pending_hours,
                    (SELECT hours FROM hours h WHERE h.volunteer_id=r.volunteer_id AND h.event_id=r.event_id LIMIT 1) AS approved_hours
                FROM event_rsvps r
                LEFT JOIN volunteers v ON v.id=r.volunteer_id
                LEFT JOIN event_roles er ON er.id=r.role_id
                LEFT JOIN kiosk_sessions ks ON ks.volunteer_id=r.volunteer_id AND ks.event_id=r.event_id AND ks.status='active'
                WHERE r.event_id = ANY(%s) AND r.status IN ('confirmed','interested')
                ORDER BY er.sort_order NULLS LAST, r.role_name, name''', (ids,)) or []
            ev_names = {e['id']: e['name'] for e in evs}
            seen = {}
            for r in rows:
                # the same person signed up twice (e.g. on both of the day's events): show them once
                key = (r.get('volunteer_id') or ('name:' + (r.get('name') or '').lower()), (r.get('role_name') or '').lower())
                if key in seen:
                    if r.get('session_id') and not seen[key]:
                        people[:] = [p for p in people if not (p['_key'] == key)]
                    else:
                        continue
                seen[key] = bool(r.get('session_id'))
                st = 'in' if r.get('session_id') else ('done' if (r.get('pending_hours') or r.get('approved_hours')) else 'waiting')
                people.append({'_key': key, 'event_name': ev_names.get(r['event_id'], ''), 'rsvp_id': r['id'], 'event_id': r['event_id'], 'volunteer_id': r.get('volunteer_id'), 'name': r.get('name') or '',
                               'phone': r.get('phone') or '', 'role': r.get('role_name') or 'Volunteer', 'status': st,
                               'signup_status': r.get('status'),
                               'block': ' – '.join(x for x in [_fmt_time12(r.get('block_time')), _fmt_time12(r.get('block_time_end'))] if x),
                               'since': (lambda m: (f'{m // 60}h {m % 60}m' if m >= 60 else f'{m} min'))(int(float(r['secs_in']) // 60)) if r.get('secs_in') is not None else '',
                               'hours': float(r.get('approved_hours') or r.get('pending_hours') or 0) or None})
        # every role with its spots, even ones nobody has taken yet
        roles = []
        if ids:
            hc = {}
            for e in ids:
                hc.update(_role_headcounts_for_event(conn, e))
            by_name = {}
            for ro in fetchall(conn, '''SELECT id, name, slots, block_time, block_time_end FROM event_roles WHERE event_id = ANY(%s)
                    ORDER BY sort_order, name''', (ids,)) or []:
                k = (ro['name'] or '').strip().lower()
                if k in by_name:      # same role on two linked events: one line, combined
                    by_name[k]['slots'] += int(ro.get('slots') or 0); by_name[k]['filled'] += int(hc.get(ro['id'], 0))
                    continue
                by_name[k] = {'name': ro['name'], 'slots': int(ro.get('slots') or 0), 'filled': int(hc.get(ro['id'], 0)),
                              'here': sum(1 for p in people if p['role'] == ro['name'] and p['status'] in ('in', 'done')),
                              'block': ' – '.join(x for x in [_fmt_time12(ro.get('block_time')), _fmt_time12(ro.get('block_time_end'))] if x)}
                roles.append(by_name[k])
        # if nothing matched, offer that day's sign-up events to link
        choices = []
        if not evs:
            choices = [{'id': c['id'], 'name': c['name'], 'time': _fmt_time12(c.get('start_time'))} for c in (fetchall(conn,
                '''SELECT id, name, start_time FROM events WHERE event_date=%s AND COALESCE(status,'') <> 'cancelled' AND rsvp_enabled=TRUE
                   ORDER BY start_time''', (str(perf['performance_date'])[:10],)) or [])]
        for p_ in people:
            p_.pop('_key', None)
        return jsonify({'events': [{'id': e['id'], 'name': e['name'], 'time': _fmt_time12(e.get('start_time'))} for e in evs],
                        'volunteers': people, 'roles': roles, 'choices': choices})
    finally:
        conn.close()


