@app.route('/api/house/ticket/<tid>', methods=['GET'])
def house_ticket_detail(tid):
    err = _require_house()
    if err: return err
    conn = get_db()
    try:
        t = fetchone(conn, '''SELECT t.*, o.guardian_name, o.guardian_email, o.guardian_phone, o.id AS order_id, o.view_token,
                COALESCE(o.sale_channel,'public') AS sale_channel, o.total_cents, tt.name AS type_name
            FROM tickets t JOIN ticket_orders o ON o.id=t.ticket_order_id LEFT JOIN ticket_types tt ON tt.id=t.ticket_type_id
            WHERE t.id=%s''', (tid,))
        if not t:
            return jsonify({'error': 'Ticket not found'}), 404
        party = fetchall(conn, 'SELECT id, seat_label, checked_in_at FROM tickets WHERE ticket_order_id=%s ORDER BY seat_label', (t['order_id'],)) or []
        scans = fetchall(conn, '''SELECT result, message, scanned_by, EXTRACT(EPOCH FROM (NOW() - created_at))::int AS ago_s
            FROM door_scan_log WHERE ticket_id=%s ORDER BY created_at DESC LIMIT 10''', (tid,)) or []
        t['tickets_url'] = (APP_BASE_URL.rstrip('/') + '/t/' + ensure_order_view_token(conn, t['order_id'])) if t.get('order_id') else ''
        t['party'] = [{'id': p['id'], 'seat_label': p['seat_label'], 'checked_in': bool(p['checked_in_at'])} for p in party]
        t['scans'] = scans
        t['checked_in_at'] = str(t['checked_in_at']) if t.get('checked_in_at') else None
        for k in ('created_at',):
            t[k] = str(t.get(k) or '')
        t.pop('view_token', None)
        return jsonify(t)
    finally:
        conn.close()


# ── Door check-in: scan ticket QR codes at /tickets/scan ──────────────────
def _usher_key_ok():
    """Ushers use the scanner without a RoleCall login, through a private
    link (/tickets/scan?key=...) the house manager shares. The page keeps
    the key and sends it with each request."""
    key = (request.headers.get('X-Door-Key') or request.args.get('key') or '').strip()
    if not key:
        return False
    conn = get_db()
    try:
        cur = _setting(conn, 'door_usher_key') or ''
    finally:
        conn.close()
    return bool(cur) and hmac.compare_digest(key, cur)


def _door_is_staff():
    if 'user_id' not in session:
        return False
    for k in ('house_manager', 'ticketing', 'kiosk'):
        if require_permission(k, 'view') is None:
            return True
    return False


def _require_door():
    """Door scanner: staff with House Manager / Ticketing / Sign-In access,
    or an usher with the current usher link."""
    if _door_is_staff() or _usher_key_ok():
        return None
    return jsonify({'error': 'This scanner link has expired. Ask the house manager for the current usher link.', 'usher_link_needed': True}), 401


def _require_house():
    """House manager view: logged in, with House Manager access."""
    if 'user_id' not in session:
        return jsonify({'error': 'Please log in to RoleCall first.'}), 401
    return require_permission('house_manager', 'view')


def _door_actor():
    if _door_is_staff():
        return session.get('name') or session.get('email') or 'Staff'
    nm = (request.headers.get('X-Door-Name') or '').strip()[:60]
    return (nm + ' (usher)') if nm else 'Usher'


@app.route('/tickets/scan')
def ticket_scanner_page():
    resp = send_from_directory('static', 'ticket-scanner.html')
    resp.headers['Cache-Control'] = 'no-store'
    return resp


def _door_counts(conn, fid):
    r = fetchone(conn, '''SELECT COUNT(*) AS sold, COUNT(checked_in_at) AS inside FROM tickets t
        JOIN ticket_orders o ON o.id=t.ticket_order_id WHERE t.performance_id=%s AND o.status='completed' ''', (fid,)) or {}
    return {'sold': int(r.get('sold') or 0), 'checked_in': int(r.get('inside') or 0)}


@app.route('/api/door/performances', methods=['GET'])
def door_performances():
    err = _require_door()
    if err: return err
    import datetime as _dt
    conn = get_db()
    try:
        t = today_eastern()
        rows = fetchall(conn, '''SELECT pf.id, pf.performance_date, pf.performance_time, p.name AS production_name
            FROM performances pf JOIN productions p ON p.id=pf.production_id
            WHERE pf.performance_date BETWEEN %s AND %s AND COALESCE(pf.status,'') NOT IN ('cancelled','draft')
            ORDER BY pf.performance_date, pf.performance_time''',
            ((t - _dt.timedelta(days=1)).isoformat(), (t + _dt.timedelta(days=180)).isoformat())) or []
        for r in rows:
            r.update(_door_counts(conn, r['id']))
            r['is_today'] = str(r['performance_date'])[:10] == t.isoformat()
        return jsonify(rows)
    finally:
        conn.close()


def _door_ticket_payload(conn, t, fid):
    o = fetchone(conn, 'SELECT id, guardian_name FROM ticket_orders WHERE id=%s', (t['ticket_order_id'],)) or {}
    party = fetchall(conn, 'SELECT id, seat_label, checked_in_at FROM tickets WHERE ticket_order_id=%s ORDER BY seat_label', (t['ticket_order_id'],)) or []
    return {'ticket_id': t['id'], 'seat_label': t.get('seat_label') or 'General admission', 'section': t.get('section') or '',
            'name': o.get('guardian_name') or '', 'order_id': o.get('id'),
            'party': [{'id': p['id'], 'seat_label': p['seat_label'], 'checked_in': bool(p['checked_in_at'])} for p in party],
            'counts': _door_counts(conn, fid)}


@app.route('/api/door/scan', methods=['POST'])
def door_scan():
    """Check one ticket in. Accepts the QR payload (HWTCT:<ticket id>) or
    the printed confirmation code."""
    err = _require_door()
    if err: return err
    d = request.json or {}
    fid = d.get('performance_id')
    code = (d.get('code') or '').strip()
    if not fid or not code:
        return jsonify({'result': 'error', 'message': 'Pick a performance and scan a ticket.'}), 400
    conn = get_db()
    try:
        if code.upper().startswith('HWTCT:'):
            t = fetchone(conn, 'SELECT * FROM tickets WHERE id=%s', (code[6:],))
        else:
            t = fetchone(conn, 'SELECT * FROM tickets WHERE UPPER(confirmation_code)=%s AND performance_id=%s', (code.upper(), fid)) \
                or fetchone(conn, 'SELECT * FROM tickets WHERE UPPER(confirmation_code)=%s', (code.upper(),))
        if not t:
            _log_door_scan(conn, fid, code, 'invalid', 'Not a valid ticket')
            return jsonify({'result': 'invalid', 'message': 'Not a valid ticket. Check their email or look them up by name.'})
        o = fetchone(conn, 'SELECT status FROM ticket_orders WHERE id=%s', (t['ticket_order_id'],)) or {}
        if o.get('status') != 'completed':
            _log_door_scan(conn, fid, code, 'invalid', 'Ticket not paid', t['id'])
            return jsonify({'result': 'invalid', 'message': 'This ticket isn\'t paid.'})
        if t['performance_id'] != fid:
            other = fetchone(conn, 'SELECT performance_date, performance_time FROM performances WHERE id=%s', (t['performance_id'],)) or {}
            _log_door_scan(conn, fid, code, 'wrong_show', 'Ticket is for ' + str(other.get('performance_date') or ''), t['id'])
            return jsonify(dict(_door_ticket_payload(conn, t, fid), result='wrong_show',
                                message='This ticket is for ' + str(other.get('performance_date') or '') + ' ' + _fmt_time12(other.get('performance_time')) + '.'))
        if t.get('checked_in_at'):
            ago = (fetchone(conn, 'SELECT EXTRACT(EPOCH FROM (NOW() - checked_in_at))::int AS s, checked_in_by FROM tickets WHERE id=%s', (t['id'],)) or {})
            mins = int((ago.get('s') or 0) // 60)
            when = 'just now' if mins < 1 else (str(mins) + ' min ago' if mins < 120 else str(mins // 60) + ' hours ago')
            _log_door_scan(conn, fid, code, 'already', 'Already checked in ' + when, t['id'])
            return jsonify(dict(_door_ticket_payload(conn, t, fid), result='already',
                                message='Already checked in ' + when + (' by ' + ago['checked_in_by'] if ago.get('checked_in_by') else '') + '.'))
        execute(conn, 'UPDATE tickets SET checked_in_at=NOW(), checked_in_by=%s WHERE id=%s',
                (_door_actor(), t['id']))
        conn.commit()
        _log_door_scan(conn, fid, code, 'ok', 'Checked in', t['id'])
        t['checked_in_at'] = True
        return jsonify(dict(_door_ticket_payload(conn, t, fid), result='ok', message='Welcome!'))
    finally:
        conn.close()


@app.route('/api/door/checkin-ticket', methods=['POST'])
def door_checkin_ticket():
    """Check a specific ticket in or out (undo) from the party list / lookup."""
    err = _require_door()
    if err: return err
    d = request.json or {}
    conn = get_db()
    try:
        if d.get('undo'):
            execute(conn, 'UPDATE tickets SET checked_in_at=NULL, checked_in_by=NULL WHERE id=%s', (d.get('ticket_id'),))
        else:
            execute(conn, 'UPDATE tickets SET checked_in_at=COALESCE(checked_in_at, NOW()), checked_in_by=COALESCE(checked_in_by,%s) WHERE id=%s',
                    (_door_actor(), d.get('ticket_id')))
        conn.commit()
        t = fetchone(conn, 'SELECT * FROM tickets WHERE id=%s', (d.get('ticket_id'),))
        if not t:
            return jsonify({'error': 'Ticket not found'}), 404
        _log_door_scan(conn, t['performance_id'], t.get('confirmation_code') or '', 'undo' if d.get('undo') else 'manual',
                       'Check-in undone' if d.get('undo') else 'Checked in by hand', t['id'])
        return jsonify(dict(_door_ticket_payload(conn, t, t['performance_id']), result='ok'))
    finally:
        conn.close()


@app.route('/api/door/lookup', methods=['GET'])
def door_lookup():
    """Find a party by name, email, phone or code for this performance."""
    err = _require_door()
    if err: return err
    fid = request.args.get('performance_id')
    q = '%' + (request.args.get('q') or '').strip().lower() + '%'
    conn = get_db()
    try:
        orders = fetchall(conn, '''SELECT DISTINCT o.id, o.guardian_name, o.guardian_email FROM ticket_orders o
            JOIN tickets t ON t.ticket_order_id=o.id
            WHERE o.performance_id=%s AND o.status='completed' AND (LOWER(o.guardian_name) LIKE %s OR LOWER(o.guardian_email) LIKE %s
              OR COALESCE(o.guardian_phone,'') LIKE %s OR LOWER(t.confirmation_code) LIKE %s OR LOWER(t.seat_label) LIKE %s)
            ORDER BY o.guardian_name LIMIT 25''', (fid, q, q, q, q, q)) or []
        staff = _door_is_staff()
        for o in orders:
            o['tickets'] = [{'id': t['id'], 'seat_label': t['seat_label'], 'checked_in': bool(t['checked_in_at'])}
                            for t in (fetchall(conn, 'SELECT id, seat_label, checked_in_at FROM tickets WHERE ticket_order_id=%s ORDER BY seat_label', (o['id'],)) or [])]
            if not staff:
                o.pop('guardian_email', None)   # ushers see names and seats only
        return jsonify({'orders': orders, 'counts': _door_counts(conn, fid)})
    finally:
        conn.close()


# ── Email the pre-sale link to a chosen group ─────────────────────────────
# Audience can mix: donors who have a chosen benefit (and can use it now),
# the cast's families (youth guardians), the production team, and any
# pasted list of emails. One email per address; addresses already sent the
# link for this show can be skipped. Sent in the background.
def presale_audience(conn, pid, d):
    import re as _re
    out = {}
    def add(email, name, source):
        e = (email or '').strip().lower()
        if not e or '@' not in e or not _re.match(r'^[^@\s]+@[^@\s]+\.[^@\s]+$', e):
            return
        k = ticket_email_key(e) or e
        if k not in out:
            out[k] = {'email': e, 'name': (name or '').strip(), 'sources': [source]}
        elif source not in out[k]['sources']:
            out[k]['sources'].append(source)
    # donors with the chosen benefit(s), eligible right now
    bids = [b for b in (d.get('benefit_ids') or []) if b]
    if bids:
        settings = donor_benefit_settings(conn)
        for bid in bids:
            b = fetchone(conn, '''SELECT b.*, t.min_amount AS tier_min FROM donor_tier_benefits b
                JOIN donor_tiers t ON t.id=b.tier_id WHERE b.id=%s''', (bid,))
            if not b:
                continue
            donors = fetchall(conn, '''SELECT dn.id, dn.display_name, dn.email, dn.tier_id, dn.tier_achieved_date, dn.benefits_override_until
                FROM donors dn JOIN donor_tiers t ON t.id=dn.tier_id
                WHERE COALESCE(dn.status,'active')='active' AND t.min_amount >= %s AND COALESCE(dn.email,'') <> '' ''', (b['tier_min'],)) or []
            for dn in donors:
                if not dn.get('tier_achieved_date'):
                    dn['tier_achieved_date'] = compute_tier_achieved_date(conn, dn['id'], dn['tier_id'])
                try:
                    if donor_benefit_status(conn, dn, settings, benefits=[b], usage=[])['eligible_now']:
                        add(dn['email'], dn['display_name'], 'Donor: ' + (b.get('name') or 'benefit'))
                except Exception:
                    pass
    if d.get('cast_families'):
        for r in fetchall(conn, '''SELECT g.email, g.name FROM youth_production_members ypm
                JOIN youth_participants y ON y.id=ypm.youth_id JOIN youth_guardians g ON g.youth_id=y.id
                WHERE ypm.production_id=%s AND COALESCE(y.status,'active')='active' ''', (pid,)) or []:
            add(r['email'], r['name'], 'Cast family')
    if d.get('team'):
        for r in fetchall(conn, '''SELECT v.email, v.name FROM production_members pm JOIN volunteers v ON v.id=pm.volunteer_id
                WHERE pm.production_id=%s''', (pid,)) or []:
            add(r['email'], r['name'], 'Production team')
    for line in _re.split(r'[\n,;]+', d.get('extra_emails') or ''):
        line = line.strip()
        m = _re.search(r'[^\s<>"]+@[^\s<>"]+', line)
        if m:
            nm = line.replace(m.group(0), '').strip(' <>"\t-')
            add(m.group(0), nm, 'Added by hand')
    sent = {r['email_key'] for r in fetchall(conn, 'SELECT email_key FROM presale_invites WHERE production_id=%s', (pid,)) or []}
    rows = list(out.values())
    for r in rows:
        r['already_sent'] = (ticket_email_key(r['email']) or r['email']) in sent
    return rows


def presale_invite_html(prod, link, message, name=''):
    opens = _presale_parse(prod.get('presale_opens_at'))
    pub = _presale_parse(prod.get('public_sale_at'))
    fmt = lambda t: t.strftime('%A, %B %-d at %-I:%M %p').replace(':00 ', ' ')
    first = (name or '').split(' ')[0] if name else ''
    when = []
    if opens and opens > now_eastern():
        when.append('Pre-sale opens <strong>' + _h(fmt(opens)) + '</strong>')
    else:
        when.append('Pre-sale is <strong>open now</strong>')
    if pub and pub > now_eastern():
        when.append('before tickets go on sale to the public ' + _h(fmt(pub)))
    body = (('<p>Hi ' + _h(first) + ',</p>' if first else '')
            + ('<p style="white-space:pre-line">' + _h(message) + '</p>' if message else '')
            + '<div style="background:#f4f8f9;border-radius:12px;padding:16px;margin:16px 0;text-align:center">'
            + '<div style="font-size:19px;font-weight:800;color:#0f5566;margin-bottom:6px">' + _h(prod['name']) + '</div>'
            + '<div style="font-size:14px;margin-bottom:14px">' + ', '.join(when) + '.</div>'
            + '<a href="' + link + '" style="display:inline-block;background:#16728b;color:#fff;text-decoration:none;font-weight:700;padding:13px 26px;border-radius:10px;font-size:15px">Get pre-sale tickets</a>'
            + '</div><p style="font-size:13px;color:#5f6b72">This link is just for you. Please don\'t share it, so our pre-sale stays special.</p>')
    return build_hwtc_email_html('Pre-sale tickets: ' + prod['name'], body)


@app.route('/api/productions/<pid>/presale-invites', methods=['POST'])
def presale_invites(pid):
    """mode: 'preview' (who would get it), 'test' (send to test_to), or
    'send' (everyone in the audience, in the background)."""
    err = _require_ticketing()
    if err: return err
    d = request.json or {}
    mode = d.get('mode') or 'preview'
    conn = get_db()
    try:
        prod = fetchone(conn, 'SELECT id, name, slug, presale_key, presale_opens_at, public_sale_at FROM productions WHERE id=%s', (pid,))
        if not prod:
            return jsonify({'error': 'Show not found'}), 404
        if not prod.get('presale_key'):
            return jsonify({'error': 'Create the pre-sale link first (Ticketing Settings → Private pre-sale link).'}), 400
        link = APP_BASE_URL.rstrip('/') + '/tickets/' + (prod.get('slug') or prod['id']) + '?presale=' + prod['presale_key']
        subject = (d.get('subject') or '').strip()[:150] or ('Pre-sale tickets for ' + prod['name'])
        message = (d.get('message') or '').strip()[:3000]
        if mode == 'test':
            to = (d.get('test_to') or '').strip()
            if '@' not in to:
                return jsonify({'error': 'Enter an email for the test.'}), 400
            res = send_email([to], '[Test] ' + subject, presale_invite_html(prod, link, message, ''), source='presale_invite_test')
            ok = res[0] if isinstance(res, tuple) else bool(res)
            return jsonify({'ok': True}) if ok else (jsonify({'error': 'The test didn\'t send.'}), 400)
        rows = presale_audience(conn, pid, d)
        if d.get('skip_sent', True):
            todo = [r for r in rows if not r['already_sent']]
        else:
            todo = rows
        if mode == 'preview':
            return jsonify({'count': len(todo), 'total': len(rows), 'already_sent': sum(1 for r in rows if r['already_sent']),
                            'recipients': [{'email': r['email'], 'name': r['name'], 'sources': r['sources'], 'already_sent': r['already_sent']} for r in rows[:500]]})
    finally:
        conn.close()
    if not todo:
        return jsonify({'ok': True, 'count': 0})
    who = session.get('name') or session.get('email') or ''
    import threading, time as _t
    def send_invites(items):
        c = get_db()
        try:
            for r in items:
                try:
                    res = send_email([r['email']], subject, presale_invite_html(prod, link, message, r['name']), source='presale_invite')
                    if (res[0] if isinstance(res, tuple) else bool(res)):
                        execute(c, '''INSERT INTO presale_invites (id, production_id, email, email_key, name, sources, sent_by)
                            VALUES (%s,%s,%s,%s,%s,%s,%s) ON CONFLICT (production_id, email_key) DO UPDATE SET sent_at=NOW()''',
                            (uuid.uuid4().hex, pid, r['email'], ticket_email_key(r['email']) or r['email'], r['name'], ', '.join(r['sources']), who))
                        c.commit()
                except Exception as e:
                    app.logger.warning(f'Pre-sale invite to {r["email"]} failed: {e}')
                    try: c.rollback()
                    except Exception: pass
                _t.sleep(0.6)
        finally:
            c.close()
    threading.Thread(target=send_invites, args=(todo,), daemon=True).start()
    return jsonify({'ok': True, 'count': len(todo), 'minutes': max(1, round(len(todo) * 0.7 / 60))})



# ── General seating capacity ──────────────────────────────────────────────
# Reserved seating can't oversell (each seat sells once), but general
# seating only had a number, and nothing checked it at checkout. Now the
# tickets sold + tickets in checkouts still being paid for can never go
# over ga_capacity, and the performance flips to Sold Out when it's full
# (and back to On Sale if tickets are later refunded).
def ga_remaining(conn, perf, exclude_order_ids=None):
    """Tickets still available for a general-seating performance, or None
    if it has no capacity set (unlimited) or is reserved seating."""
    if perf.get('reserved_seating') or not int(perf.get('ga_capacity') or 0):
        return None
    sold = (fetchone(conn, """SELECT COUNT(*) AS c FROM tickets t JOIN ticket_orders o ON o.id=t.ticket_order_id
        WHERE t.performance_id=%s AND o.status NOT IN ('refunded','cancelled')""", (perf['id'],)) or {}).get('c') or 0
    pend = 0
    for o in fetchall(conn, "SELECT id, seats_json FROM ticket_orders WHERE performance_id=%s AND status='pending' "
                            "AND created_at > NOW() - INTERVAL '" + str(TICKET_PENDING_WINDOW_MINUTES) + " minutes'", (perf['id'],)) or []:
        if exclude_order_ids and o['id'] in exclude_order_ids:
            continue
        pend += _order_ticket_count(o)
    return max(0, int(perf['ga_capacity']) - int(sold) - pend)


def performance_availability(conn, perf):
    """How full a performance is, for the "Only 6 left" / "Almost sold out"
    labels on the ticket page. Works for general and reserved seating."""
    if perf.get('reserved_seating') and perf.get('seat_map_id'):
        cap = int((fetchone(conn, 'SELECT COUNT(*) AS c FROM seat_map_seats WHERE seat_map_id=%s AND COALESCE(active,TRUE)=TRUE',
                            (perf['seat_map_id'],)) or {}).get('c') or 0)
        sold = int((fetchone(conn, """SELECT COUNT(*) AS c FROM tickets t JOIN ticket_orders o ON o.id=t.ticket_order_id
            WHERE t.performance_id=%s AND t.seat_id IS NOT NULL AND o.status NOT IN ('refunded','cancelled')""", (perf['id'],)) or {}).get('c') or 0)
        held = int((fetchone(conn, 'SELECT COUNT(*) AS c FROM seat_holds WHERE performance_id=%s AND expires_at > NOW()', (perf['id'],)) or {}).get('c') or 0)
        try:
            blocked = len(active_seat_blocks(conn, perf['id']) or {})
        except Exception:
            blocked = 0
        left = max(0, cap - sold - held - blocked)
        sold_out = cap > 0 and sold + blocked >= cap
    else:
        cap = int(perf.get('ga_capacity') or 0)
        if not cap:
            return None
        left = ga_remaining(conn, perf) or 0
        sold_out = left <= 0
    if not cap:
        return None
    pct = left * 100.0 / cap
    level = ('sold_out' if sold_out else 'none_now' if left <= 0 else 'last' if left <= 10 else
             'almost' if pct <= 20 else 'limited' if pct <= 40 else 'plenty')
    return {'left': left, 'capacity': cap, 'level': level}


def update_ga_sold_out(conn, performance_id):
    """Sold Out when full; back On Sale if it had been marked sold out
    automatically and space opened up (refund, cancelled order)."""
    perf = fetchone(conn, 'SELECT * FROM performances WHERE id=%s', (performance_id,))
    if not perf or perf.get('reserved_seating') or not int(perf.get('ga_capacity') or 0):
        return
    sold = (fetchone(conn, """SELECT COUNT(*) AS c FROM tickets t JOIN ticket_orders o ON o.id=t.ticket_order_id
        WHERE t.performance_id=%s AND o.status NOT IN ('refunded','cancelled')""", (performance_id,)) or {}).get('c') or 0
    full = int(sold) >= int(perf['ga_capacity'])
    if full and perf.get('status') == 'on_sale':
        execute(conn, "UPDATE performances SET status='sold_out', auto_sold_out=TRUE WHERE id=%s", (performance_id,))
    elif not full and perf.get('status') == 'sold_out' and perf.get('auto_sold_out'):
        execute(conn, "UPDATE performances SET status='on_sale', auto_sold_out=FALSE WHERE id=%s", (performance_id,))

def _finalize_ticket_order(conn, order_id, square_payment_id, square_order_id):
    """Turns a paid (or free) order into real tickets, releases the seat
    holds that produced them, and marks the order completed."""
    order = fetchone(conn, 'SELECT * FROM ticket_orders WHERE id=%s', (order_id,))
    if not order or order['status'] == 'completed':
        return
    try:
        line_items = json.loads(order.get('seats_json') or '[]')
    except Exception:
        line_items = []
    for li in line_items:
        execute(conn, '''INSERT INTO tickets
            (id, ticket_order_id, performance_id, seat_id, ticket_type_id, seat_label, price_cents, confirmation_code,
             section, obstructed_view, view_note)
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)''',
            (str(uuid.uuid4()), order_id, order['performance_id'], li.get('seat_id'),
             li.get('ticket_type_id'), li.get('seat_label') or '', li.get('price_cents') or 0,
             uuid.uuid4().hex[:8].upper(), li.get('section') or '', bool(li.get('obstructed_view')),
             li.get('view_note') or ''))
    execute(conn, "UPDATE ticket_orders SET status='completed' WHERE id=%s", (order_id,))
    execute(conn, 'DELETE FROM seat_holds WHERE performance_id=%s AND seat_id = ANY(%s)',
        (order['performance_id'], [li['seat_id'] for li in line_items if li.get('seat_id')]))
    try:
        update_ga_sold_out(conn, order['performance_id'])
    except Exception as e:
        app.logger.warning(f'GA sold-out check failed: {e}')
    conn.commit()
    try:
        fp = _square_card_fingerprint(square_payment_id)
        if fp:
            execute(conn, 'UPDATE ticket_orders SET card_fingerprint=%s WHERE id=%s', (fp, order_id))
            conn.commit()
        flag_ticket_order_if_over_limit(conn, order_id)
    except Exception as e:
        app.logger.warning(f'Ticket limit flag check failed: {e}')
    try:
        if order.get('benefit_code_id'):
            record_benefit_code_redemption(conn, fetchone(conn, 'SELECT * FROM ticket_orders WHERE id=%s', (order_id,)))
    except Exception as e:
        app.logger.warning(f'Benefit code redemption record failed: {e}')
    if order.get('guardian_email'):
        try:
            send_ticket_email(conn, order_id, 'confirmation')
        except Exception as e:
            app.logger.warning(f'Ticket confirmation email failed: {e}')


@app.route('/api/public/ticket-order/<oid>', methods=['GET'])
def public_ticket_order_status(oid):
    conn = get_db()
    order = fetchone(conn, 'SELECT * FROM ticket_orders WHERE id=%s', (oid,))
    if not order:
        conn.close(); return jsonify({'error': 'Not found'}), 404
    perf = fetchone(conn, 'SELECT * FROM performances WHERE id=%s', (order['performance_id'],))
    prod = fetchone(conn, 'SELECT name FROM productions WHERE id=%s', (perf['production_id'],)) if perf else None
    tickets = fetchall(conn, 'SELECT * FROM tickets WHERE ticket_order_id=%s', (oid,))
    conn.close()
    try:
        order['seats'] = json.loads(order.get('seats_json') or '[]')
    except Exception:
        order['seats'] = []
    return jsonify({'order': order, 'performance': perf, 'production_name': (prod or {}).get('name',''), 'tickets': tickets})

@app.route('/api/public/ticket-cart/<cart_id>', methods=['GET'])
def public_ticket_cart_status(cart_id):
    """Confirmation-page equivalent of public_ticket_order_status, but for
    a whole cart -- every performance's order that shared this checkout,
    each with its own tickets, so a multi-show purchase shows as one
    combined confirmation instead of only ever surfacing one of them."""
    conn = get_db()
    orders = fetchall(conn, 'SELECT * FROM ticket_orders WHERE cart_id=%s ORDER BY created_at', (cart_id,)) or []
    if not orders:
        conn.close(); return jsonify({'error': 'Not found'}), 404
    result = []
    for order in orders:
        perf = fetchone(conn, 'SELECT * FROM performances WHERE id=%s', (order['performance_id'],))
        prod = fetchone(conn, 'SELECT name FROM productions WHERE id=%s', (perf['production_id'],)) if perf else None
        tickets = fetchall(conn, 'SELECT * FROM tickets WHERE ticket_order_id=%s', (order['id'],))
        try:
            order['seats'] = json.loads(order.get('seats_json') or '[]')
        except Exception:
            order['seats'] = []
        result.append({'order': order, 'performance': perf, 'production_name': (prod or {}).get('name',''), 'tickets': tickets})
    # An add-on donation shares this same checkout's Square ids, not the
    # cart_id itself (pending_donations has no cart_id column -- it's a
    # separate table used standalone too), so it's looked up separately.
    donation = None
    ids = {o.get('square_order_id') for o in orders if o.get('square_order_id')} | {o.get('square_checkout_id') for o in orders if o.get('square_checkout_id')}
    if ids:
        donation = fetchone(conn, 'SELECT amount_cents, status FROM pending_donations WHERE square_order_id = ANY(%s) OR square_checkout_id = ANY(%s)',
            (list(ids), list(ids)))
    conn.close()
    return jsonify({'orders': result, 'donation': donation})


# ── ORDER / PATRON MANAGEMENT (staff) ────────────────────────────────────

@app.route('/api/productions/<pid>/seat-holds', methods=['GET'])
def get_production_seat_holds(pid):
    """Every currently-live (non-expired) seat hold across this
    production's performances — mainly so staff can see what a stuck or
    abandoned checkout is holding onto and clear it themselves instead of
    waiting out the 15-minute expiry, e.g. while testing or troubleshooting
    a patron's report that a seat 'won't let them pick it'."""
    err = require_auth()
    if err: return err
    performance_id = (request.args.get('performance_id') or '').strip()
    conn = get_db()
    perf_ids = [performance_id] if performance_id else [
        r['id'] for r in fetchall(conn, 'SELECT id FROM performances WHERE production_id=%s', (pid,)) or []]
    if not perf_ids:
        conn.close(); return jsonify([])
    holds = fetchall(conn, '''SELECT h.*, s.seat_label, pf.performance_date, pf.performance_time
        FROM seat_holds h
        JOIN seat_map_seats s ON s.id=h.seat_id
        JOIN performances pf ON pf.id=h.performance_id
        WHERE h.performance_id = ANY(%s) AND h.expires_at > NOW()
        ORDER BY pf.performance_date, pf.performance_time, s.seat_label''', (perf_ids,)) or []
    conn.close()
    return jsonify(holds)

@app.route('/api/seat-holds/<hold_id>', methods=['DELETE'])
def delete_seat_hold(hold_id):
    """Staff manually clearing one hold — releases it immediately instead
    of waiting for the 15-minute expiry."""
    err = _require_ticketing()
    if err: return err
    conn = get_db()
    execute(conn, 'DELETE FROM seat_holds WHERE id=%s', (hold_id,))
    conn.commit()
    conn.close()
    return jsonify({'ok': True})


@app.route('/api/productions/<pid>/ticket-orders', methods=['GET'])
def get_production_ticket_orders(pid):
    """The box-office view: every order across all of this production's
    performances, searchable by patron name/email and optionally filtered
    to one performance. Each order comes back with its ticket count and
    seat labels so staff can see what's in it without opening every one."""
    err = require_auth()
    if err: return err
    q = (request.args.get('q') or '').strip()
    performance_id = (request.args.get('performance_id') or '').strip()
    conn = get_db()
    where = ['pf.production_id=%s', "t.status <> 'superseded'"]
    params = [pid]
    if performance_id:
        where.append('t.performance_id=%s')
        params.append(performance_id)
    if q:
        where.append('(t.guardian_name ILIKE %s OR t.guardian_email ILIKE %s OR t.guardian_phone ILIKE %s)')
        like = f'%{q}%'
        params.extend([like, like, like])
    orders = fetchall(conn, f'''SELECT t.*, pf.name AS performance_name, pf.performance_date, pf.performance_time
        FROM ticket_orders t
        JOIN performances pf ON pf.id=t.performance_id
        WHERE {" AND ".join(where)}
        ORDER BY t.created_at DESC LIMIT 100''', tuple(params)) or []
    if orders:
        order_ids = [o['id'] for o in orders]
        tix = fetchall(conn, 'SELECT ticket_order_id, seat_label FROM tickets WHERE ticket_order_id = ANY(%s)', (order_ids,)) or []
        by_order = {}
        for t in tix:
            by_order.setdefault(t['ticket_order_id'], []).append(t['seat_label'])
        for o in orders:
            o['seat_labels'] = by_order.get(o['id'], [])
            if not o['seat_labels']:
                # unpaid orders have no tickets yet; show what they reserved
                try:
                    _items = json.loads(o.get('seats_json') or '[]')
                except Exception:
                    _items = []
                o['seat_labels'] = [li.get('seat_label') for li in _items if li.get('seat_label')]
                o['ticket_count'] = len(_items)
            else:
                o['ticket_count'] = len(o['seat_labels'])
    conn.close()
    return jsonify(orders)


@app.route('/api/ticket-orders/<oid>', methods=['GET'])
def get_ticket_order_admin(oid):
    """Full order detail for staff — same shape as the public confirmation
    endpoint, plus each ticket's seat_id (needed for the move-seat UI,
    which the public-facing version has no reason to expose)."""
    err = require_auth()
    if err: return err
    conn = get_db()
    order = fetchone(conn, 'SELECT * FROM ticket_orders WHERE id=%s', (oid,))
    if not order:
        conn.close(); return jsonify({'error': 'Not found'}), 404
    perf = fetchone(conn, '''SELECT pf.*, p.name AS production_name, p.id AS production_id
        FROM performances pf JOIN productions p ON p.id=pf.production_id WHERE pf.id=%s''', (order['performance_id'],))
    tickets = fetchall(conn, 'SELECT * FROM tickets WHERE ticket_order_id=%s ORDER BY seat_label', (oid,)) or []
    related = []
    try:
        flag = json.loads(order.get('limit_flag') or 'null')
    except Exception:
        flag = None
    if flag and flag.get('related_order_ids'):
        related = fetchall(conn, '''SELECT id, guardian_name, guardian_email, guardian_phone, seats_json, created_at
            FROM ticket_orders WHERE id = ANY(%s) ORDER BY created_at''', (flag['related_order_ids'],)) or []
        for r in related:
            r['ticket_count'] = _order_ticket_count(r)
            r.pop('seats_json', None)
    if order.get('status') == 'completed':
        try:
            order['tickets_url'] = APP_BASE_URL.rstrip('/') + '/t/' + ensure_order_view_token(conn, oid)
        except Exception:
            pass
    conn.close()
    try:
        order['seats'] = json.loads(order.get('seats_json') or '[]')
    except Exception:
        order['seats'] = []
    order['limit_flag'] = flag
    # staff don't need the raw matching signals
    for k in ('buyer_device_id', 'card_fingerprint', 'buyer_email_key', 'buyer_phone_key'):
        order.pop(k, None)
    return jsonify({'order': order, 'performance': perf, 'tickets': tickets, 'related_orders': related})


# ── Staff actions on ticket orders that never got paid ────────────────────
# Tickets only exist once an order is paid, so an unpaid ("pending") order
# is just a reservation: staff can cancel it, record it as paid (cash/check
# at the door), or delete it. Paid orders go through Request Refund instead.
UNPAID_TICKET_STATUSES = ('pending', 'superseded', 'cancelled')


def _cancel_ticket_checkout(conn, order):
    """Cancel the Square payment link behind an unpaid order so it can't be
    paid later. One link can cover several performances bought together,
    so every order in that checkout is cancelled with it. Returns the ids
    cancelled, or None if Square refused to cancel the link."""
    cart_id = order.get('cart_id')
    siblings = fetchall(conn, "SELECT * FROM ticket_orders WHERE cart_id=%s AND status IN ('pending','superseded')",
                        (cart_id,)) if cart_id else [order]
    siblings = siblings or [order]
    for cid in set(o.get('square_checkout_id') for o in siblings if o.get('square_checkout_id')):
        try:
            rr = requests.delete(f'{SQUARE_API_BASE}/v2/online-checkout/payment-links/{cid}',
                                 headers=square_headers(), timeout=10)
            if rr.status_code not in (200, 404):
                return None
        except Exception as e:
            app.logger.warning(f'Could not cancel ticket payment link {cid}: {e}')
            return None
    ids = [o['id'] for o in siblings]
    for o in siblings:
        seat_ids = [li.get('seat_id') for li in json.loads(o.get('seats_json') or '[]') if li.get('seat_id')]
        if seat_ids:
            execute(conn, 'DELETE FROM seat_holds WHERE performance_id=%s AND seat_id = ANY(%s)',
                    (o['performance_id'], seat_ids))
    execute(conn, "UPDATE ticket_orders SET status='cancelled' WHERE id = ANY(%s)", (ids,))
    for cid in set(o.get('square_checkout_id') for o in siblings if o.get('square_checkout_id')):
        execute(conn, "UPDATE pending_donations SET status='cancelled' WHERE square_checkout_id=%s AND status='pending'", (cid,))
    conn.commit()
    return ids


@app.route('/api/ticket-orders/<oid>/cancel', methods=['POST'])
def cancel_ticket_order(oid):
    err = _require_ticketing()
    if err: return err
    conn = get_db()
    try:
        order = fetchone(conn, 'SELECT * FROM ticket_orders WHERE id=%s', (oid,))
        if not order:
            return jsonify({'error': 'Order not found'}), 404
        if order['status'] not in ('pending', 'superseded'):
            return jsonify({'error': 'Only unpaid orders can be cancelled. Use Request Refund for paid orders.'}), 400
        ids = _cancel_ticket_checkout(conn, order)
        if ids is None:
            return jsonify({'error': "Square wouldn't cancel this checkout link. Try again in a minute."}), 502
        return jsonify({'ok': True, 'cancelled_order_ids': ids})
    finally:
        conn.close()


@app.route('/api/ticket-orders/<oid>/mark-paid', methods=['POST'])
def mark_ticket_order_paid(oid):
    """Record an unpaid order as paid outside Square (cash/check), which
    issues the tickets exactly like an online payment would."""
    err = _require_ticketing()
    if err: return err
    conn = get_db()
    try:
        order = fetchone(conn, 'SELECT * FROM ticket_orders WHERE id=%s', (oid,))
        if not order:
            return jsonify({'error': 'Order not found'}), 404
        if order['status'] not in UNPAID_TICKET_STATUSES:
            return jsonify({'error': 'This order is already paid.'}), 400
        items = json.loads(order.get('seats_json') or '[]')
        seat_ids = [li.get('seat_id') for li in items if li.get('seat_id')]
        if seat_ids:
            taken = fetchall(conn, 'SELECT seat_label FROM tickets WHERE performance_id=%s AND seat_id = ANY(%s)',
                             (order['performance_id'], seat_ids)) or []
            if taken:
                return jsonify({'error': 'Some of these seats have since been sold: '
                                + ', '.join(t['seat_label'] or '?' for t in taken)
                                + '. Move this buyer to other seats with a new order.'}), 409
        # Stop the old online link from charging them a second time
        if order['status'] in ('pending', 'superseded') and order.get('square_checkout_id'):
            try:
                requests.delete(f"{SQUARE_API_BASE}/v2/online-checkout/payment-links/{order['square_checkout_id']}",
                                headers=square_headers(), timeout=10)
            except Exception as e:
                app.logger.warning(f'Could not cancel payment link on manual payment: {e}')
        execute(conn, "UPDATE ticket_orders SET status='pending' WHERE id=%s", (oid,))
        conn.commit()
        _finalize_ticket_order(conn, oid, None, None)
        notify_ticket_sale(conn, order.get('cart_id'))
        return jsonify({'ok': True})
    finally:
        conn.close()


@app.route('/api/ticket-orders/<oid>/delete-test', methods=['POST'])
def delete_test_ticket_order(oid):
    """Remove a paid order placed in staff preview mode (tagged 'test'),
    freeing its seats. Real payments, if any, still need refunding in Square."""
    err = _require_ticketing()
    if err: return err
    conn = get_db()
    try:
        o = fetchone(conn, 'SELECT id, sale_channel FROM ticket_orders WHERE id=%s', (oid,))
        if not o:
            return jsonify({'error': 'Order not found'}), 404
        if o.get('sale_channel') != 'test':
            return jsonify({'error': 'Only test orders can be deleted this way.'}), 400
        pf_row = fetchone(conn, 'SELECT performance_id FROM ticket_orders WHERE id=%s', (oid,)) or {}
        execute(conn, 'DELETE FROM tickets WHERE ticket_order_id=%s', (oid,))
        execute(conn, 'DELETE FROM ticket_orders WHERE id=%s', (oid,))
        if pf_row.get('performance_id'):
            update_ga_sold_out(conn, pf_row['performance_id'])
        conn.commit()
        return jsonify({'ok': True})
    finally:
        conn.close()


@app.route('/api/ticket-orders/<oid>', methods=['DELETE'])
def delete_ticket_order(oid):
    """Remove an unpaid or cancelled order entirely. Paid orders can't be
    deleted here (their tickets and payment record need to stay)."""
    err = _require_ticketing()
    if err: return err
    conn = get_db()
    try:
        order = fetchone(conn, 'SELECT * FROM ticket_orders WHERE id=%s', (oid,))
        if not order:
            return jsonify({'error': 'Order not found'}), 404
        if order['status'] not in UNPAID_TICKET_STATUSES:
            return jsonify({'error': 'Paid orders can\'t be deleted. Use Request Refund instead.'}), 400
        if order['status'] in ('pending', 'superseded'):
            if _cancel_ticket_checkout(conn, order) is None:
                return jsonify({'error': "Square wouldn't cancel this checkout link, so the order wasn't deleted. Try again in a minute."}), 502
        execute(conn, 'DELETE FROM ticket_orders WHERE id=%s', (oid,))
        conn.commit()
        return jsonify({'ok': True})
    finally:
        conn.close()


@app.route('/api/tickets/<tid>/move-seat', methods=['PUT'])
def move_ticket_seat(tid):
    """Reassigns a sold ticket to a different seat in the same performance
    — e.g. a patron calls asking to move, or staff need to consolidate a
    party together. Refuses to move onto a seat that's already sold or
    currently held by someone mid-checkout; doesn't touch price or the
    ticket type, just which physical seat it points to."""
    err = _require_ticketing()
    if err: return err
    d = request.json or {}
    new_seat_id = (d.get('seat_id') or '').strip()
    if not new_seat_id:
        return jsonify({'error': 'A new seat is required'}), 400
    conn = get_db()
    ticket = fetchone(conn, 'SELECT * FROM tickets WHERE id=%s', (tid,))
    if not ticket:
        conn.close(); return jsonify({'error': 'Ticket not found'}), 404
    if not ticket.get('seat_id'):
        conn.close(); return jsonify({'error': 'This ticket is general admission and has no seat to move'}), 400
    new_seat = fetchone(conn, 'SELECT * FROM seat_map_seats WHERE id=%s', (new_seat_id,))
    if not new_seat:
        conn.close(); return jsonify({'error': 'Seat not found'}), 404
    already_sold = fetchone(conn, 'SELECT id FROM tickets WHERE performance_id=%s AND seat_id=%s AND id!=%s',
        (ticket['performance_id'], new_seat_id, tid))
    if already_sold:
        conn.close(); return jsonify({'error': f"{new_seat['seat_label']} is already sold to someone else"}), 409
    _clear_expired_holds(conn, ticket['performance_id'])
    held = fetchone(conn, 'SELECT session_token FROM seat_holds WHERE performance_id=%s AND seat_id=%s',
        (ticket['performance_id'], new_seat_id))
    if held:
        conn.close(); return jsonify({'error': f"{new_seat['seat_label']} is currently held by someone mid-checkout — try again shortly"}), 409
    old_label = ticket.get('seat_label')
    execute(conn, 'UPDATE tickets SET seat_id=%s, seat_label=%s WHERE id=%s',
        (new_seat_id, new_seat['seat_label'], tid))
    # Keep the order's own seats_json in sync too, since the confirmation
    # page and order detail both read seat labels from there directly.
    order = fetchone(conn, 'SELECT seats_json FROM ticket_orders WHERE id=%s', (ticket['ticket_order_id'],))
    try:
        seats = json.loads(order.get('seats_json') or '[]') if order else []
        for s in seats:
            if s.get('seat_id') == ticket['seat_id']:
                s['seat_id'] = new_seat_id
                s['seat_label'] = new_seat['seat_label']
        execute(conn, 'UPDATE ticket_orders SET seats_json=%s WHERE id=%s', (json.dumps(seats), ticket['ticket_order_id']))
    except Exception:
        pass
    conn.commit()
    conn.close()
    return jsonify({'ok': True, 'old_seat_label': old_label, 'new_seat_label': new_seat['seat_label']})


@app.route('/tickets/<slug>')
def public_tickets_page(slug):
    """The ticket page, with a proper title/description/image filled in on
    the server so texted or posted links preview as e.g. "HSM Jr. Pre-Sale
    Tickets" with the show art (link previews don't run the page's scripts)."""
    if slug in ('cart', 'confirmation'):
        return send_from_directory('static', 'tickets.html')
    from html import escape
    try:
        conn = get_db()
        prod = fetchone(conn, '''SELECT id, name, share_name, description, image_url, ticket_logo_url, public_sale_at, presale_key,
                presale_opens_at FROM productions WHERE slug=%s OR id=%s''', (slug, slug))
        dates = fetchall(conn, '''SELECT performance_date FROM performances WHERE production_id=%s
            AND status IN ('presale','on_sale','sold_out') ORDER BY performance_date''', (prod['id'],)) if prod else []
        venue = fetchone(conn, '''SELECT v.name FROM performances pf JOIN venues v ON v.id=pf.venue_id
            WHERE pf.production_id=%s ORDER BY pf.performance_date LIMIT 1''', (prod['id'],)) if prod else None
        conn.close()
    except Exception as e:
        app.logger.warning(f'ticket page preview lookup failed: {e}')
        prod = None
    with open(os.path.join('static', 'tickets.html'), encoding='utf-8') as f:
        page = f.read()
    if not prod:
        return page
    show = (prod.get('share_name') or prod.get('name') or 'Tickets').strip()
    key = request.args.get('presale') or ''
    is_presale = presale_key_ok(prod, key)
    opens = _presale_parse(prod.get('public_sale_at'))
    before_public = bool(opens and now_eastern() < opens)
    import datetime as _dt
    def _d(x):
        try: return _dt.date.fromisoformat(str(x)[:10])
        except Exception: return None
    ds = [d for d in (_d(r['performance_date']) for r in dates or []) if d]
    when = ''
    if ds:
        a, b = ds[0], ds[-1]
        if a == b: when = a.strftime('%b %-d, %Y')
        elif a.year == b.year and a.month == b.month: when = a.strftime('%b %-d') + '–' + b.strftime('%-d, %Y')
        else: when = a.strftime('%b %-d') + ' – ' + b.strftime('%b %-d, %Y')
    where = (venue or {}).get('name') or ''
    pre_opens = _presale_parse(prod.get('presale_opens_at'))
    if is_presale and pre_opens and now_eastern() < pre_opens:
        title = show + ' Pre-Sale Tickets'
        desc = 'Pre-sale opens ' + pre_opens.strftime('%A, %b %-d at %-I:%M %p').replace(':00 ', ' ') + '.'
    elif is_presale:
        title = show + ' Pre-Sale Tickets'
        desc = 'Early ticket access' + (' before the public sale on ' + opens.strftime('%b %-d') if before_public else '') + '.'
    elif before_public:
        title = show + ' Tickets'
        desc = 'Tickets go on sale ' + opens.strftime('%A, %b %-d at %-I:%M %p').replace(':00 ', ' ') + '.'
    else:
        title = show + ' Tickets'
        desc = 'Tickets on sale now.'
    desc = ' · '.join(x for x in [when, where] if x) + (' · ' if (when or where) else '') + desc
    image = prod.get('image_url') or prod.get('ticket_logo_url') or 'https://rolecall.hwtco.org/static/images/hwtc_logo_teal.png'
    if image.startswith('/'):
        image = 'https://rolecall.hwtco.org' + image
    url = 'https://rolecall.hwtco.org/tickets/' + slug + (('?presale=' + key) if is_presale else '')
    tags = ('<title>' + escape(title) + ' | Horizon West Theater Company</title>\n'
            '<meta name="description" content="' + escape(desc) + '"/>\n'
            '<meta property="og:type" content="website"/>\n'
            '<meta property="og:site_name" content="Horizon West Theater Company"/>\n'
            '<meta property="og:title" content="' + escape(title) + '"/>\n'
            '<meta property="og:description" content="' + escape(desc) + '"/>\n'
            '<meta property="og:image" content="' + escape(image) + '"/>\n'
            '<meta property="og:url" content="' + escape(url) + '"/>\n'
            '<meta name="twitter:card" content="summary_large_image"/>\n'
            + ('<meta name="robots" content="noindex"/>\n' if is_presale else ''))
    page = page.replace('<title>Tickets</title>', tags, 1)
    resp = app.response_class(page, mimetype='text/html')
    resp.headers['Cache-Control'] = 'no-store'
    return resp

@app.route('/tickets/confirmation')
def public_tickets_confirmation_page():
    return send_from_directory('static', 'tickets.html')


# One pass on every deploy: any upcoming ticket whose seat label no longer
# matches the seat map (because the map was corrected after people bought)
# picks up the map's current label.
try:
    _sl_conn = get_db()
    execute(_sl_conn, "SET lock_timeout = '4s'")
    _sl_n = sync_ticket_seat_labels(_sl_conn)
    _sl_conn.close()
    if _sl_n:
        app.logger.info(f'Relabeled {_sl_n} ticket(s) to match their seat maps')
except Exception as _sl_e:
    app.logger.warning(f'Startup ticket label sync skipped: {_sl_e}')
